    const normalizedPerms = isPrimarySuper
      ? { ...FULL_PERMISSIONS }
      : normalizeUserPermissions({ ...(existing.permissions || {}), ...(user?.permissions || {}) });
    const rawCols = Array.isArray(user?.allowedColumns)
      ? user.allowedColumns
