import React, { useState, useEffect, useMemo } from 'react';
import {
  X,
  ShieldCheck,
  Search,
  History,
  User,
  Clock,
  Monitor,
  FileText,
  Lock,
  ArrowLeft,
  Filter,
  CheckCircle2,
  AlertTriangle
} from 'lucide-react';
import {
  auditTrailService,
  AuditTrailRecord,
  AuditOperationType
} from '../services/auditTrailService';
import { WorkOrder, PlatformUser } from '../types';

interface AuditTrailModalProps {
  isOpen: boolean;
  onClose: () => void;
  workOrders: WorkOrder[];
  currentUser?: PlatformUser | null;
  initialWorkOrderFilter?: string;
}

const OPERATION_BADGE_CONFIG: Record<
  AuditOperationType,
  { label: string; bg: string; text: string; border: string }
> = {
  DATA_ENTRY: {
    label: 'إدخال بيانات',
    bg: 'bg-blue-50',
    text: 'text-blue-800',
    border: 'border-blue-200'
  },
  DATA_EDIT: {
    label: 'تعديل بيانات',
    bg: 'bg-amber-50',
    text: 'text-amber-800',
    border: 'border-amber-200'
  },
  DATA_DELETE: {
    label: 'حذف بيانات',
    bg: 'bg-rose-50',
    text: 'text-rose-800',
    border: 'border-rose-200'
  },
  AUDIT_OPERATION: {
    label: 'عملية تدقيق',
    bg: 'bg-indigo-50',
    text: 'text-indigo-800',
    border: 'border-indigo-200'
  },
  ITEM_STATUS_CHANGE: {
    label: 'تغيير حالة بند',
    bg: 'bg-purple-50',
    text: 'text-purple-800',
    border: 'border-purple-200'
  },
  ORDER_STATUS_CHANGE: {
    label: 'تغيير حالة أمر عمل',
    bg: 'bg-cyan-50',
    text: 'text-cyan-800',
    border: 'border-cyan-200'
  },
  ATTACHMENT_UPLOAD: {
    label: 'رفع مرفق',
    bg: 'bg-teal-50',
    text: 'text-teal-800',
    border: 'border-teal-200'
  },
  ATTACHMENT_DELETE: {
    label: 'حذف مرفق',
    bg: 'bg-red-50',
    text: 'text-red-800',
    border: 'border-red-200'
  },
  AUDIT_APPROVAL: {
    label: 'اعتماد تدقيق',
    bg: 'bg-emerald-50',
    text: 'text-emerald-800',
    border: 'border-emerald-200'
  },
  APPROVAL_REVOKE: {
    label: 'إلغاء اعتماد',
    bg: 'bg-orange-50',
    text: 'text-orange-800',
    border: 'border-orange-200'
  },
  CHECKLIST_UPDATE: {
    label: 'تحديث قائمة تحقق',
    bg: 'bg-violet-50',
    text: 'text-violet-800',
    border: 'border-violet-200'
  },
  BULK_EDIT: {
    label: 'تعديل جماعي',
    bg: 'bg-fuchsia-50',
    text: 'text-fuchsia-800',
    border: 'border-fuchsia-200'
  }
};

export const AuditTrailModal: React.FC<AuditTrailModalProps> = ({
  isOpen,
  onClose,
  workOrders,
  initialWorkOrderFilter = ''
}) => {
  const [records, setRecords] = useState<AuditTrailRecord[]>([]);
  const [searchQuery, setSearchQuery] = useState<string>(initialWorkOrderFilter);
  const [selectedType, setSelectedType] = useState<string>('ALL');

  useEffect(() => {
    if (isOpen) {
      setRecords(auditTrailService.getAllRecords());
      if (initialWorkOrderFilter) {
        setSearchQuery(initialWorkOrderFilter);
      }
    }
    const unsub = auditTrailService.subscribe((updated) => {
      setRecords(updated);
    });
    return () => unsub();
  }, [isOpen, initialWorkOrderFilter]);

  // Combine persisted AuditTrailRecords with historical editHistory from workOrders so no legacy action is missed
  const combinedRecords = useMemo(() => {
    const map = new Map<string, AuditTrailRecord>();
    records.forEach((r) => map.set(r.id, r));

    workOrders.forEach((order) => {
      if (Array.isArray(order.editHistory)) {
        order.editHistory.forEach((h) => {
          if (!map.has(h.id)) {
            map.set(h.id, {
              id: h.id,
              userName: h.userName || 'مستخدم المنصة',
              userEmail: h.userEmail || 'engmhp1@gmail.com',
              userRole: h.userRole || 'مهندس معتمد',
              timestamp: h.timestamp,
              riyadhTime: h.riyadhTime || h.timestamp,
              operationType:
                h.actionType === 'create'
                  ? 'DATA_ENTRY'
                  : h.actionType === 'delete'
                  ? 'DATA_DELETE'
                  : h.actionType === 'audit'
                  ? 'AUDIT_OPERATION'
                  : 'DATA_EDIT',
              operationLabel: h.summary || 'عملية موثقة على أمر العمل',
              fieldLabel: h.changes?.[0]?.fieldLabel || 'بيانات أمر العمل',
              previousValue: h.changes?.[0]?.oldValue || '—',
              newValue: h.changes?.[0]?.newValue || h.summary || '—',
              deviceSession: 'جلسة سحابية موثقة',
              workOrderNumber: order.workOrderNumber || 'بدون رقم',
              workOrderId: order.id,
              office: order.office,
              isFinalAction: true
            });
          }
        });
      }
    });

    return Array.from(map.values()).sort(
      (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    );
  }, [records, workOrders]);

  const filteredRecords = useMemo(() => {
    return combinedRecords.filter((rec) => {
      if (selectedType !== 'ALL' && rec.operationType !== selectedType) {
        return false;
      }
      if (!searchQuery.trim()) return true;
      const q = searchQuery.trim().toLowerCase();
      return (
        rec.workOrderNumber.toLowerCase().includes(q) ||
        rec.userName.toLowerCase().includes(q) ||
        rec.userEmail.toLowerCase().includes(q) ||
        rec.operationLabel.toLowerCase().includes(q) ||
        rec.fieldLabel.toLowerCase().includes(q) ||
        rec.previousValue.toLowerCase().includes(q) ||
        rec.newValue.toLowerCase().includes(q) ||
        (rec.office || '').toLowerCase().includes(q)
      );
    });
  }, [combinedRecords, selectedType, searchQuery]);

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/75 backdrop-blur-sm flex items-center justify-center p-2 sm:p-4 font-['Cairo',sans-serif]"
      dir="rtl"
    >
      <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 max-w-6xl w-full max-h-[92vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-150">
        {/* Header */}
        <div className="bg-gradient-to-r from-slate-950 via-slate-900 to-emerald-950 text-white px-5 py-4 flex items-center justify-between border-b border-emerald-800/40 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/20 border border-emerald-400/40 flex items-center justify-center text-emerald-300 shrink-0">
              <History className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2 flex-wrap">
                <h2 className="text-sm sm:text-base font-black text-white">
                  سجل التدقيق التاريخي الشامل (Immutable Audit Trail)
                </h2>
                <span className="px-2 py-0.5 rounded-md bg-rose-500/20 border border-rose-400/40 text-rose-200 text-[10px] font-black flex items-center gap-1">
                  <Lock className="w-3 h-3" />
                  <span>للاستعراض فقط • سياسة منع التراجع النهائية (No Undo Policy)</span>
                </span>
              </div>
              <p className="text-[11px] text-slate-300 mt-0.5">
                جميع الإجراءات المنفذة داخل المنصة نهائية (Final Action) وموثقة تلقائياً بالوقت والمستخدم والجهاز ولا يمكن التراجع عنها أو استرجاع حالتها السابقة
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-xl bg-white/10 hover:bg-white/20 text-slate-300 hover:text-white transition-colors cursor-pointer"
            title="إغلاق النافذة"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Governance Policy Notice Banner */}
        <div className="px-5 py-2.5 bg-amber-50 border-b border-amber-200 flex flex-wrap items-center justify-between gap-2 text-xs text-amber-950 shrink-0">
          <div className="flex items-center gap-2 font-bold">
            <ShieldCheck className="w-4 h-4 text-emerald-700 shrink-0" />
            <span>
              مبدأ السجل غير القابل للتراجع: تعتبر كل عملية محفوظة إجراءً نهائياً (Final Action)، وأي تعديل لاحق يُسجل كإجراء جديد مستقل مع الاحتفاظ الكامل بالسجل التاريخي.
            </span>
          </div>
          <span className="px-2.5 py-0.5 rounded-lg bg-slate-900 text-white font-mono text-[11px] font-bold">
            إجمالي العمليات الموثقة: {filteredRecords.length}
          </span>
        </div>

        {/* Filter & Search Bar */}
        <div className="p-3.5 bg-slate-50 border-b border-slate-200 flex flex-col sm:flex-row items-stretch sm:items-center gap-2.5 shrink-0">
          <div className="relative flex-1">
            <Search className="w-4 h-4 text-slate-400 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="بحث برقم أمر العمل، اسم المستخدم، نوع العملية، القيمة السابقة أو الجديدة..."
              className="w-full pr-9 pl-3 py-2 bg-white border border-slate-300 rounded-xl text-xs font-bold text-slate-900 focus:outline-none focus:ring-2 focus:ring-emerald-600"
            />
          </div>

          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-slate-500 shrink-0" />
            <select
              value={selectedType}
              onChange={(e) => setSelectedType(e.target.value)}
              className="px-3 py-2 bg-white border border-slate-300 rounded-xl text-xs font-bold text-slate-800 focus:outline-none focus:ring-2 focus:ring-emerald-600 cursor-pointer"
            >
              <option value="ALL">جميع أنواع العمليات ({combinedRecords.length})</option>
              {Object.entries(OPERATION_BADGE_CONFIG).map(([key, cfg]) => (
                <option key={key} value={key}>
                  {cfg.label}
                </option>
              ))}
            </select>

            {searchQuery && (
              <button
                type="button"
                onClick={() => setSearchQuery('')}
                className="px-3 py-2 rounded-xl bg-slate-200 hover:bg-slate-300 text-slate-700 text-xs font-bold cursor-pointer"
              >
                مسح البحث
              </button>
            )}
          </div>
        </div>

        {/* Immutable Audit Trail Table */}
        <div className="flex-1 overflow-auto p-3 sm:p-4 bg-slate-100/60">
          {filteredRecords.length === 0 ? (
            <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center space-y-2">
              <History className="w-10 h-10 text-slate-400 mx-auto" />
              <div className="text-sm font-black text-slate-700">
                لا توجد عمليات مطابقة لمعايير البحث الحالية
              </div>
              <p className="text-xs text-slate-500">
                يتم تسجيل جميع العمليات (إدخال، تعديل، حذف، تدقيق، قوائم تحقق، مرفقات، اعتمادات) تلقائياً فور حدوثها.
              </p>
            </div>
          ) : (
            <div className="bg-white rounded-2xl border border-slate-200 shadow-xs overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-right border-collapse text-xs">
                  <thead>
                    <tr className="bg-slate-900 text-white font-black text-[11px] border-b border-slate-800">
                      <th className="py-3 px-3 whitespace-nowrap">#</th>
                      <th className="py-3 px-3 whitespace-nowrap">رقم أمر العمل المرتبط</th>
                      <th className="py-3 px-3 whitespace-nowrap">نوع العملية</th>
                      <th className="py-3 px-3 whitespace-nowrap">البند / الحقل</th>
                      <th className="py-3 px-3 whitespace-nowrap">القيمة السابقة</th>
                      <th className="py-3 px-3 whitespace-nowrap">القيمة الجديدة</th>
                      <th className="py-3 px-3 whitespace-nowrap">اسم المستخدم</th>
                      <th className="py-3 px-3 whitespace-nowrap">التاريخ والوقت</th>
                      <th className="py-3 px-3 whitespace-nowrap">الجهاز / الجلسة</th>
                      <th className="py-3 px-3 whitespace-nowrap text-center">حالة الإجراء</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-200/80">
                    {filteredRecords.map((rec, index) => {
                      const badge = OPERATION_BADGE_CONFIG[rec.operationType] || {
                        label: rec.operationLabel,
                        bg: 'bg-slate-100',
                        text: 'text-slate-800',
                        border: 'border-slate-300'
                      };
                      return (
                        <tr
                          key={rec.id}
                          className="hover:bg-slate-50/90 transition-colors"
                        >
                          <td className="py-2.5 px-3 font-mono font-bold text-slate-500">
                            {index + 1}
                          </td>
                          <td className="py-2.5 px-3 whitespace-nowrap">
                            <span className="px-2.5 py-1 rounded-lg bg-slate-900 text-white font-mono font-black text-xs">
                              {rec.workOrderNumber}
                            </span>
                            {rec.office && (
                              <span className="block text-[10px] text-slate-500 font-bold mt-0.5">
                                {rec.office}
                              </span>
                            )}
                          </td>
                          <td className="py-2.5 px-3 whitespace-nowrap">
                            <span
                              className={`inline-flex items-center px-2.5 py-1 rounded-lg border font-black text-[11px] ${badge.bg} ${badge.text} ${badge.border}`}
                            >
                              {badge.label}
                            </span>
                          </td>
                          <td className="py-2.5 px-3 font-bold text-slate-800 max-w-[180px] truncate" title={rec.fieldLabel}>
                            {rec.fieldLabel}
                          </td>
                          <td className="py-2.5 px-3 max-w-[200px]">
                            <div
                              className="px-2 py-1 rounded bg-rose-50/70 border border-rose-200/70 text-rose-900 text-[11px] font-semibold truncate"
                              title={rec.previousValue}
                            >
                              {rec.previousValue}
                            </div>
                          </td>
                          <td className="py-2.5 px-3 max-w-[220px]">
                            <div
                              className="px-2 py-1 rounded bg-emerald-50/80 border border-emerald-200/80 text-emerald-950 text-[11px] font-bold truncate flex items-center gap-1"
                              title={rec.newValue}
                            >
                              <ArrowLeft className="w-3 h-3 text-emerald-600 shrink-0" />
                              <span className="truncate">{rec.newValue}</span>
                            </div>
                          </td>
                          <td className="py-2.5 px-3 whitespace-nowrap">
                            <div className="flex items-center gap-1.5 font-bold text-slate-900">
                              <User className="w-3.5 h-3.5 text-emerald-600 shrink-0" />
                              <span>{rec.userName}</span>
                            </div>
                            <div className="text-[10px] text-slate-500 font-mono" dir="ltr">
                              {rec.userEmail}
                            </div>
                          </td>
                          <td className="py-2.5 px-3 whitespace-nowrap font-mono text-[11px] text-slate-700">
                            <div className="flex items-center gap-1">
                              <Clock className="w-3 h-3 text-blue-600 shrink-0" />
                              <span>{rec.riyadhTime}</span>
                            </div>
                          </td>
                          <td className="py-2.5 px-3 whitespace-nowrap text-[10px] text-slate-600 font-mono">
                            <div className="flex items-center gap-1">
                              <Monitor className="w-3 h-3 text-slate-400 shrink-0" />
                              <span>{rec.deviceSession}</span>
                            </div>
                          </td>
                          <td className="py-2.5 px-3 whitespace-nowrap text-center">
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-slate-900 text-amber-300 text-[10px] font-black">
                              <CheckCircle2 className="w-3 h-3 text-emerald-400" />
                              <span>نهائي (Final)</span>
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-5 py-3 bg-slate-50 border-t border-slate-200 flex flex-wrap items-center justify-between gap-2 shrink-0">
          <div className="flex items-center gap-2 text-[11px] font-bold text-slate-600">
            <AlertTriangle className="w-4 h-4 text-amber-600 shrink-0" />
            <span>
              هذا السجل محمي ومخصص للاستعراض والتدقيق فقط حسب الصلاحيات، ولا يحتوي على أي وظيفة للتراجع أو استرجاع الحالات السابقة.
            </span>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2 rounded-xl bg-slate-900 hover:bg-slate-800 text-white text-xs font-black transition-colors cursor-pointer"
          >
            إغلاق سجل التدقيق
          </button>
        </div>
      </div>
    </div>
  );
};

src/components/ClearDataModal.tsx:
import React, { useState } from 'react';
import { 
  Trash2, 
  AlertTriangle, 
  X, 
  CheckCircle2, 
  ShieldAlert, 
  Building2, 
  RotateCcw,
  Sparkles
} from 'lucide-react';
import { SubOffice } from '../types';
import { verifyAdminPin } from '../utils/security';
import { soundService } from '../services/soundService';

interface ClearDataModalProps {
  isOpen: boolean;
  onClose: () => void;
  offices: SubOffice[];
  selectedOffice: string;
  totalOrdersCount: number;
  onClearOfficeOrders: (officeName: string) => Promise<void>;
  onClearAllOrders: () => Promise<void>;
  onResetToInitial: () => Promise<void>;
  onDeleteOffice?: (officeId: string, officeName: string) => Promise<void>;
}

export const ClearDataModal: React.FC<ClearDataModalProps> = ({
  isOpen,
  onClose,
  offices,
  selectedOffice,
  totalOrdersCount,
  onClearOfficeOrders,
  onClearAllOrders,
  onResetToInitial,
  onDeleteOffice
}) => {
  const [targetOffice, setTargetOffice] = useState<string>(selectedOffice === 'all' ? (offices[0]?.name || '') : selectedOffice);
  const [pin, setPin] = useState('');
  const [pinError, setPinError] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  if (!isOpen) return null;

  const verifyPin = (): boolean => {
    if (!verifyAdminPin(pin)) {
      soundService.playActionSound('auth_error');
      setPinError('الرمز السري غير صحيح! يرجى إدخال الرمز السري المصرح به.');
      return false;
    }
    soundService.playActionSound('auth_success');
    setPinError(null);
    return true;
  };

  const handleClearOffice = async () => {
    if (!targetOffice) return;
    if (!verifyPin()) return;

    setIsProcessing(true);
    try {
      await onClearOfficeOrders(targetOffice);
      soundService.playActionSound('delete');
      setStatusMessage(`تم مسح وتفريغ كافة أوامر العمل لمكتب (${targetOffice}) بنجاح وبشكل جذري.`);
      setTimeout(() => {
        setIsProcessing(false);
        setStatusMessage(null);
        setPin('');
        onClose();
      }, 1200);
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
    }
  };

  const handleClearAll = async () => {
    if (!verifyPin()) return;

    setIsProcessing(true);
    try {
      await onClearAllOrders();
      soundService.playActionSound('delete');
      setStatusMessage('تم مسح وتفريغ كافة أوامر العمل في المنظومة كاملة بشكل جذري ونهائي.');
      setTimeout(() => {
        setIsProcessing(false);
        setStatusMessage(null);
        setPin('');
        onClose();
      }, 1200);
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
    }
  };

  const handleReset = async () => {
    if (!verifyPin()) return;

    setIsProcessing(true);
    try {
      await onResetToInitial();
      soundService.playActionSound('restore');
      setStatusMessage('تمت استعادة وإعادة تعيين البيانات النموذجية بنجاح.');
      setTimeout(() => {
        setIsProcessing(false);
        setStatusMessage(null);
        setPin('');
        onClose();
      }, 1200);
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-3 sm:p-4">
      <div className="bg-white rounded-2xl shadow-2xl border border-rose-200 max-w-lg w-full my-6 overflow-hidden flex flex-col text-right animate-in fade-in zoom-in-95 duration-150">

        {/* Header */}
        <div className="bg-gradient-to-r from-rose-950 via-rose-900 to-slate-900 text-white px-5 py-4 flex items-center justify-between border-b border-rose-800/40">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl bg-rose-600/30 border border-rose-500/40 flex items-center justify-center text-rose-300">
              <ShieldAlert className="w-5 h-5 text-rose-300" />
            </div>
            <div>
              <h2 className="text-base font-bold text-white">
                إدارة عمليات المسح والتفريغ الجذري
              </h2>
              <p className="text-xs text-rose-200/80 mt-0.5">
                تفعيل إجراءات المسح الحقيقي والفوري من الخادم وقاعدة البيانات
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-rose-300 hover:text-white hover:bg-rose-800/50 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-5 space-y-4">
          <div className="p-3 bg-rose-50 border-2 border-rose-300 rounded-xl text-rose-900 text-xs font-black flex items-center gap-2">
            <AlertTriangle className="w-4 h-4 text-rose-600 shrink-0" />
            <span>هذا الإجراء نهائي ولا يمكن التراجع عنه بعد التنفيذ.</span>
          </div>

          {statusMessage && (
            <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-xl text-emerald-800 text-xs font-semibold flex items-center gap-2 animate-in fade-in">
              <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
              <span>{statusMessage}</span>
            </div>
          )}

          {/* Master PIN Authorization input */}
          <div className="p-3.5 bg-amber-50/80 border border-amber-300 rounded-xl space-y-2">
            <div className="flex items-center justify-between text-xs font-bold text-amber-950">
              <span className="flex items-center gap-1.5">
                <ShieldAlert className="w-4 h-4 text-amber-600" />
                <span>الرقم السري المصرح به لعمليات المسح (مخفي):</span>
              </span>
            </div>
            <input
              type="password"
              value={pin}
              onChange={(e) => {
                setPin(e.target.value);
                if (pinError) setPinError(null);
              }}
              placeholder="••••"
              maxLength={8}
              className="w-full text-center tracking-[0.4em] font-mono text-lg py-2 px-3 bg-white border border-amber-300 rounded-lg focus:outline-hidden focus:ring-2 focus:ring-amber-500 text-slate-900"
            />
            {pinError && (
              <div className="text-xs text-rose-600 font-bold flex items-center gap-1.5">
                <AlertTriangle className="w-3.5 h-3.5 shrink-0" />
                <span>{pinError}</span>
              </div>
            )}
          </div>

          {/* Option 1: Clear Specific Office */}
          <div className="p-4 bg-slate-50 border border-slate-200 rounded-xl space-y-2.5">
            <div className="flex items-center justify-between">
              <span className="font-bold text-slate-800 text-xs flex items-center gap-1.5">
                <Building2 className="w-4 h-4 text-blue-600" />
                <span>1. مسح أوامر العمل لمكتب فرعي محدد</span>
              </span>
              <span className="text-[11px] text-slate-500 font-mono">
                {targetOffice ? `مكتب ${targetOffice}` : 'اختر مكتب'}
              </span>
            </div>
            <p className="text-[11px] text-slate-500 leading-relaxed">
              يقوم هذا الإجراء بمسح كافة السجلات وأوامر العمل الميدانية التابعة للمكتب المختار فقط.
            </p>
            <div className="flex items-center gap-2 pt-1">
              <select
                value={targetOffice}
                onChange={(e) => setTargetOffice(e.target.value)}
                className="flex-1 px-3 py-1.5 text-xs bg-white border border-slate-300 rounded-lg focus:outline-hidden focus:ring-1 focus:ring-blue-500"
              >
                {offices.map((off) => (
                  <option key={off.id} value={off.name}>{off.name}</option>
                ))}
              </select>
              <button
                type="button"
                disabled={isProcessing || !targetOffice}
                onClick={handleClearOffice}
                className="inline-flex items-center gap-1 px-3.5 py-1.5 rounded-lg bg-rose-600 hover:bg-rose-700 active:bg-rose-800 text-white text-xs font-bold transition-colors disabled:opacity-50 cursor-pointer"
              >
                <Trash2 className="w-3.5 h-3.5" />
                <span>مسح سجلات المكتب</span>
              </button>
            </div>
          </div>

          {/* Option 2: Radical Clear All Work Orders */}
          <div className="p-4 bg-rose-50/50 border border-rose-200 rounded-xl space-y-2.5">
            <div className="flex items-center justify-between">
              <span className="font-bold text-rose-900 text-xs flex items-center gap-1.5">
                <Trash2 className="w-4 h-4 text-rose-600" />
                <span>2. مسح وتفريغ كامل الجدول جذرياً (كافة المكاتب)</span>
              </span>
              <span className="text-[11px] text-rose-700 font-bold bg-rose-100 px-2 py-0.5 rounded-full">
                {totalOrdersCount} أمر عمل
              </span>
            </div>
            <p className="text-[11px] text-rose-700 leading-relaxed">
              لحذف جميع أوامر العمل وتفريغ الجداول بالكامل في النظام وقاعدة البيانات، أدخل الرمز السري المصرح به واضغط الزر أدناه:
            </p>
            <div className="flex items-center justify-end gap-2 pt-1">
              <button
                type="button"
                disabled={isProcessing || !pin.trim()}
                onClick={handleClearAll}
                className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-rose-700 hover:bg-rose-800 active:bg-rose-900 text-white text-xs font-bold transition-colors disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
              >
                <Trash2 className="w-4 h-4" />
                <span>تنفيذ المسح الجذري لكامل الجدول</span>
              </button>
            </div>
          </div>

          {/* Option 3: Reset to sample initial data */}
          <div className="p-4 bg-blue-50/50 border border-blue-200 rounded-xl flex items-center justify-between gap-3">
            <div>
              <span className="font-bold text-blue-950 text-xs flex items-center gap-1.5">
                <RotateCcw className="w-4 h-4 text-blue-600" />
                <span>3. استعادة البيانات النموذجية الأولية</span>
                <span className="px-1.5 py-0.5 rounded bg-blue-200/70 text-blue-950 text-[10px] font-bold">
                  محمي بالرمز السري
                </span>
              </span>
              <p className="text-[11px] text-blue-800/80 mt-1">
                إعادة ضبط السجلات إلى أمثلة أوامر العمل المعتمدة (يتطلب إدخال الرمز السري أعلاه).
              </p>
            </div>
            <button
              type="button"
              disabled={isProcessing || !pin.trim()}
              onClick={handleReset}
              className="inline-flex items-center gap-1 px-3.5 py-2 rounded-lg bg-blue-600 hover:bg-blue-700 active:bg-blue-800 text-white text-xs font-semibold shrink-0 transition-colors disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
            >
              <RotateCcw className="w-3.5 h-3.5" />
              <span>استعادة النموذجية</span>
            </button>
          </div>
        </div>

        {/* Footer */}
        <div className="bg-slate-50 px-5 py-3 border-t border-slate-200 flex items-center justify-between">
          <span className="text-[11px] text-slate-500">
            جميع عمليات المسح فورية وتنعكس مباشرة على كافة المتصلين.
          </span>
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-1.5 rounded-xl border border-slate-300 bg-white hover:bg-slate-100 text-slate-700 text-xs font-semibold transition-colors"
          >
            إغلاق
          </button>
        </div>

      </div>
    </div>
  );
};

src/components/ColumnManagerModal.tsx:
import React, { useState } from 'react';
import { 
  X, 
  Plus, 
  Trash2, 
  Edit3, 
  Check, 
  Columns3, 
  Save, 
  Sliders, 
  ListFilter,
  CheckCircle2,
  AlertCircle,
  HelpCircle,
  ChevronDown,
  ChevronUp,
  Lock
} from 'lucide-react';
import { ColumnDefinition, DropdownOptionsMap } from '../types';

interface ColumnManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  columns: ColumnDefinition[];
  dropdownOptions: DropdownOptionsMap;
  onSaveColumns: (updatedColumns: ColumnDefinition[], updatedDropdownOptions?: DropdownOptionsMap) => void;
  onOpenDropdownEditorForColumn?: (dropdownKey: string) => void;
}

export const ColumnManagerModal: React.FC<ColumnManagerModalProps> = ({
  isOpen,
  onClose,
  columns,
  dropdownOptions,
  onSaveColumns,
  onOpenDropdownEditorForColumn
}) => {
  const [localColumns, setLocalColumns] = useState<ColumnDefinition[]>(() => JSON.parse(JSON.stringify(columns)));
  const [localDropdowns, setLocalDropdowns] = useState<DropdownOptionsMap>(() => JSON.parse(JSON.stringify(dropdownOptions)));

  // New column state
  const [newColTitle, setNewColTitle] = useState('');
  const [newColHasDropdown, setNewColHasDropdown] = useState(true);
  const [newColInitialOptions, setNewColInitialOptions] = useState('');
  const [expandedColDropdown, setExpandedColDropdown] = useState<string | null>(null);

  // New option under expanded column
  const [newOptionTextForCol, setNewOptionTextForCol] = useState('');
  const [saveSuccessMsg, setSaveSuccessMsg] = useState(false);

  React.useEffect(() => {
    if (isOpen) {
      setLocalColumns(JSON.parse(JSON.stringify(columns)));
      setLocalDropdowns(JSON.parse(JSON.stringify(dropdownOptions)));
      setNewColTitle('');
      setNewColInitialOptions('');
      setSaveSuccessMsg(false);
      setExpandedColDropdown(null);
    }
  }, [isOpen, columns, dropdownOptions]);

  if (!isOpen) return null;

  const handleTitleChange = (id: string, newTitle: string) => {
    setLocalColumns(prev => prev.map(c => c.id === id ? { ...c, title: newTitle } : c));
  };

  const handleToggleDropdown = (id: string) => {
    setLocalColumns(prev => prev.map(c => {
      if (c.id === id) {
        const nextHas = !c.hasDropdown;
        // ensure key exists in dropdowns
        if (nextHas && !localDropdowns[c.dropdownKey]) {
          setLocalDropdowns(d => ({ ...d, [c.dropdownKey]: ['خيار 1', 'خيار 2'] }));
        }
        return { ...c, hasDropdown: nextHas };
      }
      return c;
    }));
  };

  const handleDeleteColumn = (col: ColumnDefinition) => {
    if (!col.isRemovable) {
      alert(`العمود الأساسي "${col.title}" مطلوب للتدقيق على إجراء 155، ولكن يمكنك تعديل مسماه وخيارات قائمته المنسدلة بحرية.`);
      return;
    }

    if (confirm(`هل أنت متأكد من حذف العمود "${col.title}" نهائياً من الجدول؟`)) {
      const updated = localColumns.filter(c => c.id !== col.id);
      setLocalColumns(updated);
      onSaveColumns(updated, localDropdowns);
      showSuccessBanner();
    }
  };

  const handleAddNewColumn = (e: React.FormEvent) => {
    e.preventDefault();
    const titleTrimmed = newColTitle.trim();
    if (!titleTrimmed) return;

    const newId = `col_${Date.now()}`;
    const dropdownKey = `drop_${newId}`;

    let initialOptionsArray: string[] = [];
    if (newColHasDropdown) {
      if (newColInitialOptions.trim()) {
        initialOptionsArray = newColInitialOptions
          .split(/[,،\n]/)
          .map(s => s.trim())
          .filter(Boolean);
      }
      if (initialOptionsArray.length === 0) {
        initialOptionsArray = ['خيار 1', 'خيار 2', 'خيار 3'];
      }
    }

    const newCol: ColumnDefinition = {
      id: newId,
      title: titleTrimmed,
      field: newId,
      isRemovable: true,
      hasDropdown: newColHasDropdown,
      dropdownKey: dropdownKey,
      order: localColumns.length + 1,
      width: '150px',
      type: newColHasDropdown ? 'select' : 'text'
    };

    const updatedColumns = [...localColumns, newCol];
    const updatedDropdowns = {
      ...localDropdowns,
      [dropdownKey]: initialOptionsArray
    };

    setLocalColumns(updatedColumns);
    setLocalDropdowns(updatedDropdowns);
    setNewColTitle('');
    setNewColInitialOptions('');

    onSaveColumns(updatedColumns, updatedDropdowns);
    showSuccessBanner();
  };

  const handleSaveAll = () => {
    onSaveColumns(localColumns, localDropdowns);
    showSuccessBanner();
  };

  const showSuccessBanner = () => {
    setSaveSuccessMsg(true);
    setTimeout(() => setSaveSuccessMsg(false), 2500);
  };

  // Add option to expanded column
  const handleAddOptionToCol = (dropdownKey: string) => {
    const trimmed = newOptionTextForCol.trim();
    if (!trimmed) return;
    const currentList = localDropdowns[dropdownKey] || [];
    if (currentList.includes(trimmed)) {
      alert('هذا الخيار موجود بالفعل!');
      return;
    }
    const nextList = [...currentList, trimmed];
    const nextMap = { ...localDropdowns, [dropdownKey]: nextList };
    setLocalDropdowns(nextMap);
    setNewOptionTextForCol('');
    onSaveColumns(localColumns, nextMap);
    showSuccessBanner();
  };

  const handleDeleteOptionFromCol = (dropdownKey: string, optIdx: number) => {
    const currentList = localDropdowns[dropdownKey] || [];
    const nextList = currentList.filter((_, i) => i !== optIdx);
    const nextMap = { ...localDropdowns, [dropdownKey]: nextList };
    setLocalDropdowns(nextMap);
    onSaveColumns(localColumns, nextMap);
    showSuccessBanner();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-slate-900/60 backdrop-blur-xs animate-in fade-in duration-200">
      <div 
        className="bg-white rounded-2xl border border-slate-200 shadow-2xl max-w-3xl w-full max-h-[92vh] flex flex-col overflow-hidden text-right"
        dir="rtl"
      >
        {/* Header */}
        <div className="bg-gradient-to-r from-slate-900 via-indigo-950 to-blue-950 text-white p-5 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-indigo-500/20 border border-indigo-400/30 flex items-center justify-center text-indigo-300">
              <Columns3 className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-base sm:text-lg">
                  إدارة وهيكلة أعمدة الجدول وقوائمها المنسدلة
                </h3>
                <span className="bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 text-[10px] font-bold px-2 py-0.5 rounded-md flex items-center gap-1">
                  <Sliders className="w-2.5 h-2.5 text-emerald-400" />
                  <span>متاح ومصرح به للمستخدمين المعتمدين</span>
                </span>
              </div>
              <p className="text-xs text-indigo-200/80 mt-0.5">
                تعديل مسميات الأعمدة، إضافة وحذف أعمدة، وتعديل القوائم المنسدلة لخلايا كل عمود
              </p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-white/10 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Success Banner */}
        {saveSuccessMsg && (
          <div className="bg-emerald-600 text-white px-4 py-2 text-xs font-semibold flex items-center gap-2">
            <Check className="w-4 h-4" />
            <span>تم حفظ هيكلة الأعمدة وتحديثات القوائم المنسدلة وترحيلها لجميع المتصلين فوراً!</span>
          </div>
        )}

        {/* Modal Body */}
        <div className="p-4 sm:p-6 overflow-y-auto flex-1 space-y-6">
          {/* Add New Column Form */}
          <form onSubmit={handleAddNewColumn} className="bg-gradient-to-br from-blue-50/60 to-indigo-50/60 border border-blue-200/80 rounded-2xl p-4 space-y-3">
            <div className="flex items-center gap-2">
              <Plus className="w-4 h-4 text-blue-700 font-bold" />
              <h4 className="text-xs font-bold text-blue-900">إضافة عمود جديد إلى الجدول</h4>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  مسمى العمود الجديد:
                </label>
                <input
                  type="text"
                  value={newColTitle}
                  onChange={(e) => setNewColTitle(e.target.value)}
                  placeholder="مثال: المهندس المشرف، موقع العمل، رقم البلاغ..."
                  className="w-full px-3 py-2 text-xs bg-white rounded-xl border border-slate-300 focus:outline-hidden focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  نوع خلايا العمود:
                </label>
                <div className="flex items-center gap-4 mt-2">
                  <label className="flex items-center gap-2 text-xs cursor-pointer">
                    <input
                      type="radio"
                      name="colDropdownType"
                      checked={newColHasDropdown}
                      onChange={() => setNewColHasDropdown(true)}
                      className="text-blue-600 focus:ring-blue-500"
                    />
                    <span>قائمة منسدلة للاختيار</span>
                  </label>
                  <label className="flex items-center gap-2 text-xs cursor-pointer">
                    <input
                      type="radio"
                      name="colDropdownType"
                      checked={!newColHasDropdown}
                      onChange={() => setNewColHasDropdown(false)}
                      className="text-blue-600 focus:ring-blue-500"
                    />
                    <span>بيانات نصية</span>
                  </label>
                </div>
              </div>
            </div>

            {newColHasDropdown && (
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  خيارات القائمة المنسدلة الأولية (مفصولة بفواصل أو أسطر):
                </label>
                <input
                  type="text"
                  value={newColInitialOptions}
                  onChange={(e) => setNewColInitialOptions(e.target.value)}
                  placeholder="مثال: مكتمل، جاري الفحص، مؤجل، غير مطابق"
                  className="w-full px-3 py-2 text-xs bg-white rounded-xl border border-slate-300 focus:outline-hidden focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                />
              </div>
            )}

            <div className="flex justify-end">
              <button
                type="submit"
                disabled={!newColTitle.trim()}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-xl text-xs font-bold transition-all shadow-xs flex items-center gap-1.5"
              >
                <Plus className="w-3.5 h-3.5" />
                <span>إدراج العمود في الجدول</span>
              </button>
            </div>
          </form>

          {/* Existing Columns List */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <Sliders className="w-4 h-4 text-slate-700" />
                <h4 className="text-xs font-bold text-slate-900">
                  قائمة أعمدة الجدول الحالية ({localColumns.length} أعمدة):
                </h4>
              </div>
              <button
                type="button"
                onClick={handleSaveAll}
                className="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-bold transition-colors flex items-center gap-1.5 shadow-2xs"
              >
                <Save className="w-3.5 h-3.5" />
                <span>حفظ التعديلات وتطبيقها</span>
              </button>
            </div>

            <div className="space-y-3 max-h-[420px] overflow-y-auto pr-0.5">
              {localColumns.map((col, idx) => {
                const isExpanded = expandedColDropdown === col.id;
                const optionsForThisCol = localDropdowns[col.dropdownKey] || [];

                return (
                  <div 
                    key={col.id}
                    className="border border-slate-200 rounded-xl bg-white hover:border-slate-300 transition-all overflow-hidden"
                  >
                    <div className="p-3 flex items-center gap-3 justify-between">
                      <div className="flex items-center gap-2 flex-1 min-w-0">
                        <span className="w-6 h-6 rounded-lg bg-slate-100 text-slate-600 text-xs font-mono font-bold flex items-center justify-center shrink-0">
                          {idx + 1}
                        </span>

                        {/* Editable Title */}
                        <div className="flex-1 max-w-sm">
                          <input
                            type="text"
                            value={col.title}
                            onChange={(e) => handleTitleChange(col.id, e.target.value)}
                            className="w-full px-2.5 py-1.5 text-xs font-bold text-slate-900 bg-slate-50 border border-slate-200 rounded-lg focus:bg-white focus:border-blue-500 focus:outline-hidden"
                            title="انقر لتعديل مسمى هذا العمود"
                          />
                        </div>

                        {/* Column badges */}
                        <div className="hidden sm:flex items-center gap-1.5">
                          {col.hasDropdown ? (
                            <span className="bg-blue-50 text-blue-700 border border-blue-200 text-[10px] font-semibold px-2 py-0.5 rounded-md flex items-center gap-1">
                              <ListFilter className="w-3 h-3" />
                              <span>قائمة منسدلة ({optionsForThisCol.length})</span>
                            </span>
                          ) : (
                            <span className="bg-slate-100 text-slate-600 text-[10px] px-2 py-0.5 rounded-md">
                              نص
                            </span>
                          )}
                          {!col.isRemovable && (
                            <span className="bg-amber-50 text-amber-800 border border-amber-200 text-[10px] font-medium px-2 py-0.5 rounded-md">
                              عمود رئيسي
                            </span>
                          )}
                        </div>
                      </div>

                      {/* Actions */}
                      <div className="flex items-center gap-1.5 shrink-0">
                        {/* Manage dropdown options accordion toggle */}
                        {col.hasDropdown && (
                          <button
                            type="button"
                            onClick={() => setExpandedColDropdown(isExpanded ? null : col.id)}
                            className={`px-2.5 py-1 rounded-lg text-xs font-semibold flex items-center gap-1 border transition-colors ${
                              isExpanded 
                                ? 'bg-indigo-600 text-white border-indigo-600' 
                                : 'bg-indigo-50 hover:bg-indigo-100 text-indigo-700 border-indigo-200'
                            }`}
                            title="تعديل خيارات القائمة المنسدلة لهذا العمود"
                          >
                            <span>خيارات القائمة</span>
                            {isExpanded ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                          </button>
                        )}

                        {/* Delete Column Button */}
                        {col.isRemovable ? (
                          <button
                            type="button"
                            onClick={() => handleDeleteColumn(col)}
                            className="p-1.5 text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
                            title="حذف هذا العمود من الجدول"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        ) : (
                          <button
                            type="button"
                            disabled
                            className="p-1.5 text-slate-300 cursor-not-allowed"
                            title="الأعمدة الأساسية لإجراء 155 لا يمكن حذفها (يمكن تعديل مسماها وخياراتها)"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        )}
                      </div>
                    </div>

                    {/* Expanded Dropdown Options Manager for this specific column */}
                    {isExpanded && col.hasDropdown && (
                      <div className="bg-slate-50 border-t border-slate-200 p-3.5 space-y-3">
                        <div className="flex items-center justify-between">
                          <span className="text-xs font-bold text-slate-700 flex items-center gap-1">
                            <ListFilter className="w-3.5 h-3.5 text-indigo-600" />
                            <span>تعديل خيارات القائمة المنسدلة لعمود ({col.title}):</span>
                          </span>
                          <span className="text-[11px] text-slate-500">
                            {optionsForThisCol.length} خيارات متاحة
                          </span>
                        </div>

                        {/* Add option to this column */}
                        <div className="flex gap-2">
                          <input
                            type="text"
                            value={newOptionTextForCol}
                            onChange={(e) => setNewOptionTextForCol(e.target.value)}
                            placeholder="اكتب خياراً جديداً لإضافته لقائمة هذا العمود..."
                            className="flex-1 px-3 py-1.5 text-xs bg-white rounded-lg border border-slate-300 focus:outline-hidden focus:border-indigo-500"
                          />
                          <button
                            type="button"
                            onClick={() => handleAddOptionToCol(col.dropdownKey)}
                            disabled={!newOptionTextForCol.trim()}
                            className="px-3 py-1.5 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white rounded-lg text-xs font-bold transition-colors"
                          >
                            إضافة سطر
                          </button>
                        </div>

                        {/* List of options */}
                        <div className="flex flex-wrap gap-1.5 pt-1">
                          {optionsForThisCol.map((opt, optIdx) => (
                            <span 
                              key={optIdx}
                              className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-white border border-slate-200 text-slate-800 text-xs shadow-2xs"
                            >
                              <span>{opt}</span>
                              <button
                                type="button"
                                onClick={() => handleDeleteOptionFromCol(col.dropdownKey, optIdx)}
                                className="text-slate-400 hover:text-rose-600 transition-colors"
                                title="حذف هذا الخيار"
                              >
                                <X className="w-3 h-3" />
                              </button>
                            </span>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-4 bg-slate-50 border-t border-slate-200 flex items-center justify-between">
          <span className="text-[11px] text-slate-500">
            يتم تحديث الجدول وترحيل الأعمدة وقوائمها فورياً لكافة المستخدمين المتصلين
          </span>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handleSaveAll}
              className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold transition-colors flex items-center gap-1.5"
            >
              <Check className="w-3.5 h-3.5" />
              <span>تأكيد وحفظ</span>
            </button>
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-slate-200 hover:bg-slate-300 text-slate-700 rounded-xl text-xs font-semibold transition-colors"
            >
              إغلاق
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

src/components/CompatibleTableImportModa:
import React, { useState, useMemo, useRef } from 'react';
import {
  X,
  Link2,
  Sparkles,
  ArrowLeftRight,
  FileSpreadsheet,
  Layers,
  CheckCircle2,
  AlertCircle,
  HelpCircle,
  ChevronDown,
  Upload,
  Clipboard,
  Check,
  RefreshCw,
  Search,
  Eye,
  SlidersHorizontal,
  TableProperties
} from 'lucide-react';
import { WorkOrder, MonthTable, ColumnDefinition, DropdownOptionsMap } from '../types';
import {
  autoMapSemanticColumns,
  SemanticMapping,
  normalizeColumnText
} from '../utils/semanticColumnMatcher';
import { parseWorkOrderExcelFile } from '../services/excelImportService';
import { getArabicMonthName, resolveOrderScope, isDefaultTableId } from '../utils/tableScope';

export interface CompatibleImportResultOptions {
  mode: 'merge_matching' | 'append_all' | 'merge_and_append';
  overwriteExistingData: boolean;
  sourceTableId: string;
  sourceTableName: string;
  distinctHighlight: boolean;
  highlightColor: string;
  importedFieldKeys: string[];
}

interface CompatibleTableImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentTableId: string;
  currentTableName: string;
  currentOrders: WorkOrder[];
  allPlatformOrders: WorkOrder[];
  monthTables: MonthTable[];
  columns: ColumnDefinition[];
  dropdownOptions?: DropdownOptionsMap;
  onExecuteImport: (
    importedOrders: WorkOrder[],
    options: CompatibleImportResultOptions
  ) => Promise<boolean | void>;
}

export const CompatibleTableImportModal: React.FC<CompatibleTableImportModalProps> = ({
  isOpen,
  onClose,
  currentTableId,
  currentTableName,
  currentOrders,
  allPlatformOrders,
  monthTables,
  columns,
  dropdownOptions,
  onExecuteImport
}) => {
  const [sourceType, setSourceType] = useState<'platform_table' | 'external_file'>('platform_table');
  const [selectedSourceTableId, setSelectedSourceTableId] = useState<string>('');
  const [searchTableQuery, setSearchTableQuery] = useState('');
  const [importMode, setImportMode] = useState<'merge_and_append' | 'merge_matching' | 'append_all'>('merge_and_append');
  const [overwriteExistingData, setOverwriteExistingData] = useState(false);
  const [distinctHighlight, setDistinctHighlight] = useState(true);
  const [highlightColor, setHighlightColor] = useState('#f0fdf4'); // soft emerald tint
  const [isProcessing, setIsProcessing] = useState(false);
  const [customFile, setCustomFile] = useState<File | null>(null);
  const [fileParsedRows, setFileParsedRows] = useState<any[]>([]);
  const [fileHeaders, setFileHeaders] = useState<{ key: string; header: string; sampleValue?: any }[]>([]);
  const [columnMappings, setColumnMappings] = useState<SemanticMapping[]>([]);
  const [isParsingFile, setIsParsingFile] = useState(false);
  const [step, setStep] = useState<'select_source' | 'configure_mapping'>('select_source');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Group all platform orders by their resolved table
  const platformTablesList = useMemo(() => {
    // Collect all unique table scopes from monthTables and orders
    const tableMap = new Map<string, { id: string; name: string; year: number; month: number | 'all'; orders: WorkOrder[]; color?: string }>();

    // 1. Registered MonthTables
    monthTables.forEach(t => {
      tableMap.set(t.id, {
        id: t.id,
        name: t.name,
        year: t.year,
        month: t.month,
        orders: [],
        color: t.color
      });
    });

    // 2. Distribute all orders into their table buckets
    allPlatformOrders.forEach(o => {
      const scope = resolveOrderScope(o, monthTables);
      if (!tableMap.has(scope.tableId)) {
        tableMap.set(scope.tableId, {
          id: scope.tableId,
          name: scope.tableName,
          year: scope.year,
          month: scope.month,
          orders: [o],
          color: scope.tableColor
        });
      } else {
        tableMap.get(scope.tableId)!.orders.push(o);
      }
    });

    // Exclude the current active table itself from source list
    const list = Array.from(tableMap.values()).filter(t => t.id !== currentTableId && t.orders.length > 0);

    // Compute compatibility count for each candidate table
    const currentWonCodes = new Set(
      currentOrders.map(o => `${(o.workOrderNumber || '').trim().toLowerCase()}:::${(o.workOrderCode || '').trim().toLowerCase()}`).filter(k => k !== ':::')
    );
    const currentWons = new Set(
      currentOrders.map(o => (o.workOrderNumber || '').trim().toLowerCase()).filter(Boolean)
    );

    return list.map(t => {
      const exactMatches = t.orders.filter(o => {
        const k = `${(o.workOrderNumber || '').trim().toLowerCase()}:::${(o.workOrderCode || '').trim().toLowerCase()}`;
        return k !== ':::' && currentWonCodes.has(k);
      }).length;

      const wonMatches = t.orders.filter(o => {
        const won = (o.workOrderNumber || '').trim().toLowerCase();
        return won && currentWons.has(won);
      }).length;

      return {
        ...t,
        exactMatches,
        wonMatches,
        compatibilityScore: exactMatches * 2 + wonMatches
      };
    }).sort((a, b) => b.compatibilityScore - a.compatibilityScore);
  }, [allPlatformOrders, currentOrders, currentTableId, monthTables]);

  // Set default selected source table
  React.useEffect(() => {
    if (platformTablesList.length > 0 && !selectedSourceTableId) {
      setSelectedSourceTableId(platformTablesList[0].id);
    }
  }, [platformTablesList, selectedSourceTableId]);

  // Current selected source table object
  const selectedSourceTable = useMemo(() => {
    return platformTablesList.find(t => t.id === selectedSourceTableId);
  }, [platformTablesList, selectedSourceTableId]);

  // When source changes, automatically compute semantic column mappings
  const initializeMappingsForTable = (tableId: string) => {
    const tbl = platformTablesList.find(t => t.id === tableId);
    if (!tbl || tbl.orders.length === 0) return;

    // Extract headers from source orders
    const sample = tbl.orders[0];
    const sourceKeys = Object.keys(sample).filter(k => !['id', 'tableId', 'tableYear', 'tableMonth', 'tableName', 'createdAt', 'updatedAt'].includes(k));

    const sourceHeaders = sourceKeys.map(key => {
      // Find matching column title if known
      const matchedCol = columns.find(c => c.field === key);
      const title = matchedCol ? matchedCol.title : key;
      const sampleVal = tbl.orders.find(o => o[key])?.[key];
      return {
        key,
        header: title,
        sampleValue: sampleVal
      };
    });

    const mapped = autoMapSemanticColumns(sourceHeaders, columns);
    setColumnMappings(mapped);
  };

  const handleSelectTable = (tableId: string) => {
    setSelectedSourceTableId(tableId);
    initializeMappingsForTable(tableId);
  };

  // Handle file upload parsing for external file mode
  const handleFileUpload = async (file: File) => {
    setCustomFile(file);
    setIsParsingFile(true);
    try {
      const res = await parseWorkOrderExcelFile(file, columns);
      if (res && res.orders && res.orders.length > 0) {
        setFileParsedRows(res.orders);
        const headers = res.allDetectedColumns.map(c => ({
          key: c.matchedField || c.headerName,
          header: c.headerName,
          sampleValue: c.sampleValue
        }));
        setFileHeaders(headers);
        const mapped = autoMapSemanticColumns(headers, columns);
        setColumnMappings(mapped);
      }
    } catch (err) {
      console.error('File parsing failed:', err);
    } finally {
      setIsParsingFile(false);
    }
  };

  const handleMappingChange = (targetField: string, newSourceKey: string) => {
    setColumnMappings(prev =>
      prev.map(m => {
        if (m.targetField !== targetField) return m;
        if (!newSourceKey) {
          return {
            ...m,
            sourceKey: '',
            sourceHeader: '(غير معين)',
            confidence: 0,
            matchReason: 'تم إلغاء التعيين يدوياً',
            enabled: false
          };
        }
        return {
          ...m,
          sourceKey: newSourceKey,
          sourceHeader: newSourceKey,
          confidence: 100,
          matchReason: 'تعيين يدوي من المستخدم',
          enabled: true
        };
      })
    );
  };

  const handleToggleColumnEnable = (targetField: string) => {
    setColumnMappings(prev =>
      prev.map(m => (m.targetField === targetField ? { ...m, enabled: !m.enabled } : m))
    );
  };

  // Execute Compatible Import
  const handleProceedImport = async () => {
    setIsProcessing(true);
    try {
      let rawSourceOrders: WorkOrder[] = [];
      let sourceName = '';

      if (sourceType === 'platform_table') {
        if (!selectedSourceTable) return;
        rawSourceOrders = selectedSourceTable.orders;
        sourceName = selectedSourceTable.name;
      } else {
        rawSourceOrders = fileParsedRows as WorkOrder[];
        sourceName = customFile?.name || 'ملف خارجي';
      }

      if (rawSourceOrders.length === 0) return;

      // Map each source order into destination schema using enabled semantic mappings
      const enabledMappings = columnMappings.filter(m => m.enabled && m.sourceKey);
      const importedFieldKeys = enabledMappings.map(m => m.targetField);

      // Current orders map by (workOrderNumber:::workOrderCode) and workOrderNumber
      const currentOrdersByCode = new Map<string, WorkOrder>();
      const currentOrdersByWon = new Map<string, WorkOrder>();

      currentOrders.forEach(o => {
        const num = (o.workOrderNumber || '').trim().toLowerCase();
        const code = (o.workOrderCode || '').trim().toLowerCase();
        if (num && code) currentOrdersByCode.set(`${num}:::${code}`, o);
        if (num) currentOrdersByWon.set(num, o);
      });

      const updatedOrCreatedList: WorkOrder[] = [];

      for (const src of rawSourceOrders) {
        // Extract mapped values
        const mappedData: Record<string, any> = {};
        for (const map of enabledMappings) {
          const val = src[map.sourceKey];
          if (val !== undefined && val !== null && val !== '') {
            mappedData[map.targetField] = val;
          }
        }

        const srcWon = (src.workOrderNumber || mappedData.workOrderNumber || '').trim();
        const srcCode = (src.workOrderCode || mappedData.workOrderCode || '').trim();
        const fullKey = `${srcWon.toLowerCase()}:::${srcCode.toLowerCase()}`;

        // Find match in current table
        const matchedCurrent = (fullKey && currentOrdersByCode.get(fullKey)) || (srcWon && currentOrdersByWon.get(srcWon.toLowerCase()));

        if (matchedCurrent) {
          if (importMode === 'append_all') {
            // Treat as fresh duplicate row in append mode
            const newOrder: WorkOrder = {
              ...matchedCurrent,
              ...mappedData,
              id: `wo-imp-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
              tableId: currentTableId,
              isNew: true,
              isImported: true,
              importedFromTableId: sourceType === 'platform_table' ? selectedSourceTableId : 'external_file',
              importedFromTableName: sourceName,
              importedAt: new Date().toISOString(),
              importedFields: importedFieldKeys,
              rowBgColor: distinctHighlight ? highlightColor : undefined,
              updatedAt: new Date().toISOString()
            };
            updatedOrCreatedList.push(newOrder);
          } else {
            // Merge into matchedCurrent
            const mergedOrder: WorkOrder = {
              ...matchedCurrent,
              id: matchedCurrent.id,
              tableId: currentTableId,
              isImported: true,
              importedFromTableId: sourceType === 'platform_table' ? selectedSourceTableId : 'external_file',
              importedFromTableName: sourceName,
              importedAt: new Date().toISOString(),
              importedFields: Array.from(new Set([...(matchedCurrent.importedFields || []), ...importedFieldKeys])),
              rowBgColor: distinctHighlight ? highlightColor : matchedCurrent.rowBgColor,
              updatedAt: new Date().toISOString()
            };

            // Apply fields according to overwrite flag
            for (const [key, val] of Object.entries(mappedData)) {
              if (overwriteExistingData || (matchedCurrent as any)[key] === undefined || (matchedCurrent as any)[key] === '' || (matchedCurrent as any)[key] === null) {
                (mergedOrder as any)[key] = val;
              }
            }

            // Copy photos if available
            if (Array.isArray(src.photos) && src.photos.length > 0) {
              const curPhotos = Array.isArray(matchedCurrent.photos) ? [...matchedCurrent.photos] : [];
              const pIds = new Set(curPhotos.map(p => p.id || p.url));
              src.photos.forEach(p => {
                if (p && !pIds.has(p.id || p.url)) curPhotos.push(p);
              });
              mergedOrder.photos = curPhotos;
            }

            updatedOrCreatedList.push(mergedOrder);
          }
        } else {
          // No match in current table
          if (importMode === 'merge_matching') {
            // Skip non-matched rows in pure merge mode
            continue;
          }

          // Create brand new row in current table
          const newOrder: WorkOrder = {
            id: `wo-imp-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
            tableId: currentTableId,
            office: mappedData.office || src.office || 'مكتب عرعر',
            contractor: mappedData.contractor || src.contractor || 'غير محدد',
            workOrderNumber: srcWon || `WO-${Date.now()}`,
            workOrderCode: srcCode || '',
            executionStatus: mappedData.executionStatus || src.executionStatus || 'قيد التدقيق',
            procedure155Status: mappedData.procedure155Status || src.procedure155Status || 'مؤهل للاغلاق ( معتمد )',
            isNew: true,
            isImported: true,
            importedFromTableId: sourceType === 'platform_table' ? selectedSourceTableId : 'external_file',
            importedFromTableName: sourceName,
            importedAt: new Date().toISOString(),
            importedFields: importedFieldKeys,
            rowBgColor: distinctHighlight ? highlightColor : undefined,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
            ...mappedData
          };

          if (Array.isArray(src.photos) && src.photos.length > 0) {
            newOrder.photos = [...src.photos];
          }

          updatedOrCreatedList.push(newOrder);
        }
      }

      const result = await onExecuteImport(updatedOrCreatedList, {
        mode: importMode,
        overwriteExistingData,
        sourceTableId: sourceType === 'platform_table' ? selectedSourceTableId : 'external_file',
        sourceTableName: sourceName,
        distinctHighlight,
        highlightColor,
        importedFieldKeys
      });

      if (result !== false) {
        onClose();
      }
    } finally {
      setIsProcessing(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center p-3 sm:p-5 bg-slate-950/80 backdrop-blur-md overflow-y-auto animate-in fade-in duration-200">
      <div 
        className="relative w-full max-w-4xl bg-white rounded-3xl shadow-2xl border-2 border-indigo-600 overflow-hidden flex flex-col max-h-[92vh] text-right font-['Cairo',sans-serif]"
        onClick={(e) => e.stopPropagation()}
        dir="rtl"
      >
        {/* Modal Header */}
        <div className="p-4 sm:p-6 bg-gradient-to-r from-indigo-950 via-slate-900 to-indigo-900 text-white flex items-center justify-between border-b border-indigo-500/40 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-indigo-500 to-cyan-500 text-white flex items-center justify-center font-bold shadow-lg ring-2 ring-indigo-400/50 shrink-0">
              <Sparkles className="w-6 h-6 animate-pulse" />
            </div>
            <div>
              <div className="flex items-center gap-2 flex-wrap">
                <h3 className="text-base sm:text-lg font-black text-white tracking-tight flex items-center gap-1.5">
                  <span>استيراد البيانات من الجداول المتوافقة</span>
                </h3>
                <span className="px-2.5 py-0.5 rounded-full text-xs font-black bg-indigo-500 text-white shadow-xs">
                  بدلالة الأعمدة الدلالية
                </span>
              </div>
              <p className="text-xs text-indigo-200 mt-0.5">
                استيراد تلقائي وذكي للخلايا في أعمدتها المتوافقة مع تمييز لوني وبصري فوري لسهولة تمييزها
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="w-9 h-9 rounded-xl bg-white/10 hover:bg-white/20 text-white flex items-center justify-center transition-colors cursor-pointer"
            title="إغلاق"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Steps Navigation Bar */}
        <div className="px-4 py-2.5 bg-slate-100 border-b border-slate-200 flex items-center justify-between text-xs font-bold text-slate-700 shrink-0">
          <div className="flex items-center gap-2">
            <span className="text-slate-500">الجدول المستهدف الحالي:</span>
            <span className="px-2.5 py-0.5 rounded-lg bg-indigo-100 text-indigo-900 font-black border border-indigo-200">
              {currentTableName} ({currentOrders.length} صف)
            </span>
          </div>

          <div className="flex items-center gap-1.5">
            <button
              type="button"
              onClick={() => setStep('select_source')}
              className={`px-3 py-1 rounded-xl cursor-pointer transition-all ${
                step === 'select_source'
                  ? 'bg-indigo-600 text-white shadow-xs font-black'
                  : 'bg-white hover:bg-slate-200 text-slate-700 border border-slate-300'
              }`}
            >
              1. اختيار الجدول المصدر
            </button>
            <span>←</span>
            <button
              type="button"
              onClick={() => {
                if (selectedSourceTableId) {
                  initializeMappingsForTable(selectedSourceTableId);
                }
                setStep('configure_mapping');
              }}
              className={`px-3 py-1 rounded-xl cursor-pointer transition-all ${
                step === 'configure_mapping'
                  ? 'bg-indigo-600 text-white shadow-xs font-black'
                  : 'bg-white hover:bg-slate-200 text-slate-700 border border-slate-300'
              }`}
            >
              2. مطابقة الأعمدة الدلالية والخيارات
            </button>
          </div>
        </div>

        {/* Modal Body */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-5">
          {step === 'select_source' && (
            <div className="space-y-4">
              {/* Source Mode Toggle: Platform Tables vs External File */}
              <div className="grid grid-cols-2 gap-2 bg-slate-100 p-1.5 rounded-2xl border border-slate-200">
                <button
                  type="button"
                  onClick={() => setSourceType('platform_table')}
                  className={`py-2 px-3 rounded-xl text-xs font-black flex items-center justify-center gap-2 transition-all cursor-pointer ${
                    sourceType === 'platform_table'
                      ? 'bg-white text-indigo-900 shadow-sm border border-slate-200'
                      : 'text-slate-600 hover:text-slate-900'
                  }`}
                >
                  <Layers className="w-4 h-4 text-indigo-600" />
                  <span>من جداول المنظومة المتاحة ({platformTablesList.length})</span>
                </button>

                <button
                  type="button"
                  onClick={() => setSourceType('external_file')}
                  className={`py-2 px-3 rounded-xl text-xs font-black flex items-center justify-center gap-2 transition-all cursor-pointer ${
                    sourceType === 'external_file'
                      ? 'bg-white text-indigo-900 shadow-sm border border-slate-200'
                      : 'text-slate-600 hover:text-slate-900'
                  }`}
                >
                  <FileSpreadsheet className="w-4 h-4 text-emerald-600" />
                  <span>استيراد من ملف خارجي (Excel / CSV)</span>
                </button>
              </div>

              {sourceType === 'platform_table' ? (
                <div className="space-y-3">
                  <div className="flex items-center justify-between gap-2">
                    <span className="text-xs font-black text-slate-800">
                      اختر الجدول المتوافق الذي تود استيراد البيانات منه:
                    </span>
                    <div className="relative w-48">
                      <input
                        type="text"
                        value={searchTableQuery}
                        onChange={(e) => setSearchTableQuery(e.target.value)}
                        placeholder="بحث في الجداول..."
                        className="w-full text-xs py-1 pr-6 pl-2 bg-slate-50 border border-slate-200 rounded-lg"
                      />
                      <Search className="w-3 h-3 text-slate-400 absolute right-2 top-1/2 -translate-y-1/2" />
                    </div>
                  </div>

                  {platformTablesList.length === 0 ? (
                    <div className="p-8 text-center bg-slate-50 rounded-2xl border border-slate-200 text-slate-500 space-y-2">
                      <Layers className="w-8 h-8 text-slate-300 mx-auto" />
                      <p className="font-bold text-sm">لا توجد جداول أخرى بها بيانات في المنظومة حالياً.</p>
                      <p className="text-xs text-slate-400">يمكنك استخدام خيار الاستيراد من ملف Excel خارجي أعلاه.</p>
                    </div>
                  ) : (
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5 max-h-72 overflow-y-auto p-1">
                      {platformTablesList
                        .filter(t => t.name.toLowerCase().includes(searchTableQuery.toLowerCase()))
                        .map(table => {
                          const isSelected = selectedSourceTableId === table.id;
                          return (
                            <div
                              key={table.id}
                              onClick={() => handleSelectTable(table.id)}
                              className={`p-3 rounded-2xl border-2 transition-all cursor-pointer flex flex-col justify-between text-right ${
                                isSelected
                                  ? 'bg-indigo-50/90 border-indigo-600 ring-2 ring-indigo-400/40 shadow-sm'
                                  : 'bg-white border-slate-200 hover:border-indigo-300 hover:bg-slate-50'
                              }`}
                            >
                              <div className="flex items-start justify-between gap-2">
                                <div className="space-y-1">
                                  <div className="flex items-center gap-1.5">
                                    <span className="w-2.5 h-2.5 rounded-full bg-indigo-500" />
                                    <h4 className="text-xs font-black text-slate-900">{table.name}</h4>
                                  </div>
                                  <p className="text-[11px] text-slate-500">
                                    الفترة: {table.month === 'all' ? 'كافة الشهور' : getArabicMonthName(table.month)} {table.year}
                                  </p>
                                </div>
                                <span className="font-mono text-xs font-black px-2 py-0.5 rounded-md bg-indigo-100 text-indigo-800 border border-indigo-200">
                                  {table.orders.length} أمر
                                </span>
                              </div>

                              {/* Compatibility indicator */}
                              <div className="mt-2 pt-2 border-t border-slate-100 flex items-center justify-between text-[10px] text-slate-600">
                                <span className="flex items-center gap-1">
                                  <Link2 className="w-3 h-3 text-orange-500" />
                                  <span>تطابق رقم ورمز العمل: <strong className="text-orange-600 font-bold">{table.exactMatches}</strong></span>
                                </span>
                                {isSelected && (
                                  <span className="px-1.5 py-0.2 rounded bg-indigo-600 text-white font-bold flex items-center gap-0.5">
                                    <Check className="w-2.5 h-2.5" />
                                    <span>محدد</span>
                                  </span>
                                )}
                              </div>
                            </div>
                          );
                        })}
                    </div>
                  )}
                </div>
              ) : (
                /* External File Upload View */
                <div className="space-y-3">
                  <div 
                    onClick={() => fileInputRef.current?.click()}
                    className="p-8 border-2 border-dashed border-indigo-300 hover:border-indigo-500 rounded-2xl bg-indigo-50/40 hover:bg-indigo-50 text-center cursor-pointer transition-all space-y-2"
                  >
                    <Upload className="w-10 h-10 text-indigo-600 mx-auto" />
                    <h4 className="text-sm font-bold text-slate-800">
                      {customFile ? customFile.name : 'اسحب وأفلت ملف Excel أو CSV أو JSON هنا أو انقر للاختيار'}
                    </h4>
                    <p className="text-xs text-slate-500">
                      يدعم التنسيقات .xlsx, .xls, .csv, .json - سيتم التعرف تلقائياً على الأعمدة الدلالية
                    </p>
                    <input
                      ref={fileInputRef}
                      type="file"
                      accept=".xlsx,.xls,.csv,.json,application/json,text/plain,application/octet-stream,*/*"
                      className="hidden"
                      onChange={(e) => {
                        if (e.target.files && e.target.files[0]) {
                          handleFileUpload(e.target.files[0]);
                        }
                      }}
                    />
                  </div>

                  {fileParsedRows.length > 0 && (
                    <div className="p-3 bg-emerald-50 rounded-xl border border-emerald-200 text-emerald-900 text-xs font-bold flex items-center justify-between">
                      <span className="flex items-center gap-1.5">
                        <CheckCircle2 className="w-4 h-4 text-emerald-600" />
                        <span>تم التعرف على ({fileParsedRows.length}) سطر و ({fileHeaders.length}) عمود من الملف</span>
                      </span>
                    </div>
                  )}
                </div>
              )}

              {/* Next Step Button */}
              <div className="pt-2 flex justify-end">
                <button
                  type="button"
                  onClick={() => {
                    if (sourceType === 'platform_table' && selectedSourceTableId) {
                      initializeMappingsForTable(selectedSourceTableId);
                    }
                    setStep('configure_mapping');
                  }}
                  disabled={sourceType === 'platform_table' ? !selectedSourceTableId : fileParsedRows.length === 0}
                  className="px-5 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-black text-xs shadow-md cursor-pointer flex items-center gap-2"
                >
                  <span>متابعة إلى مطابقة الأعمدة الدلالية</span>
                  <span>←</span>
                </button>
              </div>
            </div>
          )}

          {step === 'configure_mapping' && (
            <div className="space-y-5">
              {/* Top Banner explaining Semantic Matching */}
              <div className="p-3 bg-gradient-to-r from-indigo-50 to-cyan-50 rounded-2xl border border-indigo-200 text-indigo-950 flex items-start gap-2.5 text-xs">
                <Sparkles className="w-5 h-5 text-indigo-600 shrink-0 mt-0.5" />
                <div>
                  <h4 className="font-black text-indigo-900">محرك المطابقة الدلالية الذكي للأعمدة</h4>
                  <p className="text-slate-600 mt-0.5 leading-relaxed">
                    تم التعرف تلقائياً على الأعمدة الدلالية المتوافقة (رقم أمر العمل، الرمز، المكتب، المقاول، نماذج الاستشاري، توثيق الصور، نموذج 190، نموذج 200، نموذج الفحص، ملاحظات الجودة، حالة 155). يمكنك تخصيص التعيين أو تعطيل أي عمود لا ترغب باستيراد خلاياه.
                  </p>
                </div>
              </div>

              {/* Column Mappings Grid */}
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <h4 className="text-xs font-black text-slate-800 flex items-center gap-1.5">
                    <TableProperties className="w-4 h-4 text-indigo-600" />
                    <span>مطابقة الأعمدة الدلالية والخلايا المستهدفة:</span>
                  </h4>
                  <span className="text-[11px] text-slate-500 font-bold">
                    الأعمدة المحددة للاستيراد: {columnMappings.filter(m => m.enabled && m.sourceKey).length} من {columnMappings.length}
                  </span>
                </div>

                <div className="max-h-64 overflow-y-auto border border-slate-200 rounded-2xl divide-y divide-slate-100 bg-white">
                  {columnMappings.map(mapping => {
                    const isEnabled = mapping.enabled && Boolean(mapping.sourceKey);
                    return (
                      <div
                        key={mapping.targetField}
                        className={`p-2.5 flex items-center justify-between gap-3 text-xs transition-colors ${
                          isEnabled ? 'bg-white hover:bg-slate-50' : 'bg-slate-50/70 opacity-60'
                        }`}
                      >
                        <div className="flex items-center gap-2.5 min-w-[180px]">
                          <input
                            type="checkbox"
                            checked={mapping.enabled}
                            onChange={() => handleToggleColumnEnable(mapping.targetField)}
                            className="w-4 h-4 rounded text-indigo-600 accent-indigo-600 cursor-pointer"
                          />
                          <div>
                            <span className="font-black text-slate-900">{mapping.targetTitle}</span>
                            <span className="text-[10px] text-slate-400 font-mono block">({mapping.targetField})</span>
                          </div>
                        </div>

                        <div className="flex items-center gap-1.5 text-slate-400">
                          <ArrowLeftRight className="w-3.5 h-3.5" />
                        </div>

                        <div className="flex-1 min-w-[200px]">
                          <div className="flex items-center gap-2">
                            <span className="text-xs font-bold text-indigo-900 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-200">
                              {mapping.sourceHeader || mapping.sourceKey || '(غير معين)'}
                            </span>
                            {mapping.confidence > 0 && (
                              <span className={`text-[10px] font-bold px-1.5 py-0.2 rounded-md ${
                                mapping.confidence >= 90
                                  ? 'bg-emerald-100 text-emerald-800'
                                  : 'bg-amber-100 text-amber-800'
                              }`}>
                                {mapping.confidence}% {mapping.matchReason}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* Import Execution Mode Configuration */}
              <div className="space-y-3 pt-2 border-t border-slate-200">
                <h4 className="text-xs font-black text-slate-800">طريقة الاستيراد والتطبيق بالجدول:</h4>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                  <label
                    onClick={() => setImportMode('merge_and_append')}
                    className={`p-3 rounded-2xl border-2 cursor-pointer flex flex-col justify-between text-right transition-all ${
                      importMode === 'merge_and_append'
                        ? 'bg-indigo-50 border-indigo-600 ring-2 ring-indigo-400/30'
                        : 'bg-white border-slate-200 hover:border-slate-300'
                    }`}
                  >
                    <div>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-black text-xs text-indigo-950">دمج وإضافة (شامل موصى به)</span>
                        <input
                          type="radio"
                          name="impMode"
                          checked={importMode === 'merge_and_append'}
                          onChange={() => setImportMode('merge_and_append')}
                          className="accent-indigo-600"
                        />
                      </div>
                      <p className="text-[11px] text-slate-500 leading-normal">
                        يحدث خلايا الأوامر المتطابقة برقم ورمز العمل، ويضيف الأوامر الجديدة كصفوف مستقلة.
                      </p>
                    </div>
                  </label>

                  <label
                    onClick={() => setImportMode('merge_matching')}
                    className={`p-3 rounded-2xl border-2 cursor-pointer flex flex-col justify-between text-right transition-all ${
                      importMode === 'merge_matching'
                        ? 'bg-indigo-50 border-indigo-600 ring-2 ring-indigo-400/30'
                        : 'bg-white border-slate-200 hover:border-slate-300'
                    }`}
                  >
                    <div>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-black text-xs text-indigo-950">دمج وتحديث المتطابق فقط</span>
                        <input
                          type="radio"
                          name="impMode"
                          checked={importMode === 'merge_matching'}
                          onChange={() => setImportMode('merge_matching')}
                          className="accent-indigo-600"
                        />
                      </div>
                      <p className="text-[11px] text-slate-500 leading-normal">
                        يحدث بيانات وخلايا الصفوف الموجودة فقط دون إنشاء صفوف جديدة.
                      </p>
                    </div>
                  </label>

                  <label
                    onClick={() => setImportMode('append_all')}
                    className={`p-3 rounded-2xl border-2 cursor-pointer flex flex-col justify-between text-right transition-all ${
                      importMode === 'append_all'
                        ? 'bg-indigo-50 border-indigo-600 ring-2 ring-indigo-400/30'
                        : 'bg-white border-slate-200 hover:border-slate-300'
                    }`}
                  >
                    <div>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-black text-xs text-indigo-950">إضافة كافة السجلات كصفوف جديدة</span>
                        <input
                          type="radio"
                          name="impMode"
                          checked={importMode === 'append_all'}
                          onChange={() => setImportMode('append_all')}
                          className="accent-indigo-600"
                        />
                      </div>
                      <p className="text-[11px] text-slate-500 leading-normal">
                        يدرج كافة البيانات كصفوف إضافية مباشرة داخل الجدول الحالي.
                      </p>
                    </div>
                  </label>
                </div>
              </div>

              {/* Distinct Visual Highlight Configuration (المطلب الأساسي: وتكون مميزة لسهولة تمييزها عن غيرها) */}
              <div className="p-3.5 bg-amber-50/80 rounded-2xl border-2 border-amber-300/80 space-y-2 text-right">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Sparkles className="w-4 h-4 text-amber-600" />
                    <span className="text-xs font-black text-amber-950">
                      التمييز البصري الذكي للبيانات والصفوف المستوردة:
                    </span>
                  </div>
                  <label className="flex items-center gap-1.5 cursor-pointer text-xs font-bold text-amber-900">
                    <input
                      type="checkbox"
                      checked={distinctHighlight}
                      onChange={(e) => setDistinctHighlight(e.target.checked)}
                      className="w-4 h-4 rounded text-amber-600 accent-amber-600 cursor-pointer"
                    />
                    <span>تفعيل شارة ولون التمييز</span>
                  </label>
                </div>
                <p className="text-[11px] text-amber-900/90 leading-relaxed">
                  عند تفعيل هذا الخيار، سيتم تمييز الصفوف المستوردة بشارة واضحة <span className="font-mono bg-white px-1.5 py-0.5 rounded border border-amber-300 font-bold text-indigo-900">✨ مستورد متوافق</span> مع توضيح اسم الجدول المستورد منه، وتمييز الخلايا المستوردة لتسهيل التعرف عليها وتصفيتها بضغطة زر واحدة.
                </p>

                {distinctHighlight && (
                  <div className="flex items-center gap-2 pt-1 border-t border-amber-200/60">
                    <span className="text-[11px] font-bold text-amber-900">لون خلفية التمييز:</span>
                    <div className="flex items-center gap-1.5">
                      {[
                        { color: '#f0fdf4', label: 'أخضر هادئ', ring: 'bg-emerald-100 border-emerald-400' },
                        { color: '#eff6ff', label: 'سماوي هادئ', ring: 'bg-blue-100 border-blue-400' },
                        { color: '#faf5ff', label: 'بنفسجي هادئ', ring: 'bg-purple-100 border-purple-400' },
                        { color: '#fffbeb', label: 'عنبري هادئ', ring: 'bg-amber-100 border-amber-400' },
                      ].map(swatch => (
                        <button
                          key={swatch.color}
                          type="button"
                          onClick={() => setHighlightColor(swatch.color)}
                          className={`px-2 py-0.5 rounded-lg border text-[10px] font-bold cursor-pointer transition-all ${swatch.ring} ${
                            highlightColor === swatch.color ? 'ring-2 ring-indigo-600 font-black scale-105' : 'opacity-70'
                          }`}
                        >
                          {swatch.label}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Overwrite empty only toggle */}
              <div className="flex items-center justify-between text-xs font-bold text-slate-700 bg-slate-50 p-2.5 rounded-xl border border-slate-200">
                <span>تحديث الخلايا الفارغة فقط وعدم استبدال الخلايا المملوءة مسبقاً:</span>
                <input
                  type="checkbox"
                  checked={!overwriteExistingData}
                  onChange={(e) => setOverwriteExistingData(!e.target.checked)}
                  className="w-4 h-4 rounded text-indigo-600 accent-indigo-600 cursor-pointer"
                />
              </div>

              {/* Action Buttons */}
              <div className="pt-3 border-t border-slate-200 flex items-center justify-between gap-3">
                <button
                  type="button"
                  onClick={() => setStep('select_source')}
                  className="px-4 py-2 text-xs font-bold text-slate-600 hover:text-slate-900 cursor-pointer"
                >
                  ← رجوع لاختيار المصدر
                </button>

                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={onClose}
                    className="px-4 py-2 rounded-xl text-xs font-bold text-slate-600 hover:bg-slate-100 cursor-pointer"
                  >
                    إلغاء
                  </button>

                  <button
                    type="button"
                    onClick={handleProceedImport}
                    disabled={isProcessing || columnMappings.filter(m => m.enabled && m.sourceKey).length === 0}
                    className="px-6 py-2.5 rounded-xl bg-gradient-to-r from-indigo-600 to-cyan-600 hover:from-indigo-700 hover:to-cyan-700 text-white font-black text-xs shadow-lg cursor-pointer flex items-center gap-2 disabled:opacity-50 active:scale-95 transition-all"
                  >
                    {isProcessing ? (
                      <>
                        <RefreshCw className="w-4 h-4 animate-spin" />
                        <span>جارٍ الاستيراد والمطابقة...</span>
                      </>
                    ) : (
                      <>
                        <Sparkles className="w-4 h-4" />
                        <span>تنفيذ استيراد المتوافق الآن</span>
                      </>
                    )}
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

src/components/ComprehensiveReportsModal:
import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  WorkOrder, 
  SubOffice, 
  MonthTable, 
  PlatformUser,
  SHAREPOINT_AUDIT_URL 
} from '../types';
import { 
  X, 
  FileSpreadsheet, 
  FileDown, 
  Printer, 
  Calendar, 
  Building2, 
  Briefcase, 
  Award, 
  TrendingUp, 
  CheckCircle2, 
  AlertTriangle, 
  Search, 
  Filter, 
  Sparkles, 
  ShieldCheck, 
  FileText, 
  Layers, 
  BarChart3, 
  RotateCcw, 
  Copy, 
  Check, 
  ExternalLink,
  ChevronDown,
  Clock,
  Mail,
  Zap,
  FolderOpen
} from 'lucide-react';
import { getArabicMonthName, ARABIC_MONTHS, resolveOrderScope } from '../utils/tableScope';
import { soundService } from '../services/soundService';
import { UnifiedSectionExportBar } from './UnifiedSectionExportBar';
import { exportToPdf, exportOrdersDirectToPdf } from '../services/exportService';
import ExcelJS from 'exceljs';

export type ReportViewMode = 'aggregated' | 'detailed';
export type AggregationPeriodType = 'weekly' | 'monthly' | 'quarterly' | 'semi_annual' | 'annual';

interface ComprehensiveReportsModalProps {
  isOpen: boolean;
  onClose: () => void;
  workOrders: WorkOrder[];
  allWorkOrders?: WorkOrder[];
  monthTables?: MonthTable[];
  offices?: SubOffice[];
  activeYear?: number;
  activeMonth?: number | 'all';
  selectedOffice?: string;
  currentUser?: PlatformUser | null;
  initialMode?: ReportViewMode;
  onOpenOrderFiles?: (order: WorkOrder) => void;
  onOpenExportModal?: (orders: WorkOrder[], title: string, openEmail?: boolean) => void;
}

export const ComprehensiveReportsModal: React.FC<ComprehensiveReportsModalProps> = ({
  isOpen,
  onClose,
  workOrders,
  allWorkOrders,
  monthTables = [],
  offices = [],
  activeYear = new Date().getFullYear(),
  activeMonth = 'all',
  selectedOffice = 'all',
  currentUser,
  initialMode = 'aggregated',
  onOpenOrderFiles,
  onOpenExportModal
}) => {
  const currentNow = new Date();
  const currentYearNum = typeof activeYear === 'number' && activeYear > 2000 ? activeYear : currentNow.getFullYear();

  // Mode: Aggregated (مجمعة) vs Detailed (تفصيلية)
  const [viewMode, setViewMode] = useState<ReportViewMode>(initialMode);

  useEffect(() => {
    if (isOpen) {
      setViewMode(initialMode || 'aggregated');
    }
  }, [isOpen, initialMode]);

  // Aggregated Period Selector: weekly, monthly, quarterly, semi_annual, annual
  const [periodType, setPeriodType] = useState<AggregationPeriodType>('monthly');
  const [selectedYear, setSelectedYear] = useState<number>(currentYearNum);
  const [selectedMonth, setSelectedMonth] = useState<number>(
    typeof activeMonth === 'number' ? activeMonth : currentNow.getMonth() + 1
  );
  const [selectedQuarter, setSelectedQuarter] = useState<1 | 2 | 3 | 4>(
    (Math.floor(currentNow.getMonth() / 3) + 1) as 1 | 2 | 3 | 4
  );
  const [selectedHalf, setSelectedHalf] = useState<1 | 2>(currentNow.getMonth() < 6 ? 1 : 2);
  const [selectedWeek, setSelectedWeek] = useState<'current_week' | 'last_week'>('current_week');

  // Office & Table Scope
  const [officeFilter, setOfficeFilter] = useState<string>(selectedOffice || 'all');
  const [tableFilter, setTableFilter] = useState<string>('all');

  // Detailed view filters
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [statusQualificationFilter, setStatusQualificationFilter] = useState<'all' | 'ready' | 'notReady'>('all');
  const [contractorFilter, setContractorFilter] = useState<string>('all');

  // Action status states
  const [isExporting, setIsExporting] = useState<boolean>(false);
  const [isCopiedSummary, setIsCopiedSummary] = useState<boolean>(false);
  const [notificationMsg, setNotificationMsg] = useState<string | null>(null);

  const reportContainerRef = useRef<HTMLDivElement>(null);

  // Available database source: prefer allWorkOrders if provided to cover all linked tables
  const sourceOrders = useMemo(() => {
    return Array.isArray(allWorkOrders) && allWorkOrders.length > 0 ? allWorkOrders : workOrders;
  }, [allWorkOrders, workOrders]);

  // Available Years extracted from tables and orders
  const availableYears = useMemo(() => {
    const yearsSet = new Set<number>();
    yearsSet.add(currentYearNum);
    yearsSet.add(2025);
    yearsSet.add(2026);
    yearsSet.add(2027);
    sourceOrders.forEach(o => {
      if (o.tableYear) yearsSet.add(o.tableYear);
      if (o.createdAt) {
        const y = new Date(o.createdAt).getFullYear();
        if (!isNaN(y) && y > 2020) yearsSet.add(y);
      }
    });
    monthTables.forEach(t => {
      if (t.year) yearsSet.add(t.year);
    });
    return Array.from(yearsSet).sort((a, b) => b - a);
  }, [sourceOrders, monthTables, currentYearNum]);

  // Week Date Range calculations
  const weekInfo = useMemo(() => {
    const now = new Date();
    const currentDay = now.getDay(); // 0 is Sunday
    const sunday = new Date(now);
    sunday.setDate(now.getDate() - currentDay);
    const thursday = new Date(sunday);
    thursday.setDate(sunday.getDate() + 4);

    const lastSunday = new Date(sunday);
    lastSunday.setDate(sunday.getDate() - 7);
    const lastThursday = new Date(lastSunday);
    lastThursday.setDate(lastSunday.getDate() + 4);

    const fmt = (d: Date) => `${d.getDate()} / ${d.getMonth() + 1} / ${d.getFullYear()}`;
    return {
      currentWeekRange: `${fmt(sunday)} - ${fmt(thursday)}`,
      lastWeekRange: `${fmt(lastSunday)} - ${fmt(lastThursday)}`,
      currentSunday: sunday,
      lastSunday: lastSunday
    };
  }, []);

  // Filtered Orders linked to the selected period and tables
  const periodFilteredOrders = useMemo(() => {
    return sourceOrders.filter(order => {
      // 1. Office filter
      if (officeFilter !== 'all' && order.office !== officeFilter) return false;

      // 2. Table filter
      if (tableFilter !== 'all' && order.tableId !== tableFilter) return false;

      // 3. Year scope
      const orderYear = order.tableYear || (order.createdAt ? new Date(order.createdAt).getFullYear() : selectedYear);
      if (orderYear !== selectedYear) return false;

      // 4. Period breakdown
      const orderMonth = order.tableMonth || (order.createdAt ? new Date(order.createdAt).getMonth() + 1 : 1);

      if (periodType === 'monthly') {
        return orderMonth === selectedMonth;
      }

      if (periodType === 'quarterly') {
        const quarterMonthsMap: Record<number, number[]> = {
          1: [1, 2, 3],
          2: [4, 5, 6],
          3: [7, 8, 9],
          4: [10, 11, 12]
        };
        return (quarterMonthsMap[selectedQuarter] || []).includes(orderMonth);
      }

      if (periodType === 'semi_annual') {
        if (selectedHalf === 1) {
          return orderMonth >= 1 && orderMonth <= 6;
        } else {
          return orderMonth >= 7 && orderMonth <= 12;
        }
      }

      if (periodType === 'annual') {
        return true; // All months of the selected year
      }

      if (periodType === 'weekly') {
        if (!order.createdAt) return true;
        const oDate = new Date(order.createdAt);
        const refStart = selectedWeek === 'current_week' ? weekInfo.currentSunday : weekInfo.lastSunday;
        const refEnd = new Date(refStart);
        refEnd.setDate(refEnd.getDate() + 6);
        return oDate >= refStart && oDate <= refEnd;
      }

      return true;
    });
  }, [sourceOrders, officeFilter, tableFilter, selectedYear, periodType, selectedMonth, selectedQuarter, selectedHalf, selectedWeek, weekInfo]);

  // Final Detailed Orders (with search and status filters applied)
  const detailedOrders = useMemo(() => {
    return periodFilteredOrders.filter(order => {
      // Contractor filter
      if (contractorFilter !== 'all' && order.contractor !== contractorFilter) return false;

      // Status qualification filter
      const statusStr = String(order.procedure155Status || '');
      const isQualified = !statusStr.includes('غير') && (statusStr.includes('مؤهل') || statusStr.includes('معتمد') || statusStr.includes('تم'));
      if (statusQualificationFilter === 'ready' && !isQualified) return false;
      if (statusQualificationFilter === 'notReady' && isQualified) return false;

      // Search text query
      if (searchQuery.trim()) {
        const q = searchQuery.trim().toLowerCase();
        const matchesNum = (order.workOrderNumber || '').toLowerCase().includes(q);
        const matchesCode = (order.workOrderCode || '').toLowerCase().includes(q);
        const matchesCont = (order.contractor || '').toLowerCase().includes(q);
        const matchesOffice = (order.office || '').toLowerCase().includes(q);
        const matchesNotes = (order.qualityNotes || '').toLowerCase().includes(q);
        if (!matchesNum && !matchesCode && !matchesCont && !matchesOffice && !matchesNotes) return false;
      }

      return true;
    });
  }, [periodFilteredOrders, contractorFilter, statusQualificationFilter, searchQuery]);

  // Aggregate Metrics & Key Performance Indicators
  const metrics = useMemo(() => {
    const total = periodFilteredOrders.length;
    let readyCount = 0;
    let notReadyCount = 0;
    let photoCompleteCount = 0;
    let consultantFormsCount = 0;
    let consultantClearanceCount = 0;
    let form190Count = 0;
    let form200Count = 0;
    let inspectionCount = 0;
    let withAttachedFilesCount = 0;

    periodFilteredOrders.forEach(o => {
      const s = String(o.procedure155Status || '');
      if (!s.includes('غير') && (s.includes('مؤهل') || s.includes('معتمد') || s.includes('تم'))) {
        readyCount++;
      } else {
        notReadyCount++;
      }

      if (String(o.photoDocumentation || '').includes('مكتمل')) photoCompleteCount++;
      if (String(o.consultantForms || '').includes('مكتمل')) consultantFormsCount++;
      if (String(o.consultantClearanceForms || '').includes('مكتمل')) consultantClearanceCount++;
      if (String(o.form190 || '').includes('مكتمل')) form190Count++;
      if (String(o.form200 || '').includes('مكتمل')) form200Count++;
      if (String(o.inspectionForm || '').includes('مكتمل')) inspectionCount++;
      if (o.photosFile && o.photosFile.length > 0) withAttachedFilesCount++;
    });

    const readyRate = total > 0 ? Math.round((readyCount / total) * 100) : 0;
    const notReadyRate = total > 0 ? Math.round((notReadyCount / total) * 100) : 0;

    // Quality Index average of criteria
    const criteriaRates = total > 0 ? [
      photoCompleteCount / total,
      consultantFormsCount / total,
      consultantClearanceCount / total,
      form190Count / total,
      form200Count / total,
      inspectionCount / total
    ] : [0];
    const avgCriteriaRate = Math.round((criteriaRates.reduce((a, b) => a + b, 0) / criteriaRates.length) * 100);

    return {
      total,
      readyCount,
      readyRate,
      notReadyCount,
      notReadyRate,
      photoCompleteCount,
      consultantFormsCount,
      consultantClearanceCount,
      form190Count,
      form200Count,
      inspectionCount,
      withAttachedFilesCount,
      avgCriteriaRate
    };
  }, [periodFilteredOrders]);

  // Office comparative breakdown
  const officeMetrics = useMemo(() => {
    const map: Record<string, { total: number; ready: number; notReady: number; withFiles: number }> = {};
    const defaultOffices = ['مكتب عرعر', 'مكتب رفحاء', 'مكتب طريف', 'مكتب العويقيلة'];
    defaultOffices.forEach(off => {
      map[off] = { total: 0, ready: 0, notReady: 0, withFiles: 0 };
    });

    periodFilteredOrders.forEach(o => {
      const off = (o.office || 'غير محدد').trim();
      if (!map[off]) map[off] = { total: 0, ready: 0, notReady: 0, withFiles: 0 };
      map[off].total++;
      const s = String(o.procedure155Status || '');
      if (!s.includes('غير') && (s.includes('مؤهل') || s.includes('معتمد') || s.includes('تم'))) {
        map[off].ready++;
      } else {
        map[off].notReady++;
      }
      if (o.photosFile && o.photosFile.length > 0) map[off].withFiles++;
    });

    return Object.entries(map).map(([name, d]) => ({
      name,
      total: d.total,
      ready: d.ready,
      notReady: d.notReady,
      withFiles: d.withFiles,
      rate: d.total > 0 ? Math.round((d.ready / d.total) * 100) : 0,
      evaluation: d.total === 0 ? 'لا توجد أوامر' : d.ready / d.total >= 0.8 ? 'ممتاز' : d.ready / d.total >= 0.5 ? 'جيد' : 'بحاجة لمتابعة'
    })).sort((a, b) => b.rate - a.rate || b.total - a.total);
  }, [periodFilteredOrders]);

  // Contractor comparative breakdown
  const contractorMetrics = useMemo(() => {
    const map: Record<string, { total: number; ready: number; notReady: number; withFiles: number; offices: Set<string> }> = {};

    periodFilteredOrders.forEach(o => {
      const cont = (o.contractor || 'غير محدد').trim();
      if (!map[cont]) map[cont] = { total: 0, ready: 0, notReady: 0, withFiles: 0, offices: new Set() };
      map[cont].total++;
      if (o.office) map[cont].offices.add(o.office);
      const s = String(o.procedure155Status || '');
      if (!s.includes('غير') && (s.includes('مؤهل') || s.includes('معتمد') || s.includes('تم'))) {
        map[cont].ready++;
      } else {
        map[cont].notReady++;
      }
      if (o.photosFile && o.photosFile.length > 0) map[cont].withFiles++;
    });

    return Object.entries(map).map(([name, d]) => ({
      name,
      total: d.total,
      ready: d.ready,
      notReady: d.notReady,
      withFiles: d.withFiles,
      officesText: Array.from(d.offices).join(' ، ') || 'غير محدد',
      rate: d.total > 0 ? Math.round((d.ready / d.total) * 100) : 0,
      evaluation: d.total === 0 ? '-' : d.ready / d.total >= 0.8 ? 'ملتزم جداً' : d.ready / d.total >= 0.5 ? 'متوسط' : 'متعثر في الإغلاق'
