      case 'monthly':
        return `تقرير شهري (${getArabicMonthName(selectedMonth)} ${selectedYear})`;
      case 'quarterly':
        return `تقرير الربع ${selectedQuarter === 1 ? 'الأول (Q1)' : selectedQuarter === 2 ? 'الثاني (Q2)' : selectedQuarter === 3 ? 'الثالث (Q3)' : 'الرابع (Q4)'} لعام ${selectedYear}`;
      case 'semi_annual':
