            className={`pb-2.5 px-3 text-xs font-black transition-all border-b-2 cursor-pointer whitespace-nowrap ${
              activeTab === 'server'
                ? 'border-indigo-600 text-indigo-900'
                : 'border-transparent text-slate-500 hover:text-slate-900'
