              <button
                type="button"
                onClick={handleDownloadFullExport}
                className="px-4 py-2 rounded-xl bg-amber-600 hover:bg-amber-700 text-white font-black text-xs shadow-xs transition-colors cursor-pointer flex items-center gap-1.5"
                title="تنزيل نسخة كاملة ومباشرة صالحة للاستيراد الفوري"
              >
                <Download className="w-3.5 h-3.5" />
                <span>تنزيل من السيرفر مباشرة</span>
              </button>
            </div>
          </div>
        )}

        {/* Footer */}
        <div className="p-4 sm:px-6 bg-slate-50 border-t border-slate-200 flex items-center justify-between text-xs text-slate-500">
          <div className="flex items-center gap-2">
            <ShieldCheck className="w-4 h-4 text-emerald-600" />
            <span>نظام الحماية المزدوجة (Dual-Vault Protection) مفعل بنجاح</span>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2 rounded-xl bg-slate-200 hover:bg-slate-300 text-slate-800 font-bold transition-colors cursor-pointer"
          >
            إغلاق
          </button>
        </div>

      </div>
    </div>
  );
};

src/components/DeleteTableModal.tsx:
import React, { useState } from 'react';
import { 
  Trash2, 
  ShieldAlert, 
  X, 
  KeyRound, 
  AlertCircle, 
  CheckCircle2, 
  Building2, 
  FileSpreadsheet, 
  Eye, 
  EyeOff,
  AlertTriangle
} from 'lucide-react';
import { SubOffice } from '../types';
import { verifyAdminPin } from '../utils/security';

interface DeleteTableModalProps {
  isOpen: boolean;
  onClose: () => void;
  officeTitle: string;
  currentOrdersCount: number;
  totalOrdersCount: number;
  onClearOfficeOrders: (officeName: string) => Promise<void>;
  onClearAllOrders: () => Promise<void>;
}

export const DeleteTableModal: React.FC<DeleteTableModalProps> = ({
  isOpen,
  onClose,
  officeTitle,
  currentOrdersCount,
  totalOrdersCount,
  onClearOfficeOrders,
  onClearAllOrders
}) => {
  const [pin, setPin] = useState('');
  const [showPin, setShowPin] = useState(false);
  const [error, setError] = useState(false);
  const [scope, setScope] = useState<'current' | 'all'>('current');
  const [isProcessing, setIsProcessing] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  if (!isOpen) return null;

  const handleConfirmDelete = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();

    // Verify Secret PIN strictly
    if (!verifyAdminPin(pin)) {
      setError(true);
      return;
    }

    setError(false);
    setIsProcessing(true);

    try {
      if (scope === 'current' && officeTitle !== 'جميع المكاتب الفرعية') {
        await onClearOfficeOrders(officeTitle);
        setSuccessMessage(`تم مسح وتفريغ أوامر العمل لمكتب (${officeTitle}) بنجاح وبشكل جذري`);
      } else {
        await onClearAllOrders();
        setSuccessMessage('تم مسح وتفريغ كامل بيانات الجدول جذرياً ونهائياً لكافة المكاتب');
      }

      setTimeout(() => {
        setIsProcessing(false);
        setSuccessMessage(null);
        setPin('');
        onClose();
      }, 1200);
    } catch (err) {
      console.error('Failed to clear table:', err);
      setIsProcessing(false);
    }
  };

  const handleClose = () => {
    if (isProcessing) return;
    setPin('');
    setError(false);
    setSuccessMessage(null);
    onClose();
  };

  return (
    <div 
      className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-slate-950/70 backdrop-blur-xs animate-in fade-in duration-200"
      dir="rtl"
      role="dialog"
      aria-modal="true"
    >
      <div className="bg-white rounded-2xl shadow-2xl border-2 border-rose-400/80 max-w-md w-full overflow-hidden text-right animate-in zoom-in-95 duration-150 font-['Cairo',sans-serif]">

        {/* Header with High-Impact Red/Rose Aesthetics */}
        <div className="bg-gradient-to-r from-rose-950 via-rose-900 to-slate-900 text-white p-4 sm:p-5 flex items-center justify-between border-b border-rose-800">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-rose-600/30 border border-rose-400/40 flex items-center justify-center text-rose-300 shadow-inner">
              <Trash2 className="w-5 h-5 text-rose-400" />
            </div>
            <div>
              <h3 className="font-bold text-base text-white flex items-center gap-2">
                <span>حذف ومسح بيانات الجدول</span>
                <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-500/30 text-rose-200 border border-rose-400/30">
                  إجراء جذري
                </span>
              </h3>
              <p className="text-xs text-rose-200/80 mt-0.5">
                عملية مسح حقيقية وفورية مؤمنة برمز الأمان
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={handleClose}
            disabled={isProcessing}
            className="p-1.5 rounded-lg text-rose-300 hover:text-white hover:bg-white/10 transition-colors cursor-pointer"
            title="إلغاء وإغلاق"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <form onSubmit={handleConfirmDelete} className="p-5 space-y-4">

          {/* Success Banner */}
          {successMessage && (
            <div className="p-3.5 bg-emerald-50 border-2 border-emerald-300 rounded-xl text-emerald-900 text-xs font-bold flex items-center gap-2 animate-in fade-in">
              <CheckCircle2 className="w-5 h-5 text-emerald-600 shrink-0" />
              <span>{successMessage}</span>
            </div>
          )}

          {/* Warning Card */}
          <div className="p-3.5 bg-rose-50/80 border border-rose-200 rounded-xl flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-rose-600 shrink-0 mt-0.5" />
            <div className="text-xs text-rose-900 leading-relaxed">
              <strong className="block font-bold mb-0.5">تحذير أمني هام:</strong>
              سيؤدي هذا الإجراء إلى حذف وتفريغ السجلات من الخادم وقاعدة البيانات مباشرة والمزامنة مع كافة المتصلين فوراً.
            </div>
          </div>

          {/* Scope Selector */}
          <div className="space-y-2">
            <label className="block text-xs font-bold text-slate-800">
              حدد نطاق الحذف والمسح:
            </label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">

              {/* Scope Option 1: Current Office */}
              <button
                type="button"
                onClick={() => setScope('current')}
                className={`p-3 rounded-xl border text-right transition-all cursor-pointer flex flex-col justify-between ${
                  scope === 'current'
                    ? 'bg-rose-50 border-rose-500 ring-2 ring-rose-400 text-rose-950 font-bold'
                    : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'
                }`}
              >
                <div className="flex items-center justify-between text-xs mb-1">
                  <span className="flex items-center gap-1.5 font-bold">
                    <Building2 className="w-3.5 h-3.5 text-blue-600" />
                    <span>المكتب الحالي</span>
                  </span>
                  <span className="text-[10px] font-mono px-1.5 py-0.5 rounded-md bg-white border border-slate-200">
                    {currentOrdersCount} أمر
                  </span>
                </div>
                <p className="text-[11px] text-slate-500 font-normal truncate">
                  {officeTitle}
                </p>
              </button>

              {/* Scope Option 2: Full System Wipe */}
              <button
                type="button"
                onClick={() => setScope('all')}
                className={`p-3 rounded-xl border text-right transition-all cursor-pointer flex flex-col justify-between ${
                  scope === 'all'
                    ? 'bg-rose-50 border-rose-600 ring-2 ring-rose-400 text-rose-950 font-bold'
                    : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'
                }`}
              >
                <div className="flex items-center justify-between text-xs mb-1">
                  <span className="flex items-center gap-1.5 font-bold text-rose-800">
                    <FileSpreadsheet className="w-3.5 h-3.5 text-rose-600" />
                    <span>كامل الجدول (الكل)</span>
                  </span>
                  <span className="text-[10px] font-mono px-1.5 py-0.5 rounded-md bg-rose-100 text-rose-800 border border-rose-200">
                    {totalOrdersCount} أمر
                  </span>
                </div>
                <p className="text-[11px] text-slate-500 font-normal">
                  مسح كافة المكاتب بالكامل
                </p>
              </button>

            </div>
          </div>

          {/* Hidden PIN Input (رقم سري مصرح به) */}
          <div className="space-y-1.5 pt-1">
            <div className="flex items-center justify-between">
              <label className="block text-xs font-bold text-slate-800 flex items-center gap-1.5">
                <KeyRound className="w-3.5 h-3.5 text-rose-600" />
                <span>الرقم السري المصرح به لتأكيد الحذف (مخفي):</span>
              </label>
            </div>

            <div className="relative">
              <input
                type={showPin ? 'text' : 'password'}
                value={pin}
                onChange={(e) => {
                  setPin(e.target.value);
                  if (error) setError(false);
                }}
                maxLength={8}
                autoFocus
                placeholder="••••"
                className={`w-full text-center text-xl font-mono tracking-[0.4em] py-2.5 px-10 rounded-xl border bg-slate-50 transition-all focus:outline-hidden focus:bg-white ${
                  error 
                    ? 'border-rose-500 text-rose-600 ring-2 ring-rose-200 bg-rose-50/50' 
                    : 'border-slate-300 text-slate-900 focus:border-rose-600 focus:ring-2 focus:ring-rose-100'
                }`}
              />

              {/* Toggle visibility */}
              <button
                type="button"
                onClick={() => setShowPin(!showPin)}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-1 cursor-pointer"
                title={showPin ? 'إخفاء الرمز' : 'إظهار الرمز'}
              >
                {showPin ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>

            {error && (
              <div className="flex items-center gap-1.5 mt-1 text-rose-600 text-xs font-bold animate-in fade-in">
                <AlertCircle className="w-4 h-4 shrink-0" />
                <span>الرمز السري غير صحيح! يرجى إدخال الرمز السري المصرح به لتنفيذ المسح.</span>
              </div>
            )}
          </div>

          {/* Action Buttons */}
          <div className="pt-3 border-t border-slate-200 flex items-center justify-end gap-2">
            <button
              type="button"
              onClick={handleClose}
              disabled={isProcessing}
              className="px-4 py-2 rounded-xl text-xs font-semibold text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors cursor-pointer"
            >
              إلغاء الأمر
            </button>

            <button
              type="submit"
              disabled={isProcessing || !pin.trim()}
              className="inline-flex items-center gap-2 px-5 py-2 rounded-xl text-xs font-bold text-white bg-rose-600 hover:bg-rose-700 active:bg-rose-800 transition-all shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
            >
              <Trash2 className="w-4 h-4" />
              <span>{isProcessing ? 'جارٍ المسح الجذري...' : 'تأكيد المسح النهائي والحقيقي'}</span>
            </button>
          </div>

        </form>

      </div>
    </div>
  );
};

src/components/DropdownManagerModal.tsx:
import React, { useState } from 'react';
import { 
  X, 
  Plus, 
  Trash2, 
  Edit2, 
  Check, 
  ListOrdered, 
  Save, 
  Sparkles,
  ArrowRight,
  HelpCircle,
  Layers,
  Lock
} from 'lucide-react';
import { ColumnDefinition, DropdownOptionsMap } from '../types';

interface DropdownManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  columns: ColumnDefinition[];
  dropdownOptions: DropdownOptionsMap;
  onSaveOptions: (updatedOptions: DropdownOptionsMap) => void;
  initialSelectedColumnKey?: string;
}

export const DropdownManagerModal: React.FC<DropdownManagerModalProps> = ({
  isOpen,
  onClose,
  columns,
  dropdownOptions,
  onSaveOptions,
  initialSelectedColumnKey
}) => {
  // Filter columns that support dropdowns
  const dropdownColumns = columns.filter(col => col.hasDropdown);

  const defaultKey = initialSelectedColumnKey && dropdownOptions[initialSelectedColumnKey] 
    ? initialSelectedColumnKey 
    : (dropdownColumns[0]?.dropdownKey || 'office');

  const [selectedKey, setSelectedKey] = useState<string>(defaultKey);
  const [localOptions, setLocalOptions] = useState<DropdownOptionsMap>(() => JSON.parse(JSON.stringify(dropdownOptions)));
  const [newOptionText, setNewOptionText] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [editingValue, setEditingValue] = useState('');
  const [saveSuccessMsg, setSaveSuccessMsg] = useState(false);

  // Sync when prop changes or modal opens
  React.useEffect(() => {
    if (isOpen) {
      setLocalOptions(JSON.parse(JSON.stringify(dropdownOptions)));
      if (initialSelectedColumnKey && dropdownColumns.some(c => c.dropdownKey === initialSelectedColumnKey)) {
        setSelectedKey(initialSelectedColumnKey);
      } else if (!dropdownColumns.some(c => c.dropdownKey === selectedKey)) {
        setSelectedKey(dropdownColumns[0]?.dropdownKey || 'office');
      }
      setEditingIndex(null);
      setNewOptionText('');
      setSaveSuccessMsg(false);
    }
  }, [isOpen, dropdownOptions, initialSelectedColumnKey]);

  if (!isOpen) return null;

  const currentOptionsList = localOptions[selectedKey] || [];
  const selectedColumnInfo = columns.find(c => c.dropdownKey === selectedKey);

  const handleAddOption = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = newOptionText.trim();
    if (!trimmed) return;
    if (currentOptionsList.includes(trimmed)) {
      alert('هذا الخيار موجود بالفعل في القائمة!');
      return;
    }

    const updatedList = [...currentOptionsList, trimmed];
    const updatedMap = {
      ...localOptions,
      [selectedKey]: updatedList
    };
    setLocalOptions(updatedMap);
    setNewOptionText('');
    onSaveOptions(updatedMap);
    showSuccessBanner();
  };

  const handleDeleteOption = (index: number) => {
    const itemToDelete = currentOptionsList[index];
    if (confirm(`هل أنت متأكد من حذف الخيار: "${itemToDelete}" من القائمة المنسدلة؟`)) {
      const updatedList = currentOptionsList.filter((_, i) => i !== index);
      const updatedMap = {
        ...localOptions,
        [selectedKey]: updatedList
      };
      setLocalOptions(updatedMap);
      if (editingIndex === index) {
        setEditingIndex(null);
      }
      onSaveOptions(updatedMap);
      showSuccessBanner();
    }
  };

  const handleStartEdit = (index: number, val: string) => {
    setEditingIndex(index);
    setEditingValue(val);
  };

  const handleSaveEdit = (index: number) => {
    const trimmed = editingValue.trim();
    if (!trimmed) return;
    const updatedList = [...currentOptionsList];
    updatedList[index] = trimmed;
    const updatedMap = {
      ...localOptions,
      [selectedKey]: updatedList
    };
    setLocalOptions(updatedMap);
    setEditingIndex(null);
    onSaveOptions(updatedMap);
    showSuccessBanner();
  };

  const showSuccessBanner = () => {
    setSaveSuccessMsg(true);
    setTimeout(() => setSaveSuccessMsg(false), 2500);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-slate-900/60 backdrop-blur-xs animate-in fade-in duration-200">
      <div 
        className="bg-white rounded-2xl border border-slate-200 shadow-2xl max-w-2xl w-full max-h-[92vh] flex flex-col overflow-hidden text-right"
        dir="rtl"
      >
        {/* Header */}
        <div className="bg-gradient-to-r from-slate-900 via-blue-950 to-indigo-950 text-white p-5 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-blue-500/20 border border-blue-400/30 flex items-center justify-center text-blue-300">
              <ListOrdered className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-base sm:text-lg">
                  إدارة وتعديل بيانات القوائم المنسدلة
                </h3>
                <span className="bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 text-[10px] font-bold px-2 py-0.5 rounded-md flex items-center gap-1">
                  <Lock className="w-2.5 h-2.5" />
                  <span>محمي برمز الأمان</span>
                </span>
              </div>
              <p className="text-xs text-blue-200/80 mt-0.5">
                تعديل وحذف وإضافة أسطر الخيارات لجميع خلايا أعمدة الجدول وترحيلها فوراً
              </p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-white/10 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Success Toast */}
        {saveSuccessMsg && (
          <div className="bg-emerald-600 text-white px-4 py-2 text-xs font-semibold flex items-center justify-between animate-in fade-in duration-150">
            <div className="flex items-center gap-2">
              <Check className="w-4 h-4" />
              <span>تم حفظ القائمة وترحيل التحديثات فورياً لكافة المستخدمين والمستندات!</span>
            </div>
          </div>
        )}

        {/* Modal Body */}
        <div className="p-4 sm:p-6 overflow-y-auto flex-1 space-y-5">
          {/* Column Selector Pills */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-2 flex items-center gap-1.5">
              <Layers className="w-3.5 h-3.5 text-blue-600" />
              <span>اختر العمود لتعديل خيارات القائمة المنسدلة الخاصة به:</span>
            </label>
            <div className="flex flex-wrap gap-2">
              {dropdownColumns.map(col => {
                const isSelected = col.dropdownKey === selectedKey;
                const count = (localOptions[col.dropdownKey] || []).length;
                return (
                  <button
                    key={col.id}
                    type="button"
                    onClick={() => {
                      setSelectedKey(col.dropdownKey);
                      setEditingIndex(null);
                      setNewOptionText('');
                    }}
                    className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold transition-all border ${
                      isSelected
                        ? 'bg-blue-600 text-white border-blue-600 shadow-xs'
                        : 'bg-slate-100 hover:bg-slate-200 text-slate-700 border-slate-200'
                    }`}
                  >
                    <span>{col.title}</span>
                    <span className={`px-1.5 py-0.2 rounded-full text-[10px] ${
                      isSelected ? 'bg-blue-800 text-blue-100' : 'bg-slate-200 text-slate-600'
                    }`}>
                      {count}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Add Option Form */}
          <form onSubmit={handleAddOption} className="bg-slate-50 border border-slate-200 rounded-xl p-3.5">
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-bold text-slate-800">
                إضافة سطر جديد لقائمة: {selectedColumnInfo?.title || selectedKey}
              </span>
              <span className="text-[11px] text-slate-500">
                سيظهر فورياً في القائمة المنسدلة للخلايا
              </span>
            </div>
            <div className="flex gap-2">
              <input
                type="text"
                value={newOptionText}
                onChange={(e) => setNewOptionText(e.target.value)}
                placeholder="اكتب نص الخيار الجديد هنا..."
                className="flex-1 px-3 py-2 text-xs bg-white rounded-lg border border-slate-300 focus:outline-hidden focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
              />
              <button
                type="submit"
                disabled={!newOptionText.trim()}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg text-xs font-bold transition-colors flex items-center gap-1.5 shrink-0"
              >
                <Plus className="w-3.5 h-3.5" />
                <span>إضافة سطر للقائمة</span>
              </button>
            </div>
          </form>

          {/* Options List */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-bold text-slate-700">
                الخيارات الحالية ({currentOptionsList.length} أسطر):
              </span>
              <span className="text-[11px] text-slate-400">
                يمكنك التعديل أو الحذف لأي سطر
              </span>
            </div>

            {currentOptionsList.length === 0 ? (
              <div className="p-8 text-center text-slate-400 border border-dashed border-slate-300 rounded-xl text-xs">
                لا توجد خيارات في هذه القائمة حالياً. أضف سطراً جديداً أعلاه.
              </div>
            ) : (
              <div className="space-y-2 max-h-[380px] overflow-y-auto pr-0.5">
                {currentOptionsList.map((option, idx) => (
                  <div 
                    key={idx}
                    className="flex items-center justify-between p-2.5 rounded-xl border border-slate-200 bg-white hover:border-slate-300 transition-colors gap-2"
                  >
                    {editingIndex === idx ? (
                      <div className="flex-1 flex items-center gap-2">
                        <input
                          type="text"
                          value={editingValue}
                          onChange={(e) => setEditingValue(e.target.value)}
                          autoFocus
                          className="flex-1 px-2.5 py-1 text-xs bg-slate-50 border border-blue-400 rounded-lg focus:outline-hidden"
                        />
                        <button
                          type="button"
                          onClick={() => handleSaveEdit(idx)}
                          className="p-1.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-md text-xs font-bold"
                          title="حفظ التعديل"
                        >
                          <Check className="w-3.5 h-3.5" />
                        </button>
                        <button
                          type="button"
                          onClick={() => setEditingIndex(null)}
                          className="p-1.5 bg-slate-200 hover:bg-slate-300 text-slate-700 rounded-md text-xs"
                          title="إلغاء التعديل"
                        >
                          <X className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    ) : (
                      <>
                        <div className="flex items-center gap-2 min-w-0">
                          <span className="w-5 h-5 rounded-full bg-slate-100 text-slate-500 text-[10px] font-mono font-bold flex items-center justify-center shrink-0">
                            {idx + 1}
                          </span>
                          <span className="text-xs text-slate-800 font-medium truncate" title={option}>
                            {option}
                          </span>
                        </div>

                        <div className="flex items-center gap-1 shrink-0">
                          <button
                            type="button"
                            onClick={() => handleStartEdit(idx, option)}
                            className="p-1.5 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                            title="تعديل نص الخيار"
                          >
                            <Edit2 className="w-3.5 h-3.5" />
                          </button>
                          <button
                            type="button"
                            onClick={() => handleDeleteOption(idx)}
                            className="p-1.5 text-slate-500 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
                            title="حذف هذا الخيار من القائمة"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="p-4 bg-slate-50 border-t border-slate-200 flex items-center justify-between">
          <span className="text-[11px] text-slate-500">
            تطبق التعديلات فورياً في كافة خلايا الجدول وقواعد البيانات
          </span>
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2 bg-slate-900 hover:bg-slate-800 text-white rounded-xl text-xs font-bold transition-colors"
          >
            إغلاق النافذة
          </button>
        </div>
      </div>
    </div>
  );
};

