    const emails = selectedRecipients.map(r => (r.email || '').trim()).filter(Boolean).join(';');
    const subject = encodeURIComponent(effectiveEmailSubject);
    const body = encodeURIComponent(
      `السلام عليكم ورحمة الله وبركاته\n` +
      `تحية طيبة وبعد ،،\n\n` +
      `${emailSalutation}\n\n` +
