import React from 'react';
import { X, Keyboard, Zap, Search, PlusCircle, FileSpreadsheet, FileDown, Bell, RotateCcw } from 'lucide-react';

interface KeyboardShortcutsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const KeyboardShortcutsModal: React.FC<KeyboardShortcutsModalProps> = ({ isOpen, onClose }) => {
  if (!isOpen) return null;

  const shortcuts = [
    { key: 'Ctrl + K / ⌘ + K', desc: 'فتح لوحة الأوامر السريعة والبحث الذكي الفوري', icon: <Search className="w-4 h-4 text-emerald-500" /> },
    { key: 'Alt + N', desc: 'إضافة أمر عمل جديد فورياً', icon: <PlusCircle className="w-4 h-4 text-blue-500" /> },
    { key: 'Alt + I', desc: 'استيراد أوامر العمل من ملف إكسل', icon: <FileSpreadsheet className="w-4 h-4 text-teal-500" /> },
    { key: 'Alt + E', desc: 'تصدير البيانات المعتمدة (Excel / PDF)', icon: <FileDown className="w-4 h-4 text-purple-500" /> },
    { key: 'Alt + S', desc: 'كتم أو تشغيل التنبيهات الصوتية الحية', icon: <Zap className="w-4 h-4 text-amber-500" /> },
    { key: 'Alt + B', desc: 'فتح مركز الإشعارات الفورية (الخلفية)', icon: <Bell className="w-4 h-4 text-orange-500" /> },
    { key: 'Alt + R', desc: 'المزامنة السحابية المباشرة مع الخادم', icon: <RotateCcw className="w-4 h-4 text-cyan-500" /> },
    { key: '؟ أو /', desc: 'عرض دليل اختصارات لوحة المفاتيح', icon: <Keyboard className="w-4 h-4 text-slate-500" /> },
    { key: 'Escape', desc: 'إغلاق أي نافذة منبثقة أو إلغاء التصفية', icon: <X className="w-4 h-4 text-rose-500" /> },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/70 backdrop-blur-sm animate-in fade-in duration-150 font-['Cairo',sans-serif]">
      <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 max-w-lg w-full overflow-hidden text-right">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-slate-100 bg-slate-50">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl bg-emerald-100 text-emerald-700 flex items-center justify-center">
              <Keyboard className="w-5 h-5" />
            </div>
            <div>
              <h3 className="font-black text-sm text-slate-900">اختصارات لوحة المفاتيح الذكية</h3>
              <p className="text-[11px] text-slate-500">لإنجاز العمل والتدقيق بأقصى سرعة واحترافية</p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-slate-200 transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Content list */}
        <div className="p-4 space-y-2 max-h-[65vh] overflow-y-auto">
          {shortcuts.map((s, idx) => (
            <div
              key={idx}
              className="flex items-center justify-between p-2.5 rounded-xl bg-slate-50 border border-slate-200/60 hover:border-slate-300 transition-colors"
            >
              <div className="flex items-center gap-2.5 min-w-0">
                <div className="p-1.5 rounded-lg bg-white shadow-2xs shrink-0">
                  {s.icon}
                </div>
                <span className="text-xs font-bold text-slate-800 truncate">{s.desc}</span>
              </div>
              <kbd className="px-2.5 py-1 rounded-lg bg-white border border-slate-300 text-slate-700 font-mono text-[11px] font-bold shadow-2xs shrink-0">
                {s.key}
              </kbd>
            </div>
          ))}
        </div>

        {/* Footer */}
        <div className="px-5 py-3 border-t border-slate-100 bg-slate-50 flex items-center justify-between text-xs text-slate-500">
          <span>يمكنك الضغط على <strong>؟</strong> في أي وقت لعرض هذه القائمة</span>
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-1.5 rounded-xl bg-slate-900 text-white font-bold hover:bg-slate-800 transition-colors"
          >
            إغلاق
          </button>
        </div>
      </div>
    </div>
  );
};

src/components/LoginScreen.tsx:
import React, { useState, useEffect } from 'react';
import {
  ShieldCheck,
  User,
  Lock,
  Eye,
  EyeOff,
  LogIn,
  AlertCircle,
  Radio,
  KeyRound
} from 'lucide-react';
import { PlatformUser } from '../types';
import {
  ensureDefaultSuperAdmins,
  saveSessionToken
} from '../utils/security';
import { SyncStatus, realtime } from '../services/realtimeService';
import { vaultService } from '../services/vaultService';

interface LoginScreenProps {
  onLoginSuccess: (user: PlatformUser, allUsers?: PlatformUser[]) => void;
  users?: PlatformUser[];
  syncStatus?: SyncStatus;
  onlineCount?: number;
  isConnected?: boolean;
}

export const LoginScreen: React.FC<LoginScreenProps> = ({
  onLoginSuccess,
  users = [],
  syncStatus = 'connected',
  onlineCount = 1,
  isConnected
}) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [, setLatestUsers] = useState<PlatformUser[]>(() => {
    const vaultUsers = vaultService.getSavedUsers();
    if (Array.isArray(vaultUsers) && vaultUsers.length > 0) {
      return ensureDefaultSuperAdmins(vaultUsers);
    }
    return ensureDefaultSuperAdmins(users);
  });

  useEffect(() => {
    setUsername('');
    setPassword('');
    setErrorMsg(null);

    // Fetch latest registered users from server on login screen mount
    realtime.fetchUsers().then((fetched) => {
      if (Array.isArray(fetched) && fetched.length > 0) {
        setLatestUsers(ensureDefaultSuperAdmins(fetched));
      }
    }).catch(() => {});

    // Subscribe to real-time user updates while on the login screen
    const unsubscribe = realtime.subscribe((evt) => {
      if (evt.type === 'UPDATE_USERS' && Array.isArray(evt.payload?.users)) {
        const updated = ensureDefaultSuperAdmins(evt.payload.users);
        vaultService.saveUsers(updated);
        setLatestUsers(updated);
      } else if (evt.type === 'SYNC_ALL' && Array.isArray(evt.payload?.users)) {
        const updated = ensureDefaultSuperAdmins(evt.payload.users);
        vaultService.saveUsers(updated);
        setLatestUsers(updated);
      }
    });

    return () => {
      unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (Array.isArray(users) && users.length > 0) {
      setLatestUsers(ensureDefaultSuperAdmins(users));
    }
  }, [users]);

  const effectiveSyncStatus: SyncStatus = (syncStatus || (isConnected ? 'connected' : 'connecting')) as SyncStatus;

  const normalizeDigitsAndTrim = (val: string): string =>
    String(val || '')
      .replace(/[\u200B-\u200D\uFEFF\u200E\u200F]/g, '')
      .replace(/[٠-٩]/g, (d) => String(d.charCodeAt(0) - 0x0660))
      .replace(/[۰-۹]/g, (d) => String(d.charCodeAt(0) - 0x06f0))
      .trim();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);

    const cleanUser = normalizeDigitsAndTrim(username);
    const cleanPass = normalizeDigitsAndTrim(password);

    if (!cleanUser) {
      setErrorMsg('يرجى إدخال اسم المستخدم أو البريد الإلكتروني (User / Email)');
      return;
    }
    if (!cleanPass) {
      setErrorMsg('يرجى إدخال كلمة المرور (Password)');
      return;
    }

    setIsLoading(true);
    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          username: cleanUser,
          password: cleanPass
        })
      });

      if (res.ok) {
        const data = await res.json();
        if (data.success && data.user) {
          const receivedToken = data.sessionToken || data.token;
          if (receivedToken) {
            saveSessionToken(receivedToken);
          }
          if (Array.isArray(data.users)) {
            vaultService.saveUsers(data.users);
          }
          realtime.reconnectWithAuth();
          onLoginSuccess(data.user, data.users);
          return;
        }
      } else {
        const errJson = await res.json().catch(() => ({}));
        if (errJson?.error) {
          setErrorMsg(errJson.error);
          return;
        }
      }

      setErrorMsg('اسم المستخدم أو كلمة المرور غير صحيحة. يرجى التأكد من البيانات أو مراجعة مسؤول الصلاحيات.');
    } catch {
      setErrorMsg('تعذر الاتصال بخادم المصادقة المعتمد. يرجى التحقق من الاتصال بالشبكة والمحاولة مرة أخرى.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div
      className="min-h-screen w-full bg-slate-950 text-white flex flex-col justify-between relative overflow-hidden font-['Cairo',sans-serif]"
      dir="rtl"
    >
      <div className="pointer-events-none fixed inset-0 overflow-hidden">
        <div className="absolute -top-40 -right-40 w-96 h-96 rounded-full bg-emerald-600/15 blur-3xl" />
        <div className="absolute top-1/3 -left-40 w-96 h-96 rounded-full bg-blue-600/15 blur-3xl" />
        <div className="absolute -bottom-40 right-1/3 w-96 h-96 rounded-full bg-indigo-600/15 blur-3xl" />
      </div>

      <header className="relative z-10 w-full border-b border-slate-800/80 bg-slate-900/70 backdrop-blur-md px-4 sm:px-8 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-emerald-600 to-teal-800 border border-emerald-400/40 flex items-center justify-center shadow-md">
            <ShieldCheck className="w-5 h-5 text-amber-300" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-sm sm:text-base font-black text-white tracking-wide">
                حوكمة جودة اعمال الانشاءات
              </h1>
              <span className="px-2 py-0.5 rounded-md bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 text-[10px] font-black">
                إجراء 155
              </span>
            </div>
            <p className="text-[11px] text-slate-400">
              بوابة الدخول الموحدة ونظام إدارة الصلاحيات والمزامنة الفورية
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-xl bg-slate-950/90 border border-slate-800 text-xs">
            <Radio
              className={`w-3.5 h-3.5 ${
                effectiveSyncStatus === 'connected' ? 'text-emerald-400 animate-pulse' : 'text-amber-400'
              }`}
            />
            <span className="text-slate-300 font-bold text-[11px]">
              {effectiveSyncStatus === 'connected' ? 'المزامنة الفورية متصلة' : 'جاري الاتصال بالسحابة...'}
            </span>
            <span className="px-1.5 py-0.5 rounded bg-emerald-500/15 text-emerald-300 font-mono text-[10px] font-bold">
              {onlineCount} متصل
            </span>
          </div>
        </div>
      </header>

      <main className="relative z-10 flex-1 flex items-center justify-center p-4 sm:p-6">
        <div className="w-full max-w-md bg-slate-900/95 border border-slate-800 rounded-3xl shadow-2xl overflow-hidden backdrop-blur-xl">
          <div className="bg-gradient-to-l from-emerald-950 via-slate-900 to-indigo-950 p-6 sm:p-7 border-b border-slate-800 text-center relative">
            <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-emerald-500 to-teal-700 border-2 border-emerald-300/40 flex items-center justify-center mx-auto mb-3 shadow-lg shadow-emerald-950/60">
              <KeyRound className="w-8 h-8 text-white" />
            </div>
            <h2 className="text-lg sm:text-xl font-black text-white">
              تسجيل الدخول إلى المنصة
            </h2>
            <p className="text-xs text-slate-300 font-medium mt-1">
              أدخل اسم المستخدم وكلمة المرور للمتابعة
            </p>
          </div>

          <form onSubmit={handleSubmit} className="p-6 sm:p-7 space-y-4">
            {errorMsg && (
              <div className="p-3.5 rounded-2xl bg-rose-950/70 border border-rose-500/50 text-rose-200 text-xs font-bold flex items-start gap-2.5 animate-in fade-in duration-150">
                <AlertCircle className="w-4 h-4 text-rose-400 shrink-0 mt-0.5" />
                <span>{errorMsg}</span>
              </div>
            )}

            <div className="space-y-1.5">
              <label className="block text-xs font-black text-slate-200">
                اسم المستخدم أو البريد الإلكتروني (User / Email)
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 right-0 pr-3.5 flex items-center pointer-events-none text-slate-400">
                  <User className="w-4 h-4 text-emerald-400" />
                </div>
                <input
                  type="text"
                  name="user_login_credential_id"
                  value={username}
                  onChange={(e) => {
                    setUsername(e.target.value);
                    if (errorMsg) setErrorMsg(null);
                  }}
                  placeholder="أدخل اسم المستخدم أو البريد الإلكتروني"
                  autoFocus
                  autoComplete="off"
                  data-lpignore="true"
                  dir="ltr"
                  className="w-full pr-10 pl-4 py-3 rounded-xl bg-slate-950 border border-slate-700 focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 text-white font-bold text-sm text-right placeholder:text-slate-500 outline-none transition-all"
                />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="block text-xs font-black text-slate-200">
                كلمة المرور (Password)
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 right-0 pr-3.5 flex items-center pointer-events-none text-slate-400">
                  <Lock className="w-4 h-4 text-amber-400" />
                </div>
                <input
                  type={showPassword ? 'text' : 'password'}
                  name="user_password_credential_secret"
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value);
                    if (errorMsg) setErrorMsg(null);
                  }}
                  placeholder="أدخل كلمة المرور"
                  autoComplete="new-password"
                  data-lpignore="true"
                  dir="ltr"
                  className="w-full pr-10 pl-11 py-3 rounded-xl bg-slate-950 border border-slate-700 focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20 text-white font-bold text-sm text-right placeholder:text-slate-500 outline-none transition-all"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute inset-y-0 left-0 pl-3.5 flex items-center text-slate-400 hover:text-white cursor-pointer"
                  tabIndex={-1}
                >
                  {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-3.5 px-4 rounded-xl bg-gradient-to-r from-emerald-600 via-teal-600 to-emerald-700 hover:from-emerald-500 hover:to-teal-500 text-white font-black text-sm shadow-lg shadow-emerald-950/60 border border-emerald-400/30 flex items-center justify-center gap-2 transition-all cursor-pointer active:scale-98 disabled:opacity-50 mt-2"
            >
              <LogIn className="w-4 h-4" />
              <span>{isLoading ? 'جاري التحقق والدخول...' : 'تسجيل الدخول للمنصة'}</span>
            </button>
          </form>
        </div>
      </main>

      <footer className="relative z-10 w-full border-t border-slate-800/80 bg-slate-950/80 py-3 px-6 text-center text-[11px] text-slate-400 flex flex-col sm:flex-row items-center justify-between gap-2">
        <span>إدارة كهرباء الحدود الشمالية • المساندة الفنية</span>
        <span className="font-mono text-slate-500">حوكمة جودة أعمال الإنشاءات • إجراء 155</span>
      </footer>
    </div>
  );
};

src/components/MainSectionsRow.tsx:
import React from 'react';
import {
  BarChart3,
  FolderTree,
  TableProperties,
  Building2,
  Table2,
  ChevronDown,
  X,
  Layers,
  Award,
  FileText
} from 'lucide-react';
import { MonthTable, PlatformUser } from '../types';

export type ActiveSectionCardId = 'kpis' | 'tree' | 'month_tables' | 'office' | 'hub' | null;

interface MainSectionsRowProps {
  activeSectionCard: ActiveSectionCardId;
  onToggleSectionCard: (cardId: ActiveSectionCardId) => void;
  // Stats & Period
  totalOrdersCount: number;
  ready155Count: number;
  readyRate: number;
  activeYear: number;
  activeMonth: number | 'all';
  activeTableName?: string;
  selectedOffice: string;
  offices: Array<{ id: string; name: string }>;
  monthTables: MonthTable[];
  isTableCardOpen: boolean;
  tablePresentationMode: 'docked' | 'overlay';
  onToggleTableCard: () => void;
  onChangeTablePresentationMode: (mode: 'docked' | 'overlay') => void;
  onSelectOffice: (office: string) => void;
  // Quick Actions
  onOpenSmartAudit?: () => void;
  onOpenContractorComparison?: () => void;
  onOpenWeeklyReport?: () => void;
  onOpenOfficeComparison?: () => void;
  onOpenComprehensiveReports?: () => void;
  onOpenCommandPalette?: () => void;
  onOpenAddOrder?: () => void;
  onOpenImportExcel?: () => void;
  onOpenCompatibleImport?: () => void;
  onOpenNotesReport?: (mode?: 'all' | 'recurring_all' | 'recurring_contractor', contractor?: string) => void;
  contractorsList?: string[];
  currentUser?: PlatformUser | null;
}

export const MainSectionsRow: React.FC<MainSectionsRowProps> = ({
  activeSectionCard,
  onToggleSectionCard,
  readyRate,
  activeYear,
  activeMonth,
  selectedOffice,
  offices,
  monthTables,
  isTableCardOpen,
  onToggleTableCard,
  onSelectOffice,
  onOpenContractorComparison,
  onOpenWeeklyReport,
  onOpenOfficeComparison,
  onOpenComprehensiveReports,
  onOpenNotesReport,
}) => {
  const customMonthTablesCount = monthTables.filter(
    t => !t.id.startsWith('default-') && !t.isDefault && t.year === activeYear && (activeMonth === 'all' || t.month === activeMonth)
  ).length;
  const currentMonthTablesCount = customMonthTablesCount + 1;

  return (
    <div className="w-full mb-3 select-none font-['Cairo',sans-serif]">
      <div className="w-full bg-gradient-to-l from-slate-100 via-blue-50/75 to-indigo-50/75 backdrop-blur-md rounded-2xl p-1.5 sm:p-2 border border-slate-300/90 shadow-xs flex items-center justify-between gap-1.5 sm:gap-2 overflow-x-auto scrollbar-none">
        <div className="flex items-center gap-1.5 sm:gap-2 flex-nowrap">
          <button
            type="button"
            onClick={() => onToggleSectionCard(activeSectionCard === 'kpis' ? null : 'kpis')}
            className={`h-10 px-2.5 sm:px-3 rounded-xl flex items-center gap-2 transition-all cursor-pointer border whitespace-nowrap active:scale-95 group ${
              activeSectionCard === 'kpis'
                ? 'bg-gradient-to-l from-blue-700 to-indigo-800 text-white border-blue-800 shadow-sm ring-2 ring-blue-400/50'
                : 'bg-gradient-to-l from-slate-50 to-blue-100/60 hover:from-blue-100/80 hover:to-indigo-100/70 text-slate-900 border-blue-300'
            }`}
            title="لوحة مؤشرات الأداء والقياس (KPI Dashboard)"
          >
            <div className={`w-6 h-6 rounded-lg flex items-center justify-center shrink-0 transition-transform group-hover:scale-110 ${
              activeSectionCard === 'kpis' ? 'bg-white/20 text-white' : 'bg-blue-200/80 text-blue-900'
            }`}>
              <BarChart3 className="w-3.5 h-3.5" />
            </div>
            <div className="text-right flex items-center gap-1.5">
              <span className="text-xs font-black">مؤشرات الأداء</span>
              <span className={`text-[10px] font-mono font-black px-1.5 py-0.2 rounded-md ${
                activeSectionCard === 'kpis' ? 'bg-black/25 text-amber-200' : 'bg-blue-200/80 text-blue-950 border border-blue-300'
              }`}>
                {readyRate}%
              </span>
            </div>
            <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-200 ${
              activeSectionCard === 'kpis' ? 'rotate-180 text-white' : 'text-blue-800'
            }`} />
          </button>

          <button
            type="button"
            onClick={() => onToggleSectionCard(activeSectionCard === 'month_tables' ? null : 'month_tables')}
            className={`h-10 px-2.5 sm:px-3 rounded-xl flex items-center gap-2 transition-all cursor-pointer border whitespace-nowrap active:scale-95 group ${
              activeSectionCard === 'month_tables'
                ? 'bg-gradient-to-l from-emerald-700 to-teal-800 text-white border-emerald-800 shadow-sm ring-2 ring-emerald-400/50'
                : 'bg-gradient-to-l from-slate-50 to-emerald-100/60 hover:from-emerald-100/80 hover:to-teal-100/70 text-slate-900 border-emerald-300'
            }`}
            title="قائمة جداول أوامر العمل الميدانية (عرض مبسط ومتزامن في سطرين)"
          >
            <div className={`relative w-6 h-6 rounded-lg flex items-center justify-center shrink-0 transition-transform group-hover:scale-110 ${
              activeSectionCard === 'month_tables' ? 'bg-white/20 text-white' : 'bg-emerald-600 text-white shadow-2xs'
            }`}>
              <TableProperties className="w-3.5 h-3.5" />
              <span className="absolute -top-0.5 -right-0.5 w-2 h-2 rounded-full bg-amber-400 ring-1 ring-white" />
            </div>
            <div className="text-right flex items-center gap-1.5">
              <span className="text-xs font-black">جداول أوامر العمل</span>
              <span className={`text-[10px] font-mono font-black px-1.5 py-0.2 rounded-md ${
                activeSectionCard === 'month_tables' ? 'bg-black/25 text-emerald-100' : 'bg-emerald-200/80 text-emerald-950 border border-emerald-300'
              }`}>
                {currentMonthTablesCount} جدول
              </span>
            </div>
            <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-200 ${
              activeSectionCard === 'month_tables' ? 'rotate-180 text-white' : 'text-emerald-800'
            }`} />
          </button>

          <button
            type="button"
            onClick={() => onToggleSectionCard(activeSectionCard === 'office' ? null : 'office')}
            className={`h-10 px-2.5 sm:px-3 rounded-xl flex items-center gap-2 transition-all cursor-pointer border whitespace-nowrap active:scale-95 group ${
              activeSectionCard === 'office'
                ? 'bg-gradient-to-l from-sky-700 to-blue-800 text-white border-sky-800 shadow-sm ring-2 ring-sky-400/50'
                : 'bg-gradient-to-l from-slate-50 to-sky-100/60 hover:from-sky-100/80 hover:to-blue-100/70 text-slate-900 border-sky-300'
            }`}
            title="تحديد نطاق المكتب الفرعي لتصفية أوامر العمل"
          >
            <div className={`w-6 h-6 rounded-lg flex items-center justify-center shrink-0 transition-transform group-hover:scale-110 ${
              activeSectionCard === 'office' ? 'bg-white/20 text-white' : 'bg-sky-200/80 text-sky-900'
            }`}>
              <Building2 className="w-3.5 h-3.5" />
            </div>
            <div className="text-right flex items-center gap-1.5">
              <span className="text-xs font-black">
                {selectedOffice === 'all' ? 'كافة المكاتب' : selectedOffice}
              </span>
            </div>
            <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-200 ${
              activeSectionCard === 'office' ? 'rotate-180 text-white' : 'text-sky-800'
            }`} />
          </button>

          <button
            type="button"
            onClick={() => onToggleSectionCard(activeSectionCard === 'hub' ? null : 'hub')}
            className={`h-10 px-2.5 sm:px-3 rounded-xl flex items-center gap-2 transition-all cursor-pointer border whitespace-nowrap active:scale-95 group ${
              activeSectionCard === 'hub'
                ? 'bg-gradient-to-l from-teal-700 to-emerald-800 text-white border-teal-800 shadow-sm ring-2 ring-teal-400/50'
                : 'bg-gradient-to-l from-slate-50 to-teal-100/60 hover:from-teal-100/80 hover:to-emerald-100/70 text-slate-900 border-teal-300'
            }`}
            title="التقارير الأسبوعية ومقارنة المقاولين والمكاتب"
          >
            <div className={`w-6 h-6 rounded-lg flex items-center justify-center shrink-0 transition-transform group-hover:scale-110 ${
              activeSectionCard === 'hub' ? 'bg-white/20 text-white' : 'bg-teal-200/80 text-teal-900'
            }`}>
              <BarChart3 className="w-3.5 h-3.5" />
            </div>
            <div className="text-right flex items-center gap-1.5">
              <span className="text-xs font-black">الحوكمة والتقارير</span>
            </div>
            <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-200 ${
              activeSectionCard === 'hub' ? 'rotate-180 text-white' : 'text-teal-800'
            }`} />
          </button>
        </div>

        <div className="flex items-center gap-1.5 shrink-0">
          <button
            type="button"
            onClick={onToggleTableCard}
            className={`h-10 px-3 rounded-xl flex items-center gap-1.5 text-xs font-black border transition-all cursor-pointer active:scale-95 ${
              isTableCardOpen
                ? 'bg-gradient-to-l from-emerald-700 to-teal-800 text-white border-emerald-800 shadow-sm ring-2 ring-emerald-400/50'
                : 'bg-gradient-to-l from-slate-50 to-emerald-100/70 hover:from-emerald-100 hover:to-teal-100 text-slate-900 border-emerald-300'
            }`}
            title={isTableCardOpen ? 'طي وإخفاء بطاقة الجدول' : 'عرض وإظهار بطاقة الجدول'}
          >
            <Table2 className={`w-4 h-4 ${isTableCardOpen ? 'text-amber-300' : 'text-emerald-800'}`} />
            <span>{isTableCardOpen ? 'طي الجدول' : 'عرض الجدول'}</span>
          </button>
        </div>
      </div>

      {activeSectionCard === 'office' && (
        <div className="mt-2.5 p-4 bg-white rounded-2xl shadow-xl border border-slate-200/90 animate-in fade-in zoom-in-95 duration-150 text-right">
          <div className="flex items-center justify-between pb-3 mb-3 border-b border-slate-100">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 rounded-xl bg-blue-100 text-blue-700 border border-blue-200 flex items-center justify-center shrink-0">
                <Building2 className="w-4 h-4" />
              </div>
              <div>
                <h4 className="text-xs sm:text-sm font-black text-slate-900">تحديد نطاق المكتب الفرعي</h4>
                <p className="text-[11px] text-slate-500">اختر المكتب الفرعي لتصفية الجدول وعرض الإحصائيات والمؤشرات الخاصة به</p>
              </div>
            </div>
            <button
              type="button"
              onClick={() => onToggleSectionCard(null)}
              className="p-1.5 rounded-xl text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-colors cursor-pointer"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 gap-2">
            <button
              type="button"
              onClick={() => {
