                className={`p-2.5 rounded-xl border text-xs font-black transition-all cursor-pointer flex flex-col items-center justify-center gap-1 ${
                  selectedOffice === off.name
                    ? 'bg-gradient-to-br from-blue-600 to-indigo-700 text-white border-blue-400 shadow-md'
                    : 'bg-slate-50 text-slate-800 border-slate-200 hover:bg-blue-50 hover:border-blue-300'
                }`}
              >
                <span className="truncate w-full text-center">{off.name}</span>
              </button>
            ))}
          </div>
        </div>
      )}

      {activeSectionCard === 'hub' && (
        <div className="mt-2.5 p-4 bg-white rounded-2xl shadow-xl border border-slate-200/90 animate-in fade-in zoom-in-95 duration-150 text-right">
          <div className="flex items-center justify-between pb-3 mb-3 border-b border-slate-100">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 rounded-xl bg-emerald-100 text-emerald-700 border border-emerald-200 flex items-center justify-center shrink-0">
                <BarChart3 className="w-4 h-4" />
              </div>
              <div>
                <h4 className="text-xs sm:text-sm font-black text-slate-900">مركز الحوكمة والتقارير الرسمية</h4>
                <p className="text-[11px] text-slate-500">المقارنات والتقارير التنفيذية المعتمدة للتحليل والإغلاقات</p>
              </div>
            </div>
            <button
              type="button"
              onClick={() => onToggleSectionCard(null)}
              className="p-1.5 rounded-xl text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-colors cursor-pointer"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-5 gap-2">
            {onOpenComprehensiveReports && (
              <button
                type="button"
                onClick={() => {
                  onToggleSectionCard(null);
                  onOpenComprehensiveReports();
                }}
                className="p-3 rounded-xl bg-gradient-to-r from-indigo-600 to-blue-700 hover:from-indigo-500 hover:to-blue-600 border border-indigo-400/50 text-white font-black text-xs flex items-center gap-2.5 cursor-pointer transition-all shadow-sm"
              >
                <BarChart3 className="w-4 h-4 text-amber-300 shrink-0" />
                <div className="font-black text-xs text-white text-right">مركز التقارير الشامل</div>
              </button>
            )}

            {onOpenWeeklyReport && (
              <button
                type="button"
                onClick={() => {
                  onToggleSectionCard(null);
                  onOpenWeeklyReport();
                }}
                className="p-3 rounded-xl bg-slate-50 hover:bg-blue-50 border border-slate-200 hover:border-blue-300 text-slate-900 font-black text-xs flex items-center gap-2.5 cursor-pointer transition-all"
              >
                <Award className="w-4 h-4 text-blue-600 shrink-0" />
                <div className="font-black text-xs text-slate-900 text-right">التقرير الأسبوعي</div>
              </button>
            )}

            {onOpenContractorComparison && (
              <button
                type="button"
                onClick={() => {
                  onToggleSectionCard(null);
                  onOpenContractorComparison();
                }}
                className="p-3 rounded-xl bg-slate-50 hover:bg-indigo-50 border border-slate-200 hover:border-indigo-300 text-slate-900 font-black text-xs flex items-center gap-2.5 cursor-pointer transition-all"
              >
                <Layers className="w-4 h-4 text-indigo-600 shrink-0" />
                <div className="font-black text-xs text-slate-900 text-right">مقارنة المقاولين</div>
              </button>
            )}

            {onOpenOfficeComparison && (
              <button
                type="button"
                onClick={() => {
                  onToggleSectionCard(null);
                  onOpenOfficeComparison();
                }}
                className="p-3 rounded-xl bg-slate-50 hover:bg-emerald-50 border border-slate-200 hover:border-emerald-300 text-slate-900 font-black text-xs flex items-center gap-2.5 cursor-pointer transition-all"
              >
                <Building2 className="w-4 h-4 text-emerald-600 shrink-0" />
                <div className="font-black text-xs text-slate-900 text-right">مقارنة المكاتب</div>
              </button>
            )}

            {onOpenNotesReport && (
              <button
                type="button"
                onClick={() => {
                  onToggleSectionCard(null);
                  onOpenNotesReport('all');
                }}
                className="p-3 rounded-xl bg-slate-50 hover:bg-rose-50 border border-slate-200 hover:border-rose-300 text-slate-900 font-black text-xs flex items-center gap-2.5 cursor-pointer transition-all"
              >
                <FileText className="w-4 h-4 text-rose-600 shrink-0" />
                <div className="font-black text-xs text-slate-900 text-right">تقرير الملاحظات الشامل</div>
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

src/components/ManageContractorsModal.ts:
import React, { useState } from 'react';
import { 
  Briefcase, 
  Building2, 
  Plus, 
  Trash2, 
  X, 
  Check, 
  Sparkles, 
  CheckCircle2
} from 'lucide-react';
import { SubOffice, DropdownOptionsMap } from '../types';
import { getContractorsForOffice, getConsultantsForOffice } from '../services/contractorService';

interface ManageContractorsModalProps {
  isOpen: boolean;
  onClose: () => void;
  offices: SubOffice[];
  dropdownOptions?: DropdownOptionsMap;
  onUpdateOfficeContractors: (officeName: string, contractors: string[]) => Promise<void> | void;
  onUpdateOfficeConsultants?: (officeName: string, consultants: string[]) => Promise<void> | void;
  selectedOfficeDefault?: string;
}

export const ManageContractorsModal: React.FC<ManageContractorsModalProps> = ({
  isOpen,
  onClose,
  offices,
  dropdownOptions,
  onUpdateOfficeContractors,
  onUpdateOfficeConsultants,
  selectedOfficeDefault
}) => {
  const [activeOffice, setActiveOffice] = useState<string>(() => {
    if (selectedOfficeDefault && selectedOfficeDefault !== 'all') {
      return selectedOfficeDefault;
    }
    return offices[0]?.name || 'مكتب عرعر';
  });
  const [activeEntityTab, setActiveEntityTab] = useState<'contractor' | 'consultant'>('contractor');

  const [newItemName, setNewItemName] = useState('');
  const [successToast, setSuccessToast] = useState<string | null>(null);

  React.useEffect(() => {
    if (isOpen) {
      if (selectedOfficeDefault && selectedOfficeDefault !== 'all') {
        setActiveOffice(selectedOfficeDefault);
      } else if (!offices.some(o => o.name === activeOffice)) {
        setActiveOffice(offices[0]?.name || 'مكتب عرعر');
      }
      setNewItemName('');
    }
  }, [isOpen, selectedOfficeDefault, offices]);

  if (!isOpen) return null;

  const isConsultant = activeEntityTab === 'consultant';
  const entityNoun = isConsultant ? 'الاستشاري' : 'المقاول';
  const entityPlural = isConsultant ? 'الاستشاريون' : 'المقاولون';

  const currentItems = isConsultant
    ? getConsultantsForOffice(activeOffice, dropdownOptions?.officeConsultants, offices)
    : getContractorsForOffice(activeOffice, dropdownOptions?.officeContractors, offices);

  const triggerToast = (msg: string) => {
    setSuccessToast(msg);
    setTimeout(() => setSuccessToast(null), 2500);
  };

  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = newItemName.trim();
    if (!trimmed) return;

    if (currentItems.includes(trimmed)) {
      triggerToast(`${entityNoun} "${trimmed}" مسجل بالفعل في مكتب ${activeOffice}`);
      return;
    }

    const updated = [...currentItems, trimmed];
    if (isConsultant && onUpdateOfficeConsultants) {
      await onUpdateOfficeConsultants(activeOffice, updated);
    } else if (!isConsultant) {
      await onUpdateOfficeContractors(activeOffice, updated);
    }
    setNewItemName('');
    triggerToast(`تمت إضافة ${entityNoun} "${trimmed}" لمكتب ${activeOffice} بنجاح`);
  };

  const handleDeleteItem = async (itemName: string) => {
    const confirmed = window.confirm(
      `هل أنت متأكد من حذف ${entityNoun} "${itemName}" من قائمة ${activeOffice}؟`
    );
    if (!confirmed) return;

    const updated = currentItems.filter(c => c !== itemName);
    if (isConsultant && onUpdateOfficeConsultants) {
      await onUpdateOfficeConsultants(activeOffice, updated);
    } else if (!isConsultant) {
      await onUpdateOfficeContractors(activeOffice, updated);
    }
    triggerToast(`تم حذف ${entityNoun} "${itemName}" من مكتب ${activeOffice}`);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-slate-900/60 backdrop-blur-xs animate-in fade-in duration-200">
      <div 
        className="bg-white rounded-2xl border border-slate-200 shadow-2xl max-w-2xl w-full max-h-[92vh] flex flex-col overflow-hidden text-right"
        dir="rtl"
      >
        {/* Header */}
        <div className="bg-gradient-to-r from-slate-900 via-blue-950 to-indigo-950 text-white p-5 flex items-center justify-between shrink-0 border-b border-slate-800">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center text-white shadow-xs">
              <Briefcase className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-base sm:text-lg">
                  إدارة وتوزيع مقاولي واستشاريي المكاتب الفرعية
                </h3>
                <span className="bg-blue-500/20 text-blue-300 border border-blue-400/30 text-[10px] font-bold px-2 py-0.5 rounded-md flex items-center gap-1">
                  <Sparkles className="w-3 h-3 text-blue-400" />
                  ربط تلقائي وذكي
                </span>
              </div>
              <p className="text-xs text-blue-200/80 mt-0.5">
                تخصيص قوائم المقاولين والاستشاريين لكل مكتب عند إضافة أو تعديل صف بالجدول
              </p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-300 hover:text-white hover:bg-white/10 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Entity Switcher Tabs (المقاولون / الاستشاريون) */}
        <div className="bg-slate-100 px-5 pt-3 border-b border-slate-200 flex items-center gap-2">
          <button
            type="button"
            onClick={() => setActiveEntityTab('contractor')}
            className={`px-4 py-2 rounded-t-xl text-xs font-black transition-all cursor-pointer border-b-2 ${
              activeEntityTab === 'contractor'
                ? 'bg-white text-blue-700 border-blue-600 shadow-2xs'
                : 'text-slate-600 hover:text-slate-900 border-transparent'
            }`}
          >
            إدارة المقاولين (عمود المقاول)
          </button>
          <button
            type="button"
            onClick={() => setActiveEntityTab('consultant')}
            className={`px-4 py-2 rounded-t-xl text-xs font-black transition-all cursor-pointer border-b-2 ${
              activeEntityTab === 'consultant'
                ? 'bg-white text-indigo-700 border-indigo-600 shadow-2xs'
                : 'text-slate-600 hover:text-slate-900 border-transparent'
            }`}
          >
            إدارة الاستشاريين (عمود الاستشاري)
          </button>
        </div>

        {/* Success Toast */}
        {successToast && (
          <div className="bg-emerald-600 text-white px-4 py-2 text-xs font-semibold flex items-center gap-2 animate-in fade-in">
            <Check className="w-4 h-4 shrink-0" />
            <span>{successToast}</span>
          </div>
        )}

        {/* Body */}
        <div className="p-4 sm:p-6 overflow-y-auto flex-1 space-y-5">
          {/* Office Selection Tabs */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-2 flex items-center gap-1.5">
              <Building2 className="w-3.5 h-3.5 text-blue-600" />
              <span>اختر المكتب الفرعي لعرض وتعديل قائمة {isConsultant ? 'استشارييه' : 'مقاوليه'} المعتمدين:</span>
            </label>
            <div className="flex flex-wrap gap-2">
              {offices.map(off => {
                const isSelected = off.name === activeOffice;
                const itemsList = isConsultant
                  ? getConsultantsForOffice(off.name, dropdownOptions?.officeConsultants, offices)
                  : getContractorsForOffice(off.name, dropdownOptions?.officeContractors, offices);
                return (
                  <button
                    key={off.id}
                    type="button"
                    onClick={() => setActiveOffice(off.name)}
                    className={`inline-flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs font-bold transition-all border ${
                      isSelected
                        ? 'bg-blue-600 text-white border-blue-600 shadow-xs ring-2 ring-blue-300/40'
                        : 'bg-slate-100 hover:bg-slate-200 text-slate-700 border-slate-200'
                    }`}
                  >
                    <Building2 className="w-3.5 h-3.5" />
                    <span>{off.name}</span>
                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-mono ${
                      isSelected ? 'bg-blue-800 text-blue-100' : 'bg-slate-200 text-slate-600'
                    }`}>
                      {itemsList.length}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Add Contractor/Consultant Form for Active Office */}
          <form onSubmit={handleAddItem} className="bg-blue-50/60 border border-blue-200 rounded-xl p-4 space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-xs font-bold text-blue-900 flex items-center gap-1.5">
                <Plus className="w-4 h-4 text-blue-600" />
                إضافة {isConsultant ? 'استشاري' : 'مقاول'} جديد إلى: <span className="text-blue-700 font-extrabold">{activeOffice}</span>
              </span>
              <span className="text-[11px] text-blue-600">
                سيتزامن فورياً بالقائمة المنسدلة وكافة الأقسام
              </span>
            </div>

            <div className="flex gap-2">
              <input
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                placeholder={`اكتب اسم ${entityNoun} المراد إلحاقه بـ ${activeOffice}...`}
                className="flex-1 px-3.5 py-2.5 text-xs font-bold bg-white rounded-lg border border-blue-300 focus:outline-hidden focus:border-blue-500 focus:ring-1 focus:ring-blue-500 shadow-2xs"
              />
              <button
                type="submit"
                disabled={!newItemName.trim()}
                className="px-4 py-2.5 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg text-xs font-bold transition-colors flex items-center gap-1.5 shrink-0 shadow-2xs cursor-pointer"
              >
                <Plus className="w-4 h-4" />
                <span>+ إضافة {entityNoun}</span>
              </button>
            </div>
          </form>

          {/* Current Office Items Cards/Badges */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-bold text-slate-800 flex items-center gap-1.5">
                <Briefcase className="w-4 h-4 text-blue-600" />
                {entityPlural} المعتمدون في {activeOffice} ({currentItems.length}):
              </span>
              <span className="text-[11px] text-slate-400">
                اضغط على زر (حذف) لإزالة أي عنصر
              </span>
            </div>

            {currentItems.length === 0 ? (
              <div className="p-8 text-center text-slate-400 border border-dashed border-slate-300 rounded-xl text-xs bg-slate-50/50">
                لا يوجد {entityPlural} مسجلون لمكتب {activeOffice} حالياً. أضف من الحقل أعلاه.
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-[300px] overflow-y-auto p-1">
                {currentItems.map((c, idx) => (
                  <div
                    key={c}
                    className="flex items-center justify-between p-3 rounded-xl border border-slate-200 bg-white hover:border-blue-300 transition-colors shadow-2xs"
                  >
                    <div className="flex items-center gap-2.5 min-w-0">
                      <span className="w-6 h-6 rounded-lg bg-blue-50 text-blue-700 text-xs font-bold flex items-center justify-center shrink-0 border border-blue-100">
                        {idx + 1}
                      </span>
                      <span className="text-xs font-bold text-slate-900 truncate" title={c}>
                        {c}
                      </span>
                    </div>

                    <button
                      type="button"
                      onClick={() => handleDeleteItem(c)}
                      title={`حذف "${c}" من مكتب ${activeOffice}`}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-rose-600 hover:bg-rose-50 border border-transparent hover:border-rose-200 transition-colors shrink-0 cursor-pointer"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Quick Summary of all offices */}
          <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200 text-xs text-slate-600 space-y-1.5">
            <div className="font-bold text-slate-800 flex items-center gap-1.5">
              <CheckCircle2 className="w-4 h-4 text-emerald-600" />
              <span>حالة التزامن التلقائي والذكي:</span>
            </div>
            <p className="text-[11px] text-slate-500 leading-relaxed">
              عند اختيار أي مكتب داخل نافذة إضافة أو تعديل أمر عمل، يتم جلب قائمتي المقاولين والاستشاريين الخاصة به تلقائياً بدون تدخل يدوي.
            </p>
          </div>
        </div>

        {/* Footer */}
        <div className="p-4 bg-slate-50 border-t border-slate-200 flex items-center justify-between">
          <span className="text-xs text-slate-500">
            كافة التعديلات ترحل وتتزامن سحابياً وفورياً لجميع المستخدمين
          </span>
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2 rounded-xl bg-slate-900 text-white hover:bg-slate-800 text-xs font-bold transition-colors shadow-xs"
          >
            إغلاق
          </button>
        </div>
      </div>
    </div>
  );
};

src/components/ManageOfficesModal.tsx:
import React, { useState } from 'react';
import { SubOffice, WorkOrder } from '../types';
import { 
  Building2, 
  Plus, 
  Pencil, 
  Trash2, 
  X, 
  Search, 
  MapPin, 
  User, 
  Phone, 
  ClipboardList, 
  CheckCircle2, 
  AlertTriangle,
  ArrowRightLeft,
  Sparkles,
  Info
} from 'lucide-react';

interface ManageOfficesModalProps {
  isOpen: boolean;
  onClose: () => void;
  offices: SubOffice[];
  workOrders: WorkOrder[];
  onAddNewOffice: (office: Partial<SubOffice>) => Promise<void> | void;
  onUpdateOffice: (office: SubOffice, oldName?: string) => Promise<void> | void;
  onDeleteOffice: (officeId: string, officeName: string, reassignTo?: string) => Promise<void> | void;
  initialOfficeToEdit?: SubOffice | null;
}

export const ManageOfficesModal: React.FC<ManageOfficesModalProps> = ({
  isOpen,
  onClose,
  offices,
  workOrders,
  onAddNewOffice,
  onUpdateOffice,
  onDeleteOffice,
  initialOfficeToEdit = null
}) => {
  const [activeTab, setActiveTab] = useState<'list' | 'add' | 'edit'>('list');
  const [searchQuery, setSearchQuery] = useState('');

  // Edit State
  const [editingOffice, setEditingOffice] = useState<SubOffice | null>(null);
  const [editName, setEditName] = useState('');
  const [editCode, setEditCode] = useState('');
  const [editRegion, setEditRegion] = useState('');
  const [editManager, setEditManager] = useState('');
  const [editContact, setEditContact] = useState('');
  const [editDescription, setEditDescription] = useState('');
  const [editError, setEditError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Add State
  const [addName, setAddName] = useState('');
  const [addCode, setAddCode] = useState('');
  const [addRegion, setAddRegion] = useState('');
  const [addManager, setAddManager] = useState('');
  const [addContact, setAddContact] = useState('');
  const [addDescription, setAddDescription] = useState('');
  const [addError, setAddError] = useState('');

  // Delete State with Reassignment
  const [officeToDelete, setOfficeToDelete] = useState<SubOffice | null>(null);
  const [reassignTargetOffice, setReassignTargetOffice] = useState<string>('');

  // Initialize edit when initialOfficeToEdit is provided
  React.useEffect(() => {
    if (initialOfficeToEdit) {
      startEditOffice(initialOfficeToEdit);
    } else {
      setActiveTab('list');
      setEditingOffice(null);
    }
  }, [initialOfficeToEdit, isOpen]);

  if (!isOpen) return null;

  const startEditOffice = (office: SubOffice) => {
    setEditingOffice(office);
    setEditName(office.name);
    setEditCode(office.code || '');
    setEditRegion(office.region || '');
    setEditManager(office.manager || '');
    setEditContact(office.contactNumber || '');
    setEditDescription(office.description || '');
    setEditError('');
    setActiveTab('edit');
  };

  const handleSaveEdit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingOffice) return;
    const trimmedName = editName.trim();
    if (!trimmedName) {
      setEditError('يرجى إدخال اسم المكتب');
      return;
    }

    // Check duplicate name on another office
    const duplicate = offices.some(
      o => o.id !== editingOffice.id && o.name.trim().toLowerCase() === trimmedName.toLowerCase()
    );
    if (duplicate) {
      setEditError('يوجد مكتب آخر يحمل نفس هذا الاسم مسبقاً، يرجى اختيار اسم مختلف');
      return;
    }

    setIsSubmitting(true);
    setEditError('');
    try {
      const updated: SubOffice = {
        ...editingOffice,
        name: trimmedName,
        code: editCode.trim() || editingOffice.code,
        region: editRegion.trim() || 'المنطقة الحضرية',
        manager: editManager.trim() || 'مدير المكتب الميداني',
        contactNumber: editContact.trim() || '0500000000',
        description: editDescription.trim() || 'مكتب فرعي لإدارة ومتابعة أوامر العمل الميدانية'
      };

      await onUpdateOffice(updated, editingOffice.name);
      setEditingOffice(null);
      setActiveTab('list');
    } catch (err: any) {
      setEditError(err?.message || 'حدث خطأ أثناء حفظ تعديل المكتب');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleSaveAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmedName = addName.trim();
    if (!trimmedName) {
      setAddError('يرجى إدخال اسم المكتب');
      return;
    }

    // Check duplicate
    if (offices.some(o => o.name.trim().toLowerCase() === trimmedName.toLowerCase())) {
      setAddError('يوجد مكتب بهذا الاسم بالفعل');
      return;
    }

    setIsSubmitting(true);
    setAddError('');
    try {
      await onAddNewOffice({
        name: trimmedName,
        code: addCode.trim() || `OFF-${Date.now().toString().slice(-4)}`,
        region: addRegion.trim() || 'المنطقة الحضرية',
        manager: addManager.trim() || 'مدير المكتب الميداني',
        contactNumber: addContact.trim() || '0500000000',
        description: addDescription.trim() || 'مكتب فرعي لإدارة ومتابعة أوامر العمل الميدانية'
      });

      // Reset
      setAddName('');
      setAddCode('');
      setAddRegion('');
      setAddManager('');
      setAddContact('');
      setAddDescription('');
      setActiveTab('list');
    } catch (err: any) {
      setAddError(err?.message || 'حدث خطأ أثناء إضافة المكتب');
    } finally {
      setIsSubmitting(false);
    }
  };

  const startDeleteOffice = (office: SubOffice) => {
    if (offices.length <= 1) {
      alert('لا يمكن حذف كافة المكاتب، يجب الإبقاء على مكتب فرعي واحد على الأقل في النظام.');
      return;
    }
    setOfficeToDelete(office);
    // Find default reassign target (first other office)
    const otherOffice = offices.find(o => o.id !== office.id);
    setReassignTargetOffice(otherOffice ? otherOffice.name : '');
  };

  const handleConfirmDelete = async () => {
    if (!officeToDelete) return;
    setIsSubmitting(true);
    try {
      await onDeleteOffice(officeToDelete.id, officeToDelete.name, reassignTargetOffice);
      setOfficeToDelete(null);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  // Filtered offices
  const filteredOffices = offices.filter(o => 
    o.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    (o.code && o.code.toLowerCase().includes(searchQuery.toLowerCase())) ||
    (o.manager && o.manager.toLowerCase().includes(searchQuery.toLowerCase())) ||
    (o.region && o.region.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  return (
    <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-3 sm:p-5 overflow-y-auto">
      <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 max-w-4xl w-full overflow-hidden text-right font-['Cairo',sans-serif] my-auto flex flex-col max-h-[92vh]">

        {/* Header Bar */}
        <div className="p-4 sm:p-5 bg-gradient-to-r from-slate-900 via-slate-800 to-slate-900 text-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-blue-500/20 text-blue-400 border border-blue-400/30 flex items-center justify-center shrink-0">
              <Building2 className="w-5 h-5 text-blue-400" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-base sm:text-lg font-black text-white">
                  إدارة المكاتب الفرعية وتوزيع الصلاحيات
                </h2>
                <span className="px-2 py-0.5 rounded-full text-xs font-bold bg-blue-500/20 text-blue-300 border border-blue-400/30 font-mono">
                  {offices.length} مكاتب
                </span>
              </div>
              <p className="text-xs text-slate-300 mt-0.5">
                تعديل، إضافة، وحذف المكاتب مع المزامنة الفورية لكافة أوامر العمل والقوائم المنسدلة
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-white rounded-xl hover:bg-white/10 transition-colors cursor-pointer"
            title="إغلاق النافذة"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Navigation Tabs Bar */}
        <div className="flex items-center justify-between gap-3 px-4 sm:px-6 pt-3 pb-2 bg-slate-50 border-b border-slate-200 shrink-0 flex-wrap">
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => {
                setActiveTab('list');
                setEditingOffice(null);
              }}
              className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                activeTab === 'list'
                  ? 'bg-blue-600 text-white shadow-xs'
                  : 'bg-white text-slate-700 hover:bg-slate-200/70 border border-slate-200'
              }`}
            >
              <Building2 className="w-3.5 h-3.5" />
              <span>المكاتب المسجلة ({offices.length})</span>
            </button>

            <button
              type="button"
              onClick={() => {
                setActiveTab('add');
                setEditingOffice(null);
                setAddError('');
              }}
              className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                activeTab === 'add'
                  ? 'bg-blue-600 text-white shadow-xs'
                  : 'bg-white text-blue-700 hover:bg-blue-50 border border-blue-200'
              }`}
            >
              <Plus className="w-3.5 h-3.5" />
              <span>إضافة مكتب جديد</span>
            </button>

            {activeTab === 'edit' && editingOffice && (
              <span className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold bg-amber-500 text-white shadow-xs">
                <Pencil className="w-3.5 h-3.5" />
                <span>تعديل: {editingOffice.name}</span>
              </span>
            )}
          </div>

          {activeTab === 'list' && (
            <div className="relative min-w-[200px]">
              <Search className="w-3.5 h-3.5 absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input
                type="text"
                placeholder="بحث في المكاتب..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pr-8 pl-3 py-1 text-xs rounded-lg border border-slate-300 bg-white focus:outline-hidden focus:ring-1 focus:ring-blue-500 font-medium"
              />
            </div>
          )}
        </div>

        {/* Modal Body */}
        <div className="p-4 sm:p-6 overflow-y-auto flex-1">

          {/* TAB 1: LIST OF OFFICES */}
          {activeTab === 'list' && (
            <div className="space-y-3.5">
              {filteredOffices.length === 0 ? (
                <div className="text-center py-12 bg-slate-50 rounded-2xl border border-dashed border-slate-200">
                  <Building2 className="w-10 h-10 text-slate-300 mx-auto mb-2" />
                  <p className="text-sm font-bold text-slate-700">لا توجد مكاتب مطابقة للبحث</p>
                  <p className="text-xs text-slate-400 mt-1">يمكنك إضافة مكتب جديد بالضغط على زر "إضافة مكتب جديد" بالأعلى</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3.5">
                  {filteredOffices.map((office) => {
                    const assignedOrders = workOrders.filter(w => w.office === office.name);
                    const readyCount = assignedOrders.filter(
                      w => w.procedure155Status === 'مؤهل للاستلام (معتمد)' || w.procedure155Status === 'تم الاستلام وإغلاق 155'
                    ).length;
                    const completionRate = assignedOrders.length > 0
                      ? Math.round((readyCount / assignedOrders.length) * 100)
                      : 0;

                    return (
                      <div 
                        key={office.id}
                        className="bg-white rounded-xl border border-slate-200/90 hover:border-blue-300 p-4 shadow-2xs hover:shadow-xs transition-all flex flex-col justify-between"
                      >
                        <div>
                          {/* Office Header */}
                          <div className="flex items-start justify-between gap-2 mb-2.5">
                            <div>
                              <div className="flex items-center gap-2">
                                <h3 className="text-sm font-black text-slate-900">
                                  {office.name}
                                </h3>
                                <span className="font-mono text-[10px] font-bold px-1.5 py-0.5 rounded bg-slate-100 text-slate-700 border border-slate-200">
                                  {office.code || 'بدون رمز'}
                                </span>
                              </div>
                              <span className="text-[11px] text-slate-500 flex items-center gap-1 mt-1">
                                <MapPin className="w-3 h-3 text-slate-400" />
                                <span>{office.region || 'المنطقة الحضرية'}</span>
                              </span>
                            </div>

                            {/* Orders count badge */}
                            <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-mono font-bold bg-blue-50 text-blue-800 border border-blue-200">
                              <ClipboardList className="w-3.5 h-3.5 text-blue-600" />
                              <span>{assignedOrders.length} أمر عمل</span>
                            </span>
                          </div>

                          {/* Details Details Grid */}
                          <div className="grid grid-cols-2 gap-2 my-3 p-2.5 rounded-lg bg-slate-50/80 text-xs text-slate-700 border border-slate-100">
                            <div className="flex items-center gap-1.5 truncate">
                              <User className="w-3.5 h-3.5 text-slate-400 shrink-0" />
                              <span className="truncate">{office.manager || 'المشرف الميداني'}</span>
                            </div>
                            <div className="flex items-center gap-1.5 truncate">
                              <Phone className="w-3.5 h-3.5 text-slate-400 shrink-0" />
                              <span className="font-mono text-[11px]" dir="ltr">{office.contactNumber || '0500000000'}</span>
                            </div>
                            <div className="col-span-2 flex items-center justify-between text-[11px] text-slate-600 pt-1 border-t border-slate-200/60">
                              <span>نسبة الجاهزية لإجراء 155:</span>
                              <span className="font-bold text-emerald-700 font-mono">
                                {completionRate}% ({readyCount} جاهز)
                              </span>
                            </div>
                          </div>

                          {office.description && (
                            <p className="text-[11px] text-slate-500 mb-3 line-clamp-2">
                              {office.description}
                            </p>
                          )}
                        </div>

                        {/* Actions Bottom Bar */}
                        <div className="flex items-center justify-between gap-2 pt-3 border-t border-slate-100">
                          <span className="text-[10px] text-slate-400 font-mono">
                            ID: {office.id.slice(-6)}
                          </span>

                          <div className="flex items-center gap-2">
                            {/* زر التعديل */}
                            <button
                              type="button"
                              onClick={() => startEditOffice(office)}
                              className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-bold text-amber-700 bg-amber-50 hover:bg-amber-100 border border-amber-200 transition-colors cursor-pointer"
                              title="تعديل بيانات المكتب واسمه"
                            >
                              <Pencil className="w-3.5 h-3.5 text-amber-600" />
                              <span>تعديل</span>
                            </button>

                            {/* زر الحذف */}
                            <button
                              type="button"
                              onClick={() => startDeleteOffice(office)}
                              disabled={offices.length <= 1}
                              className={`inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors cursor-pointer ${
                                offices.length <= 1
                                  ? 'opacity-40 cursor-not-allowed bg-slate-100 text-slate-400 border border-slate-200'
                                  : 'text-rose-700 bg-rose-50 hover:bg-rose-100 border border-rose-200'
                              }`}
                              title={offices.length <= 1 ? "لا يمكن حذف المكتب الوحيد المتبقي" : "حذف هذا المكتب"}
                            >
                              <Trash2 className="w-3.5 h-3.5 text-rose-600" />
                              <span>حذف</span>
                            </button>
                          </div>
                        </div>

                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}

          {/* TAB 2: ADD NEW OFFICE */}
          {activeTab === 'add' && (
            <div className="max-w-2xl mx-auto bg-slate-50/70 p-5 rounded-2xl border border-slate-200">
              <div className="mb-4">
                <h3 className="text-base font-black text-slate-900">
                  إضافة وتفعيل مكتب فرعي جديد
                </h3>
                <p className="text-xs text-slate-500 mt-0.5">
                  سيتم تسجيل المكتب في المنظومة وإتاحته فورياً في كافة القوائم المنسدلة وجدول أوامر العمل
                </p>
              </div>

              {addError && (
                <div className="mb-4 p-3 rounded-xl bg-rose-50 border border-rose-200 text-rose-800 text-xs font-bold flex items-center gap-2">
                  <AlertTriangle className="w-4 h-4 text-rose-600 shrink-0" />
