                </div>
              )}

              <form onSubmit={handleSaveAdd} className="space-y-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
                  <div>
                    <label className="block text-xs font-bold text-slate-800 mb-1">
                      اسم المكتب الفرعي *
                    </label>
