import React, { useState, useMemo, useEffect } from 'react';
import { 
  Plus, 
  Edit3, 
  Trash2, 
  FolderPlus, 
  Layers, 
  X,
  FileSpreadsheet,
  Calendar,
  TableProperties,
  ShieldCheck,
  AlertCircle,
  Lock,
  Sparkles,
  CheckCircle2
} from 'lucide-react';
import { MonthTable, WorkOrder, PlatformUser } from '../types';
import {
  ARABIC_MONTHS,
  getArabicMonthName,
  getDefaultTableId,
  isDefaultTableId,
  resolveOrderScope,
  isTableInPeriod,
  validateAndDisambiguateTableName
} from '../utils/tableScope';
import { hasUserPermission } from '../utils/security';

interface MonthTablesBarProps {
  activeYear: number;
  activeMonth: number | 'all';
  monthTables?: MonthTable[];
  selectedTableId: string; // 'all', 'default-YYYY-M', or custom table id
  onSelectTable: (tableId: string) => void;
  onSelectPeriod?: (year: number, month: number | 'all', tableId?: string) => void;
  onOpenYearMonthPicker?: () => void;
  onOpenImportForTable?: (year: number, month: number, tableId: string) => void;
  onOpenCompatibleImport?: () => void;
  onCreateTable: (name: string, description?: string, color?: string, targetYear?: number, targetMonth?: number) => Promise<any>;
  onUpdateTable: (table: MonthTable) => Promise<void>;
  onDeleteTable: (tableId: string, reassignToTableId?: string) => Promise<void>;
  onClose?: () => void;
  orders?: WorkOrder[];
  currentUser?: PlatformUser | null;
}

const TABLE_COLORS = [
  { name: 'blue', label: 'أزرق ملكي', bg: 'bg-blue-600', ring: 'ring-blue-400', badge: 'bg-blue-100 text-blue-900 border-blue-200' },
  { name: 'emerald', label: 'أخضر زمردي', bg: 'bg-emerald-600', ring: 'ring-emerald-400', badge: 'bg-emerald-100 text-emerald-900 border-emerald-200' },
  { name: 'indigo', label: 'نيلي رسمي', bg: 'bg-indigo-600', ring: 'ring-indigo-400', badge: 'bg-indigo-100 text-indigo-900 border-indigo-200' },
  { name: 'purple', label: 'بنفسجي ملكي', bg: 'bg-purple-600', ring: 'ring-purple-400', badge: 'bg-purple-100 text-purple-900 border-purple-200' },
  { name: 'amber', label: 'عنبري دافئ', bg: 'bg-amber-600', ring: 'ring-amber-400', badge: 'bg-amber-100 text-amber-900 border-amber-200' },
  { name: 'rose', label: 'وردي ياقوتي', bg: 'bg-rose-600', ring: 'ring-rose-400', badge: 'bg-rose-100 text-rose-900 border-rose-200' },
  { name: 'cyan', label: 'سماوي بحري', bg: 'bg-cyan-600', ring: 'ring-cyan-400', badge: 'bg-cyan-100 text-cyan-900 border-cyan-200' }
];

export const MonthTablesBar: React.FC<MonthTablesBarProps> = ({
  activeYear,
  activeMonth,
  monthTables = [],
  selectedTableId,
  onSelectTable,
  onSelectPeriod,
  onCreateTable,
  onUpdateTable,
  onDeleteTable,
  onClose,
  orders = [],
  currentUser
}) => {
  const safeMonthTables = useMemo(() => Array.isArray(monthTables) ? monthTables : [], [monthTables]);
  const safeOrders = useMemo(() => Array.isArray(orders) ? orders : [], [orders]);

  const defaultNumericMonth = typeof activeMonth === 'number' && activeMonth >= 1 && activeMonth <= 12
    ? activeMonth
    : (new Date().getMonth() + 1);

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newTableName, setNewTableName] = useState('');
  const [newTableDesc, setNewTableDesc] = useState('');
  const [newTableColor, setNewTableColor] = useState('blue');
  const [newTableYear, setNewTableYear] = useState<number>(activeYear);
  const [newTableMonth, setNewTableMonth] = useState<number>(defaultNumericMonth);

  const [editingTable, setEditingTable] = useState<MonthTable | null>(null);
  const [deleteConfirmTable, setDeleteConfirmTable] = useState<MonthTable | null>(null);

  useEffect(() => {
    setNewTableYear(activeYear);
    if (typeof activeMonth === 'number' && activeMonth >= 1 && activeMonth <= 12) {
      setNewTableMonth(activeMonth);
    }
  }, [activeYear, activeMonth]);

  // Available years for quick switching
  const availableYears = useMemo(() => {
    const set = new Set<number>([2024, 2025, 2026, 2027, 2028]);
    set.add(activeYear);
    safeMonthTables.forEach(t => {
      if (t && t.year >= 2000 && t.year <= 2100) set.add(Number(t.year));
    });
    safeOrders.forEach(o => {
      if (!o) return;
      const s = resolveOrderScope(o, safeMonthTables);
      if (s.year >= 2000 && s.year <= 2100) set.add(s.year);
    });
    return Array.from(set).sort((a, b) => a - b);
  }, [activeYear, safeMonthTables, safeOrders]);

  // Filter custom tables that belong strictly to the active year & month (excluding default metadata entries)
  const currentMonthTables = useMemo(() => {
    return safeMonthTables.filter(
      t => !isDefaultTableId(t.id) && !t.isDefault && isTableInPeriod(t, activeYear, activeMonth)
    );
  }, [safeMonthTables, activeYear, activeMonth]);

  // Calculate order counts per month in activeYear + order counts per table in (activeYear, activeMonth)
  const { ordersCountByMonth, ordersCountMap, totalOrdersInActivePeriod, defaultTableOrdersCount } = useMemo(() => {
    const byMonth: Record<number, number> = {};
    for (let m = 1; m <= 12; m++) byMonth[m] = 0;

    const tblMap = new Map<string, number>();
    let totalInPeriod = 0;
    let defaultInPeriod = 0;

    safeOrders.forEach(o => {
      if (!o) return;
      const scope = resolveOrderScope(o, safeMonthTables);
      if (scope.year === activeYear) {
        byMonth[scope.month] = (byMonth[scope.month] || 0) + 1;
      }

      const matchesYear = scope.year === activeYear;
      const matchesMonth = activeMonth === 'all' ? true : scope.month === Number(activeMonth);

      if (matchesYear && matchesMonth) {
        totalInPeriod++;
        if (scope.isCustomTable) {
          tblMap.set(scope.tableId, (tblMap.get(scope.tableId) || 0) + 1);
        } else {
          defaultInPeriod++;
          tblMap.set(scope.tableId, (tblMap.get(scope.tableId) || 0) + 1);
          tblMap.set('default', (tblMap.get('default') || 0) + 1);
        }
      }
    });

    return {
      ordersCountByMonth: byMonth,
      ordersCountMap: tblMap,
      totalOrdersInActivePeriod: totalInPeriod,
      defaultTableOrdersCount: defaultInPeriod
    };
  }, [safeOrders, safeMonthTables, activeYear, activeMonth]);

  // Validate new table name against existing tables in (newTableYear, newTableMonth)
  const addModalNameValidation = useMemo(() => {
    if (!newTableName.trim()) {
      return { isDuplicate: false, cleanName: '', suggestedName: '' };
    }
    return validateAndDisambiguateTableName(
      newTableName,
      newTableYear,
      newTableMonth,
      safeMonthTables
    );
  }, [newTableName, newTableYear, newTableMonth, safeMonthTables]);

  const handleCreateSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTableName.trim()) return;
    const finalName = addModalNameValidation.isDuplicate
      ? addModalNameValidation.suggestedName
      : newTableName.trim();

    await onCreateTable(finalName, newTableDesc.trim(), newTableColor, newTableYear, newTableMonth);
    setNewTableName('');
    setNewTableDesc('');
    setIsAddModalOpen(false);
  };

  const handleEditSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTable || !editingTable.name.trim()) return;
    const targetYr = Number(editingTable.year) || activeYear;
    const targetMo = editingTable.month === 'all' ? defaultNumericMonth : Number(editingTable.month);
    const check = validateAndDisambiguateTableName(
      editingTable.name,
      targetYr,
      targetMo,
      safeMonthTables,
      editingTable.id
    );
    const updatedTbl: MonthTable = {
      ...editingTable,
      year: targetYr,
      month: targetMo,
      name: check.isDuplicate ? check.suggestedName : editingTable.name.trim()
    };
    await onUpdateTable(updatedTbl);
    setEditingTable(null);
  };

  const handleDeleteSubmit = async () => {
    if (!deleteConfirmTable) return;
    await onDeleteTable(deleteConfirmTable.id);
    setDeleteConfirmTable(null);
  };

  const scopedDefaultTableId = getDefaultTableId(activeYear, activeMonth);
  const isDefaultSelected = selectedTableId === 'default' || selectedTableId === scopedDefaultTableId || isDefaultTableId(selectedTableId);

  const monthLabel = activeMonth === 'all' 
    ? `كافة شهور ${activeYear}` 
    : `${getArabicMonthName(activeMonth)} ${activeYear}`;

  return (
    <div className="bg-white rounded-2xl border border-slate-200/95 p-2.5 sm:p-3 shadow-md text-right space-y-2 animate-in fade-in zoom-in-95 duration-150">

      {/* السطر الأول (Line 1): أيقونة مميزة ومختصرة + اختيار السنة والشهور + زر إنشاء جدول جديد + إغلاق */}
      <div className="flex items-center justify-between gap-2 pb-2 border-b border-slate-100 overflow-x-auto scrollbar-none">
        <div className="flex items-center gap-1.5 shrink-0">
          {/* Distinctive Concise Synchronized Icon Badge */}
          <div
            className="flex items-center gap-1.5 px-2.5 py-1 rounded-xl bg-gradient-to-l from-emerald-700 to-teal-700 text-white shadow-2xs shrink-0"
            title="قائمة جداول أوامر العمل الميدانية المتزامنة"
          >
            <div className="relative flex items-center justify-center">
              <TableProperties className="w-3.5 h-3.5 text-amber-300" />
              <span className="absolute -top-0.5 -right-0.5 w-1.5 h-1.5 rounded-full bg-emerald-300 animate-ping" />
            </div>
            <span className="text-[11px] font-black tracking-tight">الجداول</span>
            <span className="px-1.5 py-0.2 rounded-md bg-black/25 text-amber-200 font-mono text-[10px] font-black">
              {currentMonthTables.length + 1}
            </span>
          </div>

          {/* Compact Year Selector */}
          {onSelectPeriod && (
            <div className="flex items-center gap-1 bg-indigo-50/90 border border-indigo-200/90 rounded-xl px-2 py-1 shrink-0">
              <Calendar className="w-3 h-3 text-indigo-600 shrink-0" />
              <select
                value={activeYear}
                onChange={(e) => {
                  const yr = Number(e.target.value);
                  onSelectPeriod(yr, activeMonth);
                }}
                className="bg-transparent text-indigo-950 font-mono font-black text-[11px] cursor-pointer focus:outline-hidden"
                title="تغيير السنة"
              >
                {availableYears.map(y => (
                  <option key={y} value={y}>
                    {y}
                  </option>
                ))}
              </select>
            </div>
          )}
        </div>

        {/* Compact 12-Month Strip in the same Line 1 */}
        {onSelectPeriod && (
          <div className="flex items-center gap-1 overflow-x-auto scrollbar-none flex-1">
            {ARABIC_MONTHS.map(m => {
              const isMoActive = activeMonth === m.num;
              const moOrdersCount = ordersCountByMonth[m.num] || 0;
              const moCustomTablesCount = safeMonthTables.filter(
                t => !isDefaultTableId(t.id) && !t.isDefault && isTableInPeriod(t, activeYear, m.num)
              ).length;
              const hasActivity = moOrdersCount > 0 || moCustomTablesCount > 0;

              return (
                <button
                  key={m.num}
                  type="button"
                  onClick={() => {
                    onSelectPeriod(activeYear, m.num);
                  }}
                  className={`px-2 py-1 rounded-lg text-[10.5px] font-bold transition-all cursor-pointer shrink-0 flex items-center gap-1 border ${
                    isMoActive
                      ? 'bg-indigo-600 text-white border-indigo-600 shadow-2xs font-black'
                      : hasActivity
                      ? 'bg-emerald-50/90 hover:bg-emerald-100 text-emerald-950 border-emerald-300 font-black'
                      : 'bg-slate-50 hover:bg-slate-100 text-slate-600 border-slate-200/80'
                  }`}
                  title={`شهر ${m.num} (${m.name} ${activeYear}) • ${moOrdersCount} أمر عمل • ${moCustomTablesCount + 1} جدول`}
                >
                  <span>{m.name}</span>
                  {(moOrdersCount > 0 || isMoActive) && (
                    <span className={`px-1 rounded text-[9px] font-mono font-black ${
                      isMoActive ? 'bg-white/25 text-white' : 'bg-emerald-600 text-white'
                    }`}>
                      {moOrdersCount}
                    </span>
                  )}
                </button>
              );
            })}

            <button
              type="button"
              onClick={() => onSelectPeriod(activeYear, 'all', 'all')}
              className={`px-2 py-1 rounded-lg text-[10.5px] font-bold transition-all cursor-pointer shrink-0 flex items-center gap-1 border ${
                activeMonth === 'all'
                  ? 'bg-slate-900 text-white border-slate-900 shadow-2xs'
                  : 'bg-slate-100 hover:bg-slate-200 text-slate-700 border-slate-300'
              }`}
              title={`عرض كافة شهور ${activeYear}`}
            >
              <span>الكل</span>
            </button>
          </div>
        )}

        {/* Compact Add Table Button & Close Button */}
        <div className="flex items-center gap-1 shrink-0">
          {hasUserPermission(currentUser, 'manageMonthTables') && (
            <button
              type="button"
              onClick={() => {
                const targetMo = typeof activeMonth === 'number' && activeMonth >= 1 && activeMonth <= 12
                  ? activeMonth
                  : (new Date().getMonth() + 1);
                setNewTableYear(activeYear);
                setNewTableMonth(targetMo);
                const existingInTarget = safeMonthTables.filter(
                  t => !isDefaultTableId(t.id) && !t.isDefault && isTableInPeriod(t, activeYear, targetMo)
                ).length;
                const mName = getArabicMonthName(targetMo);
                setNewTableName(`جدول ${mName} ${activeYear} - ${existingInTarget + 2}`);
                setNewTableDesc('');
                setNewTableColor('blue');
                setIsAddModalOpen(true);
              }}
              className="inline-flex items-center gap-1 px-2.5 py-1 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white font-black text-[11px] shadow-2xs transition-all cursor-pointer shrink-0 active:scale-95"
              title="إنشاء جدول مستقل جديد"
            >
              <Plus className="w-3.5 h-3.5" />
              <span>جدول جديد</span>
            </button>
          )}

          {onClose && (
            <button
              type="button"
              onClick={onClose}
              className="p-1 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-colors cursor-pointer"
              title="إغلاق القائمة"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      {/* السطر الثاني (Line 2): بطاقات الجداول المتزامنة للشهر النشط بأيقونة مميزة ومختصرة */}
      <div className="flex items-center gap-1.5 overflow-x-auto scrollbar-none pt-0.5">
        {/* Tab 1: Scoped Main Default Table */}
        {(() => {
          const defaultHasNewRows = safeOrders.some(
            o => o.isNew && !o.isEdited && !resolveOrderScope(o, safeMonthTables).isCustomTable && resolveOrderScope(o, safeMonthTables).year === activeYear && (activeMonth === 'all' || resolveOrderScope(o, safeMonthTables).month === Number(activeMonth))
          );
          const defaultMeta = safeMonthTables.find(
            t => t.id === scopedDefaultTableId || (isDefaultTableId(t.id) && t.year === activeYear && (activeMonth === 'all' || t.month === Number(activeMonth)))
          );
          const defaultDisplayName = defaultMeta?.name || `الجدول الأساسي - ${monthLabel}`;

          return (
            <div
              className={`flex items-center rounded-xl border transition-all shrink-0 ${
                isDefaultSelected && selectedTableId !== 'all'
                  ? 'bg-emerald-600 text-white border-emerald-600 shadow-2xs ring-2 ring-emerald-300/70'
                  : 'bg-slate-50/90 hover:bg-emerald-50/70 text-emerald-950 border-emerald-300'
              }`}
            >
              <button
                type="button"
                onClick={() => onSelectTable(scopedDefaultTableId)}
                className="flex items-center gap-1.5 px-2.5 py-1.5 text-[11px] font-black cursor-pointer"
                title={`${defaultDisplayName} (${monthLabel})`}
              >
                <FileSpreadsheet className="w-3.5 h-3.5 shrink-0" />
                {defaultHasNewRows && (
                  <Sparkles className="w-3 h-3 text-amber-300 animate-pulse shrink-0" />
                )}
                <span className="truncate max-w-[170px]">{defaultDisplayName}</span>
                <span className={`px-1.5 py-0.2 rounded-full text-[9.5px] font-mono font-black ${
                  isDefaultSelected && selectedTableId !== 'all' ? 'bg-white/25 text-white' : 'bg-emerald-200/80 text-emerald-950'
                }`}>
                  {totalOrdersInActivePeriod}
                </span>
              </button>

              {(hasUserPermission(currentUser, 'manageMonthTables') || hasUserPermission(currentUser, 'deleteMonthTable')) && (
                <div className="flex items-center pl-1 gap-0.5 border-r border-emerald-300/40 pr-1">
                  {hasUserPermission(currentUser, 'manageMonthTables') && (
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        setEditingTable({
                          id: scopedDefaultTableId,
                          name: defaultDisplayName,
                          year: activeYear,
                          month: activeMonth === 'all' ? defaultNumericMonth : activeMonth,
                          color: 'emerald',
                          description: 'الجدول الرئيسي للشهر',
                          createdAt: new Date().toISOString()
                        });
                      }}
                      className={`p-0.5 rounded transition-colors cursor-pointer ${
                        isDefaultSelected && selectedTableId !== 'all' ? 'hover:bg-white/20 text-white/90' : 'text-slate-400 hover:text-slate-700 hover:bg-slate-200/60'
                      }`}
                      title="تعديل اسم الجدول"
                    >
                      <Edit3 className="w-3 h-3" />
                    </button>
                  )}
                  {hasUserPermission(currentUser, 'deleteMonthTable') && (
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        setDeleteConfirmTable({
                          id: scopedDefaultTableId,
                          name: defaultDisplayName,
                          year: activeYear,
                          month: activeMonth === 'all' ? defaultNumericMonth : activeMonth,
                          color: 'emerald',
                          createdAt: new Date().toISOString()
                        });
                      }}
                      className={`p-0.5 rounded transition-colors cursor-pointer ${
                        isDefaultSelected && selectedTableId !== 'all' ? 'hover:bg-white/20 text-white/90' : 'text-slate-400 hover:text-rose-600 hover:bg-rose-50'
                      }`}
                      title="حذف هذا الجدول"
                    >
                      <Trash2 className="w-3 h-3" />
                    </button>
                  )}
                </div>
              )}
            </div>
          );
        })()}

        {/* Dynamic Independent Month Tables */}
        {currentMonthTables.map((tbl) => {
          const isSelected = selectedTableId === tbl.id;
          const count = ordersCountMap.get(tbl.id) || 0;
          const colorObj = TABLE_COLORS.find(c => c.name === tbl.color) || TABLE_COLORS[0];
          const tblHasNewRows = safeOrders.some(
            o => o.isNew && !o.isEdited && resolveOrderScope(o, safeMonthTables).tableId === tbl.id
          );
          const isTblNew = Boolean(tbl.isNew || tblHasNewRows);

          return (
            <div
              key={tbl.id}
              className={`flex items-center rounded-xl border transition-all shrink-0 ${
                isSelected
                  ? `${colorObj.bg} text-white border-transparent shadow-2xs ring-2 ${colorObj.ring}`
                  : 'bg-white hover:bg-slate-50 text-slate-800 border-slate-200'
              }`}
            >
              <button
                type="button"
                onClick={() => onSelectTable(tbl.id)}
                className="flex items-center gap-1.5 px-2.5 py-1.5 text-[11px] font-black cursor-pointer"
                title={`${tbl.name} (${getArabicMonthName(tbl.month)} ${tbl.year})`}
              >
                <span className={`w-2 h-2 rounded-full shrink-0 ${isSelected ? 'bg-amber-300' : colorObj.bg}`} />
                {isTblNew && (
                  <Sparkles className="w-3 h-3 text-emerald-500 animate-pulse shrink-0" />
                )}
                <span className="truncate max-w-[150px]">{tbl.name}</span>
                <span className={`px-1.5 py-0.2 rounded-full text-[9.5px] font-mono font-black ${
                  isSelected ? 'bg-white/25 text-white' : 'bg-slate-100 text-slate-800'
                }`}>
                  {count}
                </span>
              </button>

              {(hasUserPermission(currentUser, 'manageMonthTables') || hasUserPermission(currentUser, 'deleteMonthTable')) && (
                <div className="flex items-center pl-1 gap-0.5 border-r border-slate-200/50 pr-1">
                  {hasUserPermission(currentUser, 'manageMonthTables') && (
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        setEditingTable(tbl);
                      }}
                      className={`p-0.5 rounded transition-colors cursor-pointer ${
                        isSelected ? 'hover:bg-white/20 text-white/90' : 'text-slate-400 hover:text-slate-700 hover:bg-slate-100'
                      }`}
                      title="تعديل الجدول"
                    >
                      <Edit3 className="w-3 h-3" />
                    </button>
                  )}
                  {hasUserPermission(currentUser, 'deleteMonthTable') && (
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        setDeleteConfirmTable(tbl);
                      }}
                      className={`p-0.5 rounded transition-colors cursor-pointer ${
                        isSelected ? 'hover:bg-white/20 text-white/90' : 'text-slate-400 hover:text-rose-600 hover:bg-rose-50'
                      }`}
                      title="حذف الجدول"
                    >
                      <Trash2 className="w-3 h-3" />
                    </button>
                  )}
                </div>
              )}
            </div>
          );
        })}

        {/* Compact Combined View Pill */}
        {currentMonthTables.length > 0 && (
          <button
            type="button"
            onClick={() => onSelectTable('all')}
            className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl text-[11px] font-black transition-all cursor-pointer shrink-0 border mr-auto ${
              selectedTableId === 'all'
                ? 'bg-slate-900 text-white border-slate-900 shadow-2xs'
                : 'bg-slate-50 hover:bg-slate-100 text-slate-700 border-slate-200'
            }`}
            title="عرض تجميعي لكافة جداول هذا الشهر"
          >
            <Layers className="w-3 h-3 text-amber-500 shrink-0" />
            <span>دمج الكل</span>
            <span className={`px-1.5 py-0.2 rounded-full text-[9.5px] font-mono font-black ${
              selectedTableId === 'all' ? 'bg-white/20 text-white' : 'bg-slate-200 text-slate-800'
            }`}>
              {totalOrdersInActivePeriod}
            </span>
          </button>
        )}
      </div>

      {/* Modal: Add New Independent Table with Explicit Target Year & Target Month */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/75 backdrop-blur-sm animate-in fade-in">
          <div className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl border border-slate-200 text-right">
            <div className="flex items-center justify-between mb-4 pb-3 border-b border-slate-100">
              <div className="flex items-center gap-2.5">
                <div className="w-10 h-10 rounded-2xl bg-indigo-100 text-indigo-700 flex items-center justify-center">
                  <FolderPlus className="w-5 h-5" />
                </div>
                <div>
                  <h4 className="text-base font-black text-slate-900">
                    إدراج جدول مستقل جديد مع تحديد السنة والشهر
                  </h4>
                  <p className="text-[11px] text-slate-500">
                    يتم عزل الجدول برمجياً في السنة والشهر المحددين لمنع أي لبس أو تداخل مطلقاً
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setIsAddModalOpen(false)}
                className="p-1.5 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-slate-100 cursor-pointer"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCreateSubmit} className="space-y-4">
              {/* Target Year & Month Selection Box */}
              <div className="p-3.5 rounded-2xl bg-gradient-to-l from-indigo-50 via-blue-50/60 to-emerald-50 border border-indigo-200/80 space-y-2.5">
                <div className="text-xs font-black text-indigo-950 flex items-center gap-1.5">
                  <Lock className="w-3.5 h-3.5 text-indigo-600" />
                  <span>تحديد السنة والشهر المخصص لإدراج هذا الجدول:</span>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-[11px] font-bold text-slate-700 mb-1">
                      السنة المستهدفة *
                    </label>
                    <select
                      value={newTableYear}
                      onChange={(e) => setNewTableYear(Number(e.target.value))}
                      className="w-full px-3 py-2 text-xs font-black bg-white border border-indigo-300 rounded-xl focus:ring-2 focus:ring-indigo-500"
                    >
                      {availableYears.map(y => (
                        <option key={y} value={y}>
                          سنة {y} م
                        </option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="block text-[11px] font-bold text-slate-700 mb-1">
                      الشهر المستهدف *
                    </label>
                    <select
                      value={newTableMonth}
                      onChange={(e) => setNewTableMonth(Number(e.target.value))}
                      className="w-full px-3 py-2 text-xs font-black bg-white border border-emerald-300 rounded-xl focus:ring-2 focus:ring-emerald-500"
                    >
                      {ARABIC_MONTHS.map(m => (
                        <option key={m.num} value={m.num}>
                          شهر {m.num} - {m.name} ({newTableYear})
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  اسم الجدول المستقل *
                </label>
                <input
                  type="text"
                  required
                  value={newTableName}
                  onChange={(e) => setNewTableName(e.target.value)}
                  placeholder="مثال: جدول مشاريع الطوارئ، دفعة رقم 2، جدول الإنارة..."
                  className="w-full px-3.5 py-2.5 text-xs bg-slate-50 border border-slate-300 rounded-xl focus:bg-white focus:ring-2 focus:ring-indigo-500 font-black"
                />
              </div>

              {addModalNameValidation.isDuplicate && (
                <div className="p-2.5 rounded-xl bg-amber-50 border border-amber-300 text-amber-900 text-[11px] font-bold flex items-center gap-2">
                  <AlertCircle className="w-4 h-4 text-amber-600 shrink-0" />
                  <span>
                    يوجد جدول بنفس الاسم في شهر {getArabicMonthName(newTableMonth)} {newTableYear}؛ لمنع التشابه واللبس سيُحفظ باسم: <strong>{addModalNameValidation.suggestedName}</strong>
                  </span>
                </div>
              )}

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  وصف مختصر (اختياري)
                </label>
                <input
                  type="text"
                  value={newTableDesc}
                  onChange={(e) => setNewTableDesc(e.target.value)}
                  placeholder="مثال: أوامر العمل المستلمة بعد تاريخ 15..."
                  className="w-full px-3.5 py-2 text-xs bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1.5">
                  تمييز لون الجدول
                </label>
                <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
                  {TABLE_COLORS.map(c => (
                    <button
                      key={c.name}
                      type="button"
                      onClick={() => setNewTableColor(c.name)}
                      className={`flex items-center gap-1.5 p-2 rounded-xl border text-xs font-bold cursor-pointer transition-all ${
                        newTableColor === c.name 
                          ? 'border-indigo-600 bg-indigo-50/60 ring-2 ring-indigo-400' 
                          : 'border-slate-200 hover:bg-slate-50'
                      }`}
                    >
                      <div className={`w-3.5 h-3.5 rounded-full ${c.bg} shrink-0`} />
                      <span className="truncate">{c.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex items-center justify-between gap-2 pt-3 border-t border-slate-100">
                <span className="text-[11px] font-bold text-emerald-700 flex items-center gap-1">
                  <ShieldCheck className="w-4 h-4 text-emerald-600" />
                  <span>الوجهة: شهر {getArabicMonthName(newTableMonth)} {newTableYear}</span>
                </span>

                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={() => setIsAddModalOpen(false)}
                    className="px-4 py-2 rounded-xl text-xs font-bold text-slate-600 hover:bg-slate-100 cursor-pointer"
                  >
                    إلغاء
                  </button>
                  <button
                    type="submit"
                    className="px-5 py-2.5 rounded-xl text-xs font-black text-white bg-indigo-600 hover:bg-indigo-700 shadow-sm cursor-pointer flex items-center gap-1.5"
                  >
                    <CheckCircle2 className="w-4 h-4" />
                    <span>إدراج الجدول الآن</span>
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal: Edit Table (including moving to another Year/Month safely) */}
      {editingTable && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/75 backdrop-blur-sm animate-in fade-in">
          <div className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl border border-slate-200 text-right">
            <div className="flex items-center justify-between mb-4 pb-3 border-b border-slate-100">
              <h4 className="text-base font-black text-slate-900">
                تعديل بيانات الجدول أو تغيير سنته وشهره
              </h4>
              <button
                type="button"
                onClick={() => setEditingTable(null)}
                className="p-1 rounded-lg text-slate-400 hover:text-slate-700 cursor-pointer"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleEditSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-3 p-3 rounded-2xl bg-slate-50 border border-slate-200">
                <div>
                  <label className="block text-[11px] font-bold text-slate-700 mb-1">
                    السنة المخصصة للجدول *
                  </label>
                  <select
                    value={editingTable.year}
                    onChange={(e) => setEditingTable({ ...editingTable, year: Number(e.target.value) })}
                    className="w-full px-3 py-2 text-xs font-black bg-white border border-slate-300 rounded-xl"
                  >
                    {availableYears.map(y => (
                      <option key={y} value={y}>
                        سنة {y} م
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-[11px] font-bold text-slate-700 mb-1">
                    الشهر المخصص للجدول *
                  </label>
                  <select
                    value={editingTable.month === 'all' ? defaultNumericMonth : Number(editingTable.month)}
                    onChange={(e) => setEditingTable({ ...editingTable, month: Number(e.target.value) })}
                    className="w-full px-3 py-2 text-xs font-black bg-white border border-slate-300 rounded-xl"
                  >
                    {ARABIC_MONTHS.map(m => (
                      <option key={m.num} value={m.num}>
                        شهر {m.num} - {m.name} ({editingTable.year})
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  اسم الجدول *
                </label>
                <input
                  type="text"
                  required
                  value={editingTable.name}
                  onChange={(e) => setEditingTable({ ...editingTable, name: e.target.value })}
                  className="w-full px-3.5 py-2 text-xs bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-indigo-500 font-bold"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  الوصف
                </label>
                <input
                  type="text"
                  value={editingTable.description || ''}
                  onChange={(e) => setEditingTable({ ...editingTable, description: e.target.value })}
                  className="w-full px-3.5 py-2 text-xs bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1.5">
                  اللون
                </label>
                <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
                  {TABLE_COLORS.map(c => (
                    <button
                      key={c.name}
                      type="button"
                      onClick={() => setEditingTable({ ...editingTable, color: c.name })}
                      className={`flex items-center gap-1.5 p-2 rounded-xl border text-xs font-bold cursor-pointer transition-all ${
                        editingTable.color === c.name 
                          ? 'border-indigo-600 bg-indigo-50/60 ring-2 ring-indigo-400' 
                          : 'border-slate-200 hover:bg-slate-50'
                      }`}
                    >
                      <div className={`w-3.5 h-3.5 rounded-full ${c.bg} shrink-0`} />
                      <span className="truncate">{c.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="flex items-center justify-end gap-2 pt-3 border-t border-slate-100">
                <button
                  type="button"
                  onClick={() => setEditingTable(null)}
                  className="px-4 py-2 rounded-xl text-xs font-bold text-slate-600 hover:bg-slate-100 cursor-pointer"
                >
                  إلغاء
                </button>
                <button
                  type="submit"
                  className="px-5 py-2 rounded-xl text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 shadow-sm cursor-pointer"
                >
                  حفظ التعديلات ومزامنة الأوامر
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal: Delete Table Confirmation */}
      {deleteConfirmTable && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/75 backdrop-blur-sm animate-in fade-in">
          <div className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl border border-slate-200 text-right">
            <div className="flex items-center gap-3 text-rose-600 mb-3">
              <div className="p-2 bg-rose-100 rounded-xl">
                <Trash2 className="w-5 h-5" />
              </div>
              <h4 className="text-base font-black text-slate-900">
                حذف الجدول ({deleteConfirmTable.name})
              </h4>
            </div>

            <p className="text-xs text-slate-600 leading-relaxed mb-5">
              أنت على وشك حذف هذا الجدول ({deleteConfirmTable.name}). يحتوي الجدول حالياً على{' '}
              <strong className="text-slate-900 font-mono font-black">
                {ordersCountMap.get(deleteConfirmTable.id) || (isDefaultTableId(deleteConfirmTable.id) ? defaultTableOrdersCount : 0)}
              </strong>{' '}
              أمر عمل. سيتم حذف هذا الجدول وسجلاته بشكل مستقل وتام دون ترحيل أوامره إلى أي جدول آخر ودون التأثير على أي جداول أخرى بالمنصة.
            </p>

            <div className="flex items-center justify-end gap-2 pt-3 border-t border-slate-100">
              <button
                type="button"
                onClick={() => setDeleteConfirmTable(null)}
                className="px-4 py-2 rounded-xl text-xs font-bold text-slate-600 hover:bg-slate-100 cursor-pointer"
              >
                إلغاء
              </button>
              <button
                type="button"
                onClick={handleDeleteSubmit}
                className="px-5 py-2 rounded-xl text-xs font-bold text-white bg-rose-600 hover:bg-rose-700 shadow-sm cursor-pointer"
              >
                تأكيد حذف الجدول
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

src/components/Navbar.tsx:
import React, { useState, useEffect, useRef } from 'react';
import { 
  Users, 
  RefreshCw, 
  Calendar, 
  Clock, 
  Zap, 
  ChevronsRight, 
  ChevronsLeft, 
  Maximize, 
  Minimize, 
  UserCheck, 
  Bell, 
  LogOut, 
  ShieldCheck,
  Wifi,
  WifiOff
} from 'lucide-react';
import { SyncStatus } from '../services/realtimeService';
import { PlatformUser, ConnectedUserInfo } from '../types';
import { hasUserPermission } from '../utils/security';

interface NavbarProps {
  syncStatus: SyncStatus;
  onlineCount: number;
  connectedUsers?: ConnectedUserInfo[];
  onToggleSidebar: () => void;
  isSidebarOpen: boolean;
  onResetData: () => void;
  onManualSync?: () => void;
  isManualSyncing?: boolean;
  totalOrdersCount: number;
  ready155Count: number;
  isSoundMuted?: boolean;
  onToggleSound?: () => void;
  onOpenWeeklyReport?: () => void;
  onOpenOfficeComparison?: () => void;
  onOpenContractorComparison?: () => void;
  onOpenComprehensiveReports?: () => void;
  onOpenExportModal?: (openEmail?: boolean) => void;
  onOpenDataRecovery?: () => void;
  onOpenNotificationSettings?: () => void;
  unreadNotificationsCount?: number;
  onOpenCommandPalette?: () => void;
  activeYear?: number;
  activeMonth?: number | 'all';
  onOpenYearMonthPicker?: () => void;
  isSessionUnlockedState?: boolean;
  onOpenPinModal?: () => void;
  onLockSession?: () => void;
  currentUser?: PlatformUser | null;
  onOpenPermissionsManager?: () => void;
  onLogout?: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({
  syncStatus,
  onlineCount,
  connectedUsers = [],
  onToggleSidebar,
  isSidebarOpen,
  onOpenNotificationSettings,
  unreadNotificationsCount = 0,
  currentUser,
  onOpenPermissionsManager,
  onLogout
}) => {
  const [currentDateTime, setCurrentDateTime] = useState<Date>(new Date());
  const [isFullscreen, setIsFullscreen] = useState<boolean>(false);
  const [isSyncMenuOpen, setIsSyncMenuOpen] = useState<boolean>(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState<boolean>(false);

  const syncMenuRef = useRef<HTMLDivElement>(null);
  const userMenuRef = useRef<HTMLDivElement>(null);

  // Real-time clock tick every second
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentDateTime(new Date());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // Fullscreen change listener
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(Boolean(document.fullscreenElement));
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  // Close menus on outside click
  useEffect(() => {
    const handleOutsideClick = (e: MouseEvent) => {
      const target = e.target as Node;
      if (syncMenuRef.current && !syncMenuRef.current.contains(target)) {
        setIsSyncMenuOpen(false);
      }
      if (userMenuRef.current && !userMenuRef.current.contains(target)) {
        setIsUserMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleOutsideClick);
    return () => document.removeEventListener('mousedown', handleOutsideClick);
  }, []);

  const handleToggleFullscreen = async () => {
    try {
      if (!document.fullscreenElement) {
        if (document.documentElement.requestFullscreen) {
          await document.documentElement.requestFullscreen();
        }
      } else {
        if (document.exitFullscreen) {
          await document.exitFullscreen();
        }
      }
    } catch (err) {
      console.warn('Fullscreen toggle failed:', err);
    }
  };

  // Format 12-hour Time with seconds & AM/PM
  const formattedTime = new Intl.DateTimeFormat('ar-SA-u-ca-gregory-nu-latn', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: true
  }).format(currentDateTime);

  // Gregorian Date in Arabic
  const formattedDate = new Intl.DateTimeFormat('ar-SA-u-ca-gregory-nu-latn', {
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    year: 'numeric'
  }).format(currentDateTime);

  return (
    <header className="fixed top-0 left-0 right-0 z-40 bg-gradient-to-l from-slate-800 via-[#1e293b] to-indigo-950 text-white border-b border-slate-700/90 shadow-md font-['Cairo',sans-serif] select-none">
      <div className="w-full max-w-full px-2 sm:px-4 flex items-center justify-between h-14">
        <div className="flex items-center gap-2 sm:gap-3 shrink-0">
          <button
            type="button"
            onClick={onToggleSidebar}
            id="btn-nav-sidebar-arrow-toggle"
            className="p-1.5 sm:p-2 rounded-xl border border-slate-600/80 bg-slate-700/70 hover:bg-slate-600/80 text-amber-300 transition-all cursor-pointer shadow-2xs"
            title={isSidebarOpen ? 'إخفاء القائمة الجانبية' : 'إظهار القائمة الجانبية'}
            aria-label="تبديل القائمة الجانبية"
          >
            {isSidebarOpen ? (
              <ChevronsRight className="w-4 h-4 sm:w-5 sm:h-5 text-amber-300 stroke-[2.2]" />
            ) : (
              <ChevronsLeft className="w-4 h-4 sm:w-5 sm:h-5 text-amber-300 stroke-[2.2]" />
            )}
          </button>

          <div className="flex items-center gap-2.5 shrink-0 min-w-0">
            <div className="w-8 h-8 rounded-xl bg-gradient-to-br from-amber-400/25 to-orange-500/20 border border-amber-400/40 flex items-center justify-center text-amber-300 shadow-2xs shrink-0">
              <Zap className="w-4 h-4" />
            </div>
            <div className="text-right flex flex-col justify-center leading-tight min-w-0 max-w-[150px] xs:max-w-[210px] sm:max-w-[320px] md:max-w-none overflow-hidden">
              <div className="whitespace-nowrap animate-ticker-rtl md:animate-none">
                <h1 className="text-xs sm:text-sm font-black tracking-wide text-white">
                  حوكمة جودة اعمال الانشاءات
                </h1>
                <h2 className="text-[10px] sm:text-[11px] font-bold text-slate-300">
                  ادارة كهرباء الحدود الشمالية - المساندة الفنية
                </h2>
              </div>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-1.5 sm:gap-2 shrink-0">
          {/* 1. اسم المستخدم */}
          <div className="relative" ref={userMenuRef}>
            <button
              type="button"
              onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
              className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl bg-slate-700/75 hover:bg-slate-600/85 text-white border border-slate-600/80 transition-all cursor-pointer text-xs font-bold shadow-2xs"
              title="بيانات المستخدم الحالي"
            >
              <UserCheck className="w-3.5 h-3.5 text-amber-300" />
              <span className="truncate max-w-[110px] sm:max-w-[140px]">
                {currentUser?.displayName || currentUser?.username || 'المستخدم'}
              </span>
            </button>

            {isUserMenuOpen && (
              <div className="absolute left-0 mt-2 w-64 bg-gradient-to-br from-[#f8fafc] via-[#f1f5f9] to-[#eef2ff] rounded-2xl shadow-xl border border-slate-300 text-slate-900 p-3 z-50 animate-in fade-in zoom-in-95 text-right font-['Cairo',sans-serif]">
                <div className="pb-2.5 mb-2 border-b border-slate-300/80">
                  <div className="font-black text-xs text-slate-900">
                    {currentUser?.displayName || currentUser?.username}
                  </div>
                  <div className="text-[11px] text-slate-700 font-bold mt-0.5">
                    {currentUser?.roleTitle || 'عضو المنظومة'}
                  </div>
                  {currentUser?.email && (
                    <div className="text-[10px] text-slate-600 font-mono mt-0.5">
                      {currentUser.email}
                    </div>
                  )}
                </div>

                {onOpenPermissionsManager && hasUserPermission(currentUser, 'manageUsers') && (
                  <button
                    type="button"
                    onClick={() => {
                      setIsUserMenuOpen(false);
                      onOpenPermissionsManager();
                    }}
                    className="w-full flex items-center gap-2 p-2 rounded-xl text-xs font-black text-slate-800 hover:bg-blue-100/70 hover:text-blue-950 transition-colors cursor-pointer text-right"
                  >
                    <ShieldCheck className="w-4 h-4 text-blue-700" />
                    <span>إدارة المستخدمين والصلاحيات</span>
                  </button>
                )}

                {onLogout && (
                  <button
                    type="button"
                    onClick={() => {
                      setIsUserMenuOpen(false);
                      onLogout();
                    }}
                    className="w-full flex items-center gap-2 p-2 rounded-xl text-xs font-black text-rose-800 hover:bg-rose-100/80 transition-colors cursor-pointer mt-1 text-right"
                  >
                    <LogOut className="w-4 h-4 text-rose-700" />
                    <span>تسجيل الخروج</span>
                  </button>
                )}
              </div>
            )}
          </div>

          {/* 2. التاريخ */}
          <div 
            className="hidden md:flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl bg-slate-800/80 border border-slate-600/80 text-xs font-bold text-slate-100 shadow-2xs"
            title="التاريخ الحالي"
          >
            <Calendar className="w-3.5 h-3.5 text-sky-300" />
            <span className="font-mono text-[11px] whitespace-nowrap">{formattedDate}</span>
          </div>

          {/* 3. الوقت */}
          <div 
            className="hidden md:flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl bg-slate-800/80 border border-slate-600/80 text-xs font-bold text-slate-100 shadow-2xs"
            title="الوقت الحالي"
          >
            <Clock className="w-3.5 h-3.5 text-amber-300" />
            <span className="font-mono text-[11px] whitespace-nowrap">{formattedTime}</span>
          </div>

          {/* 4. التنبيهات */}
          <button
            type="button"
            onClick={onOpenNotificationSettings}
            className="relative p-2 rounded-xl bg-slate-700/75 hover:bg-slate-600/85 text-amber-300 border border-slate-600/80 transition-all cursor-pointer shadow-2xs"
            title="التنبيهات"
            aria-label="التنبيهات"
          >
            <Bell className="w-4 h-4" />
            {unreadNotificationsCount > 0 && (
              <span className="absolute -top-1 -right-1 min-w-[17px] h-[17px] rounded-full bg-rose-600 text-white text-[10px] font-bold flex items-center justify-center px-1 border border-white">
                {unreadNotificationsCount}
              </span>
            )}
          </button>

          {/* 5. زر المتصلون بالمنصة */}
          <div className="relative" ref={syncMenuRef}>
            <button
              type="button"
              onClick={() => setIsSyncMenuOpen(!isSyncMenuOpen)}
              className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl bg-slate-700/75 hover:bg-slate-600/85 text-white border border-slate-600/80 transition-all cursor-pointer text-xs font-bold shadow-2xs"
              title="المتصلون بالمنصة الآن والمزامنة التلقائية"
            >
              <Users className="w-3.5 h-3.5 text-emerald-300" />
              <span className="text-[11px]">المتصلون</span>
              <span className="px-1.5 py-0.2 rounded-md bg-emerald-400/20 text-emerald-200 text-[10px] font-mono font-bold flex items-center gap-1 border border-emerald-400/40">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-ping inline-block" />
                <span>{onlineCount}</span>
              </span>
            </button>

            {isSyncMenuOpen && (
              <div className="absolute left-0 mt-2 w-80 bg-gradient-to-br from-[#f8fafc] via-[#f1f5f9] to-[#eef2ff] rounded-2xl shadow-xl border border-slate-300 text-slate-900 p-3.5 z-50 animate-in fade-in zoom-in-95 text-right font-['Cairo',sans-serif]">
                <div className="flex items-center justify-between pb-2.5 mb-2.5 border-b border-slate-300/80">
                  <div className="flex items-center gap-2">
                    <Users className="w-4 h-4 text-emerald-700" />
                    <span className="text-xs font-black text-slate-900">المتصلون بالمنصة الآن</span>
                  </div>
                  <span className="text-[10px] font-black px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-900 border border-emerald-300 flex items-center gap-1">
                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                    <span>{onlineCount} متصل</span>
                  </span>
                </div>

                <div className="p-2 rounded-xl bg-emerald-50/80 border border-emerald-200 text-[11px] font-semibold text-emerald-900 mb-3 flex items-center gap-1.5">
                  <Wifi className="w-3.5 h-3.5 text-emerald-600 shrink-0" />
                  <span>المزامنة التلقائية الفورية مفعّلة ولحظية بين الجميع دون الحاجة لأي زر</span>
                </div>

                <div className="space-y-1.5 max-h-56 overflow-y-auto pr-0.5">
                  {connectedUsers && connectedUsers.length > 0 ? (
                    connectedUsers.map((u, idx) => (
                      <div
                        key={u.clientId || idx}
                        className="flex items-center justify-between p-2 rounded-xl bg-white border border-slate-200 shadow-2xs"
                      >
                        <div className="flex items-center gap-2 min-w-0">
                          <div className="w-7 h-7 rounded-lg bg-emerald-100 text-emerald-800 font-bold text-xs flex items-center justify-center shrink-0 border border-emerald-200">
                            {(u.userName || 'م')[0]}
                          </div>
                          <div className="flex flex-col min-w-0">
                            <span className="text-xs font-bold text-slate-900 truncate">
                              {u.userName || 'مستخدم متصل'}
                            </span>
                            <span className="text-[10px] text-slate-500 font-medium truncate">
                              {u.userRole || 'عضو المنظومة'}
                            </span>
                          </div>
                        </div>

                        <div className="flex items-center gap-1 text-[10px] font-bold text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-md border border-emerald-200 shrink-0">
                          <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                          <span>متصل</span>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="flex items-center justify-between p-2 rounded-xl bg-white border border-slate-200 shadow-2xs">
                      <div className="flex items-center gap-2 min-w-0">
                        <div className="w-7 h-7 rounded-lg bg-emerald-100 text-emerald-800 font-bold text-xs flex items-center justify-center shrink-0 border border-emerald-200">
                          {(currentUser?.displayName || currentUser?.username || 'م')[0]}
                        </div>
                        <div className="flex flex-col min-w-0">
                          <span className="text-xs font-bold text-slate-900 truncate">
                            {currentUser?.displayName || currentUser?.username || 'حسابك الحاضر'}
                          </span>
                          <span className="text-[10px] text-slate-500 font-medium truncate">
                            {currentUser?.roleTitle || 'عضو المنظومة'}
                          </span>
                        </div>
                      </div>

                      <div className="flex items-center gap-1 text-[10px] font-bold text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-md border border-emerald-200 shrink-0">
                        <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                        <span>نشط الآن</span>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* 6. العرض */}
          <button
            type="button"
            onClick={handleToggleFullscreen}
            className="p-2 rounded-xl bg-slate-700/75 hover:bg-slate-600/85 text-sky-300 border border-slate-600/80 transition-all cursor-pointer shadow-2xs"
            title={isFullscreen ? 'تصغير الشاشة' : 'العرض في كامل الشاشة'}
            aria-label="العرض"
          >
            {isFullscreen ? (
              <Minimize className="w-4 h-4 text-sky-300" />
            ) : (
              <Maximize className="w-4 h-4 text-sky-300" />
            )}
          </button>

          {/* 7. خروج */}
          {onLogout && (
            <button
              type="button"
              onClick={onLogout}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-rose-500/20 hover:bg-rose-500/35 text-rose-200 border border-rose-400/40 transition-all cursor-pointer text-xs font-black shadow-2xs"
              title="تسجيل الخروج من المنصة"
              aria-label="تسجيل الخروج"
            >
              <LogOut className="w-3.5 h-3.5" />
              <span>خروج</span>
            </button>
          )}
        </div>
      </div>
    </header>
  );
};

import React, { useState } from 'react';
import { BellRing, Sparkles, CheckCircle2, X, Loader2 } from 'lucide-react';
import { notificationService } from '../services/notificationService';
import { soundService } from '../services/soundService';

interface NotificationPromptBannerProps {
  isOpen: boolean;
  onClose: () => void;
  onSubscribed: () => void;
  onShowToast: (message: string, type?: 'create' | 'update' | 'delete' | 'sync') => void;
}

export const NotificationPromptBanner: React.FC<NotificationPromptBannerProps> = ({
  isOpen,
  onClose,
  onSubscribed,
  onShowToast
}) => {
  const [isSubscribing, setIsSubscribing] = useState(false);

  if (!isOpen) return null;

  const handleActivate = async () => {
    setIsSubscribing(true);
    try {
      const res = await notificationService.requestPermissionAndSubscribe();
      if (res.success) {
        soundService.playActionSound('create');
        onShowToast('تم تفعيل خدمة الإشعارات الخارجية بنجاح! ستصلك التنبيهات حتى أثناء إغلاق المنصة 🔔', 'create');
        onSubscribed();
        onClose();
      } else if (res.permission === 'denied') {
        onShowToast('تم حظر الإشعارات في المتصفح. يمكنك تفعيلها من إعدادات المتصفح', 'delete');
        onClose();
      }
    } catch (err: any) {
      console.warn('Subscription failed:', err);
    } finally {
      setIsSubscribing(false);
    }
  };

  const handleDismiss = () => {
    try {
      sessionStorage.setItem('p155_notification_banner_dismissed', 'true');
    } catch (_) {}
    onClose();
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 max-w-md w-[calc(100vw-3rem)] font-['Cairo',sans-serif] animate-in fade-in slide-in-from-bottom-6 duration-300">
      <div className="bg-gradient-to-r from-slate-950 via-slate-900 to-emerald-950 text-white p-4 sm:p-5 rounded-2xl shadow-2xl border-2 border-emerald-500/40 relative overflow-hidden backdrop-blur-md">

        {/* Glow ambient background */}
        <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 rounded-full blur-2xl pointer-events-none" />

        <div className="flex items-start gap-3.5 relative z-10">
          <div className="w-11 h-11 rounded-2xl bg-emerald-500/20 border border-emerald-400/40 text-emerald-300 flex items-center justify-center shrink-0 shadow-inner">
            <BellRing className="w-5 h-5 animate-pulse" />
          </div>

          <div className="flex-1">
            <div className="flex items-center gap-2 flex-wrap">
              <h4 className="text-sm font-black text-white">
                تفعيل الإشعارات الفورية الذكية
              </h4>
              <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-400/30">
                والمنصة مغلقة 24/7
              </span>
            </div>

            <p className="text-xs text-slate-300 mt-1 leading-relaxed">
              هل ترغب باستلام تنبيهات فورية بكل إجراء وتعديل لأوامر العمل على سطح مكتبك أو شاشة هاتفك حتى لو كان المتصفح أو الرابط مغلقاً؟
            </p>

            <div className="mt-3.5 flex items-center gap-2.5">
              <button
                type="button"
                disabled={isSubscribing}
                onClick={handleActivate}
                className="inline-flex items-center justify-center gap-1.5 px-4 py-2 rounded-xl bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white text-xs font-black shadow-md border border-emerald-400/40 transition-all cursor-pointer disabled:opacity-50 active:scale-95"
              >
                {isSubscribing ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                    <span>جاري التفعيل...</span>
                  </>
                ) : (
                  <>
                    <Sparkles className="w-3.5 h-3.5" />
                    <span>تفعيل الإشعارات الآن ⚡</span>
                  </>
                )}
              </button>

              <button
                type="button"
                onClick={handleDismiss}
                className="px-3 py-2 rounded-xl text-xs font-semibold text-slate-400 hover:text-slate-200 hover:bg-white/10 transition-colors cursor-pointer"
              >
                لاحقاً
              </button>
            </div>
          </div>

          <button
            type="button"
            onClick={handleDismiss}
            className="p-1 text-slate-400 hover:text-white rounded-lg transition-colors cursor-pointer shrink-0"
            title="إغلاق"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

src/components/NotificationSettingsModal:
import React, { useState, useEffect, useMemo } from 'react';
import { 
  X, 
  Bell, 
  BellRing, 
  CheckCircle2, 
  AlertCircle, 
  Sparkles, 
  Send, 
  Smartphone, 
  Monitor, 
  PlusCircle, 
  Edit3, 
  Trash2, 
  FileSpreadsheet, 
  ShieldCheck, 
  RefreshCw,
  Loader2,
  Users,
  Radio,
  UserCheck,
  CheckCheck,
  Clock,
  Megaphone,
  Wifi,
  Activity,
  Building2,
  FileText,
  Filter
} from 'lucide-react';
import { notificationService, NotificationPreferences, UserNotificationIdentity } from '../services/notificationService';
import { realtime, SyncStatus } from '../services/realtimeService';
import { soundService } from '../services/soundService';
import { ConnectedUserInfo, LiveNotificationItem } from '../types';

export interface NotificationSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  onShowAppNotification?: (message: string, type?: 'create' | 'update' | 'delete' | 'sync') => void;
  initialTab?: 'feed' | 'broadcast' | 'users' | 'settings';
  officesList?: string[];
}

export const NotificationSettingsModal: React.FC<NotificationSettingsModalProps> = ({
  isOpen,
  onClose,
  onShowAppNotification,
  initialTab = 'feed',
  officesList = []
}) => {
  const [activeTab, setActiveTab] = useState<'feed' | 'broadcast' | 'users' | 'settings'>(initialTab);
  const [permission, setPermission] = useState<NotificationPermission>('default');
  const [isSubscribing, setIsSubscribing] = useState(false);
  const [isTesting, setIsTesting] = useState(false);
  const [testResult, setTestResult] = useState<string | null>(null);
  const [prefs, setPrefs] = useState<NotificationPreferences>(() => notificationService.getPreferences());
  const [isSupported, setIsSupported] = useState(true);

  // User Identity State
  const [identity, setIdentity] = useState<UserNotificationIdentity>(() => notificationService.getUserIdentity());
  const [userNameInput, setUserNameInput] = useState(identity.userName);
  const [userRoleInput, setUserRoleInput] = useState(identity.userRole);
  const [identitySaved, setIdentitySaved] = useState(false);

  // Live Notification History State
  const [notifications, setNotifications] = useState<LiveNotificationItem[]>(() => notificationService.getHistory());
  const [unreadCount, setUnreadCount] = useState<number>(() => notificationService.getUnreadCount());
  const [feedFilter, setFeedFilter] = useState<'all' | 'unread' | 'create' | 'update' | 'delete' | 'broadcast'>('all');

  // Connected Users & Realtime Status
  const [syncStatus, setSyncStatus] = useState<SyncStatus>(() => realtime.getStatus());
  const [onlineCount, setOnlineCount] = useState<number>(() => realtime.getOnlineCount());
  const [connectedUsers, setConnectedUsers] = useState<ConnectedUserInfo[]>(() => realtime.getConnectedUsers());
  const [latencyMs, setLatencyMs] = useState<number>(() => realtime.getLatencyMs());
  const [isSyncingNow, setIsSyncingNow] = useState(false);

  // Broadcast Alert Form State
  const [broadcastTitle, setBroadcastTitle] = useState('تنبيه فوري لفريق تدقيق إجراء 155');
  const [broadcastMessage, setBroadcastMessage] = useState('');
  const [broadcastPriority, setBroadcastPriority] = useState<'normal' | 'high' | 'urgent'>('high');
  const [broadcastOffice, setBroadcastOffice] = useState<string>('all');
  const [isSendingBroadcast, setIsSendingBroadcast] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setIsSupported(notificationService.isSupported());
      setPermission(notificationService.getPermissionStatus());
      setPrefs(notificationService.getPreferences());
      const currentId = notificationService.getUserIdentity();
      setIdentity(currentId);
      setUserNameInput(currentId.userName);
      setUserRoleInput(currentId.userRole);
      setNotifications(notificationService.getHistory());
      setUnreadCount(notificationService.getUnreadCount());
      setConnectedUsers(realtime.getConnectedUsers());
      setOnlineCount(realtime.getOnlineCount());
      setLatencyMs(realtime.getLatencyMs());
      setTestResult(null);

      // Sync latest server notifications log
      notificationService.fetchServerNotificationsLog().catch(() => {});
    }
  }, [isOpen]);

  useEffect(() => {
    const unsubHistory = notificationService.subscribeHistory((items, unread) => {
      setNotifications(items);
      setUnreadCount(unread);
    });

    const unsubStatus = realtime.onStatusChange((status, count, users) => {
      setSyncStatus(status);
      setOnlineCount(count);
      if (users) setConnectedUsers(users);
      setLatencyMs(realtime.getLatencyMs());
    });

    return () => {
      unsubHistory();
      unsubStatus();
    };
  }, []);

  const filteredNotifications = useMemo(() => {
    return notifications.filter((item) => {
      if (feedFilter === 'unread') return !item.read;
      if (feedFilter === 'create') return item.type === 'create' || item.type === 'import';
      if (feedFilter === 'update') return item.type === 'update' || item.type === 'office' || item.type === 'restore';
      if (feedFilter === 'delete') return item.type === 'delete';
      if (feedFilter === 'broadcast') return item.type === 'broadcast' || item.type === 'sync';
      return true;
    });
  }, [notifications, feedFilter]);

  if (!isOpen) return null;

  const handleSaveIdentity = (e: React.FormEvent) => {
    e.preventDefault();
    const updated = notificationService.saveUserIdentity({
      userName: userNameInput.trim() || 'مهندس تدقيق 155',
      userRole: userRoleInput.trim() || 'مدقق جودة ومطابقة فنية'
    });
    setIdentity(updated);
    realtime.updatePresenceIdentity();
    setIdentitySaved(true);
    soundService.playActionSound('update');
    if (onShowAppNotification) {
      onShowAppNotification(`تم اعتماد اسم المعرف الفوري (${updated.userName}) لكافة المستخدمين المتصلين`, 'update');
    }
    setTimeout(() => setIdentitySaved(false), 3000);
  };

  const handleRequestPermission = async () => {
    setIsSubscribing(true);
    setTestResult(null);

    try {
      const result = await notificationService.requestPermissionAndSubscribe();
      setPermission(result.permission);

      if (result.success) {
        soundService.playActionSound('create');
        if (onShowAppNotification) {
          onShowAppNotification('تم تفعيل خدمة الإشعارات الفورية بالخلفية بنجاح!', 'create');
        }
      } else if (result.error) {
        if (onShowAppNotification) {
          onShowAppNotification(result.error, 'delete');
        }
      }
    } catch (err: any) {
      console.error(err);
    } finally {
      setIsSubscribing(false);
    }
  };

  const handleSendTestNotification = async () => {
    setIsTesting(true);
    setTestResult(null);

    try {
      soundService.playActionSound('notification');
      const res = await notificationService.sendTestNotification();
      if (res.success) {
        setTestResult('تم إرسال التنبيه التجريبي بنجاح لجميع الأجهزة المشتركة ومركز الإشعارات!');
        if (onShowAppNotification) {
          onShowAppNotification('تم إرسال إشعار تجريبي فوري إلى جهازك الآن', 'update');
        }
      } else {
        setTestResult('تعذر إرسال الإشعار الخارجي. تأكد من منح الإذن للإشعارات في المتصفح.');
      }
    } catch (err: any) {
      setTestResult('حدث خطأ أثناء إرسال التنبيه التجريبي.');
    } finally {
      setIsTesting(false);
    }
  };

  const handleSendBroadcast = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!broadcastMessage.trim()) return;

    setIsSendingBroadcast(true);
    try {
      const ok = await realtime.sendBroadcastAlert({
        title: broadcastTitle.trim() || 'تنبيه فوري - منصة إجراء 155',
        message: broadcastMessage.trim(),
        priority: broadcastPriority,
        office: broadcastOffice === 'all' ? undefined : broadcastOffice
      });

      if (ok) {
        soundService.playActionSound('notification');
        setBroadcastMessage('');
        setActiveTab('feed');
        if (onShowAppNotification) {
          onShowAppNotification('تم بث الإشعار الفوري لكافة المستخدمين المتصلين بنجاح!', 'create');
        }
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsSendingBroadcast(false);
    }
  };

  const handleManualForceSync = async () => {
    setIsSyncingNow(true);
    try {
      await realtime.forceSyncNow();
      await notificationService.fetchServerNotificationsLog();
      soundService.playActionSound('sync');
      if (onShowAppNotification) {
        onShowAppNotification('تمت المزامنة الفورية وتحديث قائمة المتصلين والإشعارات بنجاح', 'sync');
      }
    } finally {
      setIsSyncingNow(false);
    }
  };

  const handleTogglePreference = (key: keyof NotificationPreferences) => {
    const updated = {
      ...prefs,
      [key]: !prefs[key]
    };
    setPrefs(updated);
    notificationService.savePreferences(updated);
  };

  const formatTimeAgo = (isoString: string) => {
    try {
      const date = new Date(isoString);
      const diffSec = Math.floor((Date.now() - date.getTime()) / 1000);
      if (diffSec < 10) return 'الآن';
      if (diffSec < 60) return `منذ ${diffSec} ثانية`;
      const diffMin = Math.floor(diffSec / 60);
      if (diffMin < 60) return `منذ ${diffMin} دقيقة`;
      const diffHr = Math.floor(diffMin / 60);
      if (diffHr < 24) return `منذ ${diffHr} ساعة`;
      return new Intl.DateTimeFormat('ar-SA-u-ca-gregory-nu-latn', {
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      }).format(date);
    } catch {
      return '';
    }
  };

  const getNotificationBadgeStyle = (type: LiveNotificationItem['type'], priority?: string) => {
    if (priority === 'urgent') {
      return 'bg-rose-100 text-rose-800 border-rose-300';
    }
    switch (type) {
      case 'create':
      case 'import':
        return 'bg-emerald-100 text-emerald-800 border-emerald-300';
      case 'delete':
        return 'bg-rose-100 text-rose-800 border-rose-300';
      case 'broadcast':
        return 'bg-amber-100 text-amber-900 border-amber-300';
      case 'sync':
      case 'restore':
        return 'bg-indigo-100 text-indigo-800 border-indigo-300';
      default:
        return 'bg-blue-100 text-blue-800 border-blue-300';
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-900/80 backdrop-blur-xs flex items-center justify-center p-2 sm:p-4 text-right font-['Cairo',sans-serif]">
      <div className="bg-white rounded-3xl shadow-2xl border border-slate-200 max-w-3xl w-full my-4 overflow-hidden flex flex-col animate-in fade-in zoom-in-95 duration-150">

        {/* Header */}
        <div className="p-4 sm:p-5 border-b border-slate-100 flex items-center justify-between bg-gradient-to-r from-slate-950 via-slate-900 to-emerald-950 text-white">
          <div className="flex items-center gap-3">
            <div className="relative w-12 h-12 rounded-2xl bg-emerald-500/20 border border-emerald-400/40 text-emerald-300 flex items-center justify-center shadow-inner shrink-0">
              <BellRing className="w-6 h-6 animate-pulse" />
              {unreadCount > 0 && (
                <span className="absolute -top-1.5 -right-1.5 min-w-[20px] h-5 px-1 rounded-full bg-rose-600 text-white text-[11px] font-black flex items-center justify-center border-2 border-slate-950 shadow-md">
                  {unreadCount}
                </span>
              )}
            </div>
            <div>
              <div className="flex items-center gap-2 flex-wrap">
                <h3 className="text-base sm:text-xl font-black text-white">
                  مركز المزامنة الفورية والإشعارات المباشرة
                </h3>
                <span className="px-2.5 py-0.5 rounded-full text-[11px] font-mono font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-400/30 flex items-center gap-1.5">
                  <span className="w-2 h-2 rounded-full bg-emerald-400 animate-ping" />
                  <span>{onlineCount} متصل الآن</span>
                </span>
                {latencyMs > 0 && (
                  <span className="px-2 py-0.5 rounded-full text-[10px] font-mono font-bold bg-blue-500/20 text-blue-300 border border-blue-400/30">
                    {latencyMs}ms
                  </span>
                )}
              </div>
              <p className="text-xs text-slate-300 mt-1">
                مزامنة لحظية ثلاثية القنوات (WebSocket + SSE + Web Push) وتنبيهات فورية بين جميع المستخدمين
              </p>
            </div>
          </div>
          <button 
            type="button" 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-white hover:bg-white/10 rounded-xl transition-colors cursor-pointer"
            title="إغلاق"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Navigation Tabs */}
        <div className="bg-slate-900 px-3 sm:px-5 py-2 border-b border-slate-800 flex items-center gap-1.5 overflow-x-auto scrollbar-none">
          <button
            type="button"
            onClick={() => {
              setActiveTab('feed');
              notificationService.markAllAsRead();
            }}
            className={`flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-black transition-all cursor-pointer whitespace-nowrap ${
              activeTab === 'feed'
                ? 'bg-emerald-600 text-white shadow-sm'
                : 'text-slate-300 hover:text-white hover:bg-slate-800'
            }`}
          >
            <Bell className="w-3.5 h-3.5" />
            <span>سجل الإشعارات الحية</span>
            {notifications.length > 0 && (
              <span className={`px-1.5 py-0.2 rounded-full text-[10px] font-mono ${
                activeTab === 'feed' ? 'bg-black/25 text-white' : 'bg-slate-800 text-emerald-400'
              }`}>
                {notifications.length}
              </span>
            )}
          </button>

          <button
            type="button"
            onClick={() => setActiveTab('broadcast')}
            className={`flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-black transition-all cursor-pointer whitespace-nowrap ${
              activeTab === 'broadcast'
                ? 'bg-amber-600 text-white shadow-sm'
                : 'text-slate-300 hover:text-white hover:bg-slate-800'
            }`}
          >
            <Megaphone className="w-3.5 h-3.5" />
            <span>إرسال تنبيه عاجل للجميع</span>
          </button>

          <button
            type="button"
            onClick={() => setActiveTab('users')}
            className={`flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-black transition-all cursor-pointer whitespace-nowrap ${
              activeTab === 'users'
                ? 'bg-blue-600 text-white shadow-sm'
                : 'text-slate-300 hover:text-white hover:bg-slate-800'
            }`}
          >
            <Users className="w-3.5 h-3.5" />
            <span>المتصلون الآن وهويتك</span>
            <span className="px-1.5 py-0.2 rounded-full text-[10px] font-mono bg-emerald-500/20 text-emerald-300 border border-emerald-400/30">
              {onlineCount}
            </span>
          </button>

          <button
            type="button"
            onClick={() => setActiveTab('settings')}
            className={`flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-black transition-all cursor-pointer whitespace-nowrap ${
              activeTab === 'settings'
                ? 'bg-indigo-600 text-white shadow-sm'
                : 'text-slate-300 hover:text-white hover:bg-slate-800'
            }`}
          >
            <ShieldCheck className="w-3.5 h-3.5" />
            <span>إعدادات الإشعارات والـ Push</span>
          </button>
        </div>

        {/* Modal Body */}
        <div className="p-4 sm:p-6 space-y-4 max-h-[72vh] overflow-y-auto bg-slate-50/60">

          {/* TAB 1: LIVE NOTIFICATION FEED */}
          {activeTab === 'feed' && (
            <div className="space-y-4">
              {/* Feed Controls Bar */}
              <div className="flex flex-wrap items-center justify-between gap-2 bg-white p-3 rounded-2xl border border-slate-200 shadow-2xs">
                <div className="flex items-center gap-1.5 flex-wrap">
                  <Filter className="w-3.5 h-3.5 text-slate-400 ml-1" />
                  {[
                    { key: 'all', label: 'الكل' },
                    { key: 'create', label: 'إضافات واستيراد' },
                    { key: 'update', label: 'تعديلات وحالات' },
                    { key: 'delete', label: 'حذف' },
                    { key: 'broadcast', label: 'تنبيهات عامة' }
                  ].map((f) => (
                    <button
                      key={f.key}
                      type="button"
                      onClick={() => setFeedFilter(f.key as any)}
                      className={`px-2.5 py-1 rounded-lg text-[11px] font-bold transition-colors cursor-pointer ${
                        feedFilter === f.key
                          ? 'bg-slate-900 text-white'
                          : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                      }`}
                    >
                      {f.label}
