                        حوكمة جودة اعمال الانشاءات
                      </span>
                      <span className="text-xs sm:text-[13px] font-bold text-slate-800 leading-tight">
                        منظومة ادارة كهرباء الحدود الشمالية
                      </span>
                      <span className="text-[11px] font-semibold text-slate-600 leading-tight">
                        المساندة الفنية
                      </span>
                    </div>

                    <div className="text-center">
                      <h2 className="text-xs sm:text-sm font-black text-slate-950">
                        مقارنة أداء المكاتب
                      </h2>
                    </div>

                    <div className="text-left font-mono text-xs font-bold text-slate-800">
                      التاريخ: {new Intl.DateTimeFormat('ar-SA-u-ca-gregory-nu-latn', { year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date())}
                    </div>
                  </div>

                  {/* ( مؤشرات الاداء ) */}
                  <div className="text-[11px] font-black text-slate-900 text-center -mb-2">
                    ( مؤشرات الاداء )
                  </div>
                  <div className="grid grid-cols-4 gap-3 bg-slate-50 p-3.5 rounded-xl border border-slate-200">
                    <div className="bg-white p-2.5 rounded-lg border border-slate-200/80">
                      <span className="text-[11px] text-slate-500 font-bold block">إجمالي أوامر المنظومة</span>
                      <span className="text-xl font-black text-slate-900 font-mono">{systemTotals.totalOrders}</span>
                    </div>
                    <div className="bg-emerald-50/60 p-2.5 rounded-lg border border-emerald-200">
                      <span className="text-[11px] text-emerald-800 font-bold block">مؤهل لإجراء 155 (جاهز)</span>
                      <span className="text-xl font-black text-emerald-700 font-mono">
                        {systemTotals.readyCount} <span className="text-xs">({systemTotals.avgCompletion}%)</span>
                      </span>
                    </div>
                    <div className="bg-amber-50/60 p-2.5 rounded-lg border border-amber-200">
                      <span className="text-[11px] text-amber-800 font-bold block">معلق لنواقص وملاحظات</span>
                      <span className="text-xl font-black text-amber-700 font-mono">{systemTotals.pendingCount}</span>
                    </div>
                    <div className="bg-blue-50/60 p-2.5 rounded-lg border border-blue-200">
                      <span className="text-[11px] text-blue-800 font-bold block">متوسط الجودة والأداء</span>
                      <span className="text-xl font-black text-blue-700 font-mono">{systemTotals.avgScore}/100</span>
                    </div>
                  </div>

                  {/* Printable Table */}
                  <div className="overflow-hidden rounded-xl border border-slate-300">
                    <table className="w-full text-right border-collapse text-xs" style={{ tableLayout: 'fixed' }}>
                      <thead>
                        <tr className="bg-slate-900 text-white">
                          <th className="py-2.5 px-2 text-center border border-slate-800 w-[36px]">#</th>
                          <th className="py-2.5 px-3 border border-slate-800 w-[135px]">المكتب الفرعي</th>
                          <th className="py-2.5 px-3 border border-slate-800 w-[180px]">المقاول المعتمد</th>
                          <th className="py-2.5 px-2 text-center border border-slate-800 w-[85px]">إجمالي الأوامر</th>
                          <th className="py-2.5 px-2 text-center border border-slate-800 bg-emerald-950 text-emerald-300 w-[85px]">مؤهل 155</th>
                          <th className="py-2.5 px-2 text-center border border-slate-800 bg-blue-950 text-blue-300 w-[85px]">قيد التنفيذ</th>
                          <th className="py-2.5 px-2 text-center border border-slate-800 bg-amber-950 text-amber-300 w-[85px]">معلق لنواقص</th>
                          <th className="py-2.5 px-2 text-center border border-slate-800 w-[85px]">نسبة الإنجاز</th>
                          <th className="py-2.5 px-2 text-center border border-slate-800 w-[90px]">التوثيق بالصور</th>
                          <th className="py-2.5 px-2 text-center border border-slate-800 w-[85px]">التقييم العام</th>
                          <th className="py-2.5 px-2 text-center border border-slate-800">التصنيف</th>
                        </tr>
                      </thead>
                      <tbody>
                        {sortedOffices.map((office, idx) => (
                          <tr key={office.officeId} className={idx % 2 === 0 ? 'bg-white' : 'bg-slate-50'}>
                            <td className="py-2.5 px-2 text-center font-bold border border-slate-200">{idx + 1}</td>
                            <td className="py-2.5 px-3 font-black text-slate-900 border border-slate-200 truncate">{office.officeName}</td>
                            <td className="py-2.5 px-3 font-bold text-slate-800 border border-slate-200 truncate">{office.contractor}</td>
                            <td className="py-2.5 px-2 text-center font-bold border border-slate-200 font-mono">{office.total}</td>
                            <td className="py-2.5 px-2 text-center font-black text-emerald-700 bg-emerald-50/50 border border-slate-200 font-mono">{office.ready}</td>
                            <td className="py-2.5 px-2 text-center font-bold text-blue-700 bg-blue-50/50 border border-slate-200 font-mono">{office.inProgress}</td>
                            <td className="py-2.5 px-2 text-center font-bold text-amber-700 bg-amber-50/50 border border-slate-200 font-mono">{office.pending}</td>
                            <td className="py-2.5 px-2 text-center font-black border border-slate-200 font-mono">{office.completionRate}%</td>
                            <td className="py-2.5 px-2 text-center font-bold text-indigo-700 border border-slate-200 font-mono">{office.photosRate}%</td>
                            <td className="py-2.5 px-2 text-center font-black text-slate-900 border border-slate-200 font-mono">{office.score}/100</td>
                            <td className="py-2.5 px-2 text-center font-bold text-[10px] border border-slate-200 truncate">{office.tier}</td>
                          </tr>
                        ))}
                        <tr className="bg-slate-900 text-white font-black">
                          <td colSpan={3} className="py-2.5 px-3 border border-slate-800">المجموع الإجمالي / المتوسط العام</td>
                          <td className="py-2.5 px-2 text-center border border-slate-800 font-mono text-amber-400">{systemTotals.totalOrders}</td>
                          <td className="py-2.5 px-2 text-center border border-slate-800 font-mono text-emerald-400">{systemTotals.readyCount}</td>
                          <td className="py-2.5 px-2 text-center border border-slate-800 font-mono text-blue-400">{systemTotals.inProgressCount}</td>
                          <td className="py-2.5 px-2 text-center border border-slate-800 font-mono text-amber-400">{systemTotals.pendingCount}</td>
                          <td className="py-2.5 px-2 text-center border border-slate-800 font-mono text-emerald-400">{systemTotals.avgCompletion}%</td>
                          <td className="py-2.5 px-2 text-center border border-slate-800 font-mono text-indigo-400">{systemTotals.avgPhotos}%</td>
                          <td className="py-2.5 px-2 text-center border border-slate-800 font-mono text-amber-400">{systemTotals.avgScore}/100</td>
                          <td className="py-2.5 px-2 text-center border border-slate-800 font-mono text-[10px]">معتمد</td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>

                {/* Footer: Strictly Page Number Only */}
                <div className="pt-2 border-t-2 border-slate-900 text-center text-xs text-slate-800 font-mono font-black shrink-0">
                  رقم الصفحة: 1
                </div>
              </div>
            </div>
          </div>

        </div>

        {/* Modal Bottom Footer */}
        <div className="bg-slate-900 text-slate-300 p-3 sm:px-6 flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-t border-slate-800 text-xs shrink-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="font-bold text-white">إجمالي المكاتب المدرجة:</span>
            <span className="font-mono font-bold text-amber-400">{processedOffices.length} مكاتب فرعية</span>
            <span className="text-slate-600 hidden sm:inline">|</span>
            <span className="text-slate-400">إجمالي أوامر المنظومة:</span>
            <span className="font-mono font-bold text-blue-400">{totalSystemOrders} أمر عمل</span>
          </div>

          <div className="flex items-center gap-2 self-end sm:self-auto">
            {/* Weekly Report Navigation */}
            <button
              type="button"
              onClick={() => {
                onClose();
                onOpenWeeklyReport();
              }}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold bg-blue-600 hover:bg-blue-500 text-white transition-colors cursor-pointer"
            >
              <FileText className="w-3.5 h-3.5" />
              <span>التقرير الأسبوعي الإداري PDF</span>
            </button>

            {/* Close Button */}
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-white font-bold text-xs cursor-pointer"
            >
              إغلاق النافذة
            </button>
          </div>
        </div>

      </div>
    </div>
  );
};

src/components/OfficeSelector.tsx:
import React, { useState } from 'react';
import { SubOffice, WorkOrder, PlatformUser } from '../types';
import { hasUserPermission } from '../utils/security';
import { 
  Building2, 
  MapPin, 
  Plus, 
  ChevronDown, 
  ChevronUp, 
  Layers, 
  CheckCircle2, 
  Clock, 
  FileSpreadsheet, 
  Filter,
  Pencil,
  Trash2,
  SlidersHorizontal,
  ArrowRightLeft,
  AlertTriangle,
  Info,
  BarChart3,
  Briefcase
} from 'lucide-react';

interface OfficeSelectorProps {
  offices: SubOffice[];
  selectedOffice: string; // 'all' or office name
  onSelectOffice: (officeName: string) => void;
  workOrders: WorkOrder[];
  onAddNewOffice: (office: Partial<SubOffice>) => Promise<void> | void;
  onUpdateOffice?: (office: SubOffice, oldName?: string) => Promise<void> | void;
  onDeleteOffice?: (officeId: string, officeName: string, reassignTo?: string) => Promise<void> | void;
  onOpenManageOffices?: () => void;
  onOpenOfficeComparison?: () => void;
  onOpenManageContractors?: () => void;
  defaultExpanded?: boolean;
  currentUser?: PlatformUser | null;
}

export const OfficeSelector: React.FC<OfficeSelectorProps> = ({
  offices,
  selectedOffice,
  onSelectOffice,
  workOrders,
  onAddNewOffice,
  onUpdateOffice,
  onDeleteOffice,
  onOpenManageOffices,
  onOpenOfficeComparison,
  onOpenManageContractors,
  defaultExpanded = false,
  currentUser
}) => {
  const [isExpanded, setIsExpanded] = useState<boolean>(defaultExpanded);

  // Add modal state
  const [showAddOfficeModal, setShowAddOfficeModal] = useState(false);
  const [newOfficeName, setNewOfficeName] = useState('');
  const [newOfficeCode, setNewOfficeCode] = useState('');
  const [newOfficeRegion, setNewOfficeRegion] = useState('');
  const [newOfficeManager, setNewOfficeManager] = useState('');
  const [newOfficeContact, setNewOfficeContact] = useState('');
  const [newOfficeDescription, setNewOfficeDescription] = useState('');
  const [addError, setAddError] = useState('');

  // Quick Edit modal state
  const [editingOffice, setEditingOffice] = useState<SubOffice | null>(null);
  const [editName, setEditName] = useState('');
  const [editCode, setEditCode] = useState('');
  const [editRegion, setEditRegion] = useState('');
  const [editManager, setEditManager] = useState('');
  const [editContact, setEditContact] = useState('');
  const [editDescription, setEditDescription] = useState('');
  const [editError, setEditError] = useState('');

  // Delete state
  const [officeToDelete, setOfficeToDelete] = useState<SubOffice | null>(null);
  const [reassignTargetOffice, setReassignTargetOffice] = useState<string>('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Calculate statistics for currently selected view
  const currentOrders = selectedOffice === 'all' 
    ? workOrders 
    : workOrders.filter(w => w.office === selectedOffice);

  const readyFor155Count = currentOrders.filter(
    w => w.procedure155Status === 'مؤهل للاستلام (معتمد)' || w.procedure155Status === 'تم الاستلام وإغلاق 155'
  ).length;

  const pendingNotesCount = currentOrders.filter(
    w => w.procedure155Status === 'بانتظار استيفاء الملاحظات' || w.executionStatus === 'معلق لنواقص'
  ).length;

  const boqModifiedCount = currentOrders.filter(
    w => w.boqModification.includes('نعم')
  ).length;

  const auditedRate = currentOrders.length > 0 
    ? Math.round((readyFor155Count / currentOrders.length) * 100) 
    : 0;

  const handleCreateOffice = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = newOfficeName.trim();
    if (!trimmed) {
      setAddError('يرجى كتابة اسم المكتب الفرعي');
      return;
    }

    if (offices.some(o => o.name.trim().toLowerCase() === trimmed.toLowerCase())) {
      setAddError('يوجد مكتب بهذا الاسم بالفعل');
      return;
    }

    setIsSubmitting(true);
    setAddError('');
    try {
      await onAddNewOffice({
        name: trimmed,
        code: newOfficeCode.trim() || `OFF-${Date.now().toString().slice(-4)}`,
        region: newOfficeRegion.trim() || 'المنطقة الحضرية',
        manager: newOfficeManager.trim() || 'مدير المكتب الميداني',
        contactNumber: newOfficeContact.trim() || '0500000000',
        description: newOfficeDescription.trim() || 'مكتب فرعي لإدارة ومتابعة أوامر العمل الميدانية'
      });

      setNewOfficeName('');
      setNewOfficeCode('');
      setNewOfficeRegion('');
      setNewOfficeManager('');
      setNewOfficeContact('');
      setNewOfficeDescription('');
      setShowAddOfficeModal(false);
    } catch (err: any) {
      setAddError(err?.message || 'حدث خطأ أثناء إضافة المكتب');
    } finally {
      setIsSubmitting(false);
    }
  };

  const startEditOffice = (off: SubOffice) => {
    setEditingOffice(off);
    setEditName(off.name);
    setEditCode(off.code || '');
    setEditRegion(off.region || '');
    setEditManager(off.manager || '');
    setEditContact(off.contactNumber || '');
    setEditDescription(off.description || '');
    setEditError('');
  };

  const handleSaveEdit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingOffice || !onUpdateOffice) return;
    const trimmedName = editName.trim();
    if (!trimmedName) {
      setEditError('يرجى إدخال اسم المكتب');
      return;
    }

    const duplicate = offices.some(
      o => o.id !== editingOffice.id && o.name.trim().toLowerCase() === trimmedName.toLowerCase()
    );
    if (duplicate) {
      setEditError('يوجد مكتب آخر يحمل نفس هذا الاسم مسبقاً');
      return;
    }

    setIsSubmitting(true);
    setEditError('');
    try {
      const updated: SubOffice = {
        ...editingOffice,
        name: trimmedName,
        code: editCode.trim() || editingOffice.code,
        region: editRegion.trim() || 'المنطقة الحضرية',
        manager: editManager.trim() || 'مدير المكتب الميداني',
        contactNumber: editContact.trim() || '0500000000',
        description: editDescription.trim() || 'مكتب فرعي لإدارة ومتابعة أوامر العمل الميدانية'
      };

      await onUpdateOffice(updated, editingOffice.name);
      setEditingOffice(null);
    } catch (err: any) {
      setEditError(err?.message || 'حدث خطأ أثناء حفظ التعديلات');
    } finally {
      setIsSubmitting(false);
    }
  };

  const startDeleteOffice = (off: SubOffice) => {
    if (offices.length <= 1) {
      alert('لا يمكن حذف كافة المكاتب، يجب الإبقاء على مكتب فرعي واحد على الأقل في النظام.');
      return;
    }
    setOfficeToDelete(off);
    const other = offices.find(o => o.id !== off.id);
    setReassignTargetOffice(other ? other.name : '');
  };

  const handleConfirmDelete = async () => {
    if (!officeToDelete || !onDeleteOffice) return;
    setIsSubmitting(true);
    try {
      await onDeleteOffice(officeToDelete.id, officeToDelete.name, reassignTargetOffice);
      setOfficeToDelete(null);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="bg-white rounded-2xl border border-slate-200/90 shadow-2xs mb-5 overflow-hidden transition-all text-right font-['Cairo',sans-serif]">

      {/* Collapsible Header Bar (دائماً مرئي وسهل الطي والفتح بنقرة واحدة) */}
      <div 
        onClick={() => setIsExpanded(prev => !prev)}
        className="p-3.5 sm:p-4 flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 cursor-pointer hover:bg-slate-50 transition-colors select-none"
      >
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-xl bg-blue-50 text-blue-700 border border-blue-200 flex items-center justify-center shrink-0">
            <MapPin className="w-4 h-4 text-blue-600" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h3 className="text-xs sm:text-sm font-black text-slate-900">
                تقسيم المنطقة إلى مكاتب فرعية
              </h3>
              <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-700 border border-slate-200">
                {offices.length} مكاتب
              </span>
            </div>
            <p className="text-[11px] text-slate-500 mt-0.5">
              فلترة الأوامر ومتابعة مؤشرات كل مكتب فرعي على حدة مع التعديل والإضافة والحذف
            </p>
          </div>
        </div>

        {/* Right side: Active office status & collapse trigger */}
        <div className="flex items-center gap-2 justify-between sm:justify-end">
          {onOpenOfficeComparison && hasUserPermission(currentUser, 'viewOfficeComparison') && (
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                onOpenOfficeComparison();
              }}
              className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-bold text-amber-900 bg-amber-100 hover:bg-amber-200 border border-amber-300 transition-colors shadow-2xs cursor-pointer"
              title="عرض بيان مقارنة أداء وتوزيع حالات المكاتب الفرعية بالرسم البياني ومعاينة للتصدير"
            >
              <BarChart3 className="w-3.5 h-3.5 text-amber-700" />
              <span>مقارنة أداء المكاتب</span>
            </button>
          )}

          <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-bold bg-blue-50 text-blue-800 border border-blue-200">
            <Filter className="w-3.5 h-3.5 text-blue-600" />
            <span>المكتب النشط:</span>
            <strong>{selectedOffice === 'all' ? 'جميع المكاتب' : selectedOffice}</strong>
            <span className="text-[10px] text-blue-600 font-mono">({currentOrders.length})</span>
          </span>

          <button
            type="button"
            className="inline-flex items-center gap-1 px-3 py-1 rounded-xl text-xs font-bold text-slate-600 hover:text-slate-900 bg-slate-100 hover:bg-slate-200 border border-slate-200 transition-colors"
          >
            <span>{isExpanded ? 'طي البطاقة' : 'فتح وتغيير المكتب'}</span>
            {isExpanded ? (
              <ChevronUp className="w-4 h-4 text-slate-500" />
            ) : (
              <ChevronDown className="w-4 h-4 text-slate-500" />
            )}
          </button>
        </div>
      </div>

      {/* Expandable Body */}
      {isExpanded && (
        <div className="p-4 pt-0 border-t border-slate-100 space-y-4 animate-in fade-in duration-200">

          {/* Sub-Offices Tabs + Manage & Add Office Buttons */}
          <div className="flex items-center justify-between gap-3 pt-3 flex-wrap">

            <div className="flex items-center gap-2 flex-wrap py-1 flex-1">
              {/* All offices option */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onSelectOffice('all');
                }}
                className={`flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs font-bold whitespace-nowrap transition-all cursor-pointer ${
                  selectedOffice === 'all'
                    ? 'bg-slate-900 text-white shadow-xs'
                    : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
                }`}
              >
                <Layers className="w-3.5 h-3.5" />
                <span>جميع المكاتب</span>
                <span className={`px-1.5 py-0.5 rounded-full text-[10px] font-mono ${
                  selectedOffice === 'all' ? 'bg-slate-700 text-slate-200' : 'bg-slate-200 text-slate-700'
                }`}>
                  {workOrders.length}
                </span>
              </button>

              {/* Each office button with quick edit & delete controls */}
              {offices.map((off) => {
                const count = workOrders.filter(w => w.office === off.name).length;
                const isSelected = selectedOffice === off.name;
                return (
                  <div 
                    key={off.id} 
                    className={`group/tab inline-flex items-center rounded-xl text-xs font-bold whitespace-nowrap transition-all border shrink-0 ${
                      isSelected
                        ? 'bg-blue-600 text-white border-blue-600 shadow-xs'
                        : 'bg-white text-slate-700 border-slate-200 hover:border-slate-300 hover:bg-slate-50'
                    }`}
                  >
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        onSelectOffice(off.name);
                      }}
                      className="flex items-center gap-2 pl-2 pr-3.5 py-2 cursor-pointer focus:outline-hidden"
                    >
                      <Building2 className={`w-3.5 h-3.5 ${isSelected ? 'text-blue-200' : 'text-slate-500'}`} />
                      <span>{off.name}</span>
                      <span className={`px-1.5 py-0.5 rounded-full text-[10px] font-mono font-bold ${
                        isSelected ? 'bg-blue-700 text-white' : 'bg-slate-100 text-slate-700'
                      }`}>
                        {count}
                      </span>
                    </button>

                    {/* Quick action buttons for this office */}
                    {hasUserPermission(currentUser, 'manageOffices') && (
                      <div className="flex items-center gap-0.5 mr-1 pr-1.5 pl-1.5 border-r border-slate-200/40 opacity-70 group-hover/tab:opacity-100 transition-opacity">
                        {/* زر التعديل المباشر */}
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            startEditOffice(off);
                          }}
                          className={`p-1 rounded-md transition-colors cursor-pointer ${
                            isSelected 
                              ? 'text-white/80 hover:text-white hover:bg-blue-700' 
                              : 'text-slate-400 hover:text-amber-700 hover:bg-amber-50'
                          }`}
                          title={`تعديل بيانات مكتب (${off.name})`}
                        >
                          <Pencil className="w-3 h-3" />
                        </button>

                        {/* زر الحذف المباشر */}
                        {onDeleteOffice && offices.length > 1 && (
                          <button
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              startDeleteOffice(off);
                            }}
                            className={`p-1 rounded-md transition-colors cursor-pointer ${
                              isSelected 
                                ? 'text-white/80 hover:text-white hover:bg-rose-700' 
                                : 'text-slate-400 hover:text-rose-700 hover:bg-rose-50'
                            }`}
                            title={`حذف مكتب (${off.name})`}
                          >
                            <Trash2 className="w-3 h-3" />
                          </button>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {/* Management & Add Office Buttons */}
            <div className="flex items-center gap-2 shrink-0 flex-wrap">
              {/* Performance Comparison Modal Button */}
              {onOpenOfficeComparison && hasUserPermission(currentUser, 'viewOfficeComparison') && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onOpenOfficeComparison();
                  }}
                  className="inline-flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-bold text-amber-900 bg-amber-50 hover:bg-amber-100 border border-amber-300 transition-colors shrink-0 cursor-pointer shadow-2xs"
                  title="عرض بيان مقارنة أداء وتوزيع حالات المكاتب الفرعية بالرسم البياني ومعاينة للتصدير"
                >
                  <BarChart3 className="w-3.5 h-3.5 text-amber-700" />
                  <span>مقارنة أداء المكاتب</span>
                </button>
              )}

              {/* Manage Contractors Distribution Button */}
              {onOpenManageContractors && hasUserPermission(currentUser, 'manageContractors') && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onOpenManageContractors();
                  }}
                  className="inline-flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-bold text-indigo-900 bg-indigo-50 hover:bg-indigo-100 border border-indigo-200 transition-colors shrink-0 cursor-pointer shadow-2xs"
                  title="إدارة وتوزيع مقاولي المكاتب الفرعية المعتمدين"
                >
                  <Briefcase className="w-3.5 h-3.5 text-indigo-700" />
                  <span>توزيع المقاولين</span>
                </button>
              )}

              {/* Full Manage Offices Modal Button */}
              {onOpenManageOffices && hasUserPermission(currentUser, 'manageOffices') && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onOpenManageOffices();
                  }}
                  className="inline-flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-bold text-slate-800 bg-slate-100 hover:bg-slate-200 border border-slate-300 transition-colors shrink-0 cursor-pointer shadow-2xs"
                  title="فتح نافذة الإدارة الشاملة للمكاتب الفرعية"
                >
                  <SlidersHorizontal className="w-3.5 h-3.5 text-slate-600" />
                  <span>إدارة وتعديل المكاتب</span>
                </button>
              )}

              {/* Add New Sub-office button */}
              {hasUserPermission(currentUser, 'manageOffices') && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    setAddError('');
