            </div>
          </div>

          {/* Key Progress Metrics for the active office */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5 pt-2 text-slate-800">
            <div className="p-2.5 rounded-xl bg-slate-50 border border-slate-200">
