import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  X, 
  PlusCircle, 
  FileSpreadsheet, 
  FileDown, 
  BarChart3, 
  Building2, 
  Briefcase, 
  Bell, 
  ShieldCheck, 
  Volume2, 
  VolumeX, 
  Maximize, 
  Trash2, 
  Calendar, 
  RotateCw, 
  CheckCircle2, 
  AlertTriangle, 
  ArrowRight, 
  CornerDownLeft,
  Sparkles,
  Command,
  Sliders,
  History
} from 'lucide-react';
import { WorkOrder, SubOffice, PlatformUser } from '../types';
import { hasUserPermission } from '../utils/security';

export interface CommandAction {
  id: string;
  title: string;
  category: 'إجراءات سريعة' | 'أوامر العمل' | 'تقارير وتحليلات' | 'إدارة وتخصيص' | 'أدوات النظام';
  icon: React.ReactNode;
  shortcut?: string;
  badge?: string;
  perform: () => void;
  permission?: string;
}

interface QuickCommandPaletteProps {
  isOpen: boolean;
  onClose: () => void;
  orders: WorkOrder[];
  offices: SubOffice[];
  onSelectOrder: (order: WorkOrder) => void;
  onOpenAddModal: () => void;
  onOpenImportModal: () => void;
  onOpenExportModal: () => void;
  onOpenWeeklyReport: () => void;
  onOpenOfficeComparison: () => void;
  onOpenManageOffices: () => void;
  onOpenManageContractors: () => void;
  onOpenNotificationSettings: () => void;
  onOpenDataRecovery: () => void;
  onOpenRestoreDeleted: () => void;
  onManualSync: () => void;
  isSoundMuted: boolean;
  onToggleSound: () => void;
  onSelectOffice: (office: string) => void;
  onSetKpiFilter: (filter: any) => void;
  onOpenCreateTableModal?: () => void;
  onOpenSmartAudit?: () => void;
  onOpenContractorComparison?: () => void;
  onOpenCompatibleImport?: () => void;
  currentUser?: PlatformUser | null;
}

export const QuickCommandPalette: React.FC<QuickCommandPaletteProps> = ({
  isOpen,
  onClose,
  orders,
  offices,
  onSelectOrder,
  onOpenAddModal,
  onOpenImportModal,
  onOpenExportModal,
  onOpenWeeklyReport,
  onOpenOfficeComparison,
  onOpenManageOffices,
  onOpenManageContractors,
  onOpenNotificationSettings,
  onOpenDataRecovery,
  onOpenRestoreDeleted,
  onManualSync,
  isSoundMuted,
  onToggleSound,
  onSelectOffice,
  onSetKpiFilter,
  onOpenSmartAudit,
  onOpenContractorComparison,
  onOpenCompatibleImport,
  currentUser
}) => {
  const [query, setQuery] = useState('');
  const [selectedIndex, setSelectedIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen) {
      setQuery('');
      setSelectedIndex(0);
      setTimeout(() => inputRef.current?.focus(), 50);
    }
  }, [isOpen]);

  // Static Platform Commands (Filtered strictly by permissions so unauthorized commands are completely hidden)
  const baseCommands: CommandAction[] = useMemo(() => {
    const list: CommandAction[] = [
      {
        id: 'cmd-add-order',
        title: 'إضافة أمر عمل جديد',
        category: 'إجراءات سريعة',
        icon: <PlusCircle className="w-4 h-4 text-emerald-500" />,
        shortcut: 'Alt + N',
        perform: () => { onClose(); onOpenAddModal(); },
        permission: 'addWorkOrder'
      },
      {
        id: 'cmd-import-excel',
        title: 'استيراد أوامر العمل من ملف Excel',
        category: 'إجراءات سريعة',
        icon: <FileSpreadsheet className="w-4 h-4 text-teal-500" />,
        shortcut: 'Alt + I',
        badge: 'إكسل ذكي',
        perform: () => { onClose(); onOpenImportModal(); },
        permission: 'importExcel'
      },
      {
        id: 'cmd-export',
        title: 'تصدير البيانات المعتمدة (Excel / PDF / صورة)',
        category: 'إجراءات سريعة',
        icon: <FileDown className="w-4 h-4 text-purple-500" />,
        shortcut: 'Alt + E',
        perform: () => { onClose(); onOpenExportModal(); },
        permission: 'exportTable'
      },
      {
        id: 'cmd-weekly-report',
        title: 'التقرير الأسبوعي لإنجازات المكاتب والمقاولين (PDF)',
        category: 'تقارير وتحليلات',
        icon: <BarChart3 className="w-4 h-4 text-blue-500" />,
        badge: 'تقرير رسمي',
        perform: () => { onClose(); onOpenWeeklyReport(); },
        permission: 'viewWeeklyReport'
      },
      {
        id: 'cmd-office-compare',
        title: 'مقارنة وتقييم أداء المكاتب الفرعية',
        category: 'تقارير وتحليلات',
        icon: <Sparkles className="w-4 h-4 text-amber-500" />,
        perform: () => { onClose(); onOpenOfficeComparison(); },
        permission: 'viewOfficeComparison'
      },

      {
        id: 'cmd-contractor-compare',
        title: 'مقارنة المقاولين وتقارير الإغلاق الدورية',
        category: 'تقارير وتحليلات',
        icon: <Briefcase className="w-4 h-4 text-teal-400" />,
        badge: 'دوري',
        perform: () => { onClose(); onOpenContractorComparison?.(); },
        permission: 'viewContractorClosureReport'
      },
      {
        id: 'cmd-filter-ready',
        title: 'عرض أوامر العمل المؤهلة للإغلاق فقط',
        category: 'أوامر العمل',
        icon: <CheckCircle2 className="w-4 h-4 text-emerald-500" />,
        perform: () => { onClose(); onSetKpiFilter('ready'); },
        permission: 'searchAndFilter'
      },
      {
        id: 'cmd-filter-not-ready',
        title: 'عرض أوامر العمل غير المؤهلة للإغلاق (النواقص)',
        category: 'أوامر العمل',
        icon: <AlertTriangle className="w-4 h-4 text-rose-500" />,
        perform: () => { onClose(); onSetKpiFilter('not_ready'); },
        permission: 'searchAndFilter'
      },
      {
        id: 'cmd-filter-all',
        title: 'عرض كافة أوامر العمل بدون تصفية',
        category: 'أوامر العمل',
        icon: <Command className="w-4 h-4 text-slate-400" />,
        perform: () => { onClose(); onSetKpiFilter('all'); },
        permission: 'searchAndFilter'
      },
      {
        id: 'cmd-manage-offices',
        title: 'إدارة المكاتب الفرعية (إضافة / تعديل / حذف)',
        category: 'إدارة وتخصيص',
        icon: <Building2 className="w-4 h-4 text-indigo-500" />,
        perform: () => { onClose(); onOpenManageOffices(); },
        permission: 'manageOffices'
      },
      {
        id: 'cmd-manage-contractors',
        title: 'توزيع وربط مقاولي المكاتب المعتمدين',
        category: 'إدارة وتخصيص',
        icon: <Briefcase className="w-4 h-4 text-amber-500" />,
        perform: () => { onClose(); onOpenManageContractors(); },
        permission: 'manageContractors'
      },
      {
        id: 'cmd-notifications',
        title: 'مركز الإشعارات الفورية (حتى والمنصة مغلقة 24/7)',
        category: 'أدوات النظام',
        icon: <Bell className="w-4 h-4 text-amber-500" />,
        badge: 'تنبيهات حية',
        perform: () => { onClose(); onOpenNotificationSettings(); },
        permission: 'manageNotifications'
      },
      {
        id: 'cmd-data-recovery',
        title: 'مركز الأمان السحابي واستعادة النسخ الاحتياطية',
        category: 'أدوات النظام',
        icon: <ShieldCheck className="w-4 h-4 text-emerald-500" />,
        perform: () => { onClose(); onOpenDataRecovery(); },
        permission: 'restoreDeleted'
      },

      {
        id: 'cmd-sync',
        title: 'المزامنة السحابية الفورية مع الخادم',
        category: 'أدوات النظام',
        icon: <RotateCw className="w-4 h-4 text-blue-500" />,
        perform: () => { onClose(); onManualSync(); }
      },
      {
        id: 'cmd-toggle-sound',
        title: isSoundMuted ? 'تفعيل التنبيهات الصوتية' : 'كتم التنبيهات الصوتية',
        category: 'أدوات النظام',
        icon: isSoundMuted ? <VolumeX className="w-4 h-4 text-slate-400" /> : <Volume2 className="w-4 h-4 text-blue-400" />,
        perform: () => { onToggleSound(); }
      }
    ];

    return list.filter(cmd => !cmd.permission || hasUserPermission(currentUser, cmd.permission));
  }, [
    onClose, onOpenAddModal, onOpenImportModal, onOpenExportModal,
    onOpenWeeklyReport, onOpenOfficeComparison, onOpenManageOffices,
    onOpenManageContractors, onOpenNotificationSettings, onOpenDataRecovery,
    onOpenRestoreDeleted, onManualSync, isSoundMuted, onToggleSound, onSetKpiFilter,
    currentUser
  ]);

  // Dynamic Search Across Orders and Offices
  const filteredItems = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) {
      return baseCommands;
    }

    const matchedCommands = baseCommands.filter(c => 
      c.title.toLowerCase().includes(q) || c.category.toLowerCase().includes(q)
    );

    // Search inside WorkOrders
    const matchedOrders = orders.filter(o => 
      (o.workOrderNumber && o.workOrderNumber.toLowerCase().includes(q)) ||
      (o.contractor && o.contractor.toLowerCase().includes(q)) ||
      (o.office && o.office.toLowerCase().includes(q)) ||
      (o.workOrderCode && o.workOrderCode.toLowerCase().includes(q)) ||
      (o.procedure155Status && o.procedure155Status.toLowerCase().includes(q))
    ).slice(0, 12).map(o => ({
      id: `order-${o.id}`,
      title: `أمر عمل: ${o.workOrderNumber || 'بدون رقم'} (${o.office || ''} - ${o.contractor || ''})`,
      category: 'أوامر العمل' as const,
      icon: o.procedure155Status?.includes('مؤهل') ? (
        <CheckCircle2 className="w-4 h-4 text-emerald-500" />
      ) : (
        <AlertTriangle className="w-4 h-4 text-amber-500" />
      ),
      badge: o.procedure155Status || 'قيد المتابعة',
      perform: () => {
        onClose();
        onSelectOrder(o);
      }
    }));

    // Search inside Offices
    const matchedOffices = offices.filter(off => 
      off.name.toLowerCase().includes(q) || (off.code && off.code.toLowerCase().includes(q))
    ).map(off => ({
      id: `office-${off.id}`,
      title: `تصفية حسب: ${off.name}`,
      category: 'إدارة وتخصيص' as const,
      icon: <Building2 className="w-4 h-4 text-emerald-500" />,
      badge: `${orders.filter(w => w.office === off.name).length} أمر عمل`,
      perform: () => {
        onClose();
        onSelectOffice(off.name);
      }
    }));

    return [...matchedCommands, ...matchedOrders, ...matchedOffices];
  }, [query, baseCommands, orders, offices, onClose, onSelectOrder, onSelectOffice]);

  // Keyboard Navigation: Up, Down, Enter, Escape
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIndex(prev => (prev + 1) % Math.max(1, filteredItems.length));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIndex(prev => (prev - 1 + filteredItems.length) % Math.max(1, filteredItems.length));
      } else if (e.key === 'Enter') {
        e.preventDefault();
        if (filteredItems[selectedIndex]) {
          filteredItems[selectedIndex].perform();
        }
      } else if (e.key === 'Escape') {
        e.preventDefault();
        onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, filteredItems, selectedIndex, onClose]);

  // Scroll active item into view
  useEffect(() => {
    if (listRef.current) {
      const activeEl = listRef.current.querySelector('[data-selected="true"]');
      if (activeEl) {
        activeEl.scrollIntoView({ block: 'nearest' });
      }
    }
  }, [selectedIndex]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-16 sm:pt-24 p-3 bg-slate-950/70 backdrop-blur-sm animate-in fade-in duration-150 font-['Cairo',sans-serif]">
      <div 
        className="w-full max-w-2xl bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col animate-in zoom-in-95 duration-150 text-right"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Search Header */}
        <div className="flex items-center gap-3 px-4 py-3.5 border-b border-slate-200 bg-slate-50/80">
          <Search className="w-5 h-5 text-emerald-600 shrink-0" />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setSelectedIndex(0);
            }}
            placeholder="ابحث عن أمر عمل، مكتب، مقاول، أو اكتب أي إجراء تريده..."
            className="flex-1 bg-transparent border-0 outline-hidden text-sm sm:text-base font-bold text-slate-800 placeholder:text-slate-400 text-right"
          />
          {query ? (
            <button
              type="button"
              onClick={() => { setQuery(''); inputRef.current?.focus(); }}
              className="p-1 rounded-md text-slate-400 hover:text-slate-600 hover:bg-slate-200"
            >
              <X className="w-4 h-4" />
            </button>
          ) : (
            <div className="flex items-center gap-1 text-[11px] font-mono text-slate-400 bg-slate-200/80 px-2 py-0.5 rounded border border-slate-300">
              <span>ESC للإغلاق</span>
            </div>
          )}
        </div>

        {/* Results List */}
        <div 
          ref={listRef}
          className="max-h-[60vh] overflow-y-auto p-2 divide-y divide-slate-100"
        >
          {filteredItems.length === 0 ? (
            <div className="py-12 text-center text-slate-400">
              <Search className="w-8 h-8 mx-auto mb-2 opacity-40 text-slate-400" />
              <p className="text-sm font-bold text-slate-600">لا توجد نتائج مطابقة لـ "{query}"</p>
              <p className="text-xs text-slate-400 mt-1">جرب البحث برقم أمر العمل أو اسم المكتب أو الإجراء المطلوب</p>
            </div>
          ) : (
            filteredItems.map((item, index) => {
              const isSelected = index === selectedIndex;
              return (
                <div
                  key={item.id}
                  data-selected={isSelected}
                  onClick={item.perform}
                  onMouseEnter={() => setSelectedIndex(index)}
                  className={`flex items-center justify-between gap-3 px-3.5 py-2.5 rounded-xl cursor-pointer transition-all select-none ${
                    isSelected 
                      ? 'bg-gradient-to-r from-emerald-600 to-teal-700 text-white shadow-md' 
                      : 'hover:bg-slate-100/80 text-slate-800'
                  }`}
                >
                  <div className="flex items-center gap-3 min-w-0 flex-1">
                    <div className={`p-2 rounded-lg shrink-0 ${
                      isSelected ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-600'
                    }`}>
                      {item.icon}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2">
                        <span className={`text-xs sm:text-sm font-black truncate ${
                          isSelected ? 'text-white' : 'text-slate-900'
                        }`}>
                          {item.title}
                        </span>
                        {item.badge && (
                          <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold shrink-0 ${
                            isSelected 
                              ? 'bg-white/25 text-white' 
                              : 'bg-emerald-100 text-emerald-800 border border-emerald-200'
                          }`}>
                            {item.badge}
                          </span>
                        )}
                      </div>
                      <span className={`text-[11px] block mt-0.5 ${
                        isSelected ? 'text-emerald-100' : 'text-slate-400'
                      }`}>
                        {item.category}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center gap-2 shrink-0">
                    {'shortcut' in item && Boolean((item as any).shortcut) && (
                      <span className={`text-[10px] font-mono px-2 py-0.5 rounded border ${
                        isSelected 
                          ? 'border-white/30 text-white bg-white/10' 
                          : 'border-slate-200 text-slate-400 bg-slate-100'
                      }`}>
                        {(item as any).shortcut}
                      </span>
                    )}
                    {isSelected && (
                      <CornerDownLeft className="w-3.5 h-3.5 text-white animate-pulse" />
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Footer shortcuts hint */}
        <div className="px-4 py-2.5 bg-slate-50 border-t border-slate-100 flex items-center justify-between text-[11px] text-slate-500 select-none">
          <div className="flex items-center gap-4">
            <span className="flex items-center gap-1">
              <kbd className="px-1.5 py-0.5 bg-white border border-slate-200 rounded font-mono text-[10px]">↑</kbd>
              <kbd className="px-1.5 py-0.5 bg-white border border-slate-200 rounded font-mono text-[10px]">↓</kbd>
              <span>للتنقل</span>
            </span>
            <span className="flex items-center gap-1">
              <kbd className="px-1.5 py-0.5 bg-white border border-slate-200 rounded font-mono text-[10px]">↵</kbd>
              <span>للاختيار والتنفيذ</span>
            </span>
          </div>
          <span className="font-mono text-[10px] text-emerald-700 font-bold">
            Ctrl + K / ⌘ + K
          </span>
        </div>
      </div>
    </div>
  );
};

src/components/RestoreDeletedModal.tsx:
import React, { useState } from 'react';
import { 
  History, 
  RotateCcw, 
  Trash2, 
  X, 
  KeyRound, 
  ShieldAlert, 
  CheckCircle2, 
  AlertCircle,
  Building2,
  Calendar,
  Layers,
  Lock,
  FileText
} from 'lucide-react';
import { WorkOrder } from '../types';
import { verifyAdminPin } from '../utils/security';
import { soundService } from '../services/soundService';

export interface DeletedOrderEntry {
  id: string;
  order: WorkOrder;
  deletedAt: string;
  deleteType: 'single' | 'batch' | 'clear' | 'all_clear' | 'office_clear';
}

interface RestoreDeletedModalProps {
  isOpen: boolean;
  onClose: () => void;
  deletedOrders: DeletedOrderEntry[];
  onRestoreOrder: (order: WorkOrder) => Promise<void>;
  onRestoreAll: (orders: WorkOrder[]) => Promise<void>;
  onPermanentlyClearTrash: () => void;
}

export const RestoreDeletedModal: React.FC<RestoreDeletedModalProps> = ({
  isOpen,
  onClose,
  deletedOrders,
  onRestoreOrder,
  onRestoreAll,
  onPermanentlyClearTrash
}) => {
  const [pin, setPin] = useState('');
  const [pinError, setPinError] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);
  const [pendingTargetOrder, setPendingTargetOrder] = useState<WorkOrder | 'all' | null>(null);

  if (!isOpen) return null;

  const verifyPin = (): boolean => {
    if (!verifyAdminPin(pin)) {
      soundService.playActionSound('auth_error');
      setPinError('الرمز السري غير صحيح! يلزم إدخال الرمز السري المصرح به لإتمام الاستعادة.');
      return false;
    }
    soundService.playActionSound('auth_success');
    setPinError(null);
    return true;
  };

  const handleRestoreSingle = async (order: WorkOrder) => {
    if (!verifyPin()) return;

    setIsProcessing(true);
    try {
      await onRestoreOrder(order);
      soundService.playActionSound('restore');
      setStatusMessage(`تمت استعادة أمر العمل (${order.workOrderNumber}) بنجاح.`);
      setPendingTargetOrder(null);
      setTimeout(() => {
        setIsProcessing(false);
        setStatusMessage(null);
      }, 1500);
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
    }
  };

  const handleRestoreAll = async () => {
    if (deletedOrders.length === 0) return;
    if (!verifyPin()) return;

    setIsProcessing(true);
    try {
      const ordersToRestore = deletedOrders.map(d => d.order);
      await onRestoreAll(ordersToRestore);
      soundService.playActionSound('restore');
      setStatusMessage(`تمت استعادة كافة أوامر العمل المحذوفة (${ordersToRestore.length}) بنجاح.`);
      setPendingTargetOrder(null);
      setTimeout(() => {
        setIsProcessing(false);
        setStatusMessage(null);
        setPin('');
        onClose();
      }, 1500);
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/70 backdrop-blur-xs flex items-center justify-center p-3 sm:p-4">
      <div 
        className="bg-white rounded-2xl shadow-2xl border border-slate-200 max-w-2xl w-full my-6 overflow-hidden flex flex-col text-right animate-in fade-in zoom-in-95 duration-150"
        dir="rtl"
      >
        {/* Header */}
        <div className="bg-gradient-to-r from-slate-900 via-blue-950 to-slate-900 text-white px-5 py-4 flex items-center justify-between border-b border-blue-800/40">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-amber-500/20 border border-amber-400/30 flex items-center justify-center text-amber-300">
              <History className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-base">سلة المحذوفات واستعادة البيانات</h3>
                <span className="px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-300 border border-amber-500/30 text-[10px] font-bold">
                  محمي برمز الأمان
                </span>
              </div>
              <p className="text-xs text-blue-200/80 mt-0.5">
                استعراض البيانات المحذوفة وإمكانية استرجاعها حصرياً بالرمز السري المصرح به
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1 rounded-lg text-slate-400 hover:text-white hover:bg-white/10 transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Security PIN Authorization Strip */}
        <div className="bg-amber-50/90 border-b border-amber-200 px-5 py-3">
          <div className="flex items-start gap-2">
            <Lock className="w-4 h-4 text-amber-700 shrink-0 mt-0.5" />
            <div className="text-xs text-amber-900 flex-1">
              <span className="font-bold">سياسة حماية البيانات: </span>
              عملية التراجع واستعادة أي بيانات محذوفة محظورة تماماً ومحمية برمز أمان. يرجى إدخال الرمز السري المصرح به أدناه لتمكين أزرار الاستعادة.
            </div>
          </div>

          <div className="mt-2.5 flex flex-wrap items-center gap-3">
            <div className="relative flex-1 min-w-[200px] max-w-xs">
              <input
                type="password"
                maxLength={10}
                value={pin}
                onChange={(e) => {
                  setPin(e.target.value);
                  if (pinError) setPinError(null);
                }}
                placeholder="أدخل الرمز السري ••••"
                className={`w-full text-center tracking-[0.3em] font-mono text-sm py-2 px-3 pr-8 rounded-lg border bg-white focus:outline-hidden transition-all ${
                  pinError 
                    ? 'border-rose-400 text-rose-600 focus:ring-2 focus:ring-rose-200' 
                    : 'border-amber-300 text-slate-900 focus:border-amber-500 focus:ring-2 focus:ring-amber-200'
                }`}
              />
              <KeyRound className="w-3.5 h-3.5 text-slate-400 absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none" />
            </div>

            {deletedOrders.length > 0 && (
              <button
                type="button"
                disabled={isProcessing || !pin.trim()}
                onClick={handleRestoreAll}
                className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-700 active:bg-emerald-800 text-white text-xs font-bold transition-colors disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer shadow-xs"
                title="استعادة كافة البيانات المحذوفة المدرجة بالسلة"
              >
                <RotateCcw className="w-3.5 h-3.5" />
                <span>استعادة كافة المحذوفات ({deletedOrders.length})</span>
              </button>
            )}
          </div>

          {pinError && (
            <div className="flex items-center gap-1.5 mt-2 text-rose-600 text-xs font-semibold">
              <AlertCircle className="w-3.5 h-3.5 shrink-0" />
              <span>{pinError}</span>
            </div>
          )}
        </div>

        {/* Status Message */}
        {statusMessage && (
          <div className="bg-emerald-50 border-b border-emerald-200 px-5 py-2.5 flex items-center gap-2 text-xs font-bold text-emerald-900 animate-in fade-in">
            <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
            <span>{statusMessage}</span>
          </div>
        )}

        {/* Deleted Orders List */}
        <div className="p-5 max-h-96 overflow-y-auto divide-y divide-slate-100">
          {deletedOrders.length === 0 ? (
            <div className="py-12 text-center text-slate-400 space-y-2">
              <div className="w-12 h-12 rounded-full bg-slate-100 flex items-center justify-center mx-auto text-slate-400">
                <Trash2 className="w-6 h-6" />
              </div>
              <p className="text-xs font-semibold text-slate-600">سلة المحذوفات فارغة حالياً</p>
              <p className="text-[11px] text-slate-400">لا توجد أوامر عمل محذوفة مؤخراً في هذه الجلسة.</p>
            </div>
          ) : (
            deletedOrders.map((entry, idx) => (
              <div 
                key={entry.id || idx}
                className="py-3 first:pt-0 last:pb-0 flex items-center justify-between gap-4 hover:bg-slate-50/80 px-2 rounded-xl transition-colors"
              >
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <span className="font-mono font-bold text-slate-900 text-xs">
                      #{entry.order.workOrderNumber || 'بدون رقم'}
                    </span>
                    <span className="font-mono text-[11px] text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded">
                      {entry.order.workOrderCode || '-'}
                    </span>
                    <span className="text-[10px] px-2 py-0.5 rounded-full bg-slate-100 text-slate-600 font-semibold">
                      {entry.order.office}
                    </span>
                  </div>
                  <div className="flex items-center gap-3 text-[11px] text-slate-500">
                    <span>المقاول: <strong className="text-slate-700">{entry.order.contractor || '-'}</strong></span>
                    <span>•</span>
                    <span>تاريخ الحذف: <span className="font-mono text-[10px]">{new Date(entry.deletedAt).toLocaleTimeString('ar-SA')}</span></span>
                  </div>
                </div>

                <div className="flex items-center gap-2 shrink-0">
                  <button
                    type="button"
                    disabled={isProcessing || !pin.trim()}
                    onClick={() => handleRestoreSingle(entry.order)}
                    className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg bg-blue-600 hover:bg-blue-700 active:bg-blue-800 text-white text-xs font-semibold transition-colors disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer shadow-2xs"
                    title={!pin.trim() ? 'يلزم إدخال الرمز السري في الحقل أعلاه لتأكيد الاستعادة' : 'استعادة أمر العمل إلى الجدول'}
                  >
                    <RotateCcw className="w-3 h-3" />
                    <span>استعادة</span>
                  </button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Footer */}
        <div className="bg-slate-50 px-5 py-3 border-t border-slate-200 flex items-center justify-between text-xs">
          <div className="text-slate-500 text-[11px]">
            إجمالي العناصر المحذوفة: <strong className="text-slate-700 font-mono">{deletedOrders.length}</strong>
          </div>

          <div className="flex items-center gap-2">
            {deletedOrders.length > 0 && (
              <button
                type="button"
                onClick={() => {
                  onPermanentlyClearTrash();
                  soundService.playActionSound('delete');
                  onClose();
                }}
                className="px-3 py-1.5 rounded-xl text-rose-600 hover:bg-rose-50 font-semibold transition-colors cursor-pointer text-xs"
              >
                تفريغ السلة نهائياً
              </button>
            )}

            <button
              type="button"
              onClick={onClose}
              className="px-4 py-1.5 rounded-xl border border-slate-300 bg-white hover:bg-slate-100 text-slate-700 font-semibold transition-colors cursor-pointer"
            >
              إغلاق
            </button>
          </div>
        </div>

      </div>
    </div>
  );
};

src/components/SearchModal.tsx:
import React, { useState, useMemo } from 'react';
import { 
  Search, 
  X, 
  Edit, 
  Trash2, 
  FileDown, 
  Building2, 
  Tag, 
  Hash, 
  Camera, 
  Filter, 
  CheckCircle2, 
  AlertTriangle,
  Copy,
  Check,
  AlertCircle
} from 'lucide-react';
import { WorkOrder } from '../types';
import { ConfirmDeleteModal } from './ConfirmDeleteModal';
import { UnifiedSectionExportBar } from './UnifiedSectionExportBar';

interface SearchModalProps {
  isOpen: boolean;
  onClose: () => void;
  workOrders: WorkOrder[];
  onEdit: (order: WorkOrder) => void;
  onDelete: (id: string) => void;
  onDeleteBatch?: (ids: string[]) => void;
  onExportSearchResults: (filtered: WorkOrder[], title?: string, openEmail?: boolean) => void;
  onViewPhotos: (order: WorkOrder) => void;
}

export const SearchModal: React.FC<SearchModalProps> = ({
  isOpen,
  onClose,
  workOrders,
  onEdit,
  onDelete,
  onDeleteBatch,
  onExportSearchResults,
  onViewPhotos
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedOfficeFilter, setSelectedOfficeFilter] = useState('all');
  const [selectedStatusFilter, setSelectedStatusFilter] = useState('all');
  const [selectedProc155Filter, setSelectedProc155Filter] = useState('all');
  const [copiedNoteId, setCopiedNoteId] = useState<string | null>(null);
  const [deleteConfirmTarget, setDeleteConfirmTarget] = useState<{
    type: 'batch' | 'single';
    id?: string;
    title: string;
    message: string;
  } | null>(null);

  // Filter work orders based on search query and criteria
  const filteredOrders = useMemo(() => {
    const term = searchTerm.trim().toLowerCase();
    return workOrders.filter(wo => {
      // Query match across all fields
      const matchesSearch = !term || (
        wo.workOrderNumber.toLowerCase().includes(term) ||
        wo.workOrderCode.toLowerCase().includes(term) ||
        wo.contractor.toLowerCase().includes(term) ||
        (wo.consultant && wo.consultant.toLowerCase().includes(term)) ||
        wo.office.toLowerCase().includes(term) ||
        (wo.photoDocumentation && String(wo.photoDocumentation).toLowerCase().includes(term)) ||
        (wo.consultantForms && String(wo.consultantForms).toLowerCase().includes(term)) ||
        (wo.form190 && String(wo.form190).toLowerCase().includes(term)) ||
        (wo.form200 && String(wo.form200).toLowerCase().includes(term)) ||
        (wo.inspectionForm && String(wo.inspectionForm).toLowerCase().includes(term)) ||
        (wo.qualityNotes && wo.qualityNotes.toLowerCase().includes(term)) ||
        (wo.executionNotes && wo.executionNotes.toLowerCase().includes(term)) ||
        (wo.executionStatus && wo.executionStatus.toLowerCase().includes(term))
      );

      const matchesOffice = selectedOfficeFilter === 'all' || wo.office === selectedOfficeFilter;
      const matchesStatus = selectedStatusFilter === 'all' || wo.executionStatus === selectedStatusFilter;
      const matchesProc155 = selectedProc155Filter === 'all' || wo.procedure155Status === selectedProc155Filter;

      return matchesSearch && matchesOffice && matchesStatus && matchesProc155;
    });
  }, [workOrders, searchTerm, selectedOfficeFilter, selectedStatusFilter, selectedProc155Filter]);

  // Unique lists for quick filters
  const officesList = Array.from(new Set(workOrders.map(w => w.office)));

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-3 sm:p-4">
      <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 max-w-6xl w-full my-6 overflow-hidden flex flex-col text-right">

        {/* Modal Header */}
        <div className="bg-slate-900 text-white px-6 py-4 flex items-center justify-between border-b border-slate-800">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center text-white shadow-xs">
              <Search className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base sm:text-lg font-bold">
                البحث المتقدم في جدول أوامر العمل
              </h2>
              <p className="text-xs text-slate-300">
                نتائج البحث تظهر مجدولة مع إمكانية التعديل، الحذف، والتصدير التكييفي
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Search Controls */}
        <div className="p-4 sm:p-6 bg-slate-50 border-b border-slate-200">
          <div className="flex flex-col md:flex-row gap-3">
            <div className="relative flex-1">
              <Search className="w-4 h-4 text-slate-400 absolute right-3.5 top-3" />
              <input
                type="text"
                autoFocus
                placeholder="ابحث برقم أمر العمل، نوع أمر العمل، المقاول، الاستشاري، المكتب، ملاحظات التنفيذ، أو حالة إجراء 155..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pr-10 pl-4 py-2 rounded-xl border border-slate-300 bg-white text-sm text-slate-900 focus:outline-hidden focus:ring-2 focus:ring-blue-500 shadow-2xs"
              />
              {searchTerm && (
                <button
                  onClick={() => setSearchTerm('')}
                  className="absolute left-3 top-2.5 text-xs text-slate-400 hover:text-slate-700"
                >
                  مسح
                </button>
              )}
            </div>

            {/* Quick Filter: Office */}
            <div className="w-full md:w-48">
              <select
                value={selectedOfficeFilter}
                onChange={(e) => setSelectedOfficeFilter(e.target.value)}
                className="w-full px-3 py-2 rounded-xl border border-slate-300 bg-white text-xs text-slate-800"
              >
                <option value="all">كافة المكاتب</option>
                {officesList.map(off => (
                  <option key={off} value={off}>{off}</option>
                ))}
              </select>
            </div>

            {/* Quick Filter: Procedure 155 */}
            <div className="w-full md:w-56">
              <select
                value={selectedProc155Filter}
                onChange={(e) => setSelectedProc155Filter(e.target.value)}
                className="w-full px-3 py-2 rounded-xl border border-slate-300 bg-white text-xs text-slate-800"
              >
                <option value="all">كافة حالات إجراء 155</option>
                <option value="مؤهل للاستلام (معتمد)">مؤهل للاستلام (معتمد)</option>
                <option value="تم الاستلام وإغلاق 155">تم الاستلام وإغلاق 155</option>
                <option value="بانتظار استيفاء الملاحظات">بانتظار استيفاء الملاحظات</option>
                <option value="قيد التدقيق الفني">قيد التدقيق الفني</option>
                <option value="غير مطابق">غير مطابق</option>
              </select>
            </div>
          </div>

          {/* Results stats & Export Button for Search Results */}
          <div className="flex items-center justify-between mt-3 pt-2 text-xs text-slate-600">
            <div>
              تم العثور على <strong className="text-blue-700 font-bold">{filteredOrders.length}</strong> أمر عمل يطابق معايير البحث
            </div>

            {filteredOrders.length > 0 && (
              <div className="flex items-center gap-2">
                {onDeleteBatch && (
                  <button
                    type="button"
                    onClick={() => {
                      setDeleteConfirmTarget({
                        type: 'batch',
                        title: 'مسح نتائج البحث المفلترة',
                        message: `هل أنت متأكد من مسح وحذف كافة نتائج البحث الحالية (${filteredOrders.length} أمر عمل) نهائياً من قاعدة البيانات والمنظومة؟`
                      });
                    }}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-rose-50 hover:bg-rose-100 text-rose-700 border border-rose-200 font-semibold text-xs transition-colors cursor-pointer"
                    title="مسح جذري لكافة نتائج البحث المفلترة حالياً"
                  >
                    <Trash2 className="w-3.5 h-3.5 text-rose-600" />
                    <span>مسح نتائج البحث ({filteredOrders.length})</span>
                  </button>
                )}

                <UnifiedSectionExportBar
                  orders={filteredOrders}
                  sectionTitle="نتائج_البحث_المتقدم"
                  onOpenExportModal={(ordersToExport, title, openEmail) => {
                    onExportSearchResults(ordersToExport, title, openEmail);
                  }}
                  variant="light"
                />
              </div>
            )}
          </div>
        </div>

        {/* Tabular Search Results Card */}
        <div className="p-4 sm:p-6 overflow-y-auto max-h-[calc(78vh-160px)]">
          {filteredOrders.length === 0 ? (
            <div className="text-center py-12">
              <div className="w-12 h-12 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 mx-auto mb-3">
                <Search className="w-6 h-6" />
              </div>
              <p className="text-sm font-semibold text-slate-700">لا توجد نتائج تطابق بحثك</p>
              <p className="text-xs text-slate-500 mt-1">
                جرب البحث بكلمات أخرى أو اختر "كافة المكاتب"
              </p>
            </div>
          ) : (
            <div className="overflow-x-auto rounded-xl border border-slate-200">
              <table className="w-full text-right border-collapse text-xs">
                <thead>
                  <tr className="bg-slate-100 text-slate-700 font-bold border-b border-slate-200">
                    <th className="py-3 px-3">#</th>
                    <th className="py-3 px-3">المكتب</th>
                    <th className="py-3 px-3">المقاول</th>
                    <th className="py-3 px-3">الاستشاري</th>
                    <th className="py-3 px-3">رقم أمر العمل</th>
                    <th className="py-3 px-3">نوع أمر العمل</th>
                    <th className="py-3 px-3">حالة التنفيذ</th>
                    <th className="py-3 px-3 text-center">تنسيق الصور</th>
                    <th className="py-3 px-3 min-w-[200px]">ملاحظات التنفيذ</th>
                    <th className="py-3 px-3">تعديل المقايسة على النظام</th>
                    <th className="py-3 px-3">إجراء 155</th>
                    <th className="py-3 px-3 text-center">إجراءات</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-200 bg-white font-bold">
                  {filteredOrders.map((wo, index) => {
                    const notesText = (wo.executionNotes || (wo as any).qualityNotes || '').trim();
                    const isNoteCopied = copiedNoteId === wo.id;

                    return (
                      <tr key={`${wo.id || 'search'}-${index}`} className="hover:bg-blue-50/40 transition-colors">
                        <td className="py-3 px-3 font-mono font-black text-slate-900">{index + 1}</td>
                        <td className="py-3 px-3 font-black text-slate-900 whitespace-nowrap">
                          {wo.office}
                        </td>
                        <td className="py-3 px-3 text-slate-900 whitespace-nowrap font-black">
                          {wo.contractor}
                        </td>
                        <td className="py-3 px-3 text-slate-900 whitespace-nowrap font-black">
                          {wo.consultant || '-'}
                        </td>
                        <td className="py-3 px-3 font-mono font-black text-blue-700 whitespace-nowrap">
                          {wo.workOrderNumber}
                        </td>
                        <td className="py-3 px-3 font-mono font-bold text-slate-800 whitespace-nowrap">
                          {wo.workOrderCode}
                        </td>
                        <td className="py-3 px-3 whitespace-nowrap">
                          <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-black ${
                            wo.executionStatus === 'جاهز للاستلام 155'
                              ? 'bg-emerald-100 text-emerald-900 border border-emerald-300'
                              : wo.executionStatus === 'معلق لنواقص'
                              ? 'bg-amber-100 text-amber-900 border border-amber-300'
                              : wo.executionStatus === 'مرفوض'
                              ? 'bg-rose-100 text-rose-900 border border-rose-300'
                              : 'bg-blue-100 text-blue-900 border border-blue-300'
                          }`}>
                            {wo.executionStatus}
                          </span>
                        </td>
                        <td className="py-3 px-3 text-center whitespace-nowrap">
                          <div className="inline-flex items-center gap-1.5 justify-center flex-wrap">
                            <span className="inline-block px-2 py-0.5 rounded text-[11px] font-bold bg-slate-100 text-slate-900 border border-slate-300">
                              {wo.photoCoordination || (wo.photos && wo.photos.length > 0 ? 'مرفق صورة كملاحظة' : 'لا توجد صور مطلوبة')}
                            </span>
                            {wo.photos && wo.photos.length > 0 && (
                              <button
                                onClick={() => onViewPhotos(wo)}
                                className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-amber-100 hover:bg-amber-200 text-amber-900 border border-amber-300 transition-colors text-[10px] font-black"
                                title="مرفق صورة كملاحظة - انقر للمعاينة"
                              >
                                <Camera className="w-3 h-3" />
                                <span>ملاحظة ({wo.photos.length})</span>
                              </button>
                            )}
                          </div>
                        </td>
                        {/* Quality & Execution Notes - Red Card with Bold Red Text and Copy Button */}
                        <td className="py-2.5 px-3 min-w-[200px]">
                          {notesText ? (
                            <div className="bg-red-50/90 border border-red-200 rounded-xl p-2 text-right shadow-2xs">
                              <div className="flex items-center justify-between gap-1 mb-1 pb-1 border-b border-red-200/80">
                                <span className="inline-flex items-center gap-1 text-[10px] font-black text-red-700 bg-red-100/90 px-1.5 py-0.5 rounded border border-red-200">
                                  <AlertCircle className="w-3 h-3 text-red-600 shrink-0" />
                                  <span>ملاحظة</span>
                                </span>
                                <button
                                  type="button"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    if (navigator.clipboard) {
                                      navigator.clipboard.writeText(notesText);
                                      setCopiedNoteId(wo.id);
                                      setTimeout(() => setCopiedNoteId(null), 2000);
                                    }
                                  }}
                                  className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-black transition-all cursor-pointer shadow-2xs ${
                                    isNoteCopied
                                      ? 'bg-emerald-600 text-white'
                                      : 'bg-white hover:bg-red-100 text-red-700 border border-red-200'
                                  }`}
                                  title="نسخ نص الملاحظة إلى الحافظة"
                                >
                                  {isNoteCopied ? <Check className="w-3 h-3 text-white" /> : <Copy className="w-3 h-3" />}
                                  <span>{isNoteCopied ? 'تم النسخ' : 'نسخ'}</span>
                                </button>
                              </div>
                              <p className="text-xs font-black text-red-700 leading-relaxed break-words whitespace-normal select-all">
                                {notesText}
                              </p>
                            </div>
                          ) : (
                            <span className="text-slate-400 font-bold text-xs italic">-</span>
                          )}
                        </td>
                        <td className="py-3 px-3 text-[11px] whitespace-nowrap">
                          <span className={`inline-block px-1.5 py-0.5 rounded font-black ${
                            String(wo.boqModification || '').includes('نعم')
                              ? 'bg-indigo-100 text-indigo-900 font-black border border-indigo-200'
                              : 'bg-slate-100 text-slate-800'
                          }`}>
                            {wo.boqModification}
                          </span>
                          {wo.boqDetails && (
                            <div className="text-[10px] text-purple-950 font-bold mt-0.5">{wo.boqDetails}</div>
                          )}
                        </td>
                        <td className="py-3 px-3 whitespace-nowrap">
                          <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-black ${
                            wo.procedure155Status === 'مؤهل للاستلام (معتمد)' || wo.procedure155Status === 'تم الاستلام وإغلاق 155'
                              ? 'bg-emerald-500 text-white'
                              : wo.procedure155Status === 'غير مطابق'
                              ? 'bg-rose-600 text-white'
                              : 'bg-amber-500 text-white'
                          }`}>
                            {wo.procedure155Status}
                          </span>
                        </td>

                      {/* Explicit Required Actions in search result card: تعديل - حذف */}
                      <td className="py-3 px-3 text-center whitespace-nowrap">
                        <div className="flex items-center justify-center gap-1.5">
                          <button
                            onClick={() => {
                              onEdit(wo);
                            }}
                            className="p-1.5 rounded-lg bg-amber-50 text-amber-700 hover:bg-amber-600 hover:text-white transition-colors cursor-pointer"
                            title="تحديث الحالة"
                          >
                            <Edit className="w-4 h-4" />
                          </button>
                          <button
                            onClick={() => {
                              setDeleteConfirmTarget({
                                type: 'single',
                                id: wo.id,
                                title: 'حذف أمر العمل',
                                message: `هل أنت متأكد من حذف أمر العمل (${wo.workOrderNumber}) للمقاول (${wo.contractor}) نهائياً؟`
                              });
                            }}
                            className="p-1.5 rounded-lg bg-rose-50 text-rose-700 hover:bg-rose-600 hover:text-white transition-colors cursor-pointer"
                            title="حذف أمر العمل"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Modal Footer */}
        <div className="bg-slate-50 px-6 py-3 border-t border-slate-200 flex items-center justify-between">
          <span className="text-xs text-slate-500">
            يتم تحديث ومزامنة النتائج لحظياً لأي تعديل أو حذف
          </span>
          <button
            onClick={onClose}
            className="px-5 py-2 rounded-xl bg-slate-200 hover:bg-slate-300 text-slate-800 text-xs font-semibold transition-colors"
          >
            إغلاق نافذة البحث
          </button>
        </div>

      </div>

      {deleteConfirmTarget && (
        <ConfirmDeleteModal
          isOpen={!!deleteConfirmTarget}
          title={deleteConfirmTarget.title}
          message={deleteConfirmTarget.message}
          confirmText="نعم، احذف نهائياً"
          cancelText="تراجع"
          onConfirm={() => {
            if (deleteConfirmTarget.type === 'batch') {
              if (onDeleteBatch) {
                onDeleteBatch(filteredOrders.map(o => o.id));
              }
            } else if (deleteConfirmTarget.type === 'single' && deleteConfirmTarget.id) {
              onDelete(deleteConfirmTarget.id);
            }
            setDeleteConfirmTarget(null);
          }}
          onClose={() => setDeleteConfirmTarget(null)}
        />
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { 
  WorkOrder, 
  SubOffice, 
  Procedure155Status 
} from '../types';
import { 
  ShieldCheck, 
  AlertTriangle, 
  CheckCircle2, 
  Camera, 
  FileText, 
  Building2, 
  Sparkles, 
  X, 
  Zap, 
  ArrowRight, 
  Filter, 
  FileSpreadsheet, 
  TrendingUp, 
  Check, 
  AlertCircle,
  HelpCircle,
  Clock,
  Layers,
  Bot,
  Copy,
  CheckCheck,
  Loader2
} from 'lucide-react';
import { exportToExcel } from '../services/exportService';

interface SmartAuditAssistantModalProps {
  isOpen: boolean;
  onClose: () => void;
  workOrders: WorkOrder[];
  offices?: SubOffice[];
  onBatchUpdateStatus?: (orderIds: string[], status: Procedure155Status) => Promise<void>;
  onFilterDeficienciesOnly?: () => void;
  onSelectOrderToEdit?: (order: WorkOrder) => void;
}

interface OrderAuditReport {
  order: WorkOrder;
  isReady: boolean;
  score: number; // 0 - 100
  criticalIssues: string[];
  warnings: string[];
}

export const SmartAuditAssistantModal: React.FC<SmartAuditAssistantModalProps> = ({
  isOpen,
  onClose,
  workOrders,
  offices,
  onBatchUpdateStatus,
  onFilterDeficienciesOnly,
  onSelectOrderToEdit
}) => {
  const [activeFilterTab, setActiveFilterTab] = useState<'all' | 'ready' | 'critical' | 'warnings'>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isBatchApplying, setIsBatchApplying] = useState(false);
  const [appliedBatchSuccess, setAppliedBatchSuccess] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [showAiModal, setShowAiModal] = useState(false);
  const [copiedAiReport, setCopiedAiReport] = useState(false);

  // Compute detailed rule-based audit for each work order
  const auditReports = useMemo<OrderAuditReport[]>(() => {
    return workOrders.map(order => {
      const critical: string[] = [];
      const warnings: string[] = [];
      let score = 100;

      // 1. Check contractor and office assignment
      if (!order.office || order.office.trim() === '') {
        critical.push('المكتب الفرعي غير محدد');
        score -= 20;
      }
      if (!order.contractor || order.contractor.trim() === '') {
        critical.push('اسم المقاول المنفذ غير محدد');
        score -= 20;
      }

      // 2. Check Photo Documentation (إلزامي لإجراء 155)
      const photoDoc = String(order.photoDocumentation || '').trim();
      const hasActualPhotos = Array.isArray(order.photos) && order.photos.length > 0;
      if (photoDoc.includes('غير') || (!hasActualPhotos && photoDoc === 'غير مكتمل')) {
        critical.push('التوثيق الفوتوغرافي الميداني غير مكتمل');
        score -= 30;
      } else if (!hasActualPhotos && (!photoDoc || photoDoc === '(فارغ)')) {
        warnings.push('لم يتم إرفاق صور ميدانية توثيقية');
        score -= 15;
      }

      // 3. Check Form 190, 200, Inspection Form
      const f190 = String(order.form190 || '').trim();
      const f200 = String(order.form200 || '').trim();
      const insp = String(order.inspectionForm || '').trim();

      if (f190 === 'غير مكتمل') {
        critical.push('نموذج 190 غير مكتمل');
        score -= 15;
      }
      if (f200 === 'غير مكتمل') {
        critical.push('نموذج 200 غير مكتمل');
        score -= 15;
      }
      if (insp === 'غير مكتمل') {
        critical.push('نموذج الفحص والتدقيق غير مكتمل');
        score -= 15;
      }

      // 4. Check Quality Notes
      const notes = (order.qualityNotes || order.executionNotes || '').trim();
      if (notes.length > 0) {
        warnings.push(`توجد ملاحظات جودة مسجلة: "${notes.slice(0, 45)}${notes.length > 45 ? '...' : ''}"`);
        score -= 10;
      }

      // 5. Check consultant clearance
      const clearance = String(order.consultantClearanceForms || '').trim();
      if (clearance === 'غير مكتمل') {
        warnings.push('نماذج إجازة الاستشاري معلقة');
        score -= 10;
      }

      score = Math.max(0, Math.min(100, score));
      const isReady = critical.length === 0;

      return {
        order,
        isReady,
        score,
        criticalIssues: critical,
        warnings
      };
    });
  }, [workOrders]);

  // Aggregate stats
  const total = auditReports.length;
  const readyOrders = useMemo(() => auditReports.filter(r => r.isReady), [auditReports]);
  const criticalOrders = useMemo(() => auditReports.filter(r => r.criticalIssues.length > 0), [auditReports]);
  const warningOrders = useMemo(() => auditReports.filter(r => r.isReady && r.warnings.length > 0), [auditReports]);

  // Candidates for one-click approval: Orders that meet all criteria but aren't yet marked 'مؤهل للاغلاق ( معتمد )'
  const approvalCandidates = useMemo(() => {
    return readyOrders
      .filter(r => {
        const s = String(r.order.procedure155Status || '');
        return !s.includes('مؤهل') && !s.includes('معتمد') && !s.includes('تم');
      })
      .map(r => r.order.id);
  }, [readyOrders]);

  const complianceRate = total > 0 ? Math.round((readyOrders.length / total) * 100) : 100;

  // Filtered reports for the drilldown table
  const displayedReports = useMemo(() => {
    return auditReports.filter(r => {
      if (activeFilterTab === 'ready' && !r.isReady) return false;
      if (activeFilterTab === 'critical' && r.criticalIssues.length === 0) return false;
      if (activeFilterTab === 'warnings' && (r.warnings.length === 0 || !r.isReady)) return false;

      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const num = (r.order.workOrderNumber || '').toLowerCase();
        const code = (r.order.workOrderCode || '').toLowerCase();
        const off = (r.order.office || '').toLowerCase();
        const cont = (r.order.contractor || '').toLowerCase();
        return num.includes(q) || code.includes(q) || off.includes(q) || cont.includes(q);
      }
      return true;
    });
  }, [auditReports, activeFilterTab, searchQuery]);

  // One-click batch approval
  const handleBatchApprove = async () => {
    if (!onBatchUpdateStatus || approvalCandidates.length === 0) return;
    setIsBatchApplying(true);
    try {
      await onBatchUpdateStatus(approvalCandidates, 'مؤهل للاغلاق ( معتمد )');
      setAppliedBatchSuccess(true);
      setTimeout(() => setAppliedBatchSuccess(false), 3000);
    } finally {
      setIsBatchApplying(false);
    }
  };

  // Export audit summary
  const handleExportAuditReport = () => {
    const exportData = auditReports.map(r => ({
      ...r.order,
      auditScore: `${r.score}%`,
      auditReadiness: r.isReady ? 'مستوفٍ وجاهز للإغلاق 155' : 'غير مستوفٍ لنواقص',
      auditCriticalIssues: r.criticalIssues.join(' | ') || 'لا يوجد',
      auditWarnings: r.warnings.join(' | ') || 'لا يوجد'
    }));

    exportToExcel(
      exportData,
      'تقرير التدقيق الذكي وفحص الامتثال لإجراء 155',
      `تقرير_التدقيق_الذكي_155_${Date.now()}.xlsx`
    );
  };

  const handleFetchAiRecommendations = async () => {
    setIsAiLoading(true);
    setShowAiModal(true);
    try {
      const topDeficiencies = criticalOrders.slice(0, 15).map(r => ({
        workOrderNumber: r.order.workOrderNumber,
        office: r.order.office,
        contractor: r.order.contractor,
        criticalIssues: r.criticalIssues,
        warnings: r.warnings
      }));

      const res = await fetch('/api/smart-audit/ai-recommendations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          summary: {
            total,
            readyCount: readyOrders.length,
            criticalCount: criticalOrders.length,
            warningCount: warningOrders.length,
            complianceRate
          },
          deficiencies: topDeficiencies
        })
      });
      const data = await res.json();
      if (data && data.recommendations) {
        setAiReport(data.recommendations);
      } else {
        setAiReport('تعذر استخراج التوصيات في الوقت الحالي. يرجى إعادة المحاولة.');
      }
    } catch (e: any) {
      setAiReport('حدث خطأ في الاتصال بخادم التحليل الذكي: ' + (e?.message || 'خطأ غير معروف'));
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleCopyAiReport = () => {
    if (!aiReport) return;
    navigator.clipboard.writeText(aiReport);
    setCopiedAiReport(true);
    setTimeout(() => setCopiedAiReport(false), 2500);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-5 bg-slate-950/70 backdrop-blur-xs font-['Cairo',sans-serif] animate-in fade-in duration-200">
      <div 
        className="bg-white rounded-3xl border border-slate-200 shadow-2xl w-full max-w-5xl max-h-[92vh] flex flex-col overflow-hidden text-right animate-in zoom-in-95 duration-200"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Modal Header */}
        <div className="px-5 py-4 bg-gradient-to-r from-slate-950 via-slate-900 to-emerald-950 text-white flex items-center justify-between border-b border-slate-800 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-emerald-500/20 text-emerald-400 border border-emerald-400/30 flex items-center justify-center shadow-xs">
              <Sparkles className="w-5 h-5 animate-pulse" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base sm:text-lg font-black tracking-tight text-white">
                  الفاحص الذكي الشامل لجودة وامتثال أوامر العمل
                </h3>
                <span className="px-2 py-0.5 rounded-full text-[10px] font-mono font-black bg-emerald-500/30 text-emerald-300 border border-emerald-400/40">
                  إجراء 155
                </span>
              </div>
              <p className="text-xs text-slate-300 mt-0.5">
                فحص فوري وتحليلي لمطابقة التوثيق الميداني والنماذج والصور قبل التوقيع النهائي
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="w-9 h-9 rounded-xl bg-white/10 hover:bg-white/20 text-slate-300 hover:text-white flex items-center justify-center transition-colors cursor-pointer border border-white/10"
            title="إغلاق النافذة"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Top Intelligence Metrics Ribbon */}
        <div className="p-4 sm:p-5 bg-slate-50 border-b border-slate-200 shrink-0">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">

            {/* Metric 1: Compliance Rate */}
            <div className="bg-white p-3.5 rounded-2xl border border-slate-200/90 shadow-2xs text-right">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-slate-500">معدل الامتثال العام</span>
                <TrendingUp className="w-4 h-4 text-emerald-600" />
              </div>
              <div className="mt-2 flex items-baseline gap-2">
                <span className="text-2xl font-black text-slate-900 font-mono">{complianceRate}%</span>
                <span className={`text-[11px] font-bold ${complianceRate >= 70 ? 'text-emerald-700' : 'text-amber-700'}`}>
                  {complianceRate >= 70 ? 'جاهزية عالية' : 'نواقص قيد الإكمال'}
                </span>
              </div>
              <div className="w-full bg-slate-100 rounded-full h-1.5 mt-2 overflow-hidden">
                <div 
                  className={`h-full rounded-full transition-all duration-500 ${complianceRate >= 70 ? 'bg-emerald-600' : 'bg-amber-600'}`}
                  style={{ width: `${complianceRate}%` }}
                />
              </div>
            </div>

            {/* Metric 2: Ready Orders */}
            <div className="bg-white p-3.5 rounded-2xl border border-slate-200/90 shadow-2xs text-right">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-slate-500">مستوفية وجاهزة 155</span>
                <CheckCircle2 className="w-4 h-4 text-emerald-600" />
              </div>
              <div className="mt-2 flex items-baseline gap-2">
                <span className="text-2xl font-black text-emerald-700 font-mono">{readyOrders.length}</span>
                <span className="text-xs text-slate-400 font-bold">من أصل {total}</span>
              </div>
              <span className="inline-block mt-2 text-[10px] text-emerald-800 font-bold bg-emerald-50 px-2 py-0.5 rounded-md border border-emerald-200">
                كاملة المتطلبات الفنية
              </span>
            </div>

            {/* Metric 3: Critical Deficiencies */}
            <div className="bg-white p-3.5 rounded-2xl border border-slate-200/90 shadow-2xs text-right">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-slate-500">نواقص حرجة تمنع الإغلاق</span>
                <AlertCircle className="w-4 h-4 text-rose-600" />
              </div>
              <div className="mt-2 flex items-baseline gap-2">
                <span className="text-2xl font-black text-rose-700 font-mono">{criticalOrders.length}</span>
                <span className="text-xs text-rose-600 font-bold">أمر بحاجة لإجراء</span>
              </div>
              <span className="inline-block mt-2 text-[10px] text-rose-800 font-bold bg-rose-50 px-2 py-0.5 rounded-md border border-rose-200">
                صور أو نماذج غير مكتملة
              </span>
            </div>

            {/* Metric 4: Warnings & Notes */}
            <div className="bg-white p-3.5 rounded-2xl border border-slate-200/90 shadow-2xs text-right">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-slate-500">ملاحظات فنية مسجلة</span>
                <AlertTriangle className="w-4 h-4 text-amber-600" />
              </div>
              <div className="mt-2 flex items-baseline gap-2">
                <span className="text-2xl font-black text-amber-700 font-mono">{warningOrders.length}</span>
                <span className="text-xs text-amber-600 font-bold">تتطلب المراجعة</span>
              </div>
              <span className="inline-block mt-2 text-[10px] text-amber-800 font-bold bg-amber-50 px-2 py-0.5 rounded-md border border-amber-200">
                ملاحظات جودة مفتوحة
              </span>
            </div>

          </div>

          {/* Quick Smart Action Bar */}
          <div className="mt-3.5 pt-3 border-t border-slate-200 flex flex-wrap items-center justify-between gap-2.5">
            <div className="flex items-center gap-2 flex-wrap">
              {/* Batch Approve Candidate Button */}
              {approvalCandidates.length > 0 && onBatchUpdateStatus && (
                <button
                  type="button"
                  onClick={handleBatchApprove}
                  disabled={isBatchApplying}
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-black shadow-xs transition-all cursor-pointer disabled:opacity-50"
                  title="ترقية جميع الأوامر المستوفية إلى (مؤهل للاغلاق - معتمد) بنقرة واحدة"
                >
                  <Check className="w-4 h-4 stroke-[3]" />
                  <span>اعتماد الأوامر المستوفية فورياً ({approvalCandidates.length})</span>
                  {isBatchApplying && <span className="animate-spin text-xs">⏳</span>}
                </button>
              )}

              {appliedBatchSuccess && (
                <span className="inline-flex items-center gap-1.5 text-xs font-bold text-emerald-800 bg-emerald-100 px-3 py-1.5 rounded-xl border border-emerald-300 animate-in fade-in">
                  <CheckCircle2 className="w-4 h-4 text-emerald-700" />
                  تم اعتماد وترحيل الحالات السحابية بنجاح!
                </span>
              )}

              {/* Filter Table in Background */}
              {onFilterDeficienciesOnly && criticalOrders.length > 0 && (
                <button
                  type="button"
                  onClick={() => {
                    onFilterDeficienciesOnly();
                    onClose();
                  }}
                  className="inline-flex items-center gap-1.5 px-3 py-2 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-800 border border-rose-300 text-xs font-bold transition-all cursor-pointer"
                  title="إغلاق وتطبيق الفلتر في الجدول الرئيسي لعرض النواقص فقط"
                >
                  <Filter className="w-3.5 h-3.5 text-rose-600" />
                  <span>تصفية الجدول الرئيسي على النواقص ({criticalOrders.length})</span>
                </button>
              )}
            </div>

            {/* AI Recommendations Button */}
            <div className="flex items-center gap-2 mr-auto">
              <button
                type="button"
                onClick={handleFetchAiRecommendations}
                className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-xl bg-gradient-to-r from-purple-700 via-indigo-700 to-blue-700 hover:from-purple-600 hover:to-blue-600 text-white text-xs font-black shadow-xs transition-all cursor-pointer group"
                title="توليد توصيات استشارية واستراتيجية متقدمة لإغلاق الأوامر"
              >
                <Sparkles className="w-4 h-4 text-amber-300 animate-pulse" />
                <span>التحليل الاستشاري المتقدم (Audit Analysis)</span>
              </button>

              {/* Export Audit Report Button */}
              <button
                type="button"
                onClick={handleExportAuditReport}
                className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-xl bg-white hover:bg-slate-100 text-slate-800 border border-slate-300 text-xs font-bold transition-all cursor-pointer shadow-2xs"
                title="تصدير نتائج الفحص والتدقيق كملف إكسل تفصيلي"
              >
                <FileSpreadsheet className="w-4 h-4 text-emerald-600" />
                <span>تصدير تقرير الفحص (Excel)</span>
              </button>
            </div>
          </div>
        </div>

        {/* Drilldown Toolbar: Tabs & Search */}
        <div className="px-5 py-3 bg-white border-b border-slate-200 flex flex-wrap items-center justify-between gap-3 shrink-0">
          <div className="flex items-center gap-1 bg-slate-100 p-1 rounded-xl">
            <button
              type="button"
              onClick={() => setActiveFilterTab('all')}
              className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all cursor-pointer ${
                activeFilterTab === 'all'
                  ? 'bg-white text-slate-900 shadow-xs'
                  : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              كافة الأوامر ({total})
            </button>

            <button
              type="button"
              onClick={() => setActiveFilterTab('critical')}
              className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all cursor-pointer flex items-center gap-1 ${
                activeFilterTab === 'critical'
                  ? 'bg-rose-600 text-white shadow-xs'
                  : 'text-rose-700 hover:bg-rose-100'
              }`}
            >
              <AlertCircle className="w-3 h-3" />
              <span>نواقص حرجة ({criticalOrders.length})</span>
            </button>

            <button
              type="button"
              onClick={() => setActiveFilterTab('warnings')}
              className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all cursor-pointer flex items-center gap-1 ${
                activeFilterTab === 'warnings'
                  ? 'bg-amber-600 text-white shadow-xs'
                  : 'text-amber-800 hover:bg-amber-100'
              }`}
            >
              <AlertTriangle className="w-3 h-3" />
              <span>ملاحظات ({warningOrders.length})</span>
            </button>

            <button
              type="button"
              onClick={() => setActiveFilterTab('ready')}
              className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all cursor-pointer flex items-center gap-1 ${
                activeFilterTab === 'ready'
                  ? 'bg-emerald-600 text-white shadow-xs'
                  : 'text-emerald-800 hover:bg-emerald-100'
              }`}
            >
              <CheckCircle2 className="w-3 h-3" />
              <span>مستوفية ({readyOrders.length})</span>
            </button>
          </div>

          <div className="relative w-full sm:w-64">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="بحث برقم أمر العمل أو المقاول..."
              className="w-full pl-8 pr-3 py-1.5 rounded-xl border border-slate-300 text-xs bg-slate-50 focus:bg-white focus:border-blue-500 focus:outline-none"
            />
            {searchQuery && (
              <button
                type="button"
                onClick={() => setSearchQuery('')}
                className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700"
              >
                <X className="w-3 h-3" />
              </button>
            )}
          </div>
        </div>

        {/* Drilldown List Area */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-5 space-y-2.5 bg-slate-50/60">
          {displayedReports.length === 0 ? (
            <div className="py-16 text-center text-slate-500">
              <CheckCircle2 className="w-12 h-12 text-emerald-500 mx-auto mb-2 opacity-80" />
              <div className="font-bold text-slate-800">لا توجد سجلات مطابقة لهذا الفرز</div>
              <div className="text-xs text-slate-500 mt-1">كافة الأوامر المحددة مستوفية للشروط المطلوبة</div>
            </div>
          ) : (
            displayedReports.map(rep => {
              const { order, isReady, score, criticalIssues, warnings } = rep;
              return (
                <div 
                  key={order.id}
                  className={`bg-white rounded-2xl p-4 border transition-all shadow-2xs hover:shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-right ${
                    !isReady
                      ? 'border-rose-200 hover:border-rose-300'
                      : warnings.length > 0
                      ? 'border-amber-200 hover:border-amber-300'
                      : 'border-emerald-200 hover:border-emerald-300'
                  }`}
                >
                  {/* Left (RTL Right): Core Info */}
                  <div className="space-y-1.5 flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-black text-sm text-slate-900 font-mono">
                        #{order.workOrderNumber || '(بدون رقم)'}
                      </span>
                      {order.workOrderCode && (
                        <span className="text-[11px] font-mono font-bold px-2 py-0.5 rounded-md bg-slate-100 text-slate-700 border border-slate-200">
                          {order.workOrderCode}
                        </span>
                      )}
                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                        isReady
                          ? 'bg-emerald-100 text-emerald-800 border border-emerald-300'
                          : 'bg-rose-100 text-rose-800 border border-rose-300'
                      }`}>
                        {isReady ? 'مستوفٍ لمعايير 155' : 'نواقص غير مكتملة'}
                      </span>
                    </div>

                    <div className="flex items-center gap-3 text-xs text-slate-600 flex-wrap">
                      <span className="font-semibold text-slate-700 flex items-center gap-1">
                        <Building2 className="w-3.5 h-3.5 text-slate-400" />
                        {order.office || 'مكتب غير محدد'}
                      </span>
                      <span>•</span>
                      <span>المقاول: <strong className="text-slate-800">{order.contractor || 'غير محدد'}</strong></span>
                      {order.receiptDate && (
                        <>
                          <span>•</span>
                          <span className="font-mono text-slate-500">{order.receiptDate}</span>
                        </>
                      )}
                    </div>

                    {/* Deficiencies Checklist */}
                    {(criticalIssues.length > 0 || warnings.length > 0) && (
                      <div className="pt-2 flex flex-wrap gap-1.5">
                        {criticalIssues.map((crit, idx) => (
                          <span 
                            key={`c-${idx}`}
                            className="inline-flex items-center gap-1 px-2 py-1 rounded-lg text-[11px] font-bold bg-rose-50 text-rose-800 border border-rose-200"
                          >
                            <AlertCircle className="w-3 h-3 text-rose-600 shrink-0" />
                            <span>{crit}</span>
                          </span>
                        ))}
                        {warnings.map((warn, idx) => (
                          <span 
                            key={`w-${idx}`}
                            className="inline-flex items-center gap-1 px-2 py-1 rounded-lg text-[11px] font-semibold bg-amber-50 text-amber-800 border border-amber-200"
                          >
                            <AlertTriangle className="w-3 h-3 text-amber-600 shrink-0" />
                            <span>{warn}</span>
                          </span>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Right (RTL Left): Score & Action */}
                  <div className="flex items-center gap-3 shrink-0 self-end sm:self-center">
                    <div className="text-center px-3 py-1.5 bg-slate-50 rounded-xl border border-slate-200">
                      <div className="text-[10px] text-slate-500 font-bold">درجة الامتثال</div>
                      <div className={`text-base font-black font-mono ${
                        score >= 80 ? 'text-emerald-700' : score >= 50 ? 'text-amber-700' : 'text-rose-700'
                      }`}>
                        {score}%
                      </div>
                    </div>

                    {onSelectOrderToEdit && (
                      <button
                        type="button"
                        onClick={() => {
                          onSelectOrderToEdit(order);
                          onClose();
                        }}
                        className="px-3 py-2 rounded-xl bg-slate-900 hover:bg-slate-800 text-white text-xs font-bold transition-all cursor-pointer shadow-2xs whitespace-nowrap"
                      >
                        معالجة وتعديل
                      </button>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Modal Footer */}
        <div className="px-5 py-3.5 bg-white border-t border-slate-200 flex items-center justify-between text-xs text-slate-500 shrink-0">
          <div className="flex items-center gap-2">
            <span className="font-bold text-slate-700">حوكمة جودة أعمال الإنشاءات</span>
            <span>•</span>
            <span>نظام التدقيق الرقمي الميداني 155</span>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="px-4 py-1.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-800 font-bold transition-colors cursor-pointer"
          >
            إغلاق
          </button>
        </div>

        {/* AI Recommendations Dialog Overlay */}
        {showAiModal && (
          <div className="absolute inset-0 z-50 bg-slate-950/80 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in">
            <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden text-right animate-in zoom-in-95">

              {/* Header */}
              <div className="px-5 py-4 bg-gradient-to-r from-purple-900 via-indigo-900 to-slate-950 text-white flex items-center justify-between border-b border-purple-800 shrink-0">
                <div className="flex items-center gap-2.5">
                  <div className="w-8 h-8 rounded-xl bg-purple-500/20 text-purple-300 flex items-center justify-center">
                    <Sparkles className="w-4 h-4 animate-pulse" />
                  </div>
                  <div>
                    <h4 className="font-black text-sm text-white">التقرير الاستشاري والتدقيق المتقدم</h4>
                    <p className="text-[11px] text-purple-200">تحليل فني استراتيجي لتأهيل الأوامر لإجراء 155</p>
                  </div>
                </div>

                <button
                  type="button"
                  onClick={() => setShowAiModal(false)}
                  className="p-1 rounded-lg text-slate-300 hover:text-white hover:bg-white/10 transition-colors"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              {/* Body */}
              <div className="p-5 overflow-y-auto flex-1 font-['Cairo',sans-serif] leading-relaxed text-slate-800 text-xs sm:text-sm">
                {isAiLoading ? (
                  <div className="py-16 flex flex-col items-center justify-center gap-3 text-purple-700">
                    <Loader2 className="w-8 h-8 animate-spin text-purple-600" />
                    <span className="font-bold text-xs text-slate-600">جاري صياغة التوصيات الذكية وفحص النواقص الحرجة...</span>
                  </div>
                ) : (
                  <div className="whitespace-pre-wrap font-sans bg-slate-50 p-4 rounded-xl border border-slate-200/80">
                    {aiReport}
                  </div>
                )}
              </div>

              {/* Footer */}
              <div className="px-5 py-3 bg-slate-100 border-t border-slate-200 flex items-center justify-between shrink-0">
                <button
                  type="button"
                  onClick={handleCopyAiReport}
                  disabled={isAiLoading || !aiReport}
                  className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-white hover:bg-slate-50 text-slate-700 border border-slate-300 text-xs font-bold transition-all shadow-2xs disabled:opacity-50 cursor-pointer"
                >
                  {copiedAiReport ? <CheckCheck className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5 text-slate-500" />}
                  <span>{copiedAiReport ? 'تم النسخ بنجاح' : 'نسخ التقرير'}</span>
                </button>

                <button
                  type="button"
                  onClick={() => setShowAiModal(false)}
                  className="px-4 py-1.5 rounded-lg bg-purple-700 hover:bg-purple-800 text-white font-bold text-xs transition-colors cursor-pointer"
                >
                  حسناً، تم الاطلاع
                </button>
              </div>

            </div>
          </div>
        )}

      </div>
    </div>
  );
};

src/components/TableSmartToolbar.tsx:
import React, { useState, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import {
  Plus,
  FileSpreadsheet,
  FileDown,
  Printer,
  Mail,
  Sparkles,
  ShieldCheck,
  CheckCircle2,
  TableProperties,
  Link2,
  Search,
  SlidersHorizontal,
  Trash2,
  AlertTriangle,
  RotateCcw,
  Edit3,
  FileText,
  Copy,
  Camera,
  Filter,
  ChevronDown,
  Maximize2,
  Minimize2,
  X,
  Presentation,
  Image as ImageIcon,
  Loader2,
  Lock,
  LayoutList,
  HardHat,
  ZoomIn,
  ZoomOut,
  Expand,
  Pin,
  WrapText,
  Palette,
  CalendarPlus,
  Layers,
  Check
} from 'lucide-react';
import { WorkOrder, PlatformUser } from '../types';
import { calculateSmartPopoverPosition, getPopoverStyle, TriggerRect } from '../utils/popoverPosition';
import { useUIDesignMode } from '../utils/uiDesignMode';

export type SmartQuickFilterMode =
  | 'all'
  | 'ready'
  | 'not_ready'
  | 'with_photos'
  | 'without_photos'
  | 'new_rows'
  | 'duplicate'
  | 'unmodified'
  | 'edited'
  | 'cross_table_match'
  | 'imported';

export type SmartToolbarMenuKey =
  | 'operations'
  | 'governance'
  | 'table_data'
  | 'filter'
  | 'view_display'
  | 'export'
  | 'security'
  | null;

interface TableSmartToolbarProps {
  // Counts & Stats
  totalOrdersCount: number;
  filteredOrdersCount: number;
  ready155Count: number;
  selectedOrderIdsCount: number;
  crossTableMatchesCount: number;
  newRowsCount: number;
  duplicateRowsCount: number;
  unmodifiedRowsCount: number;
  editedRowsCount: number;
  withPhotosCount: number;
  withoutPhotosCount: number;
  importedRowsCount?: number;
  selectedOrder?: WorkOrder | null;
  overallReadyRate: number;
  columnsCount: number;

  // Search & Filter State
  searchText: string;
  onSearchChange: (text: string) => void;
  smartQuickFilter: SmartQuickFilterMode;
  onSelectQuickFilter: (mode: SmartQuickFilterMode) => void;
  activeColumnFiltersCount?: number;
  onClearAllColumnFilters?: () => void;

  // Actions
  onOpenAddModal: () => void;
  onOpenImportModal?: () => void;
  onOpenCompatibleImport?: () => void;
  onOpenEditStatus?: () => void;
  onOpenEditBasicData?: () => void;
  onOpenSmartAudit?: () => void;
  onBulkApprove155?: () => void;
  onOpenColumnManager?: () => void;
  onOpenDropdownManager?: () => void;
  onDeleteSelectedOrders?: () => void;
  onDeleteSingleOrder?: () => void;
  onOpenDeleteTableModal?: () => void;
  onOpenDataRecovery?: () => void;
  onOpenYearMonthPicker?: () => void;

  // Visual Display, Zoom, Containment & Row Coloring
  zoomPercent?: number;
  onZoomIn?: () => void;
  onZoomOut?: () => void;
  onZoomReset?: () => void;
  onAutoFitAll?: () => void;
  isAutoFitToScreen?: boolean;
  onToggleAutoFitToScreen?: () => void;
  isFullyExpanded?: boolean;
  onToggleFullyExpanded?: () => void;
  isStickyCoreColumns?: boolean;
  onToggleStickyCoreColumns?: () => void;
  isWrapTextEnabled?: boolean;
  onToggleWrapText?: () => void;
  tableDensity?: 'compact' | 'normal' | 'spacious';
  onChangeTableDensity?: (density: 'compact' | 'normal' | 'spacious') => void;
  onSetRowColor?: (color: string | null) => void;
  onClearAllRowColors?: () => void;
  hasCustomRowColors?: boolean;

  // Export
  exportScope: 'all' | 'filtered' | 'selected';
  onSetExportScope: (scope: 'all' | 'filtered' | 'selected') => void;
  onOpenComprehensiveExportModal?: (openEmail?: boolean) => void;
  onDirectExportExcel: () => void;
  onDirectExportPdf: () => void;
  onDirectExportPptx: () => void;
  onDirectExportImage: () => void;
  onDirectExportCsv: () => void;
  onInstantPrint: () => void;
  isExportingPdf?: boolean;
  isExportingImage?: boolean;

  // Presentation Mode & Collapse
  presentationMode: 'docked' | 'overlay';
  onTogglePresentationMode: () => void;
  onCloseTable?: () => void;

  // Notes Report
  onOpenNotesReport?: (mode?: 'all' | 'recurring_all' | 'recurring_contractor', contractor?: string) => void;
  contractorsList?: string[];

  // Auth & Permissions
  currentUser?: PlatformUser | null;
}

export const TableSmartToolbar: React.FC<TableSmartToolbarProps> = ({
  totalOrdersCount,
  filteredOrdersCount,
  ready155Count,
  selectedOrderIdsCount,
  crossTableMatchesCount,
  newRowsCount,
  duplicateRowsCount,
  unmodifiedRowsCount,
  editedRowsCount,
  withPhotosCount,
  withoutPhotosCount,
  importedRowsCount = 0,
  selectedOrder,
  overallReadyRate,
  columnsCount,
  searchText,
  onSearchChange,
  smartQuickFilter,
  onSelectQuickFilter,
  activeColumnFiltersCount = 0,
  onClearAllColumnFilters,
  onOpenAddModal,
  onOpenImportModal,
  onOpenCompatibleImport,
  onOpenEditStatus,
  onOpenEditBasicData,
  onOpenSmartAudit,
  onBulkApprove155,
  onOpenColumnManager,
  onOpenDropdownManager,
  onDeleteSelectedOrders,
  onDeleteSingleOrder,
  onOpenDeleteTableModal,
  onOpenDataRecovery,
  onOpenYearMonthPicker,
  zoomPercent = 100,
  onZoomIn,
  onZoomOut,
  onZoomReset,
  onAutoFitAll,
  isAutoFitToScreen = false,
  onToggleAutoFitToScreen,
  isFullyExpanded = false,
  onToggleFullyExpanded,
  isStickyCoreColumns = true,
  onToggleStickyCoreColumns,
  isWrapTextEnabled = true,
  onToggleWrapText,
  tableDensity = 'normal',
  onChangeTableDensity,
  onSetRowColor,
  onClearAllRowColors,
  hasCustomRowColors = false,
  exportScope,
  onSetExportScope,
  onOpenComprehensiveExportModal,
  onDirectExportExcel,
  onDirectExportPdf,
  onDirectExportPptx,
  onDirectExportImage,
  onDirectExportCsv,
  onInstantPrint,
  isExportingPdf,
  isExportingImage,
  presentationMode,
  onTogglePresentationMode,
  onCloseTable,
  onOpenNotesReport,
  contractorsList
}) => {
  const [uiMode] = useUIDesignMode();
  const isERP = uiMode === 'official_erp';
  const [activeMenu, setActiveMenu] = useState<SmartToolbarMenuKey>(null);
  const [menuAnchorRect, setMenuAnchorRect] = useState<TriggerRect | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const popoverMenuRef = useRef<HTMLDivElement>(null);

  // Close menus on click outside or Escape, and keep anchor coordinates synced on scroll/resize
  useEffect(() => {
    if (!activeMenu) return;

    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as Node;
      if (popoverMenuRef.current && popoverMenuRef.current.contains(target)) {
        return;
      }
      if (containerRef.current && containerRef.current.contains(target)) {
        return;
      }
      setActiveMenu(null);
      setMenuAnchorRect(null);
    };

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setActiveMenu(null);
        setMenuAnchorRect(null);
      }
    };

    const updateAnchorCoordinates = () => {
      const trigger = containerRef.current?.querySelector(`[data-menu-trigger="${activeMenu}"]`);
      if (trigger) {
        const rect = trigger.getBoundingClientRect();
        setMenuAnchorRect({
          top: rect.top,
          bottom: rect.bottom,
          left: rect.left,
          right: rect.right,
          width: rect.width,
          height: rect.height
        });
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleKeyDown);
    window.addEventListener('scroll', updateAnchorCoordinates, { passive: true });
    window.addEventListener('resize', updateAnchorCoordinates);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('scroll', updateAnchorCoordinates);
      window.removeEventListener('resize', updateAnchorCoordinates);
    };
  }, [activeMenu]);

  const toggleMenu = (menu: Exclude<SmartToolbarMenuKey, null>, e: React.MouseEvent) => {
    e.stopPropagation();
    if (activeMenu === menu) {
      setActiveMenu(null);
      setMenuAnchorRect(null);
    } else {
      const rect = e.currentTarget.getBoundingClientRect();
      setMenuAnchorRect({
        top: rect.top,
        bottom: rect.bottom,
        left: rect.left,
        right: rect.right,
        width: rect.width,
        height: rect.height
      });
      setActiveMenu(menu);
    }
  };

  const getFilterLabel = () => {
    switch (smartQuickFilter) {
      case 'ready':
        return 'جاهز 155';
      case 'not_ready':
        return 'نواقص';
      case 'with_photos':
        return 'بصور';
      case 'without_photos':
        return 'بدون صور';
      case 'new_rows':
        return 'مضافة جديدة';
      case 'duplicate':
        return 'مكررة';
      case 'unmodified':
        return 'غير معدلة';
      case 'edited':
        return 'معدلة';
      case 'cross_table_match':
        return 'متطابقة الجداول';
      case 'imported':
        return 'مستوردة';
      default:
        return activeColumnFiltersCount > 0 ? `فلاتر (${activeColumnFiltersCount})` : 'الفلترة والتصفية';
    }
  };

  const isDataViewFilterActive =
    smartQuickFilter === 'new_rows' ||
    smartQuickFilter === 'duplicate' ||
    smartQuickFilter === 'unmodified' ||
    smartQuickFilter === 'edited' ||
    smartQuickFilter === 'imported' ||
    smartQuickFilter === 'cross_table_match';

  return (
    <div
      ref={containerRef}
      className="relative w-full border-b px-2.5 py-2 sm:px-4 select-none font-['Cairo',sans-serif] bg-slate-50 border-slate-200 text-slate-800"
    >
      {/* =========================================================================
          SINGLE UNIFIED WORLD-CLASS COMMAND BAR ROW (كل الأيقونات مجمعة في سطر واحد متكامل)
          ========================================================================= */}
      <div className="flex items-center justify-between gap-1.5 sm:gap-2 overflow-x-auto scrollbar-none flex-nowrap text-xs">

        {/* RIGHT / START CLUSTER: Instant Search + Grouped Command Hubs */}
        <div className="flex items-center gap-1.5 sm:gap-2 shrink-0">

          {/* 0. البحث الفوري المباشر (Instant Search Input) */}
          <div className="relative w-36 sm:w-44 md:w-52 shrink-0">
            <input
              type="text"
              value={searchText}
              onChange={(e) => onSearchChange(e.target.value)}
              placeholder="بحث فوري بالجدول..."
              className="w-full pl-6 pr-7 py-1.5 text-xs h-8.5 font-bold transition-all focus:outline-none rounded-xl bg-white border border-slate-300 text-slate-900 placeholder:text-slate-400 focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 shadow-2xs"
            />
            <Search className="w-3.5 h-3.5 text-slate-400 absolute right-2.5 top-1/2 -translate-y-1/2 pointer-events-none" />
            {searchText && (
              <button
                type="button"
                onClick={() => onSearchChange('')}
                className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700 cursor-pointer"
                title="مسح البحث"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            )}
          </div>

          <div className={`h-6 w-px shrink-0 ${isERP ? 'bg-slate-300' : 'bg-slate-800'}`} />

          {/* 1. أيقونة الإدخال والعمليات (Operations, Import & Edit Hub) */}
          <div className="flex items-center gap-1 p-0.5 shrink-0 bg-white rounded-xl border border-slate-300 shadow-2xs">
            {/* زر سريع لإضافة أمر بنقرة واحدة */}
            <button
              type="button"
              onClick={onOpenAddModal}
              className="h-7.5 px-2.5 font-black text-xs flex items-center gap-1 cursor-pointer transition-all rounded-lg bg-blue-600 hover:bg-blue-700 text-white shadow-2xs active:scale-95"
              title="إضافة أمر عمل جديد فوراً"
            >
              <Plus className="w-3.5 h-3.5" />
              <span>إضافة</span>
            </button>

            {/* القائمة المنسدلة الشاملة للإدخال والاستيراد والتعديل */}
            <button
              type="button"
              data-menu-trigger="operations"
              onClick={(e) => toggleMenu('operations', e)}
              className={`h-7.5 px-2.5 font-bold text-xs flex items-center gap-1.5 transition-all cursor-pointer border ${
                activeMenu === 'operations'
                  ? 'rounded-lg bg-blue-100 text-blue-900 border-blue-400 font-black'
                  : 'rounded-lg bg-slate-50 hover:bg-slate-100 text-slate-800 border-slate-200'
              }`}
              title="قائمة الإدخال، استيراد Excel، استيراد المتوافق، وتعديل أوامر العمل"
            >
              <Layers className="w-3.5 h-3.5 text-blue-700" />
              <span>الإدخال والعمليات</span>
              <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-200 ${activeMenu === 'operations' ? 'rotate-180' : 'text-slate-400'}`} />
            </button>
          </div>

          {/* 2. أيقونة حوكمة وتدقيق 155 والملاحظات */}
          <button
            type="button"
            data-menu-trigger="governance"
            onClick={(e) => toggleMenu('governance', e)}
            className={`h-8.5 px-3 text-xs flex items-center gap-1.5 transition-all cursor-pointer border rounded-xl shrink-0 ${
              activeMenu === 'governance'
                ? 'bg-emerald-600 text-white border-emerald-700 font-black shadow-2xs'
                : 'bg-white hover:bg-slate-50 text-slate-800 border-slate-300 font-bold shadow-2xs'
            }`}
            title="اعتماد مؤهل 155، وتقارير الملاحظات والملاحظات المتكررة"
          >
            <ShieldCheck className={`w-4 h-4 shrink-0 ${activeMenu === 'governance' ? 'text-amber-200' : 'text-emerald-700'}`} />
            <span>حوكمة وتدقيق 155</span>
            <span className={`font-mono text-[10px] px-1.5 py-0.2 rounded ${
              activeMenu === 'governance'
                ? 'bg-emerald-700 text-white font-black'
                : 'bg-emerald-50 text-emerald-800 border border-emerald-250 font-black'
            }`}>
              {overallReadyRate}%
            </span>
            <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-200 ${activeMenu === 'governance' ? 'rotate-180' : 'text-slate-400'}`} />
          </button>

          {/* 3. أيقونة بيانات وتطابق الجداول */}
          <button
            type="button"
            data-menu-trigger="table_data"
            onClick={(e) => toggleMenu('table_data', e)}
            className={`h-8.5 px-3 text-xs flex items-center gap-1.5 transition-all cursor-pointer border rounded-xl shrink-0 ${
              activeMenu === 'table_data' || isDataViewFilterActive
                ? 'bg-blue-600 text-white border-blue-700 font-black shadow-2xs'
                : 'bg-white hover:bg-slate-50 text-slate-800 border-slate-300 font-bold shadow-2xs'
            }`}
            title="تطابق الجداول المتقاطعة وحالات أسطر الجدول (جديدة، مستوردة، مكررة، معدلة، غير معدلة)"
          >
            <TableProperties className={`w-4 h-4 shrink-0 ${activeMenu === 'table_data' || isDataViewFilterActive ? 'text-amber-200' : 'text-blue-700'}`} />
            <span>بيانات وتطابق الجداول</span>
            {crossTableMatchesCount > 0 && (
              <span className={`font-mono text-[10px] px-1.5 py-0.2 rounded ${
                activeMenu === 'table_data'
                  ? 'bg-blue-700 text-white font-black'
