                      >
                        <div className="flex items-center gap-2">
                          <Trash2 className="w-4 h-4" />
                          <span>حذف الأوامر المحددة</span>
                        </div>
                        <span className="font-mono text-[10px] bg-black/30 px-1.5 py-0.5 rounded font-bold">
                          {selectedOrderIdsCount}
