              } else if (internalClipboardText) {
                await applyPaste(internalClipboardText);
              } else {
                setExportNotification('انقر على الخلية المطلوبة واستخدم النسخ/اللصق المباشر');
                setTimeout(() => setExportNotification(null), 3000);
              }
            }}
