export function createEmptyAuditColumnData(): WorkOrderAuditColumnData {
  const data: WorkOrderAuditColumnData = {
    mainStatus: 'غير محدد',
    lastUpdatedAt: new Date().toISOString()
  };
  for (const cat of AUDIT_CATEGORIES_META) {
    data[cat.key] = {
      items: {},
      notes: '',
      status: 'قيد التدقيق',
      compliancePercentage: 0
    };
  }
  return data;
}

export function calculateCategoryAuditStatus(
  categoryData?: AuditSectionCategoryData,
  totalItems: number = 5
): {
  status: 'ممتثل' | 'غير ممتثل' | 'لا ينطبق' | 'قيد التدقيق';
  compliancePercentage: number;
  compliantCount: number;
  nonCompliantCount: number;
  naCount: number;
  totalAnswered: number;
} {
  if (!categoryData || !categoryData.items || typeof categoryData.items !== 'object') {
    return {
      status: 'قيد التدقيق',
      compliancePercentage: 0,
      compliantCount: 0,
      nonCompliantCount: 0,
      naCount: 0,
      totalAnswered: 0
    };
  }
  const items = categoryData.items;
  if (Object.keys(items).length === 0) {
    return {
      status: 'قيد التدقيق',
      compliancePercentage: 0,
      compliantCount: 0,
      nonCompliantCount: 0,
      naCount: 0,
      totalAnswered: 0
    };
  }

  let compliantCount = 0;
  let nonCompliantCount = 0;
  let naCount = 0;
  let totalAnswered = 0;

  for (let i = 0; i < totalItems; i++) {
    const val = items[i];
    if (val === 'ممتثل') {
      compliantCount++;
      totalAnswered++;
    } else if (val === 'غير ممتثل') {
      nonCompliantCount++;
      totalAnswered++;
    } else if (val === 'لا ينطبق') {
      naCount++;
      totalAnswered++;
    }
  }

  if (totalAnswered === 0) {
    return {
      status: 'قيد التدقيق',
      compliancePercentage: 0,
      compliantCount: 0,
      nonCompliantCount: 0,
      naCount: 0,
      totalAnswered: 0
    };
  }

  const effectiveTotal = totalItems - naCount;
  const compliancePercentage =
    effectiveTotal > 0 ? Math.round((compliantCount / effectiveTotal) * 100) : 100;

  let status: 'ممتثل' | 'غير ممتثل' | 'لا ينطبق' | 'قيد التدقيق' = 'قيد التدقيق';
  if (nonCompliantCount > 0) {
    status = 'غير ممتثل';
  } else if (naCount === totalAnswered && totalAnswered > 0) {
    status = 'لا ينطبق';
  } else if (compliantCount > 0) {
    status = 'ممتثل';
  }

  return {
    status,
    compliancePercentage,
    compliantCount,
    nonCompliantCount,
    naCount,
    totalAnswered
  };
}

export function calculateOverallAuditColumnSummary(
  columnData?: WorkOrderAuditColumnData
): {
  compliantCategories: number;
  nonCompliantCategories: number;
  naCategories: number;
  pendingCategories: number;
  averageCompliance: number;
  derivedMainStatus: 'مؤهل' | 'غير مؤهل' | 'غير محدد';
} {
  if (!columnData || typeof columnData !== 'object') {
    return {
      compliantCategories: 0,
      nonCompliantCategories: 0,
      naCategories: 0,
      pendingCategories: AUDIT_CATEGORIES_META.length,
      averageCompliance: 0,
      derivedMainStatus: 'غير محدد'
    };
  }

  let compliantCategories = 0;
  let nonCompliantCategories = 0;
  let naCategories = 0;
  let pendingCategories = 0;
  let evaluatedPercentageSum = 0;
  let evaluatedCount = 0;

  for (const cat of AUDIT_CATEGORIES_META) {
    const catData = columnData[cat.key] as AuditSectionCategoryData | undefined;
    const calc = calculateCategoryAuditStatus(catData, cat.itemCount);
    if (calc.status === 'ممتثل') {
      compliantCategories++;
      evaluatedPercentageSum += calc.compliancePercentage;
      evaluatedCount++;
    } else if (calc.status === 'غير ممتثل') {
      nonCompliantCategories++;
      evaluatedPercentageSum += calc.compliancePercentage;
      evaluatedCount++;
    } else if (calc.status === 'لا ينطبق') {
      naCategories++;
      evaluatedPercentageSum += 100;
      evaluatedCount++;
    } else {
      pendingCategories++;
    }
  }

  const averageCompliance =
    evaluatedCount > 0 ? Math.round(evaluatedPercentageSum / evaluatedCount) : 0;

  let derivedMainStatus: 'مؤهل' | 'غير مؤهل' | 'غير محدد' = 'غير محدد';
  if (nonCompliantCategories > 0) {
    derivedMainStatus = 'غير مؤهل';
  } else if (evaluatedCount > 0 && (compliantCategories > 0 || naCategories > 0)) {
    derivedMainStatus = 'مؤهل';
  } else if (columnData.mainStatus === 'مؤهل' || columnData.mainStatus === 'غير مؤهل') {
    derivedMainStatus = columnData.mainStatus;
  } else {
    derivedMainStatus = 'غير محدد';
  }

  return {
    compliantCategories,
    nonCompliantCategories,
    naCategories,
    pendingCategories,
    averageCompliance,
    derivedMainStatus
  };
}

