import crypto from 'crypto';
import type {
  WorkOrder,
  SubOffice,
  ColumnDefinition,
  DropdownOptionsMap,
  MonthTable,
  ArchivedReportSnapshot,
  LiveNotificationItem,
  PlatformUser
} from '../types.ts';
import { INITIAL_OFFICES, INITIAL_COLUMNS, INITIAL_DROPDOWN_OPTIONS } from '../data/initialData.ts';
import { ensureDefaultSuperAdmins, DEFAULT_SUPER_ADMIN_USERS } from './security.ts';

export interface CloudDatabaseSchema {
  workOrders: WorkOrder[];
  offices: SubOffice[];
  columns: ColumnDefinition[];
  dropdownOptions: DropdownOptionsMap;
  monthTables?: MonthTable[];
  archivedReports?: ArchivedReportSnapshot[];
  deletedOrderIds?: string[];
  lastClearedAt?: string;
  notificationsLog?: LiveNotificationItem[];
  users?: PlatformUser[];
  smtpSettings?: any;
}

export interface CloudChunkRecord {
  vaultKey: string;
  chunkId: string;
  chunkType: 'workOrders' | 'customTemplate' | 'extraCore';
  chunkIndex: number;
  version: number;
  updatedAtIso: string;
  payloadJson: string;
  sha256?: string;
}

export interface CloudManifestRecord {
  vaultKey: string;
  version: number;
  updatedAtIso: string;
  workOrderCount: number;
  tableCount: number;
  userCount: number;
  chunkCount: number;
  chunkIds: string[];
  coreJson: string;
  coreSha256?: string;
  chunkChecksums?: Record<string, string>;
}

export interface CloudStoreAdapter {
  getManifest(vaultKey: string): Promise<CloudManifestRecord | null>;
  setManifest(vaultKey: string, manifest: CloudManifestRecord): Promise<void>;
  getChunk(vaultKey: string, chunkId: string): Promise<CloudChunkRecord | null>;
  setChunk(vaultKey: string, chunkId: string, chunk: CloudChunkRecord): Promise<void>;
}

export function computeSha256(input: string): string {
  return crypto.createHash('sha256').update(input, 'utf-8').digest('hex');
}

export interface AttachmentSlice {
  __sliceRecord: true;
  attKey: string;
  sliceIndex: number;
  totalSlices: number;
  dataSlice: string;
  sha256?: string;
}

const MAX_ATTACHMENT_SLICE_CHARS = 320000;
const MAX_CHUNK_JSON_CHARS = 350000;

/**
 * Extracts base64 data from workOrders (`photosFile`, `photos`, `qualityNoteItems`)
 * into slice records so no workOrder or attachment ever exceeds Firestore's 1 MiB document limit,
 * while guaranteeing 100% lossless reassembly.
 */
export function detachAndSliceAttachments(workOrders: WorkOrder[]): {
  lightweightOrders: WorkOrder[];
  attachmentSlices: any[];
  totalAttachmentsCount: number;
} {
  const attachmentSlices: any[] = [];
  let attCounter = 0;
  const seenHashToAttKey = new Map<string, string>();

  const pushSlicedString = (rawStr: string, prefix: string): string => {
    const rawSha = computeSha256(rawStr);
    const existingKey = seenHashToAttKey.get(rawSha);
    if (existingKey) {
      return `__ATT_REF__:${existingKey}`;
    }
    const attKey = `${prefix}_${attCounter++}`;
    seenHashToAttKey.set(rawSha, attKey);
    const totalLen = rawStr.length;
    const totalSlices = Math.max(1, Math.ceil(totalLen / MAX_ATTACHMENT_SLICE_CHARS));
    for (let i = 0; i < totalSlices; i++) {
      const start = i * MAX_ATTACHMENT_SLICE_CHARS;
      const dataSlice = rawStr.slice(start, start + MAX_ATTACHMENT_SLICE_CHARS);
      attachmentSlices.push({
        __sliceRecord: true,
        attKey,
        sliceIndex: i,
        totalSlices,
        dataSlice,
        sha256: computeSha256(dataSlice)
      });
    }
    return `__ATT_REF__:${attKey}`;
  };

  const lightweightOrders: WorkOrder[] = (Array.isArray(workOrders) ? workOrders : []).map((wo) => {
    if (!wo || typeof wo !== 'object') return wo;
    const clone: WorkOrder = { ...wo };

    // 1. Detach photosFile dataUrl
    if (Array.isArray(clone.photosFile) && clone.photosFile.length > 0) {
      clone.photosFile = clone.photosFile.map((pf) => {
        if (pf && typeof pf.dataUrl === 'string' && pf.dataUrl.length > 16) {
          return {
            ...pf,
            dataUrl: pushSlicedString(pf.dataUrl, `pf_${wo.id}_${pf.id || 'f'}`)
          };
        }
        return pf;
      });
    }

    // 2. Detach photos url
    if (Array.isArray(clone.photos) && clone.photos.length > 0) {
      clone.photos = clone.photos.map((p) => {
        if (p && typeof p.url === 'string' && p.url.length > 16) {
          return {
            ...p,
            url: pushSlicedString(p.url, `ph_${wo.id}_${p.id || 'p'}`)
          };
        }
        return p;
      });
    }

    // 3. Detach qualityNoteItems photos & files
    if (Array.isArray(clone.qualityNoteItems) && clone.qualityNoteItems.length > 0) {
      clone.qualityNoteItems = clone.qualityNoteItems.map((qni, qIdx) => {
        if (!qni || typeof qni !== 'object') return qni;
        const nextQni = { ...qni };
        if (Array.isArray(nextQni.photos) && nextQni.photos.length > 0) {
          nextQni.photos = nextQni.photos.map((pUrl, idx) =>
            typeof pUrl === 'string' && pUrl.length > 16
              ? pushSlicedString(pUrl, `qn_${wo.id}_${qni.id || qIdx}_${idx}`)
              : pUrl
          );
        }
        if (Array.isArray(nextQni.files) && nextQni.files.length > 0) {
          nextQni.files = nextQni.files.map((qf, fIdx) =>
            qf && typeof qf.dataUrl === 'string' && qf.dataUrl.length > 16
              ? { ...qf, dataUrl: pushSlicedString(qf.dataUrl, `qnf_${wo.id}_${qni.id || qIdx}_${qf.id || fIdx}`) }
              : qf
          );
        }
        return nextQni;
      });
    }

    return clone;
  });

  return { lightweightOrders, attachmentSlices, totalAttachmentsCount: attCounter };
}

/**
 * Reassembles detached attachment slices back into their exact original workOrders fields.
 */
export function reassembleAttachmentsIntoOrders(
  lightweightOrders: WorkOrder[],
  attachmentSlices: any[]
): { orders: WorkOrder[]; missingAttachments: string[] } {
  const slicesByKey = new Map<string, any[]>();
  for (const s of attachmentSlices) {
    if (s && s.__sliceRecord && s.attKey) {
      if (s.sha256 && computeSha256(s.dataSlice || '') !== s.sha256) {
        throw new Error(`Attachment slice checksum mismatch for ${s.attKey} slice ${s.sliceIndex}`);
      }
      const list = slicesByKey.get(s.attKey) || [];
      list.push(s);
      slicesByKey.set(s.attKey, list);
    }
  }

  const reassembledMap = new Map<string, string>();
  const missingAttachments = [] as string[];

  for (const [attKey, list] of slicesByKey.entries()) {
    list.sort((a, b) => a.sliceIndex - b.sliceIndex);
    const expectedTotal = list[0]?.totalSlices || 1;
    if (list.length !== expectedTotal) {
      missingAttachments.push(`${attKey} (expected ${expectedTotal} slices, found ${list.length})`);
      continue;
    }
    reassembledMap.set(attKey, list.map((x) => x.dataSlice).join(''));
  }

  const resolveRef = (val: string): string => {
    if (typeof val === 'string' && val.startsWith('__ATT_REF__:')) {
      const key = val.slice('__ATT_REF__:'.length);
      if (reassembledMap.has(key)) {
        return reassembledMap.get(key)!;
      }
      missingAttachments.push(key);
    }
    return val;
  };

  const orders = (Array.isArray(lightweightOrders) ? lightweightOrders : []).map((wo) => {
    if (!wo || typeof wo !== 'object') return wo;
    const clone: WorkOrder = { ...wo };

    if (Array.isArray(clone.photosFile) && clone.photosFile.length > 0) {
      clone.photosFile = clone.photosFile.map((pf) =>
        pf && typeof pf.dataUrl === 'string'
          ? { ...pf, dataUrl: resolveRef(pf.dataUrl) }
          : pf
      );
    }

    if (Array.isArray(clone.photos) && clone.photos.length > 0) {
      clone.photos = clone.photos.map((p) =>
        p && typeof p.url === 'string'
          ? { ...p, url: resolveRef(p.url) }
          : p
      );
    }

    if (Array.isArray(clone.qualityNoteItems) && clone.qualityNoteItems.length > 0) {
      clone.qualityNoteItems = clone.qualityNoteItems.map((qni) => {
        if (!qni || typeof qni !== 'object') return qni;
        const nextQni = { ...qni };
        if (Array.isArray(nextQni.photos)) {
          nextQni.photos = nextQni.photos.map((pUrl) => (typeof pUrl === 'string' ? resolveRef(pUrl) : pUrl));
        }
        if (Array.isArray(nextQni.files)) {
          nextQni.files = nextQni.files.map((qf) =>
            qf && typeof qf.dataUrl === 'string'
              ? { ...qf, dataUrl: resolveRef(qf.dataUrl) }
              : qf
          );
        }
        return nextQni;
      });
    }

    return clone;
  });

  return { orders, missingAttachments };
}

export function splitArrayIntoHashedChunks(
  items: any[],
  versionPrefix: string,
  chunkType: 'workOrders' | 'customTemplate' | 'extraCore',
  maxChars = MAX_CHUNK_JSON_CHARS
): Array<{
  chunkId: string;
  chunkType: 'workOrders' | 'customTemplate' | 'extraCore';
  chunkIndex: number;
  payloadJson: string;
  sha256: string;
}> {
  const chunks: Array<{
    chunkId: string;
    chunkType: 'workOrders' | 'customTemplate' | 'extraCore';
    chunkIndex: number;
    payloadJson: string;
    sha256: string;
  }> = [];

  if (!Array.isArray(items) || items.length === 0) return chunks;

  let currentBatch: any[] = [];
  let currentSize = 2; // "[]"
  let chunkIndex = 0;

  for (const item of items) {
    const itemStr = JSON.stringify(item);
    if (currentBatch.length > 0 && currentSize + itemStr.length + 1 > maxChars) {
      const payloadJson = JSON.stringify(currentBatch);
      chunks.push({
        chunkId: `${versionPrefix}_${chunkIndex}`,
        chunkType,
        chunkIndex,
        payloadJson,
        sha256: computeSha256(payloadJson)
      });
      chunkIndex++;
      currentBatch = [item];
      currentSize = itemStr.length + 2;
    } else {
      currentBatch.push(item);
      currentSize += itemStr.length + 1;
    }
  }

  if (currentBatch.length > 0) {
    const payloadJson = JSON.stringify(currentBatch);
    chunks.push({
      chunkId: `${versionPrefix}_${chunkIndex}`,
      chunkType,
      chunkIndex,
      payloadJson,
      sha256: computeSha256(payloadJson)
    });
  }

  return chunks;
}

/**
 * Atomically writes versioned chunks to the cloud store, verifies every chunk's read-back
 * existence and SHA-256 checksum, and ONLY commits the parent manifest after 100% verification.
 * If any chunk write or verification fails, the previous manifest and its chunks remain untouched.
 */
export async function commitDatabaseToCloudStore(
  store: CloudStoreAdapter,
  vaultKey: string,
  data: CloudDatabaseSchema,
  versionToCommit: number,
  options?: {
    allowExplicitZeroOrders?: boolean;
    lastKnownOrderCount?: number;
    parentManifestInitialized?: boolean;
    strictRuleCompatibleManifest?: boolean;
    reason?: string;
  }
): Promise<{
  committed: boolean;
  version: number;
  chunkCount: number;
  workOrderCount: number;
  coreSha256?: string;
  chunkChecksums?: Record<string, string>;
  error?: string;
  failedChunkId?: string;
}> {
  const ordersList = Array.isArray(data.workOrders) ? data.workOrders : [];
  const lastKnown = options?.lastKnownOrderCount || 0;

  if (ordersList.length === 0 && !options?.allowExplicitZeroOrders && lastKnown > 0) {
    return {
      committed: false,
      version: versionToCommit,
      chunkCount: 0,
      workOrderCount: 0,
      error: `Anti-Wipe Guard: Blocked saving 0 work orders over ${lastKnown} cloud orders`
    };
  }

  const nowIso = new Date().toISOString();
  const safeVersion = Math.max(1, Math.floor(versionToCommit));
  const vTag = `v${safeVersion}`;

  // 1. Detach & slice heavy attachments so no chunk exceeds Firestore limits and zero attachments are lost
  const { lightweightOrders, attachmentSlices, totalAttachmentsCount } = detachAndSliceAttachments(ordersList);

  const woChunks = splitArrayIntoHashedChunks(lightweightOrders, `${vTag}_wo`, 'workOrders', MAX_CHUNK_JSON_CHARS);
  const attChunks = splitArrayIntoHashedChunks(attachmentSlices, `${vTag}_att`, 'customTemplate', MAX_CHUNK_JSON_CHARS);
  const repChunks = splitArrayIntoHashedChunks(data.archivedReports || [], `${vTag}_rep`, 'extraCore', MAX_CHUNK_JSON_CHARS);

  if (options?.strictRuleCompatibleManifest) {
    for (const c of woChunks) c.chunkId = `wo_h_${c.sha256.slice(0, 24)}_${c.chunkIndex}`;
    for (const c of attChunks) c.chunkId = `att_h_${c.sha256.slice(0, 24)}_${c.chunkIndex}`;
    for (const c of repChunks) c.chunkId = `rep_h_${c.sha256.slice(0, 24)}_${c.chunkIndex}`;
  }

  const allChunks = [...woChunks, ...attChunks, ...repChunks];
  const chunkIds = allChunks.map((c) => c.chunkId);
  const chunkChecksums: Record<string, string> = {};
  for (const ch of allChunks) {
    chunkChecksums[ch.chunkId] = ch.sha256;
  }

  const coreSectionsPayload = JSON.stringify({
    offices: data.offices || INITIAL_OFFICES,
    columns: data.columns || INITIAL_COLUMNS,
    monthTables: data.monthTables || [],
    users: ensureDefaultSuperAdmins(data.users || [])
  });
  const sectionsSha256 = computeSha256(coreSectionsPayload);

  const coreObject = {
    offices: data.offices || INITIAL_OFFICES,
    columns: data.columns || INITIAL_COLUMNS,
    dropdownOptions: data.dropdownOptions || INITIAL_DROPDOWN_OPTIONS,
    monthTables: data.monthTables || [],
    deletedOrderIds: data.deletedOrderIds || [],
    lastClearedAt: data.lastClearedAt || null,
    notificationsLog: (data.notificationsLog || []).slice(0, 100),
    users: ensureDefaultSuperAdmins(data.users || []),
    smtpSettings: data.smtpSettings || null,
    __integrity: {
      version: safeVersion,
      sectionsSha256,
      chunkChecksums,
      attachmentSliceCount: attachmentSlices.length,
      totalAttachmentsCount,
      attachmentChunkIds: attChunks.map((c) => c.chunkId)
    }
  };

  let coreJson = JSON.stringify(coreObject);
  if (coreJson.length > 880000) {
    coreObject.notificationsLog = coreObject.notificationsLog.slice(0, 20);
    coreJson = JSON.stringify(coreObject);
  }
  const coreSha256 = computeSha256(coreJson);

  // 2. Ensure parent manifest exists if first-ever bootstrap (so subcollection Master Gate succeeds),
  // WITHOUT overwriting an existing manifest!
  if (!options?.parentManifestInitialized) {
    const existingManifest = await store.getManifest(vaultKey);
    if (!existingManifest) {
      const bootstrapManifest: CloudManifestRecord = {
        vaultKey,
        version: safeVersion,
        updatedAtIso: nowIso,
        workOrderCount: 0,
        tableCount: 0,
        userCount: coreObject.users.length,
        chunkCount: 0,
        chunkIds: [],
        coreJson
      };
      try {
        await store.setManifest(vaultKey, bootstrapManifest);
      } catch (bootErr: any) {
        return {
          committed: false,
          version: safeVersion,
          chunkCount: allChunks.length,
          workOrderCount: ordersList.length,
          error: `Bootstrap manifest write failed: ${bootErr?.message || String(bootErr)}`
        };
      }
    }
  }

  // 3. Stage all versioned chunks (`v${safeVersion}_...`) in controlled parallel batches (concurrency = 15)
  // without touching any previous version's chunks
  const CONCURRENCY = 15;
  for (let i = 0; i < allChunks.length; i += CONCURRENCY) {
    const batch = allChunks.slice(i, i + CONCURRENCY);
    try {
      await Promise.all(
        batch.map(async (ch) => {
          const chunkPayload: CloudChunkRecord = {
            vaultKey,
            chunkId: ch.chunkId,
            chunkType: ch.chunkType,
            chunkIndex: ch.chunkIndex,
            version: safeVersion,
            updatedAtIso: nowIso,
            payloadJson: ch.payloadJson
          };
          if (!options?.strictRuleCompatibleManifest) {
            chunkPayload.sha256 = ch.sha256;
          }
          await store.setChunk(vaultKey, ch.chunkId, chunkPayload);
        })
      );
    } catch (chunkErr: any) {
      return {
        committed: false,
        version: safeVersion,
        chunkCount: allChunks.length,
        workOrderCount: ordersList.length,
        failedChunkId: batch[0]?.chunkId,
        error: `Chunk write failed: ${chunkErr?.message || String(chunkErr)}`
      };
    }
  }

  // 4. Pre-Commit Read-Back & Cryptographic SHA-256 Verification in parallel batches
  // Verify that every single staged chunk exists in the store and its SHA-256 matches before committing manifest!
  for (let i = 0; i < allChunks.length; i += CONCURRENCY) {
    const batch = allChunks.slice(i, i + CONCURRENCY);
    const verifiedBatch = await Promise.all(
      batch.map(async (ch) => {
        const verifiedChunk = await store.getChunk(vaultKey, ch.chunkId);
        return { ch, verifiedChunk };
      })
    );
    for (const { ch, verifiedChunk } of verifiedBatch) {
      if (!verifiedChunk || typeof verifiedChunk.payloadJson !== 'string') {
        return {
          committed: false,
          version: safeVersion,
          chunkCount: allChunks.length,
          workOrderCount: ordersList.length,
          failedChunkId: ch.chunkId,
          error: `Pre-commit verification failed: Chunk ${ch.chunkId} missing on read-back`
        };
      }
      const actualSha = computeSha256(verifiedChunk.payloadJson);
      if (actualSha !== ch.sha256) {
        return {
          committed: false,
          version: safeVersion,
          chunkCount: allChunks.length,
          workOrderCount: ordersList.length,
          failedChunkId: ch.chunkId,
          error: `Pre-commit verification failed: SHA-256 mismatch on chunk ${ch.chunkId} (expected ${ch.sha256}, got ${actualSha})`
        };
      }
    }
  }

  // 5. Commit Authoritative Manifest ONLY after all chunks are verified
  const finalManifest: CloudManifestRecord = {
    vaultKey,
    version: safeVersion,
    updatedAtIso: nowIso,
    workOrderCount: ordersList.length,
    tableCount: (data.monthTables || []).length,
    userCount: coreObject.users.length,
    chunkCount: allChunks.length,
    chunkIds,
    coreJson
  };
  if (!options?.strictRuleCompatibleManifest) {
    finalManifest.coreSha256 = coreSha256;
    finalManifest.chunkChecksums = chunkChecksums;
  }

  try {
    await store.setManifest(vaultKey, finalManifest);
  } catch (manifestErr: any) {
    return {
      committed: false,
      version: safeVersion,
      chunkCount: allChunks.length,
      workOrderCount: ordersList.length,
      error: `Manifest write failed: ${manifestErr?.message || String(manifestErr)}`
    };
  }

  return {
    committed: true,
    version: safeVersion,
    chunkCount: allChunks.length,
    workOrderCount: ordersList.length,
    coreSha256,
    chunkChecksums
  };
}

/**
 * Loads the authoritative database state from the cloud store, verifying every chunk's
 * existence and SHA-256 checksum, and reassembling all detached attachments.
 */
export async function loadDatabaseFromCloudStore(
  store: CloudStoreAdapter,
  vaultKey: string = 'sec_qcms_v2_831300_321_perm'
): Promise<{
  loaded: boolean;
  success: boolean;
  data?: CloudDatabaseSchema;
  db?: CloudDatabaseSchema;
  manifest?: CloudManifestRecord & {
    workOrdersCount: number;
    totalAttachmentsCount: number;
    attachmentChunkIds: string[];
  };
  version?: number;
  updatedAtIso?: string;
  verifiedChunksCount?: number;
  error?: string;
}> {
  const manifest = await store.getManifest(vaultKey);
  if (!manifest) {
    return { loaded: false, success: false };
  }

  const core = JSON.parse(manifest.coreJson || '{}');
  if (manifest.coreSha256) {
    const actualCoreSha = computeSha256(manifest.coreJson || '');
    if (actualCoreSha !== manifest.coreSha256) {
      throw new Error(`Manifest coreJson SHA-256 mismatch: expected ${manifest.coreSha256}, got ${actualCoreSha}`);
    }
  }

  const expectedChecksums: Record<string, string> =
    manifest.chunkChecksums || core.__integrity?.chunkChecksums || {};
  const chunkIds: string[] = Array.isArray(manifest.chunkIds) ? manifest.chunkIds : [];

  const lightweightOrders: WorkOrder[] = [];
  const attachmentSlices: any[] = [];
  const loadedReports: ArchivedReportSnapshot[] = [];
  const attachmentChunkIds: string[] = [];

  const LOAD_CONCURRENCY = 20;
  const loadedChunksOrdered: Array<{ chunkId: string; chData: CloudChunkRecord | null }> = [];
  for (let i = 0; i < chunkIds.length; i += LOAD_CONCURRENCY) {
    const batchIds = chunkIds.slice(i, i + LOAD_CONCURRENCY);
    const batchResults = await Promise.all(
      batchIds.map(async (chunkId) => {
        const chData = await store.getChunk(vaultKey, chunkId);
        return { chunkId, chData };
      })
    );
    loadedChunksOrdered.push(...batchResults);
  }

  for (const { chunkId, chData } of loadedChunksOrdered) {
    if (!chData) {
      throw new Error(`Integrity Error: Referenced chunk ${chunkId} is missing from cloud store`);
    }
    const expectedSha = expectedChecksums[chunkId] || chData.sha256;
    if (expectedSha) {
      const actualSha = computeSha256(chData.payloadJson || '');
      if (actualSha !== expectedSha) {
        throw new Error(`Integrity Error: Chunk ${chunkId} SHA-256 mismatch (expected ${expectedSha}, got ${actualSha})`);
      }
    }

    const parsedSlice = JSON.parse(chData.payloadJson || '[]');
    if (Array.isArray(parsedSlice)) {
      if (chData.chunkType === 'workOrders') {
        lightweightOrders.push(...parsedSlice);
      } else if (chData.chunkType === 'customTemplate') {
        attachmentChunkIds.push(chunkId);
        attachmentSlices.push(...parsedSlice);
      } else if (chData.chunkType === 'extraCore') {
        loadedReports.push(...parsedSlice);
      }
    }
  }

  const { orders: reassembledOrders, missingAttachments } = reassembleAttachmentsIntoOrders(
    lightweightOrders,
    attachmentSlices
  );
  if (missingAttachments.length > 0) {
    throw new Error(`Integrity Error: Missing attachment slices during reassembly: ${missingAttachments.join(', ')}`);
  }

  const uniqueAttKeys = new Set(attachmentSlices.map((s) => s?.attKey).filter(Boolean));
  const totalAttachmentsCount = core.__integrity?.totalAttachmentsCount ?? uniqueAttKeys.size;

  const activeOrderIds = new Set(reassembledOrders.map((w) => w.id));
  const cleanDeletedIds = (Array.isArray(core.deletedOrderIds) ? core.deletedOrderIds : []).filter(
    (id: string) => id && !activeOrderIds.has(id)
  );

  const cloudData: CloudDatabaseSchema = {
    workOrders: reassembledOrders,
    offices: Array.isArray(core.offices) && core.offices.length > 0 ? core.offices : INITIAL_OFFICES,
    columns: Array.isArray(core.columns) && core.columns.length > 0 ? core.columns : INITIAL_COLUMNS,
    dropdownOptions: core.dropdownOptions || INITIAL_DROPDOWN_OPTIONS,
    monthTables: Array.isArray(core.monthTables) ? core.monthTables : [],
    archivedReports: loadedReports,
    deletedOrderIds: cleanDeletedIds,
    lastClearedAt: reassembledOrders.length > 0 ? undefined : core.lastClearedAt || undefined,
    notificationsLog: Array.isArray(core.notificationsLog) ? core.notificationsLog : [],
    users: ensureDefaultSuperAdmins(Array.isArray(core.users) ? core.users : DEFAULT_SUPER_ADMIN_USERS),
    smtpSettings: core.smtpSettings || undefined
  };

  return {
    loaded: true,
    success: true,
    data: cloudData,
    db: cloudData,
    manifest: {
      ...manifest,
      workOrdersCount: manifest.workOrderCount ?? reassembledOrders.length,
      totalAttachmentsCount,
      attachmentChunkIds
    },
    version: Number(manifest.version) || Date.now(),
    updatedAtIso: manifest.updatedAtIso,
    verifiedChunksCount: chunkIds.length
  };
}

src/utils/externalBackupEngine.ts:
import crypto from 'crypto';
import fs from 'fs';
import path from 'path';
import { computeSha256, type CloudDatabaseSchema } from './chunkEngine.ts';
import type { PlatformUser } from '../types.ts';
import { isUserSuperAdmin, hasUserPermission } from './security.ts';

export interface IndependentBackupBundle {
  bundleFormat: 'SEC_QCMS_155_INDEPENDENT_BACKUP_V2';
  bundleId: string;
  createdAtIso: string;
  createdBy: {
    userId: string;
    username: string;
    role: string;
  };
  storageLayer: 'OUT_OF_DATABASE_INDEPENDENT_ARCHIVE';
  counts: {
    workOrders: number;
    monthTables: number;
    offices: number;
    users: number;
    archivedReports: number;
    totalAttachments: number;
    attachments?: number;
    totalAttachmentBytes: number;
  };
  checksums: {
    workOrdersSha256: string;
    monthTablesSha256: string;
    officesSha256: string;
    usersSha256: string;
    archivedReportsSha256: string;
    attachmentsInventorySha256: string;
    payloadSha256: string;
  };
  hmacSignature: string;
  attachmentManifest: Array<{
    orderId: string;
    kind: 'photosFile' | 'photo' | 'qualityNotePhoto';
    itemId: string;
    name?: string;
    length: number;
    sha256: string;
  }>;
  payload: CloudDatabaseSchema;
}

/**
 * Builds a complete inventory of all attachments across all work orders
 * with individual SHA-256 digests so zero attachment loss can be proved cryptographically.
 */
export function buildAttachmentInventory(data: CloudDatabaseSchema): {
  items: IndependentBackupBundle['attachmentManifest'];
  totalBytes: number;
  inventorySha256: string;
} {
  const items: IndependentBackupBundle['attachmentManifest'] = [];
  let totalBytes = 0;

  for (const wo of data.workOrders || []) {
    if (!wo) continue;
    if (Array.isArray(wo.photosFile)) {
      for (const pf of wo.photosFile) {
        if (!pf) continue;
        const raw = String(pf.dataUrl || '');
        const len = Buffer.byteLength(raw, 'utf-8');
        totalBytes += len;
        items.push({
          orderId: wo.id,
          kind: 'photosFile',
          itemId: pf.id || pf.name || 'file',
          name: pf.name,
          length: len,
          sha256: computeSha256(raw)
        });
      }
    }
    if (Array.isArray(wo.photos)) {
      for (const ph of wo.photos) {
        if (!ph) continue;
        const raw = String(ph.url || '');
        const len = Buffer.byteLength(raw, 'utf-8');
        totalBytes += len;
        items.push({
          orderId: wo.id,
          kind: 'photo',
          itemId: ph.id || 'photo',
          length: len,
          sha256: computeSha256(raw)
        });
      }
    }
    if (Array.isArray(wo.qualityNoteItems)) {
      for (const qni of wo.qualityNoteItems) {
        if (!qni || !Array.isArray(qni.photos)) continue;
        qni.photos.forEach((pUrl, idx) => {
          const raw = String(pUrl || '');
          const len = Buffer.byteLength(raw, 'utf-8');
          totalBytes += len;
          items.push({
            orderId: wo.id,
            kind: 'qualityNotePhoto',
            itemId: `${qni.id || 'qn'}_${idx}`,
            length: len,
            sha256: computeSha256(raw)
          });
        });
      }
    }
  }

  const inventorySha256 = computeSha256(JSON.stringify(items));
  return { items, totalBytes, inventorySha256 };
}

/**
 * Verifies separate Backup Operator authorization (requires both SuperAdmin/restoreDeleted
 * permission OR dedicated backupOperatorSecret header).
 */
export function authorizeIndependentBackupOperation(
  user: PlatformUser | null | undefined,
  providedOperatorSecret?: string,
  configuredOperatorSecret?: string
): { authorized: boolean; error?: string } {
  if (
    configuredOperatorSecret &&
    providedOperatorSecret &&
    providedOperatorSecret.length === configuredOperatorSecret.length &&
    crypto.timingSafeEqual(
      Buffer.from(providedOperatorSecret, 'utf-8'),
      Buffer.from(configuredOperatorSecret, 'utf-8')
    )
  ) {
    return { authorized: true };
  }

  if (!user) {
    return {
      authorized: false,
      error: 'غير مصرح (401): تتطلب عمليات النسخ الاحتياطي المستقل مصادقة مسؤول معتمد أو مفتاح مشغل النسخ الاحتياطي المنفصل'
    };
  }

  if (isUserSuperAdmin(user) || hasUserPermission(user, 'restoreDeleted')) {
    return { authorized: true };
  }

  return {
    authorized: false,
    error: 'مرفوض (403): صلاحية إدارة واستعادة النسخ الاحتياطية المستقلة غير متوفرة لهذا الحساب'
  };
}

/**
 * Creates a cryptographically signed, out-of-database backup bundle with section-level
 * and attachment-level SHA-256 digests.
 */
export function createIndependentBackupBundle(
  data: CloudDatabaseSchema,
  signingSecret: string,
  actor?: { userId?: string; username?: string; role?: string }
): IndependentBackupBundle {
  const payloadClone: CloudDatabaseSchema = JSON.parse(JSON.stringify(data));
  const payloadJson = JSON.stringify(payloadClone);

  const workOrdersSha256 = computeSha256(JSON.stringify(payloadClone.workOrders || []));
  const monthTablesSha256 = computeSha256(JSON.stringify(payloadClone.monthTables || []));
  const officesSha256 = computeSha256(JSON.stringify(payloadClone.offices || []));
  const usersSha256 = computeSha256(JSON.stringify(payloadClone.users || []));
  const archivedReportsSha256 = computeSha256(JSON.stringify(payloadClone.archivedReports || []));
  const payloadSha256 = computeSha256(payloadJson);

  const attInv = buildAttachmentInventory(payloadClone);

  const bundleId = `sec155_ind_bkp_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`;
  const createdAtIso = new Date().toISOString();

  const checksums = {
    workOrdersSha256,
    monthTablesSha256,
    officesSha256,
    usersSha256,
    archivedReportsSha256,
    attachmentsInventorySha256: attInv.inventorySha256,
    payloadSha256
  };

  const signingInput = `${bundleId}|${createdAtIso}|${payloadSha256}|${attInv.inventorySha256}`;
  const hmacSignature = crypto
    .createHmac('sha256', signingSecret)
    .update(signingInput, 'utf-8')
    .digest('hex');

  return {
    bundleFormat: 'SEC_QCMS_155_INDEPENDENT_BACKUP_V2',
    bundleId,
    createdAtIso,
    createdBy: {
      userId: actor?.userId || 'system-backup-operator',
      username: actor?.username || 'Backup Operator',
      role: actor?.role || 'BACKUP_OPERATOR'
    },
    storageLayer: 'OUT_OF_DATABASE_INDEPENDENT_ARCHIVE',
    counts: {
      workOrders: (payloadClone.workOrders || []).length,
      monthTables: (payloadClone.monthTables || []).length,
      offices: (payloadClone.offices || []).length,
      users: (payloadClone.users || []).length,
      archivedReports: (payloadClone.archivedReports || []).length,
      totalAttachments: attInv.items.length,
      attachments: attInv.items.length,
      totalAttachmentBytes: attInv.totalBytes
    },
    checksums,
    hmacSignature,
    attachmentManifest: attInv.items,
    payload: payloadClone
  };
}

/**
 * Independently verifies a backup bundle's HMAC signature, section SHA-256 digests,
 * and every single attachment's SHA-256 digest before allowing restoration.
 */
export function verifyIndependentBackupBundle(
  bundle: IndependentBackupBundle,
  signingSecret: string
): {
  valid: boolean;
  errors: string[];
  verifiedCounts?: IndependentBackupBundle['counts'];
} {
  const errors: string[] = [];
  if (!bundle || bundle.bundleFormat !== 'SEC_QCMS_155_INDEPENDENT_BACKUP_V2') {
    return { valid: false, errors: ['Invalid or unsupported backup bundle format'] };
  }
  if (!bundle.payload || typeof bundle.payload !== 'object') {
    return { valid: false, errors: ['Missing backup payload'] };
  }

  const actualWorkOrdersSha = computeSha256(JSON.stringify(bundle.payload.workOrders || []));
  const actualTablesSha = computeSha256(JSON.stringify(bundle.payload.monthTables || []));
  const actualOfficesSha = computeSha256(JSON.stringify(bundle.payload.offices || []));
  const actualUsersSha = computeSha256(JSON.stringify(bundle.payload.users || []));
  const actualReportsSha = computeSha256(JSON.stringify(bundle.payload.archivedReports || []));
  const actualPayloadSha = computeSha256(JSON.stringify(bundle.payload));
  const actualAttInv = buildAttachmentInventory(bundle.payload);

  if (actualWorkOrdersSha !== bundle.checksums?.workOrdersSha256) {
    errors.push('workOrders SHA-256 mismatch');
  }
  if (actualTablesSha !== bundle.checksums?.monthTablesSha256) {
    errors.push('monthTables SHA-256 mismatch');
  }
  if (actualOfficesSha !== bundle.checksums?.officesSha256) {
    errors.push('offices SHA-256 mismatch');
  }
  if (actualUsersSha !== bundle.checksums?.usersSha256) {
    errors.push('users SHA-256 mismatch');
  }
  if (actualReportsSha !== bundle.checksums?.archivedReportsSha256) {
    errors.push('archivedReports SHA-256 mismatch');
  }
  if (actualPayloadSha !== bundle.checksums?.payloadSha256) {
    errors.push('payload SHA-256 mismatch');
  }
  if (actualAttInv.inventorySha256 !== bundle.checksums?.attachmentsInventorySha256) {
    errors.push('attachmentsInventory SHA-256 mismatch');
  }

  const signingInput = `${bundle.bundleId}|${bundle.createdAtIso}|${bundle.checksums?.payloadSha256}|${bundle.checksums?.attachmentsInventorySha256}`;
  const expectedHmac = crypto
    .createHmac('sha256', signingSecret)
    .update(signingInput, 'utf-8')
    .digest('hex');

  const sigA = Buffer.from(String(bundle.hmacSignature || ''), 'utf-8');
  const sigB = Buffer.from(expectedHmac, 'utf-8');
  if (sigA.length !== sigB.length || !crypto.timingSafeEqual(sigA, sigB)) {
    errors.push('Cryptographic HMAC signature verification failed');
  }

  return {
    valid: errors.length === 0,
    errors,
    verifiedCounts: {
      workOrders: (bundle.payload.workOrders || []).length,
      monthTables: (bundle.payload.monthTables || []).length,
      offices: (bundle.payload.offices || []).length,
      users: (bundle.payload.users || []).length,
      archivedReports: (bundle.payload.archivedReports || []).length,
      totalAttachments: actualAttInv.items.length,
      attachments: actualAttInv.items.length,
      totalAttachmentBytes: actualAttInv.totalBytes
    }
  };
}

/**
 * Writes an independent backup bundle to an isolated external directory outside Firestore,
 * along with a detached `.sha256` verification file, and verifies read-back immediately.
 */
export function writeIndependentBackupToDisk(
  bundle: IndependentBackupBundle,
  externalArchiveDir: string,
  signingSecret: string
): {
  filePath: string;
  checksumFilePath: string;
  fileSha256: string;
  sizeBytes: number;
} {
  fs.mkdirSync(externalArchiveDir, { recursive: true });
  const fileName = `${bundle.bundleId}.backup.bundle.json`;
  const filePath = path.join(externalArchiveDir, fileName);
  const checksumFilePath = `${filePath}.sha256`;

  const rawJson = JSON.stringify(bundle, null, 2);
  const fileSha256 = computeSha256(rawJson);

  const tmpPath = `${filePath}.tmp`;
  fs.writeFileSync(tmpPath, rawJson, 'utf-8');
  fs.renameSync(tmpPath, filePath);
  fs.writeFileSync(checksumFilePath, `${fileSha256}  ${fileName}\n`, 'utf-8');

  // Immediate independent read-back verification
  const readBackRaw = fs.readFileSync(filePath, 'utf-8');
  const readBackSha = computeSha256(readBackRaw);
  if (readBackSha !== fileSha256) {
    throw new Error('Disk read-back SHA-256 mismatch on independent backup');
  }
  const parsed = JSON.parse(readBackRaw) as IndependentBackupBundle;
  const check = verifyIndependentBackupBundle(parsed, signingSecret);
  if (!check.valid) {
    throw new Error(`Independent backup verification failed after write: ${check.errors.join(', ')}`);
  }

  return {
    filePath,
    checksumFilePath,
    fileSha256,
    sizeBytes: Buffer.byteLength(rawJson, 'utf-8')
  };
}

src/utils/localChunkedVault.ts:
import fs from 'fs';
import path from 'path';
import zlib from 'zlib';
import crypto from 'crypto';

function sha256Hex(input: string | Buffer): string {
  return crypto.createHash('sha256').update(input).digest('hex');
}

const BLOB_REF_PREFIX = '__VAULT_BLOB_REF__:';
const MAX_SLICE_CHARS = 480000;

export interface ChunkedVaultManifest {
  vaultFormat: string;
  version: number;
  savedAtIso: string;
  workOrdersCount: number;
  usersCount: number;
  monthTablesCount: number;
  officesCount: number;
  coreFile: string;
  coreSha256: string;
  coreGzBytes: number;
  blobsCount: number;
  blobs: Array<{
    blobId: string;
    fullSha: string;
    totalLength: number;
    sliceFiles: Array<{
      fileName: string;
      sizeBytes: number;
      sha256: string;
    }>;
  }>;
}

/**
 * Loads and cryptographically verifies the chunked production vault from `<seedDir>/vault_chunks`.
 * Every single file in `<seedDir>/vault_chunks` is < 380 KB so Cloud Run / AI Studio Publish
 * bundles the container image rapidly while preserving 100% of workOrders, users (with passwordHash),
 * monthTables, offices, columns, and all base64 attachments.
 */
export function loadAuthoritativeChunkedVault(seedDir: string): {
  loaded: boolean;
  version: number;
  data?: any;
  error?: string;
} {
  try {
    const chunksDir = path.join(seedDir, 'vault_chunks');
    const manifestPath = path.join(chunksDir, 'manifest.json');
    let manifest: ChunkedVaultManifest | null = null;
    if (fs.existsSync(manifestPath)) {
      try {
        manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf-8'));
      } catch (_) {
        manifest = null;
      }
    }

    const coreFileName = manifest?.coreFile || 'core_db.json.gz';
    const corePath = path.join(chunksDir, coreFileName);
    if (!fs.existsSync(corePath)) {
      return { loaded: false, version: 0, error: 'Missing core_db.json.gz in vault_chunks' };
    }

    const coreGzBuf = fs.readFileSync(corePath);
    const coreJsonStr = zlib.gunzipSync(coreGzBuf).toString('utf-8');
    const corePayload = JSON.parse(coreJsonStr);
    const blobsMap = new Map<string, string>();

    for (const blobEntry of manifest?.blobs || []) {
      const parts: string[] = [];
      let sliceMissingOrCorrupt = false;
      for (const sliceMeta of blobEntry.sliceFiles || []) {
        const slicePath = path.join(chunksDir, sliceMeta.fileName);
        if (!fs.existsSync(slicePath)) {
          sliceMissingOrCorrupt = true;
          break;
        }
        try {
          const partStr = zlib.gunzipSync(fs.readFileSync(slicePath)).toString('utf-8');
          if (sliceMeta.sha256 && sha256Hex(partStr) !== sliceMeta.sha256) {
            sliceMissingOrCorrupt = true;
            break;
          }
          parts.push(partStr);
        } catch (_) {
          sliceMissingOrCorrupt = true;
          break;
        }
      }
      if (!sliceMissingOrCorrupt && parts.length > 0) {
        const fullBlob = parts.join('');
        if (!blobEntry.fullSha || sha256Hex(fullBlob) === blobEntry.fullSha) {
          blobsMap.set(blobEntry.blobId, fullBlob);
        }
      }
    }

    const resolveBlobRef = (val: any): any => {
      if (typeof val === 'string' && val.startsWith(BLOB_REF_PREFIX)) {
        const blobId = val.slice(BLOB_REF_PREFIX.length);
        return blobsMap.get(blobId) || '';
      }
      return val;
    };

    const reassembledOrders = (Array.isArray(corePayload.workOrders) ? corePayload.workOrders : []).map((wo: any) => {
      if (!wo || typeof wo !== 'object') return wo;
      const clone = { ...wo };
      if (Array.isArray(clone.photos)) {
        clone.photos = clone.photos
          .map((p: any) => (p && p.url ? { ...p, url: resolveBlobRef(p.url) } : p))
          .filter((p: any) => p && p.url);
      }
      if (Array.isArray(clone.photosFile)) {
        clone.photosFile = clone.photosFile
          .map((pf: any) => (pf && pf.dataUrl ? { ...pf, dataUrl: resolveBlobRef(pf.dataUrl) } : pf))
          .filter((pf: any) => pf && pf.dataUrl);
      }
      if (Array.isArray(clone.qualityNoteItems)) {
        clone.qualityNoteItems = clone.qualityNoteItems.map((q: any) => {
          if (!q || typeof q !== 'object') return q;
          const nq = { ...q };
          if (Array.isArray(nq.photos)) {
            nq.photos = nq.photos.map((u: any) => resolveBlobRef(u)).filter(Boolean);
          }
          if (Array.isArray(nq.files)) {
            nq.files = nq.files
              .map((f: any) => (f && f.dataUrl ? { ...f, dataUrl: resolveBlobRef(f.dataUrl) } : f))
              .filter((f: any) => f && f.dataUrl);
          }
          return nq;
        });
      }
      return clone;
    });

    return {
      loaded: true,
      version: Math.max(Number(manifest?.version) || 0, Number(corePayload.version) || 0, Date.now()),
      data: {
        workOrders: reassembledOrders,
        offices: corePayload.offices || [],
        columns: corePayload.columns || [],
        dropdownOptions: corePayload.dropdownOptions || {},
        monthTables: corePayload.monthTables || [],
        archivedReports: corePayload.archivedReports || [],
        deletedOrderIds: corePayload.deletedOrderIds || [],
        notificationsLog: corePayload.notificationsLog || [],
        users: corePayload.users || [],
        smtpSettings: corePayload.smtpSettings
      }
    };
  } catch (err: any) {
    return {
      loaded: false,
      version: 0,
      error: err?.message || String(err)
    };
  }
}

/**
 * Updates the chunked production vault in `<seedDir>/vault_chunks`.
 * Existing content-addressed attachment slices (`blob_<sha256>_s<i>.gz`) are reused if already present on disk,
 * so updating `core_db.json.gz` (~21 KB) is instantaneous (< 5ms) and safe.
 */
export function saveAuthoritativeChunkedVault(seedDir: string, data: any, version: number): boolean {
  try {
    const orders = Array.isArray(data?.workOrders) ? data.workOrders : [];
    if (orders.length === 0) return false;

    const chunksDir = path.join(seedDir, 'vault_chunks');
    fs.mkdirSync(chunksDir, { recursive: true });

    const blobsMap = new Map<string, string>();
    const extractBlobRef = (val: any): any => {
      if (typeof val !== 'string' || val.length < 256) return val;
      const h = sha256Hex(val).slice(0, 24);
      const blobId = `blob_${h}`;
      if (!blobsMap.has(blobId)) {
        blobsMap.set(blobId, val);
      }
      return `${BLOB_REF_PREFIX}${blobId}`;
    };

    const lightweightOrders = orders.map((wo: any) => {
      if (!wo || typeof wo !== 'object') return wo;
      const clone = { ...wo };
      if (Array.isArray(clone.photos)) {
        clone.photos = clone.photos.map((p: any) => (p && p.url ? { ...p, url: extractBlobRef(p.url) } : p));
      }
      if (Array.isArray(clone.photosFile)) {
        clone.photosFile = clone.photosFile.map((pf: any) =>
          pf && pf.dataUrl ? { ...pf, dataUrl: extractBlobRef(pf.dataUrl) } : pf
        );
      }
      if (Array.isArray(clone.qualityNoteItems)) {
        clone.qualityNoteItems = clone.qualityNoteItems.map((q: any) => {
          if (!q || typeof q !== 'object') return q;
          const nq = { ...q };
          if (Array.isArray(nq.photos)) {
            nq.photos = nq.photos.map((u: any) => extractBlobRef(u));
          }
          if (Array.isArray(nq.files)) {
            nq.files = nq.files.map((f: any) =>
              f && f.dataUrl ? { ...f, dataUrl: extractBlobRef(f.dataUrl) } : f
            );
          }
          return nq;
        });
      }
      return clone;
    });

    const savedAtIso = new Date().toISOString();
    const corePayload = {
      vaultFormat: 'SEC_QCMS_155_CHUNKED_VAULT_V2',
      version,
      savedAtIso,
      workOrders: lightweightOrders,
      offices: data.offices || [],
      columns: data.columns || [],
      dropdownOptions: data.dropdownOptions || {},
      monthTables: data.monthTables || [],
      archivedReports: data.archivedReports || [],
      deletedOrderIds: data.deletedOrderIds || [],
      notificationsLog: (data.notificationsLog || []).slice(0, 150),
      users: data.users || [],
      smtpSettings: data.smtpSettings
    };

    const coreJsonStr = JSON.stringify(corePayload);
    const coreGz = zlib.gzipSync(Buffer.from(coreJsonStr, 'utf-8'), { level: 6 });
    const coreTmp = path.join(chunksDir, 'core_db.json.gz.tmp');
    const coreFinal = path.join(chunksDir, 'core_db.json.gz');
    fs.writeFileSync(coreTmp, coreGz);
    fs.renameSync(coreTmp, coreFinal);

    const blobManifest: ChunkedVaultManifest['blobs'] = [];
    for (const [blobId, fullStr] of blobsMap.entries()) {
      const fullSha = sha256Hex(fullStr);
      const totalSlices = Math.ceil(fullStr.length / MAX_SLICE_CHARS);
      const sliceFiles: Array<{ fileName: string; sizeBytes: number; sha256: string }> = [];
      for (let i = 0; i < totalSlices; i++) {
        const part = fullStr.slice(i * MAX_SLICE_CHARS, (i + 1) * MAX_SLICE_CHARS);
        const fileName = `${blobId}_s${i}.gz`;
        const filePath = path.join(chunksDir, fileName);
        const partSha = sha256Hex(part);
        let sizeBytes = 0;
        if (fs.existsSync(filePath)) {
          sizeBytes = fs.statSync(filePath).size;
        } else {
          const gz = zlib.gzipSync(Buffer.from(part, 'utf-8'), { level: 6 });
          const tmpSlice = `${filePath}.tmp`;
          fs.writeFileSync(tmpSlice, gz);
          fs.renameSync(tmpSlice, filePath);
          sizeBytes = gz.length;
        }
        sliceFiles.push({ fileName, sizeBytes, sha256: partSha });
      }
      blobManifest.push({ blobId, fullSha, totalLength: fullStr.length, sliceFiles });
    }

    const manifest: ChunkedVaultManifest = {
      vaultFormat: 'SEC_QCMS_155_CHUNKED_VAULT_V2',
      version,
      savedAtIso,
      workOrdersCount: lightweightOrders.length,
      usersCount: (data.users || []).length,
      monthTablesCount: (data.monthTables || []).length,
      officesCount: (data.offices || []).length,
      coreFile: 'core_db.json.gz',
      coreSha256: sha256Hex(coreJsonStr),
      coreGzBytes: coreGz.length,
      blobsCount: blobManifest.length,
      blobs: blobManifest
    };

    const manifestTmp = path.join(chunksDir, 'manifest.json.tmp');
    const manifestFinal = path.join(chunksDir, 'manifest.json');
    fs.writeFileSync(manifestTmp, JSON.stringify(manifest, null, 2), 'utf-8');
    fs.renameSync(manifestTmp, manifestFinal);
    return true;
  } catch (err) {
    console.warn('[Chunked Vault] Warning saving chunked vault:', err);
    return false;
  }
}

src/utils/popoverPosition.ts:
/**
 * Smart Popover & Dropdown Viewport Boundary Engine
 * Ensures any dropdown, popover, or floating menu appears strictly
 * WITHIN the browser viewport boundaries without clipping, overflow, or errors.
 */
import type React from 'react';

export interface TriggerRect {
  top: number;
  bottom: number;
  left: number;
  right: number;
  width: number;
  height: number;
}

export interface PopoverPositionOptions {
  preferredWidth?: number;
  minWidth?: number;
  maxWidth?: number;
  maxHeight?: number;
  offset?: number;
  padding?: number;
  align?: 'end' | 'start' | 'center'; // In RTL, 'end' aligns with right edge
  forceDirection?: 'up' | 'down';
}

export interface CalculatedPopoverPosition {
  top?: number;
  bottom?: number;
  left: number;
  width: number;
  maxHeight: number;
  openUpward: boolean;
  align: 'end' | 'start' | 'center';
}

export type PopoverCoords = CalculatedPopoverPosition;

/**
 * Calculates intelligent coordinates for any floating popover / dropdown.
 * - Auto flips vertically if there is not enough room below
 * - Smart bottom anchoring when opening upward to prevent floating gaps
 * - Auto clamps horizontally so it never exceeds screen edges (left or right)
 * - Automatically restricts maxHeight and enables smooth internal scrolling
 */
export function calculateSmartPopoverPosition(
  triggerRect: TriggerRect,
  estimatedHeight: number,
  options: PopoverPositionOptions = {}
): CalculatedPopoverPosition {
  const padding = options.padding ?? 10;
  const offset = options.offset ?? 6;
  const viewportWidth = typeof window !== 'undefined' ? window.innerWidth : 1200;
  const viewportHeight = typeof window !== 'undefined' ? window.innerHeight : 800;

  // Determine width with screen containment
  const preferredWidth = options.preferredWidth ?? Math.max(220, triggerRect.width);
  const minWidth = options.minWidth ?? 160;
  const maxAllowedWidth = Math.min(options.maxWidth ?? 460, viewportWidth - padding * 2);
  let width = Math.max(minWidth, Math.min(preferredWidth, maxAllowedWidth));
  if (width > viewportWidth - padding * 2) {
    width = Math.max(minWidth, viewportWidth - padding * 2);
  }

  // Determine vertical available space
  const desiredMaxH = options.maxHeight ?? 520;
  const spaceBelow = Math.max(0, viewportHeight - triggerRect.bottom - offset - padding);
  const spaceAbove = Math.max(0, triggerRect.top - offset - padding);

  let openUpward = false;
  if (options.forceDirection === 'up') {
    openUpward = true;
  } else if (options.forceDirection === 'down') {
    openUpward = false;
  } else {
    // Flip upward only if space below is insufficient AND space above is meaningfully larger
    if (spaceBelow < Math.min(estimatedHeight, 260) && spaceAbove > spaceBelow + 40) {
      openUpward = true;
    }
  }

  // Calculate coordinates & maxHeight so the menu NEVER shrinks into a tiny clipped box
  let top: number | undefined;
  let bottom: number | undefined;
  let maxHeight: number;

  const targetHeight = Math.min(estimatedHeight, desiredMaxH, viewportHeight - padding * 2);

  if (openUpward && spaceAbove >= 220) {
    maxHeight = Math.min(desiredMaxH, Math.max(220, spaceAbove));
    bottom = Math.round(viewportHeight - triggerRect.top + offset);
    top = Math.max(padding, triggerRect.top - Math.min(targetHeight, maxHeight) - offset);
  } else if (spaceBelow >= targetHeight || spaceBelow >= 240) {
    openUpward = false;
    maxHeight = Math.min(desiredMaxH, Math.max(240, spaceBelow));
    top = Math.round(triggerRect.bottom + offset);
    bottom = undefined;
  } else {
    // Viewport is tight both above and below: float over the page clamped to viewport bounds so no items are hidden
    openUpward = false;
    maxHeight = Math.min(desiredMaxH, Math.max(260, viewportHeight - padding * 2));
    const idealTop = Math.round(triggerRect.bottom + offset);
    const maxTop = Math.max(padding, viewportHeight - targetHeight - padding);
    top = Math.max(padding, Math.min(idealTop, maxTop));
    bottom = undefined;
  }

  // Determine horizontal positioning (RTL aware: default is align to right edge)
  let left: number;
  const align = options.align ?? 'end'; // 'end' in RTL = right edge

  if (align === 'end') {
    // Right edge aligned with trigger's right edge
    left = triggerRect.right - width;
  } else if (align === 'start') {
    // Left edge aligned with trigger's left edge
    left = triggerRect.left;
  } else {
    // Center aligned
    left = triggerRect.left + (triggerRect.width / 2) - (width / 2);
  }

  // Viewport bounds clamping (ensure 100% inside screen horizontally)
  if (left < padding) {
    left = padding;
  }
  if (left + width > viewportWidth - padding) {
    left = Math.max(padding, viewportWidth - width - padding);
  }

  return {
    top: top !== undefined ? Math.round(top) : undefined,
    bottom: bottom !== undefined ? Math.round(bottom) : undefined,
    left: Math.round(left),
    width: Math.round(width),
    maxHeight: Math.round(maxHeight),
    openUpward,
    align
  };
}

/**
 * Helper to convert CalculatedPopoverPosition into React.CSSProperties
 * Automatically anchors via `bottom` when opening upward to guarantee zero gap and zero offscreen clipping.
 */
export function getPopoverStyle(pos: CalculatedPopoverPosition): React.CSSProperties {
  const style: React.CSSProperties = {
    position: 'fixed',
    left: `${pos.left}px`,
    width: `${pos.width}px`,
    maxHeight: `${pos.maxHeight}px`,
    zIndex: 999999,
    overflowY: 'auto'
  };

  if (pos.openUpward && pos.bottom !== undefined) {
    style.bottom = `${pos.bottom}px`;
    style.top = 'auto';
  } else if (pos.top !== undefined) {
    style.top = `${pos.top}px`;
    style.bottom = 'auto';
  }

  return style;
}

